// islamic: 48 lessons, 8 units
LESSONS.push(
  {"id":"g8-islamic-1-1","grade":"g8","subject":"islamic","term":1,"title":"اجتناب الغيبة","summary":"شرح متحرك لمعنى الغيبة وحكمها وأمثلة منها في المدرسة والأسرة وطرق الوقاية والتوبة، ثم أنشطة بثلاثة مستويات.","page":"lesson-avoiding-backbiting.html","video":"","pdf":"","notes":["الغيبة: ذكرك أخاك الغائب بما يكره، ولو كان ما تقوله صحيحًا (رواه مسلم).","إن كان الكلام كاذبًا فهو بهتان، وهو أشد من الغيبة.","نهى الله عنها في سورة الحجرات، وشبّهها بأكل لحم الأخ ميتًا.","تقع الغيبة بالقول أو الإشارة أو التقليد أو الكتابة، في المدرسة والأسرة وعلى الهاتف.","نحفظ لساننا: «فليقل خيرًا أو ليصمت»، وإذا بدأ أحد يغتاب غيّرنا الموضوع أو دافعنا عن الغائب أو غادرنا المجلس.","يجوز ذكر العيب للحاجة، كرفع الأذى وطلب النصيحة والتحذير من الضرر، بقصد الإصلاح وبقدر الحاجة. ومن وقع في الغيبة تاب واستغفر وعزم ألا يعود."],"exercises":["عرّف الغيبة، واذكر ركنيها.","اذكر موقفًا من المدرسة أو البيت تقع فيه الغيبة، وبيّن كيف تتجنبها.","متى يجوز ذكر عيب الغير؟ اذكر مثالين."],"levels":{"easy":[{"type":"mcq","q":"عرّف النبي ﷺ الغيبة بأنها:","options":["الكذب على أخيك","ذكرك أخاك بما يكره","ذكر محاسن الناس","السكوت عن الحق"],"answer":1,"why":"قال ﷺ: «ذكرك أخاك بما يكره» (رواه مسلم)."},{"type":"mcq","q":"في أي سورة جاء قوله تعالى: ﴿وَلَا يَغْتَب بَّعْضُكُم بَعْضًا﴾؟","options":["البقرة","الفاتحة","ق","الحجرات"],"answer":3,"why":"جاء النهي عن الغيبة في سورة الحجرات، الآية ١٢."},{"type":"mcq","q":"بماذا شبّه القرآن الكريم الغيبة؟","options":["بإشعال النار","بسرقة المال","بأكل لحم الأخ ميتًا","بقطع الطريق"],"answer":2,"why":"قال تعالى: ﴿أَيُحِبُّ أَحَدُكُمْ أَن يَأْكُلَ لَحْمَ أَخِيهِ مَيْتًا فَكَرِهْتُمُوهُ﴾."},{"type":"mcq","q":"ما حكم الغيبة في الإسلام؟","options":["محرّمة","مباحة","مستحبة","مكروهة فقط"],"answer":0,"why":"الغيبة محرّمة بنص القرآن والسنة."}],"medium":[{"type":"mcq","q":"قال النبي ﷺ: «إن كان فيه ما تقول فقد اغتبته». يدل ذلك على أن الغيبة:","options":["لا تكون إلا بالكذب","تقع ولو كان الكلام صحيحًا","جائزة إذا كان الكلام صدقًا","لا تقع إلا بالكتابة"],"answer":1,"why":"الصدق لا يبيح الغيبة، فهي ذكر الغائب بما يكره ولو كان فيه."},{"type":"tfr","q":"إذا ذكرت زميلك الغائب بعيب فيه حقًّا فلا يُعدّ ذلك غيبة.","answer":false,"reasons":["لأن الغيبة هي ذكر الغائب بما يكره، ولو كان ما تقوله صحيحًا","لأن الصدق يبيح الغيبة","لأن الغيبة لا تقع إلا في الأسرة"],"reason":0},{"type":"essay","q":"اذكر ركنَي الغيبة.","model":"الأول: شخص غائب لا يسمع الكلام. والثاني: كلام عنه يكرهه لو سمعه."},{"type":"tfr","q":"يجوز لك أن تستمع إلى الغيبة ما دمت لا تتكلم.","answer":false,"reasons":["لأن الاستماع بلا كلام لا أثر له","لأن السامع الراضي بالغيبة شريك فيها، فعليه أن ينكرها أو يغادر المجلس","لأن الغيبة تقع بالسكوت فقط"],"reason":1},{"type":"mcq","q":"ما معنى «بهتّه» في الحديث: «وإن لم يكن فيه فقد بهتّه»؟","options":["مدحته","نصحته","كذبت عليه","سامحته"],"answer":2,"why":"البهتان أن تقول عن الإنسان ما ليس فيه، وهو كذب وظلم أكبر من الغيبة."},{"type":"essay","q":"اذكر موقفًا من المدرسة أو البيت تقع فيه الغيبة، وبيّن كيف تتجنبها.","model":"مثال: زملاء يسخرون من درجات زميل غائب. أتجنب الغيبة بتغيير الموضوع بلطف، أو أدافع عن الغائب، أو أغادر المجلس. وتُقبل أي إجابة صحيحة."},{"type":"tfr","q":"قوله ﷺ: «فليقل خيرًا أو ليصمت» يرشدنا إلى حفظ اللسان.","answer":true,"reasons":["لأن الكلام كله ممنوع في الإسلام","لأن الصمت أفضل من الصلاة","لأن المؤمن إما أن يقول خيرًا أو يسكت، فيحفظ لسانه من الغيبة وغيرها"],"reason":2}],"hard":[{"type":"mcq","q":"أيّ المواقف الآتية يُعدّ غيبة؟","options":["أن تشكو إلى معلمك طالبًا يؤذيك ليمنع أذاه","أن تسأل والدك عن حكم شرعي","أن تسخر من درجات زميلك الغائب أمام أصدقائك","أن تحذّر الناس من شخص يضرّهم"],"answer":2,"why":"السخرية من زميل غائب بما يكره غيبة. أما الشكوى لرفع الأذى وطلب الفتوى والتحذير من الضرر فمن المواضع التي أجازها العلماء للحاجة."},{"type":"essay","q":"اشرح لماذا حرّم الإسلام الغيبة.","model":"لأن لكل إنسان كرامة وعِرضًا محفوظًا، قال ﷺ: «كل المسلم على المسلم حرام: دمه وماله وعرضه». والغيبة تعتدي على هذه الكرامة، وتُفقد الثقة بين الناس، وتؤذي المشاعر، وتفسد الأخوّة."},{"type":"tfr","q":"الكتابة عن زميل غائب في مجموعة الصف على الهاتف لا تُعدّ غيبة لأن الكاتب لم يتكلم.","answer":false,"reasons":["لأن الغيبة تقع بالقول والإشارة والكتابة متى ذُكر الغائب بما يكره","لأن الكتابة ليست كلامًا","لأن المجموعة خاصة بأصدقائه"],"reason":0},{"type":"mcq","q":"ما التصرف الصحيح إذا بدأ أحدهم يغتاب زميلًا أمامك؟","options":["نضحك معه","نسكت ونكمل الاستماع","نسجّل كلامه وننشره","نغيّر الموضوع بلطف، أو ندافع عن الغائب، أو نغادر المجلس"],"answer":3,"why":"هذه الطرق تنكر الغيبة وتحفظ حق الغائب، ولا نستمع إليها راضين بها."},{"type":"essay","q":"استدل بآية من القرآن الكريم على تحريم الغيبة، واكتب معناها بأسلوبك.","model":"قال تعالى: ﴿وَلَا يَغْتَب بَّعْضُكُم بَعْضًا أَيُحِبُّ أَحَدُكُمْ أَن يَأْكُلَ لَحْمَ أَخِيهِ مَيْتًا فَكَرِهْتُمُوهُ﴾ (الحجرات: ١٢). نهى الله عن الغيبة وشبّهها بأكل لحم الأخ الميت لينفّرنا منها."},{"type":"tfr","q":"يجوز أن يذكر الطالب عيب زميل عند معلمه إذا كان قصده منع أذاه والإصلاح.","answer":true,"reasons":["لأن الغيبة جائزة في كل الأحوال","لأن العلماء أجازوا ذكر العيب للحاجة، كرفع الأذى وطلب النصيحة، بقصد الإصلاح وبقدر الحاجة","لأن المعلم لا يسأل عن الأسباب"],"reason":1},{"type":"mcq","q":"ما الشرط الذي يجعل ذكر عيب الغير جائزًا للحاجة؟","options":["أن يكون القصد الإصلاح وبقدر الحاجة فقط","أن يكون أمام الجميع","أن نضحك منه","أن نكتبه في مجموعة الصف"],"answer":0,"why":"يجوز ذكر العيب لرفع الأذى أو طلب النصيحة أو التحذير من الضرر، بشرط أن يكون القصد الإصلاح وبقدر الحاجة فقط."},{"type":"essay","q":"ماذا يفعل من وقع في غيبة أحد؟","model":"يندم ويستغفر الله ويعزم ألا يعود، ويذكر الغائب بخير، ويطلب منه السماح بلطف إن أمكن ولم يسبب ذلك أذى أكبر."},{"type":"tfr","q":"من وقع في الغيبة فلا توبة له.","answer":false,"reasons":["لأن الغيبة لا تُغفر أبدًا","لأن التوبة للصلاة فقط","لأن باب التوبة مفتوح، فنندم ونستغفر ونعزم ألا نعود، وقد قال تعالى: ﴿إِنَّ اللَّهَ تَوَّابٌ رَّحِيمٌ﴾"],"reason":2},{"type":"essay","q":"اكتب ثلاث نصائح لزميل لك ليتجنب الغيبة في المدرسة.","model":"أمثلة: يحفظ لسانه ويقول خيرًا أو يصمت، ويغيّر الموضوع بلطف إذا بدأ أحد يغتاب، ويدافع عن الزميل الغائب أو يغادر المجلس. وتُقبل أي نصائح صحيحة."}]}},
  {"id":"g9-islamic-1-u1-1","grade":"g9","subject":"islamic","term":1,"unit":1,"no":1,"title":"المكيّ والمدنيّ (علوم القرآن)","summary":"شرح متحرك بـ SVG لدرس المكيّ والمدنيّ (علوم القرآن) للصف التاسع (سلطنة عُمان)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.","page":"lesson-makki-and-madani.html","video":"","pdf":"","notes":["المكي: ما نزل قبل الهجرة؛ والمدني: ما نزل بعد الهجرة وإن نزل بمكة.","ضوابط المكي: وجود «كلّا»، سجدة تلاوة، «يا أيها الناس»، قصر الآيات، والتركيز على التوحيد والعقيدة.","ضوابط المدني: تفصيل الفرائض والحدود، ذكر المنافقين، طول الآيات، والخطاب بـ«يا أيها الذين آمنوا».","فوائد معرفته: فهم تدرّج التشريع، والناسخ والمنسوخ، وتتبّع السيرة النبوية."],"exercises":["قارن بين القرآن المكي والمدني من حيث التعريف والأسلوب والموضوعات.","علّل: تُعد الآيات التي نزلت في حجة الوداع بمكة من القرآن المدني.","اذكر ثلاث فوائد لدراسة علم المكي والمدني."],"levels":{"easy":[{"type":"mcq","q":"القرآن المكي على التعريف الراجح هو ما نزل:","options":["بعد وفاة النبي ﷺ","بعد الهجرة في مكة","قبل هجرة النبي ﷺ","في المدينة المنورة"],"answer":2,"why":"المعيار الراجح زمني: قبل الهجرة مكي."},{"type":"mcq","q":"من أبرز علامات السور المكية ورود لفظ:","options":["ذكر المنافقين","أحكام الجهاد","أحكام المواريث التفصيلية","«كلّا»"],"answer":3,"why":"وردت «كلّا» في السور المكية فقط."},{"type":"mcq","q":"يتميّز أسلوب السور المدنية عادةً بـ:","options":["طول الآيات والتفصيل في الأحكام","ورود لفظ كلّا","خلوّها من الأحكام","قصر الآيات جدًّا"],"answer":0,"why":"المدني يفصّل التشريعات بآيات طويلة واضحة."},{"type":"mcq","q":"العلم الذي يبحث في المكي والمدني يُعد من فروع:","options":["علم النحو فقط","علوم القرآن","علم الأحياء","علم الفلك"],"answer":1,"why":"المكي والمدني من أهم مباحث علوم القرآن."}],"medium":[{"type":"mcq","q":"نزلت آية ﴿اليوم أكملت لكم دينكم﴾ في عرفة بمكة في حجة الوداع؛ فتُصنّف:","options":["مكيةً لأنها في مكة","منسوخة","مدنيةً لأنها نزلت بعد الهجرة","ليست مكية ولا مدنية"],"answer":2,"why":"بالمعيار الزمني المعتمد: ما نزل بعد الهجرة مدني وإن نزل بمكة."},{"type":"mcq","q":"ما الحكمة من تركيز القرآن المكي على التوحيد والعقيدة قبل التشريعات التفصيلية؟","options":["لأسباب لغوية فقط","لأن أهل مكة كانوا يعرفون الأحكام كلها","لعدم وجود أحكام في الإسلام","لأن رسوخ الإيمان في القلب يهيّئ النفس لتقبّل الأحكام والالتزام بها طوعًا"],"answer":3,"why":"التدرّج الحكيم يبني العقيدة أولًا ثم يشرّع الأحكام."},{"type":"mcq","q":"أي سورة مما يلي «مدنية» رغم بدئها بحروف مقطّعة؟","options":["سورة البقرة وآل عمران","سورة ق","سورة ص","سورة يس"],"answer":0,"why":"البقرة وآل عمران استثناء مدني لقاعدة الحروف المقطعة."},{"type":"tfr","q":"كل سورة فيها سجدة تلاوة فهي سورة مكية.","answer":true,"reasons":["وهذا من الضوابط الأغلبية المشهورة التي استقرأها العلماء في القرآن","لأن السجدات في المدني فقط","لأن السجدات في البقرة"],"reason":0},{"type":"tfr","q":"لا فائدة عملية من معرفة المكي والمدني سوى معرفة أسماء السور.","answer":false,"reasons":["يستخدم للعدّ فقط","بل له فوائد عظيمة كمعرفة الناسخ والمنسوخ وفهم تدرّج التشريع وتفسير الآيات بسياقها","ليس له أي فائدة"],"reason":1},{"type":"essay","q":"قارن بين المكي والمدني من حيث: الموضوع الرئيس، طول الآيات، ومثالين لكل منهما.","model":"المكي: التوحيد والعقيدة واليوم الآخر، آيات قصيرة قوية (مثل الإخلاص والمدثر). المدني: التشريعات والمعاملات وبناء المجتمع، آيات طويلة مفصّلة (مثل البقرة والمائدة)."},{"type":"essay","q":"كيف يستفيد الداعية والمعلم من منهج القرآن في التدرّج بين المكي والمدني؟","model":"يتعلّم البدء بالأصول الكلية والقيم الكبرى ومخاطبة العقل والقلب بالرفق، ثم التدرّج في التفاصيل العملية حسب حال المخاطبين."}],"hard":[{"type":"mcq","q":"سورة العنكبوت مكية، ومع ذلك ورد فيها ذكر المنافقين في بدايتها؛ فماذا يدل ذلك؟","options":["أن الضوابط غير مفيدة","أن ضابط ذكر المنافقين ضابط أغلبي له استثناء (وهو أوائل سورة العنكبوت)","أن سورة العنكبوت مدنية بالكامل","أنه لا توجد ضوابط أصلًا"],"answer":1,"why":"ضوابط المكي والمدني أغلبية وقد تستثنى آيات محددة نقلًا عن الصحابة."},{"type":"mcq","q":"لماذا يُعد التعريف «الزماني» للمكي والمدني أدقّ من التعريف «المكاني»؟","options":["لأنه أسهل في الحفظ فقط","لأنه يستبعد الآيات في مكة","لأنه يحصر جميع آيات القرآن دون استثناء (حتى ما نزل في السفر كغزوة تبوك أو بدر)","لأنه لا يعتمد على الهجرة"],"answer":2,"why":"التعريف المكاني يترك الآيات التي نزلت في الأسفار دون تصنيف."},{"type":"mcq","q":"عند وجود آيتين ظاهرهما التعارض في حكم واحد، كيف يفيدنا علم المكي والمدني؟","options":["نأخذ بالمكية دائمًا","نترك الآيتين معًا","نأخذ بالأقصر","نعرف أن الآية المدنية المتأخرة هي الناسخة للمكية المتقدمة عند ثبوت النسخ"],"answer":3,"why":"معرفة تاريخ النزول أساس باب الناسخ والمنسوخ."},{"type":"mcq","q":"كثرة القسم بأشياء كونية (والشمس، والليل، والتين) من أبرز السمات الأسلوبية للقرآن:","options":["المكي","كتب الفقه","المدني فقط","الأمثال فقط"],"answer":0,"why":"يكثر القسم الكوني في المكي لإثبات قدرة الله والبعث."},{"type":"tfr","q":"يمكن أن تحتوي السورة المكية على بضع آيات مدنية والعكس، وتُسمى السورة بحسب أغلب آياتها أو بدايتها.","answer":true,"reasons":["كل سورة نزلت دفعة واحدة","لا يمكن اجتماع آية مدنية في سورة مكية أبدًا","فقد نقل الصحابة نزول بعض الآيات المدنية وإلحاقها بسور مكية بوحي وتوقيف"],"reason":2},{"type":"tfr","q":"وردت عبارة «يا أيها الناس» في القرآن المكي بكثرة لأن الخطاب كان موجهًا للبشرية كلها بالدعوة للتوحيد.","answer":true,"reasons":["بينما كثر «يا أيها الذين آمنوا» في المدني لتوجيه الأوامر الشرعية للمؤمنين","لأنها خاصة بالمدينة فقط","لأن أهل مكة لم يكونوا ناسًا"],"reason":0},{"type":"tfr","q":"معرفة المكي والمدني تُغني المفسّر عن الرجوع إلى روايات الصحابة.","answer":false,"reasons":["لا دور للصحابة","بل تعتمد معرفته أصلًا على النقل الصحيح عن الصحابة الذين شهدوا التنزيل","القياس وحده يكفي دائمًا"],"reason":1},{"type":"essay","q":"علّل: لماذا اهتمّ علماء الإسلام بتوثيق أماكن وأوقات نزول الآيات القرآنية بهذه الدقة الفائقة؟","model":"لصون القرآن وفهم معانيه في سياقها الصحيح، ومعرفة تدرج التشريع، وتمييز الناسخ والمنسوخ، والوقوف على حكمة الله في تربية الأمة."},{"type":"essay","q":"بيّن أثر اختلاف حال المخاطبين في مكة والمدينة على أسلوب الخطاب القرآني.","model":"في مكة واجه القرآن مكذبين فجاءت الآيات قصيرة قوية الحجة مؤثرة بالوعد والوعيد؛ وفي المدينة خاطب مؤمنين مستقرين فجاءت الآيات طويلة هادئة مفصّلة للأحكام والمعاملات."},{"type":"essay","q":"اذكر ثلاثة ضوابط للسور المكية وضابطين للسور المدنية.","model":"المكي: ورود «كلّا»، وجود سجدة تلاوة، افتتاحها بالحروف المقطعة (عدا البقرة وآل عمران). المدني: تفصيل الفرائض والحدود، ذكر المنافقين (عدا العنكبوت)."}]}},
  {"id":"g9-islamic-1-u1-2","grade":"g9","subject":"islamic","term":1,"unit":1,"no":2,"title":"سورة آل عمران (١٤–١٧) — تفسير","summary":"شرح متحرك بـ SVG لدرس سورة آل عمران (١٤–١٧) — تفسير للصف التاسع (سلطنة عُمان)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.","page":"lesson-surah-al-imran-14-17.html","video":"","pdf":"","notes":["ذكرت الآية ١٤ ست شهوات دنيوية زُيّنت للناس، وبيّنت أنها متاع زائل مقارنةً بحسن المآب عند الله.","نعيم المتقين في الآية ١٥: جنات تجري من تحتها الأنهار خالدين فيها، أزواج مطهرة، ورضوان من الله.","صفات المتقين الخمس في الآية ١٧: الصابرين، الصادقين، القانتين، المنفقين، والمستغفرين بالأسحار.","الإسلام لا يحرّم الطيبات الحلال، لكنه يوازن بين الدنيا والآخرة ويجعل الآخرة هي الغاية."],"exercises":["اذكر صفات المتقين الخمس الواردة في الآية ١٧ مع شرح كل صفة باختصار.","ما معنى: القناطير المقنطرة، الخيل المسوّمة، حسن المآب؟","كيف تطبّق التوازن بين الدنيا والآخرة في حياتك كطالب؟"],"levels":{"easy":[{"type":"mcq","q":"معنى «القناطير المقنطرة» في الآية ١٤ هو:","options":["الأراضي الزراعية","الأموال الكثيرة المتراكمة","الجسور الحجرية","السفن البحرية"],"answer":1,"why":"القنطار مقدار كبير من المال، والمقنطرة أي المتراكمة الكثيرة."},{"type":"mcq","q":"معنى «الأسحار» في الآية ١٧ هو:","options":["وقت الغروب","أول المساء","آخر الليل قبيل الفجر","منتصف النهار"],"answer":2,"why":"السحر آخر الليل قبيل الفجر."},{"type":"mcq","q":"معنى «الحرث» في الآية ١٤ هو:","options":["الخيل السريعة","البيوت","الذهب والفضة","الزرع والأرض الزراعية"],"answer":3,"why":"الحرث يطلق على الزراعة والمزارع."},{"type":"mcq","q":"من صفات المتقين في الآية ١٧:","options":["الصابرين والصادقين والقانتين والمنفقين والمستغفرين بالأسحار","المتكبرين فقط","التاركين للعمل","المنشغلين بالدنيا وحدها"],"answer":0,"why":"هذه هي الصفات الخمس المذكورة في الآية ١٧."}],"medium":[{"type":"mcq","q":"لماذا قدّمت الآية ١٧ «الصبر» على سائر صفات المتقين؟","options":["لأنه خاص بالمرض فقط","لأن الصبر أساس الثبات على الطاعات وترك المعاصي والتحمل في كل الأعمال","لأنه آخر صفة","لأنه أسهل صفة"],"answer":1,"why":"بدون الصبر لا يثبت الإنسان على الصدق والقنوت والإنفاق."},{"type":"mcq","q":"ما دلالة وصف نعيم الدنيا بـ«متاع» ووصف نعيم الجنة بـ«خالدين فيها»؟","options":["لا فرق بينهما","كلاهما زائل","متاع الدنيا مؤقت زائل بينما نعيم الآخرة دائم لا ينقطع","الدنيا أدوم من الآخرة"],"answer":2,"why":"المقارنة تبرز عظيم الفرق بين الفاني والباقي."},{"type":"mcq","q":"في الآية ١٦ ﴿ربنا إننا آمنا فاغفر لنا ذنوبنا﴾، بمَ توسّل المتقون إلى الله؟","options":["بأنسابهم","بمراكبهم","بأموالهم","بإيمانهم بالله تعالى"],"answer":3,"why":"التوسّل بالإيمان والعمل الصالح من آداب الدعاء."},{"type":"tfr","q":"تحرّم الآية ١٤ من سورة آل عمران امتلاك المال والأراضي والانتفاع بالطيبات الحلال.","answer":false,"reasons":["لأن الزراعة محرمة","لأن المال حرام مطلقًا","بل تبيّن أنها فطرة مباحة في حدود الحلال، وتحذّر من التعلّق بها ونسيان الآخرة"],"reason":2},{"type":"tfr","q":"ختم صفات المتقين بالاستغفار بالأسحار يدل على تواضع المؤمن وعدم اغتراره بطاعته.","answer":true,"reasons":["فبعد الصبر والصدق والإنفاق يستغفر الله لقصوره وافتقاره لرحمته","لأنهم لم يعملوا أي خير","لأن الاستغفار في النهار ممنوع"],"reason":0},{"type":"essay","q":"قارن بين متاع الدنيا ونعيم الآخرة كما ورد في الآيتين ١٤ و١٥ من سورة آل عمران.","model":"متاع الدنيا زائل ناقص يزول بالموت أو تغير الأحوال، أما نعيم الآخرة فدائم خالد فيه جنات وأنهار وأزواج مطهرة وأعظمه رضوان الله تعالى."},{"type":"essay","q":"اذكر ثلاثة أنواع للصبر يتحلّى بها طالب الصف التاسع في يومه.","model":"١) الصبر على الطاعة (كالقيام لصلاة الفجر). ٢) الصبر عن المعصية (كترك الغش والكذب). ٣) الصبر على المشقة والأقدار (كالاجتهاد في الدراسة والصبر عند المرض)."}],"hard":[{"type":"mcq","q":"كيف يرتبط «الإنفاق في سبيل الله» (والمنفقين) بالآية ١٤ التي ذكرت حب المال؟","options":["الإنفاق دليل عملي على أن حب الله والآخرة في قلب المؤمن أقوى من حب المال","المال لا يُنفق منه","لا علاقة بينهما","الإنفاق يمنع الكسب"],"answer":0,"why":"بذل المال المحبوب للنفس يبرهن صدق الإيمان والتقوى."},{"type":"mcq","q":"ما المقصود بـ«الخيل المسوّمة» في الآية ١٤؟","options":["الجمال فقط","الخيل الحسنة ذات العلامات المميزة أو المعدّة للركوب والجهاد والزينة","السفن","الخيل الضعيفة"],"answer":1,"why":"المسوّمة أي ذات العلامة المميزة لحسنها أو رعيها."},{"type":"mcq","q":"تقديم الإيمان ثم طلب المغفرة ثم الوقاية من النار في الآية ١٦ يُعلّمنا:","options":["الاتكال بلا عمل","الاكتفاء بالقول فقط","الجمع بين الرجاء في رحمة الله والخوف من عذابه مع العمل الصالح","اليأس من المغفرة"],"answer":2,"why":"التوازن بين الخوف والرجاء منهج القرآن في تربية المؤمن."},{"type":"mcq","q":"أي سلوك يطبّق صفة «الصادقين» في سورة آل عمران داخل المدرسة؟","options":["إخفاء الحقائق","تبرير الغش","المبالغة في المدح","الوفاء بالوعد والأمانة في الاختبار والصدق في الحديث والاعتراف بالخطأ"],"answer":3,"why":"الصدق يشمل القول والعمل والنية."},{"type":"tfr","q":"قوله تعالى ﴿والله بصير بالعباد﴾ في ختام الآية ١٥ يبعث في نفس المؤمن المراقبة الذاتية في السر والعلن.","answer":true,"reasons":["لأن الله لا يرى إلا العلن","لأن استشعار رؤية الله وعلمه بحال العباد يدفع للإخلاص والبعد عن الرياء","لا أثر له في السلوك"],"reason":1},{"type":"tfr","q":"تقتصر صفة «القنوت» في الآية ١٧ على دعاء القنوت في صلاة الوتر فقط.","answer":false,"reasons":["تعني الصمت فقط","نعم تقتصر على الوتر فقط","القنوت في الآية أوسع، ويعني دوام الطاعة والخشوع والانقياد لأوامر الله في كل العبادات"],"reason":2},{"type":"tfr","q":"السعي في كسب الرزق الحلال وإعمار الأرض يتوافق تمامًا مع توجيهات الآيات إذا لم يُلهِ عن طاعة الله.","answer":true,"reasons":["فقد أمر الإسلام بالسعي في الأرض مع حفظ التوازن وابتغاء الآخرة","العمل يفسد التقوى","الإسلام يمنع التجارة"],"reason":0},{"type":"essay","q":"استنبط ثلاث قيم تربوية من الآيات (١٤–١٧) من سورة آل عمران وكيفية تطبيقها في المجتمع العُماني.","model":"١) الاعتدال وعدم الإسراف في المظاهر. ٢) التكافل والإنفاق على المحتاجين. ٣) الصدق والأمانة والصبر في طلب العلم والعمل."},{"type":"essay","q":"لماذا خصّ الله «وقت السحر» بالاستغفار في الآية ١٧؟","model":"لأنه وقت الهدوء وصفاء النفس وبعدها عن الرياء، وقد وردت الأحاديث بفضل الدعاء والاستغفار في الثلث الأخير من الليل."},{"type":"essay","q":"فسّر كيف يكون «رضوان الله» أعظم من سائر نعيم الجنة المادي.","model":"لأن رضا الخالق سبحانه عن عبده هو الغاية العظمى وسر السعادة الروحية المطلقة والأمان الدائم في الجنة."}]}},
  {"id":"g9-islamic-1-u1-3","grade":"g9","subject":"islamic","term":1,"unit":1,"no":3,"title":"الإجمال في طلب الدُّنيا (حديث شريف)","summary":"شرح متحرك بـ SVG لدرس الإجمال في طلب الدُّنيا (حديث شريف) للصف التاسع (سلطنة عُمان)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.","page":"lesson-moderation-seeking-provision.html","video":"","pdf":"","notes":["الحديث عن جابر بن عبد الله: «اتقوا الله وأجملوا في الطلب، فإن نفسًا لن تموت حتى تستوفي رزقها وإن أبطأ عنها... خذوا ما حلّ ودعوا ما حرم».","الإجمال في الطلب: الاعتدال في السعي للرزق بطرق مشروعة حلال دون جشع أو غش.","اليقين بأن الرزق مقدّر يورث القناعة ويبعد عن الحرام حتى لو تأخّر الرزق.","الإجمال لا يعني الكسل (التواكل)، بل الأخذ بالأسباب بأمانة (التوكل)."],"exercises":["اشرح معنى قوله ﷺ: «فإن نفسًا لن تموت حتى تستوفي رزقها وإن أبطأ عنها».","اذكر ثلاث ثمرات للإجمال في الطلب على الفرد والمجتمع.","قارن بين التوكّل والتواكل بمثال من حياة الطالب."],"levels":{"easy":[{"type":"mcq","q":"راوي حديث «الإجمال في طلب الدنيا» هو الصحابي الجليل:","options":["جابر بن عبد الله رضي الله عنهما","سعد بن معاذ","بلال بن رباح","خالد بن الوليد"],"answer":0,"why":"روى الحديث الصحابي الجليل جابر بن عبد الله."},{"type":"mcq","q":"معنى «تستوفي رزقها» في الحديث الشريف:","options":["تترك العمل","تأخذ نصيبها المقدّر من الرزق كاملًا","تبيع ممتلكاتها","تسافر بعيدًا"],"answer":1,"why":"الاستيفاء يعني أخذ الشيء كاملًا غير منقوص."},{"type":"mcq","q":"أي سلوك يتعارض مع «الإجمال في الطلب»؟","options":["إتقان العمل بأمانة","الادخار المعتدل","الغش في البيع لزيادة الربح سريعًا","الرضا بما قسم الله"],"answer":2,"why":"الغش كسب محرم يناقض «خذوا ما حلّ ودعوا ما حرم»."},{"type":"mcq","q":"الاعتماد على الله مع الأخذ بالأسباب والعمل الجاد يُسمّى:","options":["اليأس","الجشع","التواكل","التوكّل"],"answer":3,"why":"التوكّل يجمع بين ثقة القلب بالله والعمل بالأسباب."}],"medium":[{"type":"mcq","q":"ما السبب الذي ذَكَره الحديث ليطمئن الناس فلا يقعوا في الحرام عند تأخر الرزق؟","options":["أن النفس لن تموت حتى تستوفي رزقها المقدّر كاملًا","أن الدنيا بلا أسباب","أن العمل ممنوع","أن المال غير مهم"],"answer":0,"why":"اليقين باستيفاء الرزق يمنع استعجاله بالحرام."},{"type":"mcq","q":"كيف يرتبط الكسب الحلال بإجابة الدعاء؟","options":["الحرام يعجّل الدعاء","إطابة المطعم والمكسب من أعظم أسباب قبول الدعاء، وأكل الحرام يمنع الإجابة","لا علاقة بينهما","الدعاء لا يحتاج حلالًا"],"answer":1,"why":"في الحديث الشريف: «أطب مطعمك تكن مستجاب الدعوة»."},{"type":"mcq","q":"طالب يذاكر بجد ويستعين بالله، وآخر يترك المذاكرة ويقول «رزقي سيجعلني أنجح». الأول والثاني يمثّلان:","options":["كلاهما توكل","التواكل ثم التوكل","التوكل ثم التواكل","كلاهما تواكل"],"answer":2,"why":"الاجتهاد مع الاستعانة بالله توكّل، وترك الأسباب تواكل."},{"type":"tfr","q":"يدعو حديث «الإجمال في طلب الدنيا» إلى ترك التجارة والعمل والتفرّغ للجلوس فقط.","answer":false,"reasons":["ينهى عن التجارة","بل يأمر بالطلب والسعي المعتدل الحلال مع تقوى الله والقناعة","نعم ينهى عن العمل"],"reason":1},{"type":"tfr","q":"من صور الإجمال في الطلب ألا يشغلك السعي للمال عن أداء الفرائض وحقوق الأسرة.","answer":true,"reasons":["لا علاقة بالأسرة","المال مقدّم على الصلاة","فالاعتدال يحفظ التوازن بين حق الله وحق النفس والأسرة والعمل"],"reason":2},{"type":"essay","q":"اذكر أربعة آثار إيجابية لتطبيق «الإجمال في الطلب» في السوق والمجتمع.","model":"١) اختفاء الغش والاحتكار والرشوة. ٢) شيوع الأمانة والثقة في المعاملات. ٣) التكافل والبركة في الأموال. ٤) قلة النزاعات والحسد بين الناس."},{"type":"essay","q":"كيف تعالج شعور القلق من المستقبل والرزق في ضوء هذا الحديث الشريف؟","model":"ببذل الجهد الشريف وتطوير المهارات (الأخذ بالأسباب) مع اليقين بأن الرزق بيد الله ولن تفوتني نعمة كتبها الله لي."}],"hard":[{"type":"mcq","q":"لماذا قرن النبي ﷺ «التقوى» بالإجمال في الطلب في قوله «اتقوا الله وأجملوا في الطلب»؟","options":["لأن التقوى للعبادة فقط","للسجع فقط","لأنهما متضادان","لأن التقوى هي الوازع الداخلي الذي يضبط النفس عند إغراء المال الحرام ويدفع للالتزام بالحلال"],"answer":3,"why":"تقوى الله ومراقبته هي الحارس الحقيقي للسلوك المالي."},{"type":"mcq","q":"ما الأثر النفسي على شخص يركض وراء المال بكل وسيلة مشروعة وغير مشروعة؟","options":["القلق الدائم وعدم الشبع وفقدان البركة وراحة البال","زيادة البركة","الطمأنينة الدائمة","محبة جميع الناس"],"answer":0,"why":"الجشع يورث القلق وفقدان السكينة مهما كثر المال."},{"type":"mcq","q":"تاجر يرفض بيع بضاعة منتهية الصلاحية رغم أنها تدرّ عليه ربحًا كبيرًا، يُعد مثالًا عمليًا على:","options":["التواكل","قوله ﷺ: «خذوا ما حلّ ودعوا ما حرم»","اليأس","البخل"],"answer":1,"why":"ترك الربح الحرام طاعةً لله وحفظًا لصحة الناس هو عين الإجمال."},{"type":"mcq","q":"أي عبارة تلخّص علاقة المسلم بالمال وفق هذا الحديث؟","options":["يكره المال ويترك العمل","ينفقه في الإسراف فقط","يسعى في كسبه بالحلال باعتدال، ويؤدي حقه، ولا يستعبده الطمع","يجمع المال من أي مصدر"],"answer":2,"why":"هذا هو المنهج الإسلامي الوسطي المتوازن."},{"type":"tfr","q":"الغش في الامتحانات للحصول على شهادة ووظيفة لاحقًا يخالف مبدأ «الإجمال في الطلب».","answer":true,"reasons":["لأنه سلوك محرم يعتدي على حقوق الآخرين ويفسد أصل الكسب","لأن الغش حلال","لأن الامتحان ليس له علاقة بالرزق"],"reason":0},{"type":"tfr","q":"القناعة تعني الرضا بما قسم الله بعد بذل الجهد المشروع، لا الرضا بالكسل.","answer":true,"reasons":["القناعة تعني ترك العمل","فالمؤمن القنوع يعمل بإتقان ويرضى بالنتيجة التي يقدّرها الله له","القناعة تمنع الطموح"],"reason":1},{"type":"tfr","q":"إذا تأخّر رزق المسلم فهذا دليل دائم على غضب الله عليه.","answer":false,"reasons":["الرزق لا يتأخر أبدًا","نعم دليل غضب دائمًا","قد يؤخّر الله الرزق لحكمة وابتلاء ورفعة درجات، كما قال ﷺ «وإن أبطأ عنها»"],"reason":2},{"type":"essay","q":"قارن بين «الطموح المشروع» و«الطمع المذموم» في ضوء حديث الإجمال في طلب الدنيا.","model":"الطموح المشروع: سعي للتفوق والرزق بوسائل حلال مع الرضا بالقدر ومراعاة حقوق الآخرين. الطمع المذموم: جشع لا يشبع يدفع للغش أو الظلم أو إهمال الواجبات الدينية والأسرية."},{"type":"essay","q":"اكتب نصيحةً لزميل يشعر بالإحباط لأن مشروعه الصغير لم يحقق ربحًا سريعًا، مستشهدًا بالحديث.","model":"ذكّره بالحديث الشريف بأن الرزق قد يبطئ لحكمة، وأن عليه الاستمرار بالتطوير والأخذ بالأسباب مع تقوى الله وتحري الحلال، فسيأتيه رزقه المقدّر في وقته المبارك."},{"type":"essay","q":"بيّن كيف يحفظ حديث «الإجمال في الطلب» كرامة الإنسان وعزّة نفسه.","model":"لأنه يمنع الإنسان من التذلّل للناس أو التنازل عن مبادئه وأخلاقه طمعًا في المال، ويربط قلبه بالله الرزّاق وحده."}]}},
  {"id":"g9-islamic-1-u1-4","grade":"g9","subject":"islamic","term":1,"unit":1,"no":4,"title":"المعطي المانع (عقيدة)","summary":"شرح متحرك بـ SVG لدرس المعطي المانع (عقيدة) للصف التاسع (سلطنة عُمان)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.","page":"lesson-al-muti-al-mani.html","video":"","pdf":"","notes":["المعطي: الذي يفيض النعم على خلقه بفضله (عطاء عام لجميع الخلق، وخاص للمؤمنين كالهداية).","المانع: الذي يمنع العطاء بحكمته ويحمي عباده من الشرور، ويُذكر مقترنًا بالمعطي.","الذكر النبوي بعد الصلاة: «اللهم لا مانع لما أعطيت، ولا معطي لما منعت، ولا ينفع ذا الجدّ منك الجدّ».","آثار الإيمان بهما: التوحيد وعزة النفس، الشكر والتواضع عند العطاء، والرضا وحسن الظن وترك الحسد عند المنع."],"exercises":["اشرح المعنيين لاسم الله «المانع» وسبب اقترانه بـ«المعطي».","اذكر ثلاث حِكَم قد تكون وراء منع الله شيئًا يحبه العبد.","كيف يحرّر الإيمان بـ«المعطي المانع» المسلم من داء الحسد؟"],"levels":{"easy":[{"type":"mcq","q":"معنى «الجدّ» في قوله ﷺ: «ولا ينفع ذا الجدّ منك الجدّ» هو:","options":["السفر الطويل","والد الأب","الاجتهاد في الدراسة","الغنى والحظ والسلطان"],"answer":3,"why":"ذا الجدّ هو صاحب الغنى والحظ الدنيوي."},{"type":"mcq","q":"مثال على «عطاء الله الخاص» للمؤمنين:","options":["الهداية للإيمان والتوفيق للطاعة","المطر","شروق الشمس","الهواء والماء"],"answer":0,"why":"الهداية والإيمان عطاء خاص، بينما الهواء والشمس عطاء عام."},{"type":"mcq","q":"من معاني «المانع» سبحانه:","options":["عدم السماع","حماية عباده ومنع الشرور عنهم، ومنع العطاء بحكمته","العجز عن العطاء","البخل حاشاه"],"answer":1,"why":"المنع الإلهي كله حكمة ورحمة وحماية."},{"type":"mcq","q":"يُقال الذكر «اللهم لا مانع لما أعطيت ولا معطي لما منعت»:","options":["في السجود فقط","عند النوم فقط","بعد الصلوات المكتوبة","في الركوع فقط"],"answer":2,"why":"هو من الأذكار الثابتة دبر الصلوات المكتوبة."}],"medium":[{"type":"mcq","q":"قد يكون منع الله العبد من مال أو منصب معين «نعمةً خفيةً» لأن:","options":["الله لا يحب أن يعطي أحدًا","الأسباب غير مطلوبة","الدعاء لا يفيد","الله يعلم أن ذلك قد يضرّ دينه أو دنياه فيحميه منه أو يعوّضه خيرًا منه"],"answer":3,"why":"الله أرحم بعبده وأعلم بما يصلحه في دينه ودنياه."},{"type":"mcq","q":"أثر الإيمان بالمعطي المانع في تعامل المؤمن مع أصحاب النفوذ والغنى هو:","options":["عزة النفس وعدم التذلل لأن العطاء الحقيقي بيد الله وحده","الإساءة إليهم","التذلل والخوف منهم","حسدهم الدائم"],"answer":0,"why":"معرفة أن المعطي هو الله تورث عزة النفس والتوكل."},{"type":"mcq","q":"ما الموقف الصحيح لطالب لم يُقبل في فريق أو مسابقة كان يتمناها؟","options":["اليأس وترك الأنشطة","الرضا بقضاء الله وحسن الظن بحكمته والاستمرار في تطوير نفسه","حسد الفائزين","الاعتراض على القدر"],"answer":1,"why":"المؤمن يجمع بين الرضا بالقدر والأخذ بالأسباب."},{"type":"tfr","q":"ينقص ملك الله وخزائنه كلما أعطى عباده من النعم والرزق.","answer":false,"reasons":["خزائن الله ملأى لا تنقصها النفقة أبدًا، فهو الغني الكريم","يعطي فئة واحدة فقط","نعم تنقص قليلًا"],"reason":0},{"type":"tfr","q":"حسد الآخرين على نعمهم يناقض كمال الإيمان بحكمة الله المعطي المانع.","answer":true,"reasons":["لا علاقة له بالعقيدة","لأن الحاسد يعترض بقلبه على عدل الله وحكمته في توزيع عطائه","لأن الحسد محمود"],"reason":1},{"type":"essay","q":"قارن بين «العطاء العام» و«العطاء الخاص» لله تعالى مع مثالين لكل منهما.","model":"العطاء العام: يشمل جميع المخلوقات مؤمنها وكافرها مثل الحياة والرزق والصحة والشمس. العطاء الخاص: يختص به الله عباده المؤمنين مثل الهداية، الإيمان، العلم النافع، والجنة."},{"type":"essay","q":"اذكر أربعة آثار سلوكية لإيمانك بأن الله هو المعطي المانع.","model":"١) الشكر والتواضع عند النعمة. ٢) الرضا والصبر عند المنع. ٣) عزة النفس والتوجه لله وحده بالدعاء. ٤) سلامة الصدر وترك الحسد."}],"hard":[{"type":"mcq","q":"لماذا قال العلماء: «ربما أعطاك فمنعك، وربما منعك فأعطاك»؟","options":["لأن العطاء والمنع متساويان بلا حكمة","لأن المنع شر محض","لأن العطاء قد يكون فتنةً إذا أنسى العبد ربه، والمنع قد يكون نعمةً وحفظًا يقرب العبد من الله","لأن العطاء شر محض"],"answer":2,"why":"الحكمة الإلهية قد تجعل في المنع حفظًا ورفعةً للعبد."},{"type":"mcq","q":"كيف نوفّق بين أن الله هو «المعطي المانع» وبين وجوب «الأخذ بالأسباب»؟","options":["الأسباب وحدها تعطي دون الله","لا يمكن التوفيق","نترك الأسباب تمامًا","الأسباب مأمور بها شرعًا، لكنها لا تُنتج نفعًا إلا بإذن الله ومشيئته"],"answer":3,"why":"نأخذ بالأسباب طاعةً لله ونعلّق القلوب بالله المعطي وحده."},{"type":"mcq","q":"ما دلالة تكرار المسلم لـ«اللهم لا مانع لما أعطيت ولا معطي لما منعت» خمس مرات يوميًا بعد الصلوات؟","options":["تجديد التوحيد والرضا والطمأنينة في القلب طوال اليوم","مجرد عادة بلا معنى","الانعزال عن الناس","ترك العمل"],"answer":0,"why":"التكرار اليومي يرسّخ اليقين ويحصّن القلب من القلق والتعلق بغير الله."},{"type":"mcq","q":"أي سلوك يعكس شكر نعمة «العلم والتفوق» الذي أعطاك الله إياه؟","options":["ترك المذاكرة","التواضع ومساعدة الزملاء واستخدام العلم في نفع المجتمع","إخفاء الفائدة عن الزملاء","التفاخر والاستهزاء بالآخرين"],"answer":1,"why":"شكر النعمة يكون باستعمالها في الخير والتواضع."},{"type":"tfr","q":"لا يجوز للمسلم أن يدعو الله بقوله «يا مانع» منفردًا دون اقترانه بـ«يا معطي».","answer":true,"reasons":["لا يجوز ذكرهما أصلًا","يجوز إفراده دائمًا","لأن الكمال في اقترانهما معًا (المعطي المانع) دلالةً على الجمع بين الفضل والحكمة"],"reason":2},{"type":"tfr","q":"مواساة أخيك الذي فاته أمر يحبه بتذكيره بحكمة الله المعطي المانع من أثر هذا الدرس في حياتنا.","answer":true,"reasons":["فهو يبعث الأمل وحسن الظن بالله ويخفف الحزن","يمنع الدعاء","يزيد الحزن"],"reason":0},{"type":"tfr","q":"الابتلاء بالمنع دليل على أن الله لا يريد الخير بعبده.","answer":false,"reasons":["المؤمن لا يُبتلى بالمنع","كثيرًا ما يكون المنع لحفظ العبد أو تعويضه بخير منه أو رفع درجته في الآخرة","نعم دليل دائم"],"reason":1},{"type":"essay","q":"اشرح بمثال واقعي من حياة طالب كيف يمكن أن يكون «المنع» في ظاهر الأمر «عطاءً وحفظًا» في حقيقته.","model":"طالب أراد السفر في رحلة أو شراء شيء فتعذّر الأمر، ثم اكتشف لاحقًا وجود مشكلة أو خطر فيها أو وجد فرصةً تعليميةً أفضل في ذلك الوقت، فيحمد الله على حكمته."},{"type":"essay","q":"كيف يربط الذكر النبوي «اللهم لا مانع لما أعطيت...» بين العقيدة وبين الصحة النفسية للإنسان؟","model":"لأنه يزيل الخوف من الناس والقلق على المستقبل والحسد، ويملأ النفس رضا وسكينةً وثقةً بأن الأمر كله بيد الله الحكيم الرحيم."},{"type":"essay","q":"اذكر ثلاث نعم عظيمة أعطاك الله إياها وبيّن كيف تشكر الله على كل واحدة منها عمليًا.","model":"١) نعمة الإيمان: بالمحافظة على الصلاة والعمل الصالح. ٢) نعمة الصحة: بحفظها واستغلالها في الخير. ٣) نعمة العلم والمدرسة: بالاجتهاد والأمانة ومساعدة الآخرين."}]}},
  {"id":"g9-islamic-1-u1-5","grade":"g9","subject":"islamic","term":1,"unit":1,"no":5,"title":"صلح الحُديبية (سيرة)","summary":"شرح متحرك بـ SVG لدرس صلح الحُديبية (سيرة) للصف التاسع (سلطنة عُمان)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.","page":"lesson-treaty-of-hudaybiyyah.html","video":"","pdf":"","notes":["وقع صلح الحديبية في ذي القعدة سنة ٦ هـ عندما خرج النبي ﷺ في نحو ١٤٠٠ صحابي للعمرة.","بيعة الرضوان: بايع الصحابة تحت الشجرة على الثبات بعد إشاعة مقتل عثمان بن عفان رضي الله عنه.","أهم بنوده: هدنة ١٠ سنوات، العمرة العام القادم، حرية تحالف القبائل، وبند ردّ من جاء من قريش.","سُمّي فتحًا مبينًا لأنه حقّق اعتراف قريش، وأتاح مراسلة الملوك (ومنهم ملكا عُمان)، ونشر الإسلام سريعًا ومهّد لفتح مكة."],"exercises":["اذكر بنود صلح الحديبية الأربعة.","علّل تسمية القرآن الكريم لصلح الحديبية بـ«الفتح المبين».","ما الدرس المستفاد من مشورة أم المؤمنين أم سلمة رضي الله عنها يوم الحديبية؟"],"levels":{"easy":[{"type":"mcq","q":"السنة الهجرية التي وقع فيها صلح الحديبية هي:","options":["السنة الثالثة (٣ هـ)","السنة التاسعة (٩ هـ)","السنة السادسة (٦ هـ)","السنة الأولى (١ هـ)"],"answer":2,"why":"وقع صلح الحديبية عام ٦ هـ."},{"type":"mcq","q":"الصحابي الذي أرسله النبي ﷺ لمفاوضة قريش وأُشيع مقتله هو:","options":["زيد بن حارثة","أبو بكر الصديق","سعد بن أبي وقاص","عثمان بن عفان رضي الله عنه"],"answer":3,"why":"أُرسل عثمان لمكانته وعشيرته في مكة."},{"type":"mcq","q":"القبيلة التي دخلت في حلف النبي ﷺ وفق بنود صلح الحديبية هي:","options":["خزاعة","الروم","الفرس","بنو بكر"],"answer":0,"why":"دخلت خزاعة في حلف النبي ﷺ ودخلت بنو بكر في حلف قريش."},{"type":"mcq","q":"السورة القرآنية التي نزلت في طريق العودة من الحديبية وسمّته «فتحًا مبينًا» هي:","options":["سورة الفيل","سورة الفتح","سورة المسد","سورة الكوثر"],"answer":1,"why":"افتتحت بقوله تعالى: ﴿إنا فتحنا لك فتحًا مبينًا﴾."}],"medium":[{"type":"mcq","q":"مفاوض قريش الذي وقّع بنود صلح الحديبية مع النبي ﷺ هو:","options":["أبو جهل","أبو لهب","سهيل بن عمرو","أمية بن خلف"],"answer":2,"why":"أرسلت قريش سهيل بن عمرو لعقد الصلح."},{"type":"mcq","q":"ما دلالة أخذ النبي ﷺ بمشورة أم سلمة رضي الله عنها في الحديبية؟","options":["الاستبداد بالرأي","التسرع في القرار","إهمال رأي الصحابة","مبدأ الشورى وتقدير الإسلام لحكمة المرأة ورأيها السديد"],"answer":3,"why":"يؤكد تكريم الإسلام للمرأة وأهمية الشورى والقدوة العملية."},{"type":"mcq","q":"من أبرز نتائج صلح الحديبية على الدعوة خارج الجزيرة العربية:","options":["تفرّغ النبي ﷺ لمراسلة الملوك والحكام (ومنهم ملكا عُمان) ودعوتهم للإسلام","انقطاع التجارة","تراجع عدد المسلمين","توقف الدعوة عشر سنوات"],"answer":0,"why":"الأمن والهدنة فتحا آفاق الدعوة العالمية."},{"type":"tfr","q":"خرج النبي ﷺ وأصحابه في الحديبية عام ٦ هـ بقصد قتال قريش وفتح مكة عسكريًا.","answer":false,"reasons":["نعم خرجوا للحرب","خرجوا للتجارة فقط","بل خرجوا محرمين للعمرة وساقوا الهدي دون سلاح حرب"],"reason":2},{"type":"tfr","q":"دخل في الإسلام في السنتين اللتين تلتا صلح الحديبية أضعاف ما دخل فيه طوال ١٩ سنة قبل ذلك.","answer":true,"reasons":["بفضل أجواء السلم والأمن والحوار التي أتاحتها الهدنة","لأن الحرب استمرت","لأن الناس لم يسمعوا بالإسلام"],"reason":0},{"type":"essay","q":"اذكر ثلاث نتائج عظيمة لصلح الحديبية أثبتت بُعد نظر النبي ﷺ.","model":"١) اعتراف قريش بالدولة الإسلامية. ٢) انتشار الإسلام بسرعة هائلة في جو السلم والأمن. ٣) التفرغ لمراسلة الملوك ومنهم ملكا عُمان، ثم التمهيد لفتح مكة بعد نقض قريش للصلح."},{"type":"essay","q":"كيف طبّق النبي ﷺ مبدأ «الوفاء بالعهود» يوم الحديبية؟","model":"ردّ أبا جندل رضي الله عنه التزامًا ببند الاتفاق الذي أُبرم مع سهيل بن عمرو، مع تطمينه أن الله سيجعل له فرجًا ومخرجًا."}],"hard":[{"type":"mcq","q":"ما علاقة «صلح الحديبية» بإسلام أهل عُمان؟","options":["لم تكن هناك علاقة","أمن الهدنة أتاح للنبي ﷺ إرسال رسائله إلى الملوك والأمراء، ومنها رسالته إلى ملكَي عُمان جيفر وعبد ابني الجلندى","أُرسلت الرسالة قبل الهجرة","وقع الصلح في عُمان"],"answer":1,"why":"مراسلة ملوك العالم كانت من أهم ثمار السلم بعد الحديبية."},{"type":"mcq","q":"لماذا رضيت قريش لاحقًا بإلغاء البند الرابع (ردّ من جاء مسلمًا من قريش) من تلقاء نفسها؟","options":["لأنهم أسلموا فورًا","لأنهم نسوا البند","لأن المسلمين الذين رُدّوا تجمّعوا بقيادة أبي بصير على طريق تجارة قريش إلى الشام فاضطرت قريش لطلب إلغائه","لأن عشر سنوات انتهت"],"answer":2,"why":"أثبتت الأحداث صدق بشارة النبي ﷺ بأن الله سيجعل لهم فرجًا ومخرجًا."},{"type":"mcq","q":"تُعدّ صياغة بنود الحديبية وقبول حذف كلمة «رسول الله» عند الكتابة دليلًا على:","options":["الضعف العسكري","عدم أهمية الكتابة","التنازل عن العقيدة","المرونة القيادية في الشكليات مع الثبات على الأهداف الكبرى"],"answer":3,"why":"ثبات على الجوهر ومرونة في الشكليات لتحقيق المصلحة العليا."},{"type":"mcq","q":"ما السبب الذي أدى إلى «فتح مكة» في السنة الثامنة للهجرة رغم أن مدة الصلح كانت ١٠ سنوات؟","options":["نقض قريش للصلح بإعانتها بني بكر في الاعتداء على قبيلة خزاعة حليفة المسلمين","نقض المسلمين للصلح","انتهاء العشر سنوات","طلب سهيل بن عمرو"],"answer":0,"why":"نقض قريش للميثاق هو ما أبطل الصلح وأدى لفتح مكة."},{"type":"tfr","q":"تُثبت بيعة الرضوان أن السلام في الإسلام ينبع من قوة وثبات لا من ضعف واستسلام.","answer":true,"reasons":["لأن المسلمين كانوا خائفين","فقد بايع ١٤٠٠ صحابي على الثبات، مما دفع قريشًا نفسها لطلب الصلح","لأن قريشًا رفضت الصلح"],"reason":1},{"type":"tfr","q":"تعلّمنا سيرة الحديبية أن النظرة العاطفية السريعة قد تخالف المصلحة البعيدة التي يراها القائد الحكيم.","answer":true,"reasons":["لا فائدة من التريّث","العجلة دائمًا أصوب","فما ظنّه بعض الصحابة صعبًا في يومه تبيّن أنه أعظم فتح مبين بعدها بقليل"],"reason":2},{"type":"tfr","q":"استمرت هدنة صلح الحديبية عشر سنوات كاملةً دون أن تنقضها قريش.","answer":false,"reasons":["نقضتها قريش بعد نحو سنتين بإعانة بني بكر على خزاعة، فكان فتح مكة في السنة ٨ هـ","استمرت عشرين سنة","لم يُوقّع الصلح"],"reason":0},{"type":"essay","q":"قارن بين الموقف الظاهري لبعض الصحابة يوم الحديبية وبين النتائج الفعلية للصلح بعد سنتين.","model":"ظاهريًا ظنّوا أن العودة دون عمرة وبند الرد فيهما غبن؛ لكن فعليًا اعترفت قريش بالمسلمين، وانتشر الإسلام بأضعاف مضاعفة، وأسلم خالد بن الوليد وعمرو بن العاص، وتم فتح مكة."},{"type":"essay","q":"استخلص ثلاثة دروس قيادية وتربوية من صلح الحديبية يمكنك تطبيقها في حياتك المدرسية والعملية.","model":"١) الحوار والهدوء يحققان ما لا تحققه العجلة والغضب. ٢) الوفاء بالوعد والاتفاق قيمة لا تتجزأ. ٣) الشورى والقدوة العملية أسرع طريق للإقناع."},{"type":"essay","q":"علّل: لماذا أمر النبي ﷺ أصحابه بلبس الإحرام وسوق الهدي قبل التوجه لمكة عام ٦ هـ؟","model":"ليعلن للعرب وقريش بوضوح أنه قادم للعمرة وتعظيم البيت الحرام في الشهر الحرام وليس للقتال."}]}},
  {"id":"g9-islamic-1-u1-6","grade":"g9","subject":"islamic","term":1,"unit":1,"no":6,"title":"الأمن النفسيّ (قيم وأخلاق)","summary":"شرح متحرك بـ SVG لدرس الأمن النفسيّ (قيم وأخلاق) للصف التاسع (سلطنة عُمان)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.","page":"lesson-psychological-security.html","video":"","pdf":"","notes":["الأمن النفسي: طمأنينة القلب واستقرار النفس وتحرّرها من القلق والخوف المَرَضي.","مصادره في الإسلام: الإيمان والتوكل، ذكر الله والصلاة، الرضا بالقضاء والتفاؤل، والأسرة الدافئة والصحبة الصالحة.","مهدّداته: البعد عن الله، المعاصي، التنمر، والمقارنة المستمرة بالآخرين على وسائل التواصل.","ثمراته: التفوق الدراسي، والإبداع، والعلاقات الإيجابية، وتماسك المجتمع."],"exercises":["اذكر أربعة أسباب تعزّز الأمن النفسي لدى طالب الصف التاسع.","كيف تسهم في نشر الأمن النفسي داخل صفك المدرسي؟","استدل بآية قرآنية وحديث شريف على قيمة الأمن النفسي والطمأنينة."],"levels":{"easy":[{"type":"mcq","q":"أعظم مصدر لتحقيق طمأنينة القلب والأمن النفسي في الإسلام هو:","options":["التفاخر بالمظاهر","الإيمان بالله وذكره وحسن التوكل عليه","المقارنة بالآخرين","السهر الطويل"],"answer":1,"why":"قال تعالى: ﴿ألا بذكر الله تطمئن القلوب﴾."},{"type":"mcq","q":"قول النبي ﷺ «عجبًا لأمر المؤمن إن أمره كله خير» يغرس في النفس:","options":["الغضب الدائم","الحسد","الرضا والتفاؤل في السراء والضراء","اليأس والتشاؤم"],"answer":2,"why":"المؤمن بين شكر في السراء وصبر في الضراء وكلاهما خير له."},{"type":"mcq","q":"من أبرز مهدّدات الأمن النفسي في البيئة المدرسية:","options":["التعاون الدراسي","الكلمة الطيبة","احترام المعلم","التنمر والسخرية من الزملاء"],"answer":3,"why":"التنمر يؤذي مشاعر الزملاء ويسلبهم الشعور بالأمان."},{"type":"mcq","q":"من ثمرات الأمن النفسي على الطالب:","options":["زيادة التركيز والإبداع والتحصيل الدراسي","تشتّت الذهن","العزلة والقلق","ترك الهوايات"],"answer":0,"why":"النفس المطمئنة أقدر على التعلم والإبداع."}],"medium":[{"type":"mcq","q":"كيف تؤثّر «المقارنة المستمرة» بحياة الآخرين على مواقع التواصل في الأمن النفسي؟","options":["تقوي الصلة بالله","تولّد عدم الرضا والقلق لأن الناس يعرضون أجمل لحظاتهم فقط","تزيد القناعة دائمًا","تعالج التوتر"],"answer":1,"why":"القناعة وشكر النعم تحمي النفس من أذى المقارنات الزائفة."},{"type":"mcq","q":"قول النبي ﷺ: «المسلم من سلم المسلمون من لسانه ويده» يسهم في الأمن النفسي للمجتمع عبر:","options":["منع الحديث تمامًا","العزلة الاجتماعية","حفظ كرامة الناس ومشاعرهم ومنع الأذى اللفظي والجسدي","التنافس غير الشريف"],"answer":2,"why":"سلامة الناس من أذى اللسان واليد أساس الأمان الاجتماعي والنفسي."},{"type":"mcq","q":"إذا شعر طالب بضيق أو قلق مستمر بسبب ضغوط الدراسة، فأفضل خطوة مساندة بجانب الذكر والدعاء هي:","options":["السهر على الهاتف","ترك الدراسة","كتمان الأمر والانعزال التام","تنظيم وقته والتحدث بصراحة مع والديه أو الأخصائي الاجتماعي/النفسي بالمدرسة"],"answer":3,"why":"الجمع بين الصلة بالله وتنظيم الوقت والاستشارة الواعية يحقق التوازن."},{"type":"tfr","q":"تتحقّق السكينة والأمن النفسي بامتلاك المال الكثير وحده حتى مع البعد عن الله.","answer":false,"reasons":["الفقراء لا يملكون أمنًا نفسيًا","المال وسيلة لا تصنع الطمأنينة وحدها؛ فالأمن النفسي الحقيقي يبدأ بالإيمان وذكر الله والرضا","نعم المال يكفي وحده"],"reason":1},{"type":"tfr","q":"العمل الصالح ومساعدة المحتاجين يُدخلان السرور والطمأنينة إلى قلب المؤمن.","answer":true,"reasons":["العطاء يسبب القلق","لا أثر للعمل الصالح على النفس","فالعطاء يوسّع الصدر ويحقق قوله تعالى ﴿فلنحيينه حياة طيبة﴾"],"reason":2},{"type":"essay","q":"اذكر أربع وسائل عملية تساعدك على المحافظة على أمنك النفسي خلال أسبوع الامتحانات.","model":"١) المذاكرة المنظمة مبكرًا وأخذ قسط كافٍ من النوم. ٢) المحافظة على الصلاة والأذكار والتوكل على الله. ٣) تجنّب المقارنات المقلقة مع الآخرين. ٤) التفاؤل والرضا بالنتيجة بعد بذل الجهد."},{"type":"essay","q":"بيّن دور الأسرة في بناء الأمن النفسي للأبناء.","model":"بتوفير بيئة يسودها الحب والحوار الهادئ، والاستماع لمشكلات الأبناء دون سخرية، والتشجيع والقدوة الحسنة في الصلاة والذكر."}],"hard":[{"type":"mcq","q":"في قوله تعالى ﴿الذين آمنوا ولم يلبسوا إيمانهم بظلم أولئك لهم الأمن﴾، ما معنى «ولم يلبسوا إيمانهم بظلم»؟","options":["لم يخلطوا إيمانهم بالشرك والظلم، فأخلصوا التوحيد لله","لم يرتدوا ثيابًا جديدة","لم يعملوا في التجارة","لم يسافروا"],"answer":0,"why":"إخلاص التوحيد والعدل هما أساس الأمن الحقيقي في الدنيا والآخرة."},{"type":"mcq","q":"ما العلاقة بين «سلامة الصدر من الحقد والحسد» وبين «الأمن النفسي»؟","options":["الحقد يريح النفس","سلامة الصدر تريح القلب من التوتر والغضب وتقوّي العلاقات الإيجابية، فتعزّز الأمن النفسي","لا علاقة بينهما","سلامة الصدر ضعف"],"answer":1,"why":"تطهير القلب من الحقد والحسد مصدر مباشر للسكينة."},{"type":"mcq","q":"كيف يواجه المؤمن «الخطأ أو الإخفاق» دون أن يفقد أمنه النفسي؟","options":["بلوم الآخرين دائمًا","بإخفاء الخطأ بالكذب","بالتوبة والاستغفار والتعلّم من التجربة والبدء من جديد بروح متفائلة","باليأس وجلد الذات المستمر"],"answer":2,"why":"باب التوبة والتصحيح مفتوح دائمًا في الإسلام مما يبعث الأمل."},{"type":"mcq","q":"أي سلوك رقمي يحمي الأمن النفسي للمراهقين اليوم؟","options":["الدخول في جدالات مسيئة","ترك النوم لأجل الهاتف","قضاء ١٠ ساعات يوميًا في المقارنات","تحديد وقت معتدل للشاشات، ومتابعة المحتوى النافع، وحظر الحسابات المسيئة"],"answer":3,"why":"الاستخدام الواعي والمتوازن للتقنية يحمي الصحة النفسية."},{"type":"tfr","q":"الوقوع في المعاصي والإصرار عليها يولّد قلقًا داخليًا وشعورًا بعدم الأمان النفسي.","answer":true,"reasons":["بخلاف الاستقامة والتوبة التي تعيد للنفس صفاءها وطمأنينتها","المعاصي تجلب الطمأنينة","لا أثر للمعاصي على القلب"],"reason":0},{"type":"tfr","q":"الأمن النفسي للفرد ينعكس إيجابًا على استقرار المجتمع وأمنه العام.","answer":true,"reasons":["الأمن النفسي شأن فردي لا يؤثر في المجتمع","لأن الفرد المطمئن المتزن يكون بنّاءً ومتسامحًا ومبتعدًا عن العنف والانحراف","لا علاقة بين الفرد والمجتمع"],"reason":1},{"type":"tfr","q":"الشعور ببعض القلق الطبيعي قبل امتحان مهم يعني أن الإيمان ضعيف.","answer":false,"reasons":["المؤمن لا يشعر بأي خوف فطري","نعم يبطل الإيمان","القلق الطبيعي البسيط فطرة بشرية تدفع للاستعداد؛ والمذموم هو القلق المَرَضي أو اليأس"],"reason":2},{"type":"essay","q":"اقترح مبادرةً مدرسيةً بسيطةً لنشر «الأمن النفسي» بين طلاب مدرستك.","model":"مبادرة «الكلمة الطيبة» تتضمن ميثاقًا صفيًا لمنع التنمر، وصندوقًا لرسائل التشجيع الإيجابية بين الطلاب، وركنًا للتوعية بأذكار الصباح وإدارة ضغط الاختبارات."},{"type":"essay","q":"قارن بين نظرة المؤمن ونظرة غيره عند وقوع مصيبة أو خسارة مادية من حيث الأمن النفسي.","model":"المؤمن يصبر ويرضى ويحتسب الأجر ويؤمن بأن الله سيعوّضه خيرًا فيحافظ على توازنه؛ أما من غاب عنه الإيمان فيغلب عليه الجزع واليأس والاضطراب النفسي."},{"type":"essay","q":"لخّص في أربع نقاط كيف يحقق الإسلام التوازن بين «الأمن الروحي» و«الأمن الاجتماعي» لبناء الأمن النفسي.","model":"١) توثيق الصلة بالله بالإيمان والذكر. ٢) الرضا بالقدر والتفاؤل. ٣) بناء أسرة متحابة وصحبة صالحة. ٤) حماية كرامة الناس بمنع الغيبة والتنمر والظلم."}]}},
  {"id":"g9-islamic-1-u2-1","grade":"g9","subject":"islamic","term":1,"unit":2,"no":1,"title":"التقاء الساكنين (١) — تجويد","summary":"شرح متحرك بـ SVG لدرس التقاء الساكنين (١) — تجويد للصف التاسع (سلطنة عُمان)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.","page":"lesson-meeting-of-two-sakins-1.html","video":"","pdf":"","notes":["التقاء الساكنين: مجيء حرفين ساكنين متتاليين بلا فاصل متحرك.","التقاء الساكنين في كلمة واحدة جائز ومغتفر في حالتين: (١) وصلاً ووقفًا في المد اللازم (٦ حركات) مثل ﴿الضالين﴾، (٢) وقفًا فقط.","حالات الوقف فقط في كلمة: قبل الأخير حرف مد (العارض للسكون: ﴿نستعينْ﴾)، أو حرف لين (﴿خوفْ﴾)، أو حرف صحيح ساكن (﴿والعصرْ﴾)."],"exercises":["بيّن نوع التقاء الساكنين وحكمه في: ﴿الْحَاقَّةُ﴾، ﴿الرَّحِيمْ﴾ وقفًا، ﴿وَالْفَجْرْ﴾ وقفًا.","اشرح كيف التقى ساكنان في كلمة ﴿الضَّالِّينَ﴾.","ما الفرق بين التقاء الساكنين في ﴿الْحَاقَّةُ﴾ وفي ﴿الْقَدْرْ﴾ عند الوصل؟"],"levels":{"easy":[{"type":"mcq","q":"التقاء الساكنين في كلمة ﴿الْحَاقَّةُ﴾ يكون:","options":["في كلمة واحدة وصلاً ووقفًا","عند الوقف فقط","في كلمتين","لا يوجد التقاء ساكنين"],"answer":0,"why":"الألف المدية الساكنة تلتقي بالقاف الأولى الساكنة من المشدّد."},{"type":"mcq","q":"الحرف المشدّد (مثل لّ في الضَّالِّينَ) يتكوّن في الحقيقة من:","options":["ثلاثة حروف","حرفين: الأول ساكن والثاني متحرك","حرف واحد مفتوح","حرفين متحركين"],"answer":1,"why":"كل حرف مشدّد أصله حرفان: ساكن ثم متحرك."},{"type":"mcq","q":"الوقف على ﴿وَالْفَجْرْ﴾ مثال على التقاء ساكنين:","options":["مد لازم","وصلاً ووقفًا","في كلمة واحدة عند الوقف فقط (حرفان صحيحان)","في كلمتين"],"answer":2,"why":"الجيم الساكنة تلتقي بالراء الساكنة عند الوقف فقط."},{"type":"mcq","q":"المدّ الذي يظهر عند الوقف على ﴿الْعَالَمِينْ﴾ يُسمّى:","options":["إخفاءً","إقلابًا","مدًّا لازمًا","مدًّا عارضًا للسكون (٢ أو ٤ أو ٦ حركات)"],"answer":3,"why":"السكون هنا عارض لأجل الوقف فقط."}],"medium":[{"type":"mcq","q":"ماذا يحدث لالتقاء الساكنين في قوله ﴿وَالْعَصْرِ إِنَّ الْإِنسَانَ﴾ عند «وصل» الآيتين؟","options":["يزول التقاء الساكنين لأن الراء تصبح مكسورةً متحركةً","تُحذف الراء","يبقى الساكنان كما هما","يُمدّ ٦ حركات"],"answer":0,"why":"في الوصل تتحرّك الراء بالكسرة فلا يلتقي ساكنان."},{"type":"mcq","q":"أي مثال مما يلي يمثّل «مدّ اللين» عند الوقف؟","options":["﴿وَالْعَصْرْ﴾","﴿خَوْفْ﴾ و﴿بَيْتْ﴾","﴿الضَّالِّينَ﴾","﴿الْقَدْرْ﴾"],"answer":1,"why":"اللين هو واو أو ياء ساكنة مفتوح ما قبلها."},{"type":"mcq","q":"في كلمة ﴿آلْآنَ﴾ (بسورة يونس)، الساكن الأول هو الألف المدّية والساكن الثاني هو:","options":["لا يوجد ساكن ثانٍ","الهمزة","اللام الساكنة سكونًا أصليًا","النون المفتوحة"],"answer":2,"why":"وهو مثال للمد اللازم الكلمي المخفّف (٦ حركات)."},{"type":"tfr","q":"يُغتفر التقاء الساكنين في كلمة واحدة عند الوقف على ﴿الْقَدْرْ﴾ مع مراعاة قلقلة الدال.","answer":true,"reasons":["نُبقي الدال ساكنة مقلقلة ونقف على الراء بالسكون دون تحريك الدال","يُحذف حرف الراء","يجب فتح الدال"],"reason":0},{"type":"tfr","q":"يجوز قصر المد في ﴿وَلَا الضَّالِّينَ﴾ إلى حركتين فقط.","answer":false,"reasons":["لا مدّ فيه أصلًا","بل هو مد لازم كلمي مثقّل يجب مدّه ٦ حركات لزومًا وصلاً ووقفًا","يجوز حركتان فقط"],"reason":1},{"type":"essay","q":"اذكر الحالات الثلاث التي يجتمع فيها ساكنان في «كلمة واحدة» مع مثال قرآني لكل حالة.","model":"١) مد لازم وصلاً ووقفًا: ﴿الضَّالِّينَ﴾. ٢) مد عارض أو لين وقفًا فقط: ﴿نَسْتَعِينْ﴾، ﴿خَوْفْ﴾. ٣) ساكنان صحيحان وقفًا فقط: ﴿وَالْعَصْرْ﴾."},{"type":"essay","q":"لماذا لا يواجه القارئ صعوبةً في النطق بالساكنين في ﴿الصَّاخَّةُ﴾ عند تطبيق المدّ اللازم؟","model":"لأن إشباع المد ٦ حركات يفصل صوتيًا ويمهّد اللسان للنطق بالحرف الساكن المشدّد بعده بيسر وسلاسة."}],"hard":[{"type":"mcq","q":"في سورة الفاتحة: ﴿الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ﴾، أي كلمة يحصل فيها التقاء ساكنين «عند الوقف فقط»؟","options":["رَبِّ","الْحَمْدُ","لِلَّهِ","الْعَالَمِينْ"],"answer":3,"why":"الياء المدية الساكنة تلتقي بالنون الساكنة للوقف."},{"type":"mcq","q":"أي كلمة مما يلي تجمع بين التقاء ساكنين وصلاً ووقفًا (في وسطها) والتقاء ساكنين وقفًا (في آخرها)؟","options":["﴿الضَّالِّينْ﴾ عند الوقف عليها","﴿مَلِكِ﴾","﴿وَالْعَصْرْ﴾","﴿رَبِّ﴾"],"answer":0,"why":"في وسطها مد لازم (الألف + اللام الساكنة) وفي آخرها مد عارض عند الوقف (الياء + النون)!"},{"type":"mcq","q":"الخطأ التجويدي عند الوقف على ﴿خُلْقْ﴾ بتحريك اللام بالضم يُسمّى:","options":["إخفاءً","تحريك الساكن الأول بغير وجه حق","مدًّا لازمًا","إدغامًا صحيحًا"],"answer":1,"why":"يجب إبقاء اللام ساكنةً والوقف على القاف بالسكون مع قلقلتها."},{"type":"mcq","q":"في الحروف المقطعة أوائل السور مثل ﴿الم﴾ (ألف لام ميم)، يوجد التقاء ساكنين في كلمة «لام» و«ميم» وحكمه:","options":["لا مدّ فيه","حركتان فقط","مدّ لازم حرفي ٦ حركات","حذف الساكن"],"answer":2,"why":"الألف في «لام» والياء في «ميم» تلتقيان بالميم الساكنة فيُمدّ ٦ حركات."},{"type":"tfr","q":"لا يقع التقاء الساكنين في «الحرف الأول» من الكلمة العربية لأن العرب لا تبدأ بساكن.","answer":true,"reasons":["لا يوجد ساكن في آخر الكلمة","تبدأ العربية بساكنين دائمًا","لذا لا يقع التقاء الساكنين في كلمة واحدة إلا في وسطها أو آخرها"],"reason":2},{"type":"tfr","q":"الوقف على كلمة ﴿قُرَيْشْ﴾ يجمع بين ياء لين ساكنة وشين ساكنة للوقف، وهو مغتفر.","answer":true,"reasons":["ويُمدّ فيه مدّ لين عارض للسكون ٢ أو ٤ أو ٦ حركات","غير جائز","يُمد ٦ حركات لزومًا فقط"],"reason":0},{"type":"tfr","q":"التقاء الساكنين في ﴿وَالْفَجْرْ﴾ يستمر حتى لو وصلناها بقوله ﴿وَلَيَالٍ عَشْرٍ﴾.","answer":false,"reasons":["يبقى الساكنان في الوصل","عند الوصل تُكسر الراء (وَالْفَجْرِ) فيزول التقاء الساكنين","تُحذف الراء في الوصل"],"reason":1},{"type":"essay","q":"استخرج من سورة العصر مثالين لالتقاء الساكنين في كلمة واحدة عند الوقف، وحدّد نوع الساكن الأول في كل منهما.","model":"١) ﴿وَالْعَصْرْ﴾: الساكن الأول حرف صحيح (الصاد). ٢) ﴿خُسْرْ﴾ (أو ﴿بِالصَّبْرْ﴾): الساكن الأول حرف صحيح ساكن (السين / الباء)."},{"type":"essay","q":"اشرح الفرق بين «المد اللازم» و«المد العارض للسكون» من حيث سبب التقاء الساكنين ومقدار المد.","model":"المد اللازم سببه سكون أصلي ثابت وصلاً ووقفًا ومقداره ٦ حركات لزومًا (مثل ﴿الحاقة﴾). المد العارض سببه سكون عارض للوقف فقط ومقداره ٢ أو ٤ أو ٦ حركات جوازًا (مثل ﴿نستعينْ﴾)."},{"type":"essay","q":"كيف تتدرّب عمليًا على إتقان الوقف على ﴿الْقَدْرْ﴾ و﴿الضَّالِّينَ﴾ دون لحن؟","model":"في ﴿الضالين﴾: أمد الألف ٦ حركات كاملة ثم أشدد اللام بوضوح. وفي ﴿القدرْ﴾: أُظهر قلقلة الدال الساكنة دون تحريكها بفتحة ثم أقف على الراء بسكون وتفخيم."}]}},
  {"id":"g9-islamic-1-u2-2","grade":"g9","subject":"islamic","term":1,"unit":2,"no":2,"title":"سورة الإسراء (١٠٥–١١١) — تفسير","summary":"شرح متحرك بـ SVG لدرس سورة الإسراء (١٠٥–١١١) — تفسير للصف التاسع (سلطنة عُمان)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.","page":"lesson-surah-al-isra-105-111.html","video":"","pdf":"","notes":["نزل القرآن بالحق محفوظًا، ومهمة الرسول ﷺ التبشير والإنذار.","نزل القرآن مفرّقًا (على مكث) لتثبيت القلوب وتيسير الحفظ والفهم والتدرج في العمل.","أهل العلم الصادقون يخشعون ويسجدون وتفيض أعينهم عند سماع القرآن (آية ١٠٧–١٠٩ وفيها سجدة تلاوة).","نُدعو الله بأسمائه الحسنى كلها، ونعتدل في الصوت في الصلاة والدعاء، وننزّه الله عن الولد والشريك والذل."],"exercises":["اذكر ثلاث حِكَم لنزول القرآن الكريم مفرّقًا.","ما سبب نزول قوله تعالى ﴿قل ادعوا الله أو ادعوا الرحمن﴾؟","استخرج ثلاث صفات لتنزيه الله تعالى من الآية ١١١."],"levels":{"easy":[{"type":"mcq","q":"معنى «عَلَىٰ مُكْثٍ» في الآية ١٠٦ هو:","options":["بصوت خافت جدًّا","في السفر","بسرعة فائقة","على مهل وتؤدة وتأنٍّ"],"answer":3,"why":"المكث هو التمهّل والتؤدة ليتدبّره الناس."},{"type":"mcq","q":"معنى «وَلِيٌّ مِّنَ الذُّلِّ» في الآية ١١١ هو:","options":["نصير أو حليف يحتاج إليه الله لدفع ضعف (والله منزه عن ذلك)","صديق صالح","حاكم عادل","عالم جليل"],"answer":0,"why":"الله عزيز غني لا يحتاج نصيرًا يعينه على ضعف."},{"type":"mcq","q":"تُعد آية ﴿وَيَخِرُّونَ لِلْأَذْقَانِ يَبْكُونَ وَيَزِيدُهُمْ خُشُوعًا﴾ موضع:","options":["وقف ممنوع","سجدة تلاوة","قصة موسى","أحكام ميراث"],"answer":1,"why":"الآية ١٠٩ من سورة الإسراء فيها سجدة تلاوة."},{"type":"mcq","q":"الدعاء بـ«يا الله» أو «يا رحمن» يُعد:","options":["غير جائز","خاصًا بالأنبياء فقط","دعاءً لإله واحد له الأسماء الحسنى كلها","دعاء لإلهين"],"answer":2,"why":"الله والرحمن اسمان لله الواحد الأحد."}],"medium":[{"type":"mcq","q":"ما أثر سماع القرآن الكريم على قلوب «العلماء الصادقين» كما وصفت الآيات؟","options":["التكبر على الناس","الجدال والعناد","الغفلة والإعراض","السجود والبكاء وزيادة الخشوع لله تعالى"],"answer":3,"why":"العلم الحقيقي يقود للخشوع والتواضع أمام كلام الله."},{"type":"mcq","q":"توجيه الآية ١١٠ ﴿وابتغ بين ذلك سبيلًا﴾ يعلّمنا في الحياة والعبادة قيمة:","options":["الاعتدال والتوسّط في كل الأمور","التطرّف والغلو","إزعاج الآخرين","التفريط والتكاسل"],"answer":0,"why":"الإسلام دين الوسطية والاعتدال حتى في نبرة الصوت."},{"type":"mcq","q":"أمر الله نبيه ﷺ أن يقول ﴿الحمد لله الذي لم يتخذ ولدًا...﴾ لتعليم الأمة:","options":["الخوف من المشركين","التوحيد الخالص وتنزيه الله عن كل نقص","ترك الحمد","نسب الولد لله"],"answer":1,"why":"تنزيه الله عن الولد والشريك والذل أصل التوحيد."},{"type":"tfr","q":"نزل القرآن الكريم كاملًا في ليلة واحدة على النبي ﷺ مكتوبًا في صحف.","answer":false,"reasons":["نزل في سنة واحدة","نعم نزل دفعة واحدة في يوم","نزل مفرّقًا (منجّمًا) على النبي ﷺ خلال ٢٣ سنة لحكم عظيمة كالتثبيت وتيسير الحفظ"],"reason":2},{"type":"tfr","q":"يُستحب للمسلم أن يدعو الله بالاسم المناسب لحاجته من أسماء الله الحسنى.","answer":true,"reasons":["مثل يا غفور اغفر لي ويا شافي اشفني، عملًا بقوله ﴿فله الأسماء الحسنى﴾","لا يُدعى بالرحمن","يجوز اسم واحد فقط"],"reason":0},{"type":"essay","q":"اذكر ثلاث حِكَم من نزول القرآن الكريم مفرّقًا على مهل.","model":"١) تثبيت قلب النبي ﷺ والمؤمنين. ٢) تيسير الحفظ والفهم والتدبّر. ٣) التدرّج في التشريع ومواكبة الأحداث والإجابة عن الأسئلة."},{"type":"essay","q":"كيف تطبّق أدب «التوسط في الصوت» في المسجد والمدرسة والبيت؟","model":"في المسجد: لا أرفع صوتي بالقراءة فأشوش على المصلين. وفي المدرسة والبيت: أتحدث بصوت هادئ معتدل يحترم الآخرين."}],"hard":[{"type":"mcq","q":"لماذا قدّمت الآية ١٠٧ عبارة ﴿إن الذين أوتوا العلم من قبله﴾ عند الحديث عن الإيمان بالقرآن؟","options":["لأن العلم يمنع الإيمان","لأنه خاص بالعلماء فقط","لأن أهل العلم المنصفين من أهل الكتاب عرفوا صفة النبي ﷺ والقرآن في كتبهم فآمنوا وخشعوا","لأن الجاهل لا يؤمن أبدًا"],"answer":2,"why":"العلماء المنصفون كانوا أسرع الناس لتمييز الحق والخشوع له."},{"type":"mcq","q":"ما دلالة تقديم ﴿وبالحق أنزلناه وبالحق نزل﴾ بتكرار كلمة «بالحق»؟","options":["أنه نزل بالصدفة","للتطويل فقط","أنه يتغير مع الزمن","تأكيد أن القرآن حق في مصدره ومضمونه وحفظه عند وصوله للنبي ﷺ دون تبديل"],"answer":3,"why":"نزل بالحق من الله ووصل بالحق سالمًا من أي تحريف."},{"type":"mcq","q":"ما العلاقة بين «قراءة القرآن على مكث (بتؤدة)» وبين «الخشوع»؟","options":["القراءة المتمهّلة تتيح للعقل التدبّر وللقلب التأثر بالمعاني فيحصل الخشوع","لا علاقة بينهما","السرعة تزيد الخشوع","الخشوع لا يحتاج فهمًا"],"answer":0,"why":"التدبّر لا يتحقق إلا بالترتيل والتمهّل."},{"type":"mcq","q":"سُمّيت الآية ١١١ من سورة الإسراء بـ«آية العزّ» لأنها:","options":["تتحدث عن المال","تؤكّد عزة الله المطلقة وغناه عن الولد والشريك والنصير، وتمنح المؤمن عزة بالتوحيد","تتحدث عن القصور","تتحدث عن السفر"],"answer":1,"why":"تنزيه الله عن الذل والشريك يملأ قلب الموحّد بالعزة."},{"type":"tfr","q":"يجوز قراءة القرآن بصوت مرتفع جدًّا في المسجد حتى لو شوّشت على من يصلّي بجانبك.","answer":false,"reasons":["نعم كلما علا الصوت كان أفضل","بل يُنهى عن التشويش على المصلين؛ والمأمور به التوسّط والاعتدال في الصوت","لا يهم حال المصلين"],"reason":1},{"type":"tfr","q":"ذكر «الرحمن» مع «الله» في الآية ١١٠ يبرز سعة رحمة الله بعباده في ختام السورة.","answer":true,"reasons":["لا صلة له بالرحمة","الرحمن اسم غير معروف","فالدعاء بالرحمن يفتح باب الرجاء والرحمة مع هيبة التوحيد"],"reason":2},{"type":"tfr","q":"ختم السورة بالأمر ﴿وكبّره تكبيرًا﴾ يعلّم المسلم استحضار عظمة الله في كل شؤون حياته.","answer":true,"reasons":["فالتكبير القلبي واللفظي يعظّم الله فوق كل شيء","التكبير للعيد فقط","التكبير خاص بالأذان فقط"],"reason":0},{"type":"essay","q":"بيّن كيف نردّ بأسلوب علمي هادئ على من يظن أن تعدد أسماء الله الحسنى يعني تعدد الآلهة.","model":"نستشهد بالآية ١١٠ ﴿قل ادعوا الله أو ادعوا الرحمن أيًا ما تدعوا فله الأسماء الحسنى﴾؛ فالذات الإلهية واحدة، وتعدد الأسماء إنما هو تعدد لصفات الكمال لإله واحد لا شريك له."},{"type":"essay","q":"قارن بين أثر «العلم المصحوب بالتواضع» و«العلم المصحوب بالكبر» في ضوء الآيات ١٠٧–١٠٩.","model":"العلم المتواضع يقود صاحبه لقبول الحق والخشوع والخضوع لله (كما في حال أهل العلم بالآية)، أما الكبر فيعمي صاحبه عن الحق ولو رآه واضحًا."},{"type":"essay","q":"اكتب ثلاث فوائد عملية تحفظها من خواتيم سورة الإسراء وتطبّقها في صلاتك اليومية.","model":"١) الترتيل والتدبّر على مهل. ٢) التوسط في الصوت دون إزعاج. ٣) الدعاء بأسماء الله الحسنى واستحضار التوحيد والتكبير."}]}},
  {"id":"g9-islamic-1-u2-3","grade":"g9","subject":"islamic","term":1,"unit":2,"no":3,"title":"شُعَب الإيمان (حديث شريف)","summary":"شرح متحرك بـ SVG لدرس شُعَب الإيمان (حديث شريف) للصف التاسع (سلطنة عُمان)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.","page":"lesson-branches-of-faith.html","video":"","pdf":"","notes":["الحديث عن أبي هريرة: «الإيمان بضع وسبعون — أو بضع وستون — شعبة، فأفضلها قول لا إله إلا الله، وأدناها إماطة الأذى عن الطريق، والحياء شعبة من الإيمان».","أقسام شعب الإيمان: شعب القلب (كالتوكل والحياء)، وشعب اللسان (كالتوحيد والصدق)، وشعب الجوارح (كالصلاة وإماطة الأذى).","الحياء المحمود يبعث على ترك القبيح ولا يمنع من تعلم العلم وقول الحق.","إماطة الأذى تشمل النظافة العامة وحفظ البيئة وإزالة كل ما يضر الناس."],"exercises":["قسّم شعب الإيمان الثلاثة مع مثالين لكل قسم.","فرّق بين الحياء المحمود والخجل المذموم بمثال من الصف الدراسي.","كيف نطبّق شعبة «إماطة الأذى» في الحفاظ على شواطئ وحدائق سلطنة عُمان؟"],"levels":{"easy":[{"type":"mcq","q":"معنى «الشُّعبة» في حديث شعب الإيمان هو:","options":["القرية الصغيرة","الطريق الطويل","الفرع والجزء من الشيء","العملة"],"answer":2,"why":"شُعب الإيمان أي فروعه وأجزاؤه كفروع الشجرة."},{"type":"mcq","q":"أدنى (أيسر) شُعب الإيمان المذكورة في الحديث هي:","options":["الصيام","الحج","الزكاة","إماطة الأذى عن الطريق"],"answer":3,"why":"إماطة الأذى سهلة ومتاحة لكل مسلم يوميًا."},{"type":"mcq","q":"تُصنّف «الصلاة وإماطة الأذى» ضمن شُعب:","options":["الجوارح (الأعمال البدنية)","النوم","اللسان فقط","القلب فقط"],"answer":0,"why":"الأعمال التي تؤدى بالأعضاء من شعب الجوارح."},{"type":"mcq","q":"يُصنّف «الحياء والتوكل» ضمن شُعب:","options":["الطريق","القلب","اللسان فقط","المال"],"answer":1,"why":"الحياء والتوكل أعمال قلبية يظهر أثرها في السلوك."}],"medium":[{"type":"mcq","q":"ما دلالة ربط «إماطة الأذى عن الطريق» بالإيمان في الإسلام؟","options":["أن الإيمان يقتصر على المسجد فقط","أن النظافة غير مهمة","أن الحفاظ على النظافة وسلامة الآخرين عبادة وجزء من الدين وليس مجرد سلوك عادي","أن التوحيد غير ضروري"],"answer":2,"why":"الإسلام يربط السلوك الحضاري والمجتمعي بالإيمان مباشرة."},{"type":"mcq","q":"طالب يخجل من سؤال معلمه عمّا لم يفهمه في الدرس؛ هذا يُعد:","options":["أعلى درجات الحياء","شعبة من الإيمان","أدبًا مطلوبًا","خجلًا سلبيًا مذمومًا وليس حياءً شرعيًا"],"answer":3,"why":"الحياء المحمود لا يمنع من طلب العلم النافع والسؤال عنه."},{"type":"mcq","q":"أي سلوك في العصر الرقمي يدخل في معنى «إماطة الأذى»؟","options":["عدم نشر الشائعات والمحتوى المسيء والتبليغ عن الروابط الضارة","إرسال الشائعات للجميع","السخرية من الزملاء","إضاعة الوقت"],"answer":0,"why":"إبعاد الأذى يشمل الطريق الحقيقي والطريق الرقمي على الإنترنت."},{"type":"tfr","q":"لا يضرّ الإيمان تركُ الأعمال الصالحة والأخلاق ما دام الإنسان يقول «لا إله إلا الله» بلسانه فقط.","answer":false,"reasons":["نعم القول وحده يكفي","الإيمان قول وعمل واعتقاد، وترك الشعب ينقص الإيمان ويضعفه","الأخلاق ليست من الإيمان"],"reason":1},{"type":"tfr","q":"يزيد الإيمان بالطاعات وتطبيق شُعبه، وينقص بالمعاصي والغفلة.","answer":true,"reasons":["الإيمان لا يزيد ولا ينقص","المعاصي تزيد الإيمان","وهذا ما يقرّره القرآن والسنة في تفاوت درجات الإيمان"],"reason":2},{"type":"essay","q":"اذكر ثلاث صور حديثة لـ«إماطة الأذى» في المدرسة والشارع والإنترنت.","model":"١) في المدرسة: إزالة الأوراق أو الأشياء التي قد يتعثر بها الطلاب. ٢) في الشارع: عدم إلقاء القمامة وترك المواقف والطرق سالكة. ٣) على الإنترنت: منع نشر الشائعات والأذى اللفظي."},{"type":"essay","q":"لماذا شبّه النبي ﷺ الإيمان بشجرة لها شُعَب وفروع؟","model":"لأن الشجرة لها أصل ثابت (التوحيد) وفروع كثيرة مترابطة (الأعمال والأخلاق)، وكل فرع يجمّل الشجرة ويقوّيها ويثمر خيرًا للمجتمع."}],"hard":[{"type":"mcq","q":"لو أزال طالب زجاجًا مكسورًا من ملعب المدرسة بنية حماية زملائه وطاعة الله، فإنه ينال:","options":["إثمًا","أجر شعبة من شعب الإيمان بالإضافة لحماية زملائه","لا أجر له","تعبًا بلا فائدة"],"answer":1,"why":"النية الصالحة تحوّل إماطة الأذى إلى عبادة يؤجر عليها."},{"type":"mcq","q":"قال النبي ﷺ: «الحياء لا يأتي إلا بخير». أي مثال يطبّق هذا الحديث بدقة؟","options":["السكوت عن الحق خوفًا","رفض السؤال عن درس غامض","ترك الغش في الاختبار حياءً من الله الذي يراه","ترك الصلاة حياءً من الأصدقاء"],"answer":2,"why":"الحياء من الله يمنع المعصية ويدفع للخير والاستقامة."},{"type":"mcq","q":"التدرّج في الحديث من «أعلاها» (لا إله إلا الله) إلى «أدناها» (إماطة الأذى) يفيد:","options":["أن إماطة الأذى تساوي التوحيد","أن بينهما شعبتين فقط","إهمال الصلاة","شمول الإيمان لكل مراتب الخير من أعظم العقائد حتى أبسط الآداب اليومية"],"answer":3,"why":"يغطي الإيمان جميع مجالات الحياة الكبيرة والصغيرة."},{"type":"mcq","q":"عندما تترك أداةً حادةً أو قشر موز على الرصيف عمدًا، فإنك تقع في:","options":["ضد شعبة إماطة الأذى (إيذاء الناس المحرّم)","مزاح مقبول","شعبة إيمان","سلوك مباح"],"answer":0,"why":"وضع الأذى في طريق الناس إثم واعتداء على حق عام."},{"type":"tfr","q":"تتفاوت درجات المؤمنين في الإيمان بقدر أخذهم بشُعَب الإيمان وتطبيقها في حياتهم.","answer":true,"reasons":["فمن حقق شعبًا أكثر كان أكمل إيمانًا وأعظم أجرًا","الناس كلهم في درجة واحدة","الشعب لا تؤثر في الإيمان"],"reason":0},{"type":"tfr","q":"يقتصر الحياء في الإسلام على الحياء من الناس فقط دون الحياء من الله.","answer":false,"reasons":["الحياء من الناس فقط","بل أعظم الحياء هو الحياء من الله تعالى في السر والعلن، ثم الحياء من الناس ومن النفس","لا يوجد حياء من الله"],"reason":1},{"type":"tfr","q":"المشاركة في حملة تطوعية لتنظيف شاطئ في عُمان تطبيق عملي لشعبة إماطة الأذى.","answer":true,"reasons":["إماطة الأذى في الصحراء فقط","لا علاقة لها بالحديث","لأنها تزيل الأذى عن مرتادي الشاطئ وتحمي البيئة البحرية بنية الخير"],"reason":2},{"type":"essay","q":"اشرح كيف يمكن لمدرسة كاملة أن تجعل حديث «شُعَب الإيمان» مشروعًا تربويًا شهريًا.","model":"تخصيص كل أسبوع لشعبة عملية: أسبوع الصدق، أسبوع بر الوالدين، أسبوع إماطة الأذى ونظافة المدرسة، أسبوع الحياء والأدب، مع متابعة وتكريم المبادرات الطلابية."},{"type":"essay","q":"قارن بين «أعلى شعبة» و«أدنى شعبة» في الحديث من حيث المكانة والأثر.","model":"أعلاها «لا إله إلا الله»: هي أصل الدين وبها يدخل الإنسان الإسلام وتُقبل أعماله. وأدناها «إماطة الأذى»: عمل يسير متاح للجميع يوميًا، يثمر أمنًا ونظافةً وأجرًا عظيمًا."},{"type":"essay","q":"ما المقصود بالحياء من الله، والحياء من الناس، والحياء من النفس؟","model":"من الله: ألا يراك حيث نهاك ولا يفقدك حيث أمرك. من الناس: كفّ الأذى وترك المجاهرة بالقبيح. من النفس: صون الكرامة والعفة حتى في الخلوة."}]}},
  {"id":"g9-islamic-1-u2-4","grade":"g9","subject":"islamic","term":1,"unit":2,"no":4,"title":"دعوة نوح عليه السلام (عقيدة)","summary":"شرح متحرك بـ SVG لدرس دعوة نوح عليه السلام (عقيدة) للصف التاسع (سلطنة عُمان)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.","page":"lesson-call-of-prophet-nuh.html","video":"","pdf":"","notes":["نوح عليه السلام أول الرسل إلى أهل الأرض وأحد أولي العزم الخمسة، دعا قومه ٩٥٠ سنة.","نوّع أساليبه في الدعوة: ليلًا ونهارًا، سرًا وجهارًا، بالترغيب والترهيب، وبالتفكر في آيات الله.","بنى السفينة بأمر الله ونجّى الله المؤمنين وأغرق المكذبين، وهلك ابنه لكفره لبيان أن المعيار الإيمان لا النسب.","أرشد قومه إلى الاستغفار وبيّن ثماره في المغفرة والمطر والرزق والبركة."],"exercises":["اذكر أربعة أساليب استخدمها نوح عليه السلام في دعوة قومه.","ما العبرة من سخرية قوم نوح منه أثناء بنائه السفينة؟","اذكر ثلاث ثمرات للاستغفار وردت في دعوة نوح عليه السلام."],"levels":{"easy":[{"type":"mcq","q":"يُعد نبي الله نوح عليه السلام:","options":["آخر الأنبياء","أول الرسل إلى أهل الأرض ومن أولي العزم","ملكًا في مصر","من أنبياء بني إسرائيل"],"answer":1,"why":"نوح عليه السلام أول رسول أُرسل بعد ظهور الشرك في الأرض."},{"type":"mcq","q":"المدة التي قضاها نوح عليه السلام في دعوة قومه هي:","options":["١٠٠٠ سنة كاملة","٥٠٠ سنة","٩٥٠ سنة","٥٠ سنة"],"answer":2,"why":"ألف سنة إلا خمسين عامًا = ٩٥٠ سنة."},{"type":"mcq","q":"من أساليب نوح عليه السلام في الدعوة المذكورة في القرآن:","options":["الإكراه بالسيف","إهمال الضعفاء","الدعوة مرة واحدة فقط","الدعوة سرًا وجهارًا، وليلًا ونهارًا"],"answer":3,"why":"نوّع الأوقات والطرق بحكمة وصبر."},{"type":"mcq","q":"استكبر كبراء قوم نوح عن اتباعه لأن:","options":["أتباعه كانوا من الفقراء والضعفاء في نظرهم","طلب منهم مالًا","دعوته كانت غامضة","لم يصبر عليهم"],"answer":0,"why":"عابوا عليه اتباع الضعفاء فردّ عليهم أن ميزان الله التقوى."}],"medium":[{"type":"mcq","q":"ما دلالة دعوة نوح عليه السلام قومه «سرًا» ثم «جهارًا»؟","options":["إخفاء التوحيد","الحكمة والرفق في النصح لأن النصيحة الفردية سرًا أدعى للقبول وأبعد عن الحرج","تغيّر الرسالة","الخوف من الكلام"],"answer":1,"why":"البدء بالنصح الفردي الهادئ من أعظم آداب الدعوة والإصلاح."},{"type":"mcq","q":"لماذا أمر الله نوحًا عليه السلام بصنع السفينة رغم قدرته على إنجائهم بغير سفينة؟","options":["للتجارة البحرية","لتسليته فقط","لتعليم المؤمنين وجوب «الأخذ بالأسباب» مع التوكّل على الله","لعجز الماء عن حملهم"],"answer":2,"why":"الأخذ بالأسباب سنة كونية وشرعية مع الاعتماد على الله."},{"type":"mcq","q":"موقف نوح عليه السلام حين طلب قومه طرد المؤمنين الضعفاء كان:","options":["السكوت","ترك الدعوة","الموافقة الفورية","الرفض القاطع ﴿وما أنا بطارد الذين آمنوا﴾"],"answer":3,"why":"رفض طردهم لأن الكرامة في الإسلام بالتقوى لا بالمال."},{"type":"tfr","q":"الغلو في تعظيم الصالحين كان السبب الأول في وقوع الشرك في الأرض في قوم نوح.","answer":true,"reasons":["فقد صنعوا تماثيل لهم ثم عُبدت من دون الله بعد أجيال","لم يكن فيهم شرك","كان السبب كثرة المطر"],"reason":0},{"type":"tfr","q":"شفاعة القرابة وحدها أنجت ابن نوح عليه السلام من الغرق رغم كفره.","answer":false,"reasons":["ركب السفينة في النهاية","بل غرق مع المكذبين لأن النجاة بالإيمان والعمل الصالح لا بالنسب","نعم نجا لكونه ابن نبي"],"reason":1},{"type":"essay","q":"استخلص أربعة دروس من دعوة نوح عليه السلام تنفعك في حياتك اليومية.","model":"١) الصبر وعدم اليأس عند بطء النتائج. ٢) تنويع أساليب الإقناع والنصح بالرفق سرًا. ٣) الأخذ بالأسباب مع التوكل على الله (بناء السفينة). ٤) عدم الالتفات لسخرية المبطلين."},{"type":"essay","q":"بيّن كيف خاطب نوح عليه السلام عقول قومه بآيات الكون في سورة نوح.","model":"لفت أنظارهم إلى أطوار خلق الإنسان، وخلق السماوات السبع طباقًا، وجعل القمر نورًا والشمس سراجًا، وتذليل الأرض لهم، ليستدلوا بها على وحدانية الخالق."}],"hard":[{"type":"mcq","q":"ما أسلوب الحوار الذي استخدمه نوح مع ابنه في قوله ﴿يا بنيّ اركب معنا﴾؟","options":["النداء بالشفقة والرحمة الأبوية والرفق حتى اللحظة الأخيرة","الإكراه بالقوة","الغضب والشتم","التجاهل"],"answer":0,"why":"استعمل «يا بنيّ» للتصغير الدال على المحبة والشفقة."},{"type":"mcq","q":"قولة نوح عليه السلام ﴿وما أسألكم عليه من أجر إن أجري إلا على رب العالمين﴾ تبيّن صفة مهمة للداعي والمصلح هي:","options":["الانعزال","الإخلاص لله وعدم طلب مقابل دنيوي على النصح والخير","كراهية المال الحلال","ترك العمل"],"answer":1,"why":"إخلاص النية لله يكسب النصيحة صدقًا وتأثيرًا في القلوب."},{"type":"mcq","q":"لماذا عاقب الله قوم نوح بالطوفان بعد ٩٥٠ سنة من الدعوة؟","options":["بسبب خطأ غير مقصود","بعد يوم واحد من الدعوة","بعد إقامة الحجة الكاملة عليهم وإصرارهم على الكفر والعناد والفساد","قبل أن يرسل لهم رسولًا"],"answer":2,"why":"لا يعذب الله قومًا إلا بعد إقامة الحجة التامة وإرسال الرسل."},{"type":"mcq","q":"أي قيمة إنسانية عظيمة يرسّخها رفض نوح عليه السلام طرد الضعفاء من مجلسه؟","options":["التفرقة الطبقية","ترك الدعوة للأغنياء","تفضيل الأغنياء","المساواة وكرامة الإنسان وأن التفاضل بالتقوى والعمل لا بالمال والنسب"],"answer":3,"why":"الإسلام يساوي بين البشر في الكرامة الإنسانية."},{"type":"tfr","q":"وُصف نوح عليه السلام في القرآن بأنه «عبد شكور» مما يعلّمنا الجمع بين الصبر والشكر في كل حال.","answer":true,"reasons":["الشكر للغنى فقط","لم يذكر بالشكر في القرآن","فقد شكر الله على نعمه وثبت على طاعته طوال عمره المديد"],"reason":2},{"type":"tfr","q":"قصة نوح عليه السلام تثبت أن كثرة الأتباع ليست دائمًا هي المعيار الوحيد على صحة المنهج.","answer":true,"reasons":["فقد كان نوح على الحق المبين ومع ذلك لم يؤمن معه إلا قليل","قلة الأتباع تعني بطلان الدعوة","الحق دائمًا مع الأكثرية فقط"],"reason":0},{"type":"tfr","q":"يجوز للمسلم الاستهزاء بزميله الملتزم بالحق كما سخر قوم نوح من بناء السفينة.","answer":false,"reasons":["لا بأس بذلك","السخرية من أهل الحق صفة المكذبين المذمومة، والمؤمن يعظّم الحق ويشجع عليه","المزاح بالسخرية مباح"],"reason":1},{"type":"essay","q":"قارن بين موقف المؤمنين وموقف كبراء قوم نوح من الدعوة، وبيّن عاقبة كل فريق.","model":"المؤمنون: تواضعوا للحق واتبعوا نوحًا وركبوا السفينة فأنجاهم الله وبارك فيهم. الكبراء: استكبروا وسخروا وأصرّوا على الشرك فأغرقهم الطوفان وخسروا الدنيا والآخرة."},{"type":"essay","q":"اشرح كيف تطبّق «تنوع أساليب الإقناع» عند نصح صديق لك يقصر في صلاته أو دراسته.","model":"أبدأ بالتحدث معه سرًا بلطف ومحبة، وأشجّعه ببيان فوائد الصلاة والتفوق (الترغيب)، وأساعده بعمل جدول منظم دون توبيخ أمام الآخرين."},{"type":"essay","q":"اذكر أسماء «أولي العزم من الرسل» الخمسة وبيّن سبب تسميتهم بهذا اللقب.","model":"هم: نوح، وإبراهيم، وموسى، وعيسى، ومحمد عليهم الصلاة والسلام؛ وسُمّوا بذلك لقوة عزمهم وعظيم صبرهم وثباتهم في تبليغ رسالة الله."}]}},
  {"id":"g9-islamic-1-u2-5","grade":"g9","subject":"islamic","term":1,"unit":2,"no":5,"title":"من مصادر التشريع الإسلامي (١) — فقه","summary":"شرح متحرك بـ SVG لدرس من مصادر التشريع الإسلامي (١) — فقه للصف التاسع (سلطنة عُمان)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.","page":"lesson-sources-of-islamic-law-1.html","video":"","pdf":"","notes":["المصادر الأربعة المتفق عليها: القرآن الكريم، السنة النبوية، الإجماع، والقياس.","القرآن الكريم: المصدر الأول والأعلى، نُقل بالتواتر وتضمّن قواعد كلية وأحكامًا تفصيلية.","أنواع السنة النبوية: قولية (أحاديثه)، فعلية (أفعاله كالصلاة والوضوء)، وتقريرية (موافقته على فعل صحابي).","علاقة السنة بالقرآن: مؤكدة لحكمه، مبيّنة ومفصّلة لمجمله (كالصلاة والزكاة)، أو منشئة لأحكام جديدة."],"exercises":["اذكر أنواع السنة النبوية الثلاثة مع مثال واحد لكل نوع.","اشرح الوظائف الثلاث للسنة النبوية مع القرآن الكريم مع مثال لكل وظيفة.","لماذا لا يمكن للمسلم الاستغناء عن السنة النبوية في عباداته؟"],"levels":{"easy":[{"type":"mcq","q":"أول مصادر التشريع الإسلامي هو:","options":["القرآن الكريم","الإجماع","السنة النبوية","القياس"],"answer":0,"why":"القرآن الكريم هو المصدر الأول والأعلى."},{"type":"mcq","q":"المصدر الثاني للتشريع الإسلامي هو:","options":["القياس","السنة النبوية الشريفة","العرف","الآراء الشخصية"],"answer":1,"why":"تأتي السنة النبوية في المرتبة الثانية مباشرةً بعد القرآن."},{"type":"mcq","q":"قول النبي ﷺ: «صلّوا كما رأيتموني أصلّي» مثال على:","options":["السنة التقريرية","القياس","السنة الفعلية (المبيّنة لكيفية الصلاة)","الإجماع"],"answer":2,"why":"بيّن النبي ﷺ الصلاة بفعله العملي وأمر بالاقتداء به."},{"type":"mcq","q":"أمر القرآن الكريم بالزكاة، ثم حدّدت السنة النصاب والمقدار؛ هذا مثال على السنة:","options":["المستقلة فقط","التقريرية فقط","المخالفة للقرآن","المبيّنة والمفصّلة لمجمل القرآن"],"answer":3,"why":"السنة تفصّل ما جاء مجملًا في القرآن."}],"medium":[{"type":"mcq","q":"أقرّ النبي ﷺ أكل الضبّ على مائدته ولم يُنكره؛ هذا مثال على:","options":["السنة التقريرية","القرآن","السنة القولية","القياس"],"answer":0,"why":"موافقته وسكوته على فعل أُجري بحضرته يُسمّى سنةً تقريرية."},{"type":"mcq","q":"تحريم الجمع بين المرأة وعمتها أو خالتها مثال على السنة:","options":["القياس","المنشِئة لحكم جديد لم يُنصّ عليه في القرآن","التقريرية فقط","المؤكّدة فقط"],"answer":1,"why":"ثبت هذا التحريم بالسنة النبوية المستقلة بالتشريع."},{"type":"mcq","q":"ما الحكمة من ورود كثير من أحكام المعاملات في القرآن كـ«قواعد كلية عامة» (كالعدل والشورى ورفع الحرج)؟","options":["لأنها مؤقتة","لصعوبة الكتابة","لتكون صالحةً ومرنةً لاستيعاب مستجدات كل زمان ومكان","لأنها غير مهمة"],"answer":2,"why":"القواعد الكلية تحقق صلاحية الشريعة لكل عصر."},{"type":"tfr","q":"يمكن للمسلم معرفة عدد ركعات الظهر والمغرب والعشاء من القرآن الكريم وحده دون السنة.","answer":false,"reasons":["نعم ذُكرت الركعات بالتفصيل في الفاتحة","لا يوجد عدد محدد للركعات","جاء الأمر بالصلاة في القرآن مجملًا، وبيّنت السنة عدد الركعات والأوقات والهيئة"],"reason":2},{"type":"tfr","q":"السنة النبوية وحي من الله في معناها لقوله تعالى ﴿وما ينطق عن الهوى إن هو إلا وحي يوحى﴾.","answer":true,"reasons":["فهي محفوظة ومكملة للقرآن ولا تتعارض معه أبدًا","لأنها رأي بشري مجرد","لأنها تخالف القرآن"],"reason":0},{"type":"essay","q":"قارن بين «القرآن الكريم» و«السنة النبوية» من حيث اللفظ والمعنى والتعبّد بالتلاوة.","model":"القرآن لفظه ومعناه من الله تعالى ويُتعبّد بتلاوته في الصلاة؛ أما السنة فمعناها وحي من الله ولفظها من النبي ﷺ ولا يُتعبّد بتلاوة ألفاظها في الصلاة لكن يُعمل بأحكامها."},{"type":"essay","q":"وضّح بمثال واحد لكل نوع من أنواع السنة الثلاثة (القولية، الفعلية، التقريرية).","model":"قولية: «إنما الأعمال بالنيات». فعلية: كيفية وضوئه وصلاته وحجه ﷺ. تقريرية: إقراره الصحابة على صلاة العصر في بني قريظة أو أكل الضب على مائدته."}],"hard":[{"type":"mcq","q":"ما الردّ العلمي على من يدّعي الاكتفاء بالقرآن وترك السنة النبوية؟","options":["الصلاة بلا كيفية محددة","نعم يمكن ترك السنة","السنة خاصة بالصحابة فقط","القرآن نفسه أمر بطاعة الرسول ﷺ، ولا يمكن أداء الصلاة والزكاة والحج دون بيان السنة"],"answer":3,"why":"ترك السنة يُعطّل معظم أركان الإسلام التي أمر بها القرآن."},{"type":"mcq","q":"قول النبي ﷺ: «لا يحل مال امرئ مسلم إلا بطيب نفس منه» يُعد مع قوله تعالى ﴿ولا تأكلوا أموالكم بينكم بالباطل﴾ مثالًا على السنة:","options":["المؤكّدة والمقرّرة لحكم القرآن","المخالفة","المنشئة لحكم جديد","التقريرية"],"answer":0,"why":"الحديث يؤكد نفس الحكم المذكور في القرآن الكريم."},{"type":"mcq","q":"ما المقصود بـ«التواتر» الذي نُقل به القرآن الكريم؟","options":["نقله بالرأي","نقله جمع غفير عن جمع غفير يستحيل تواطؤهم على الكذب جيلًا بعد جيل","نقله بعد مئتي سنة","نقله شخص واحد فقط"],"answer":1,"why":"التواتر يورث العلم اليقيني القطعي بحفظ كل حرف من القرآن."},{"type":"mcq","q":"طالب وجد حديثًا منتشرًا في مجموعة واتساب دون مصدر أو سند؛ ما التصرف الشرعي والعلمي الصحيح؟","options":["تأليف حديث آخر","العمل به دون تحقق","التثبّت من صحته عبر المصادر الموثوقة قبل نشره لتجنب الكذب على النبي ﷺ","إعادة إرساله فورًا"],"answer":2,"why":"التثبّت من صحة الحديث أمانة علمية وشرعية."},{"type":"tfr","q":"لا يمكن أن يتعارض حديث صحيح ثابت مع آية محكمة من القرآن الكريم.","answer":true,"reasons":["السنة تلغي القرآن","لأن مصدرهما واحد وهو الوحي من الله تعالى، وما يُظن تعارضًا يكون تخصيصًا أو تقييدًا أو بيانًا","قد يتعارضان دائمًا"],"reason":1},{"type":"tfr","q":"حكم «تحريم أكل لحم الحمار الأهلي» ثبت بالسنة النبوية المنشئة لحكم جديد.","answer":true,"reasons":["ذُكر نصًا في الفاتحة","هو مباح","فقد نهى النبي ﷺ عن أكل لحوم الحمر الأهلية يوم خيبر"],"reason":2},{"type":"tfr","q":"تقتصر أحكام القرآن الكريم على العبادات كالصلاة والصيام ولا تشمل المعاملات والأخلاق.","answer":false,"reasons":["القرآن شامل للعقائد والعبادات والمعاملات المالية والأسرية والأخلاق","المعاملات ليست من الدين","لا توجد آيات معاملات"],"reason":0},{"type":"essay","q":"اشرح كيف تتكامل الأدوار الثلاثة للسنة مع القرآن الكريم في بناء نظام تشريعي متكامل.","model":"فما ذُكر بوضوح في القرآن تؤكده السنة، وما جاء مجملًا تفصّله السنة عمليًا (كالصلاة والزكاة)، وما استجدّ أو سكت عنه القرآن تبيّن السنة حكمه، فيكتمل البيان للأمة."},{"type":"essay","q":"اذكر مثالين لأحكام فصّلها القرآن الكريم ومثالين لأحكام جاءت مجملة ففصّلتها السنة.","model":"فصّلها القرآن: أنصبة المواريث والمحرمات من النساء. فصّلتها السنة: عدد ركعات الصلوات وأوقاتها، ومقدار ونصاب الزكاة، ومناسك الحج."},{"type":"essay","q":"لماذا يُعد «علم الحديث» من أعظم العلوم التي ابتكرتها الحضارة الإسلامية؟","model":"لأنه وضع منهجًا علميًا صارمًا لفحص الأسانيد والمتون وحفظ السنة النبوية الصحيحة نقيةً من الدس والتحريف عبر القرون."}]}},
  {"id":"g9-islamic-1-u2-6","grade":"g9","subject":"islamic","term":1,"unit":2,"no":6,"title":"سَمْت أهل عُمان (قيم وأخلاق)","summary":"شرح متحرك بـ SVG لدرس سَمْت أهل عُمان (قيم وأخلاق) للصف التاسع (سلطنة عُمان)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.","page":"lesson-omani-etiquette-and-character.html","video":"","pdf":"","notes":["السَّمت: حسن الهيئة والوقار والهدي الصالح والأدب الرفيع في القول والفعل.","أثنى النبي ﷺ على أهل عُمان: «لو أن أهل عُمان أتيتَ ما سبّوك ولا ضربوك» (رواه مسلم).","مظاهر السمت العُماني: التواضع وخفض الصوت، وتوقير الكبير، والكرم والضيافة في السبلة، والتسامح، والحشمة في الزي.","يمتد السمت العُماني إلى السلوك الرقمي عبر الكلمة الطيبة واحترام الآخرين على الإنترنت."],"exercises":["عرّف السَّمت، واذكر الحديث النبوي الذي أثنى على أخلاق أهل عُمان.","اذكر أربعة مظاهر عملية للسمت العُماني في المجالس والمدرسة.","كيف نُحافظ على السمت العُماني في عصر وسائل التواصل الاجتماعي؟"],"levels":{"easy":[{"type":"mcq","q":"يُقصد بـ«السَّمْت» في الأخلاق الإسلامية:","options":["الغضب السريع","الانعزال","المباهاة والإسراف","الوقار وحسن الهيئة والأدب الرفيع"],"answer":3,"why":"السَّمت هو الهدي الصالح والوقار والأدب."},{"type":"mcq","q":"الحديث الشريف «لو أن أهل عُمان أتيتَ ما سبّوك ولا ضربوك» رواه الإمام:","options":["مسلم","سيبويه","ابن خلدون","المتنبي"],"answer":0,"why":"الحديث ثابت في صحيح مسلم."},{"type":"mcq","q":"المكان الاجتماعي العُماني التقليدي الذي يرسّخ آداب الضيافة والحوار هو:","options":["المطار","السبلة العُمانية","المصنع","المخزن"],"answer":1,"why":"السبلة العُمانية مركز للتواصل والتشاور وتعليم الآداب."},{"type":"mcq","q":"أي سلوك يعبّر عن السمت العُماني الأصيل؟","options":["رفع الصوت في المجالس","مقاطعة المتحدثين","خفض الصوت وتوقير الكبير وإكرام الضيف","التقليد الأعمى لمظاهر غير لائقة"],"answer":2,"why":"الوقار واللطف والتواضع جوهر السمت العُماني."}],"medium":[{"type":"mcq","q":"كيف أسهم السمت العُماني قديمًا في نشر الإسلام في آسيا وشرقي أفريقيا؟","options":["برفض التعامل مع غيرهم","بإغلاق الموانئ","بالشدة والغلظة","بأمانة التجار العُمانيين ولطف معاملتهم وتسامحهم مما حبّب الناس في الإسلام"],"answer":3,"why":"القدوة الأخلاقية كانت أقوى وسيلة دعوية."},{"type":"mcq","q":"الاعتزاز بالزي العُماني المحتشم والأنيق يدل على:","options":["احترام الهوية الوطنية والوقار والالتزام بالذوق الإسلامي","التعصب","الإسراف المذموم","التخلّف عن العصر"],"answer":0,"why":"الهوية والأصالة والوقار لا تتعارض أبدًا مع التطور والعصرنة."},{"type":"mcq","q":"أي عبارة تلخّص علاقة «السَّمت العُماني» بالتعاليم الإسلامية؟","options":["عادات مؤقتة فقط","مستمدّ مباشرةً من قيم الإسلام في التواضع والرحمة والكرم وحسن الخلق","منفصل تمامًا عن الإسلام","خاص بالماضي فقط"],"answer":1,"why":"تشكّلت الشخصية العُمانية بامتزاج الأصالة العربية بقيم الإسلام."},{"type":"tfr","q":"التسامح ولين الجانب في السمت العُماني دليل ضعف وتنازل عن الكرامة.","answer":false,"reasons":["نعم دليل ضعف","بل هو دليل قوة أخلاقية وثقة بالنفس وتحضر مستمد من هدي النبي ﷺ","القوة في الفظاظة فقط"],"reason":1},{"type":"tfr","q":"حرص الآباء على اصطحاب أبنائهم إلى السبلة العُمانية ينقل الآداب والسمت عمليًا للأجيال.","answer":true,"reasons":["السبلة لكبار السن فقط","لا فائدة من حضور الصغار","فيتعلم الأبناء بالمشاهدة والممارسة آداب السلام والإنصات والضيافة"],"reason":2},{"type":"essay","q":"اذكر أربعة آداب يتحلّى بها الطالب العُماني داخل المدرسة تعكس السمت الأصيل.","model":"١) احترام المعلمين والإنصات لهم. ٢) خفض الصوت وتجنب الألفاظ النابية. ٣) المحافظة على نظافة المدرسة ومظهره المحتشم. ٤) مساعدة الزملاء والتسامح معهم."},{"type":"essay","q":"علّل: لماذا يحظى الإنسان العُماني بسمعة طيبة واحترام واسع عند سفره لدول العالم؟","model":"لالتزامه بالقوانين، ولطف تعامله، وهدوئه، وتسامحه، وحسن تمثيله لدينه ووطنه."}],"hard":[{"type":"mcq","q":"في موقف خلافي ساخن على مجموعة إلكترونية، كيف يتصرف الشاب المتحلّي بالسمت العُماني؟","options":["يرد بالإساءة والشتم","يسخر من المخالف","يلتزم بالحوار الهادئ المحترم أو يعتذر عن الجدل العقيم دون إساءة لأحد","ينشر أسرار الآخرين"],"answer":2,"why":"ضبط النفس وأدب الحوار من أرفع مظاهر السمت."},{"type":"mcq","q":"ما الفرق بين «الكرم المحمود» في السمت العُماني و«الإسراف المذموم»؟","options":["الإسراف واجب في الضيافة","لا فرق بينهما","الكرم يعني إهدار الطعام","الكرم بذل بطيب نفس بقدر الحاجة ودون تبذير، أما الإسراف فمباهاة وإهدار للنعم نهى الله عنه"],"answer":3,"why":"الإسلام يمدح الكرم وينهي عن الإسراف والتبذير."},{"type":"mcq","q":"ارتباط السمت العُماني بـ«تعلّم العلوم والأخبار» في بداية المجالس يهدف إلى:","options":["الاطمئنان على أحوال الناس والمجتمع وتقوية الترابط والتكافل","التدخل في خصوصيات الآخرين","الغيبة والنميمة","إضاعة الوقت"],"answer":0,"why":"«الأخبار» التقليدية تهدف للاطمئنان والتراحم والتكافل دون غيبة."},{"type":"mcq","q":"كيف نوفّق بين «الانفتاح على ثقافات العالم» و«الحفاظ على السمت العُماني»؟","options":["ننعزل عن العالم","نستفيد من علوم وتقنيات العالم النافعة مع التمسك الراسخ بقيمنا وأخلاقنا وهويتنا","نقلّد كل شيء بلا تمييز","نرفض التكنولوجيا والعلم"],"answer":1,"why":"الأصالة والمعاصرة تتكاملان دون ذوبان الهوية."},{"type":"tfr","q":"حفظ اللسان عن السبّ والغيبة من أوضح العلامات التي أثنى بها النبي ﷺ على أهل عُمان.","answer":true,"reasons":["لقوله ﷺ «ما سبّوك ولا ضربوك»، مما يحثّنا على صون هذا الشرف النبوي","المزاح بالسب مقبول","لا علاقة لحفظ اللسان بالحديث"],"reason":0},{"type":"tfr","q":"الابتسامة الصادقة ولطف الترحيب بالضيف جزء لا يتجزأ من السمت والضيافة العُمانية.","answer":true,"reasons":["لا أهمية للبشاشة","فتبسّمك في وجه أخيك صدقة، والبشاشة نصف الضيافة","الوقار يعني العبوس الدائم"],"reason":1},{"type":"tfr","q":"يختص السمت العُماني بكبار السن فقط ولا يُطالب به الشباب والطلاب.","answer":false,"reasons":["نعم خاص بالكبار فقط","الشباب غير معنيين به","السمت والأدب الرفيع زينة لكل الأعمار، والشباب هم حملة هذه الرسالة للمستقبل"],"reason":2},{"type":"essay","q":"اقترح ميثاقًا من ٤ بنود بعنوان «سمتنا في العالم الرقمي» لطلاب مدرستك.","model":"١) أكتب ما يرضي الله ويحفظ كرامة الناس. ٢) أحاور بهدوء وأتجنب السخرية والتنمر. ٣) أتثبت من الأخبار قبل نشرها. ٤) أمثّل ديني ووطني عُمان بأرقى أسلوب."},{"type":"essay","q":"بيّن أثر التمسك بالسمت العُماني في تعزيز السياحة والانطباع الإيجابي عن سلطنة عُمان.","model":"الزائر يتذكر قبل كل شيء لطف الناس وأمانتهم وكرمهم واحترامهم، وهو ما يجعل عُمان وجهةً مفضلةً ومحبوبةً عالميًا."},{"type":"essay","q":"اشرح كيف يجمع السمت العُماني بين «عزة النفس» و«التواضع».","model":"التواضع يعني لين الجانب وعدم الكبر على الناس، وعزة النفس تعني صون الكرامة والأخلاق وعدم التذلل للباطل؛ فكلاهما يكمل الآخر في شخصية المؤمن العُماني."}]}},
  {"id":"g9-islamic-1-u3-1","grade":"g9","subject":"islamic","term":1,"unit":3,"no":1,"title":"التقاء الساكنين (٢) — تجويد","summary":"شرح متحرك بـ SVG لدرس التقاء الساكنين (٢) — تجويد للصف التاسع (سلطنة عُمان)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.","page":"lesson-meeting-of-two-sakins-2.html","video":"","pdf":"","notes":["في كلمتين لا يُغتفر التقاء الساكنين؛ ونتخلص منه بالحذف (إن كان الأول حرف مد) أو بالتحريك.","الحذف لفظًا لا خطًا: ﴿إِذَا الشَّمْسُ﴾، ﴿فِي الْأَرْضِ﴾، ﴿وَقَالُوا الْحَمْدُ﴾.","التحريك بالكسر (الأصل): الصحيح والتنوين مثل ﴿قُلِ ادْعُوا﴾ و﴿أَحَدٌ اللَّهُ﴾.","التحريك بالفتح: «مِنْ» الجارة ﴿مِنَ اللَّهِ﴾. والتحريك بالضم: ميم الجمع ﴿لَهُمُ الْبُشْرَىٰ﴾ وواو اللين للجمع ﴿اشْتَرَوُا الضَّلَالَةَ﴾."],"exercises":["بيّن طريقة التخلص من التقاء الساكنين في: ﴿وَقَالُوا اتَّخَذَ﴾، ﴿قُمِ اللَّيْلَ﴾، ﴿مِنَ الشَّاهِدِينَ﴾، ﴿لَهُمُ الْبُشْرَىٰ﴾.","قارن بين ﴿قَالُوا الْحَمْدُ﴾ و﴿فَتَمَنَّوُا الْمَوْتَ﴾ في طريقة التخلص من الساكنين.","كيف نقرأ ﴿أَحَدٌ اللَّهُ﴾ عند الوصل؟"],"levels":{"easy":[{"type":"mcq","q":"التخلّص من التقاء الساكنين في ﴿إِذَا الشَّمْسُ﴾ عند الوصل يكون بـ:","options":["كسر الألف","ضم الألف","حذف الألف المدية لفظًا لا خطًا","مدها ٦ حركات"],"answer":2,"why":"الألف حرف مد فيُحذف لفظًا عند الوصل."},{"type":"mcq","q":"في قوله تعالى ﴿مِنَ الْجِنَّةِ﴾ حُرّكت نون «مِنْ» بـ:","options":["الضم","السكون","الكسر","الفتح"],"answer":3,"why":"نون «مِنْ» الجارة تُحرّك بالفتح دائمًا عند التقاء الساكنين."},{"type":"mcq","q":"في قوله تعالى ﴿أَنتُمُ الْفُقَرَاءُ﴾ حُرّكت ميم الجمع بـ:","options":["الضم","الحذف","الكسر","الفتح"],"answer":0,"why":"ميم الجمع تُحرّك بالضم."},{"type":"mcq","q":"في قوله تعالى ﴿قُلِ اللَّهُمَّ﴾ حُرّكت اللام بـ:","options":["الضم","الكسر (على الأصل)","الفتح","الحذف"],"answer":1,"why":"الأصل في تحريك الساكن الصحيح هو الكسر."}],"medium":[{"type":"mcq","q":"كيف نتخلص من التقاء الساكنين في قوله ﴿اشْتَرَوُا الضَّلَالَةَ﴾؟","options":["بحذف الواو لفظًا","بمدها ٦ حركات","بتحريك واو اللين بالضم","بكسر الواو"],"answer":2,"why":"واو اللين للجمع (قبلها فتح) تُحرّك بالضم ولا تُحذف."},{"type":"mcq","q":"عند وصل ﴿قُلْ هُوَ اللَّهُ أَحَدٌ ۝ اللَّهُ الصَّمَدُ﴾ نتخلّص من التقاء نون التنوين بلام لفظ الجلالة عن طريق:","options":["فتح التنوين","حذف التنوين","ضم التنوين","كسر نون التنوين (أَحَدُنِ اللَّهُ)"],"answer":3,"why":"التنوين نون ساكنة فيُحرّك بالكسر على الأصل."},{"type":"mcq","q":"ماذا يحدث للياء في ﴿فِي الْأَرْضِ﴾ إذا وقف القارئ اضطرارًا على كلمة ﴿فِي﴾؟","options":["تُثبت الياء وتُمدّ مدًّا طبيعيًا حركتين لزوال التقاء الساكنين","تُضم","تُكسر","تبقى محذوفة"],"answer":0,"why":"الحذف يكون في الوصل فقط، أما الوقف فيثبت حرف المد."},{"type":"tfr","q":"يُحذف حرف المد في ﴿فِي السَّمَاءِ﴾ خطًا من المصحف ولفظًا في القراءة.","answer":false,"reasons":["يُحذف «لفظًا فقط» عند الوصل، ويبقى مكتوبًا في رسم المصحف","يُحذف من المصحف","لا يُحذف لفظًا"],"reason":0},{"type":"tfr","q":"حركة التاء في قوله تعالى ﴿قَالَتِ امْرَأَتُ﴾ هي الكسر للتخلّص من التقاء الساكنين.","answer":true,"reasons":["لأنها مجرورة","أصلها «قالتْ» ساكنة فحُرّكت بالكسر على الأصل عند وصلها بساكن","حركتها الضم"],"reason":1},{"type":"essay","q":"اذكر ثلاث حالات مختلفة لتحريك الساكن الأول (بالكسر، بالفتح، بالضم) مع مثال قرآني لكل حالة.","model":"بالكسر: ﴿قُلِ ادْعُوا﴾. بالفتح: ﴿مِنَ اللَّهِ﴾. بالضم: ﴿عَلَيْكُمُ الصِّيَامُ﴾."},{"type":"essay","q":"لماذا حُذفت الواو لفظًا في ﴿قَالُوا الْحَمْدُ﴾ بينما ضُمّت في ﴿فَتَمَنَّوُا الْمَوْتَ﴾؟","model":"لأن الواو في ﴿قالوا﴾ حرف مد (قبلها ضم) فتُحذف لفظًا؛ أما في ﴿فتمنّوا﴾ فهي واو لين (قبلها فتح) فتُحرّك بالضم."}],"hard":[{"type":"mcq","q":"في قوله تعالى ﴿عَنِ النَّبَإِ﴾ و﴿مِنَ النَّاسِ﴾، ما حركة النون في الكلمتين على الترتيب؟","options":["الكسر في كليهما","الكسر في «عَنِ»، والفتح في «مِنَ»","الفتح في كليهما","الضم في كليهما"],"answer":1,"why":"«عنْ» تُكسر على الأصل، أما «مِنْ» فتُفتح للتخفيف وكثرة دورانها."},{"type":"mcq","q":"في قوله تعالى ﴿وَقَالَتَا أَتَيْنَا﴾ (عند الوصل بساكن كـ ﴿ذَاقَا الشَّجَرَةَ﴾)، كيف يُقرأ الألف في ﴿ذَاقَا الشَّجَرَةَ﴾؟","options":["تُضم","تُكسر الألف","تُحذف ألف التثنية لفظًا وتبقى الفتحة دليلًا عليها","تُمدّ ٦ حركات"],"answer":2,"why":"الألف حرف مد فيُحذف لفظًا في الوصل عند التقاء الساكنين."},{"type":"mcq","q":"في قوله تعالى ﴿خَيْرًا الْوَصِيَّةُ﴾، كيف تُقرأ «خيرًا» عند وصلها بـ«الوصية»؟","options":["خَيْرَا الْوَصِيَّةُ","بمد الألف","خَيْرُنُ الْوَصِيَّةُ","خَيْرَنِ الْوَصِيَّةُ (بكسر نون التنوين)"],"answer":3,"why":"تنوين الفتح نون ساكنة تُكسر عند التقائها بساكن."},{"type":"mcq","q":"أي مثال مما يلي ليس فيه التقاء ساكنين في كلمتين؟","options":["﴿إِنَّ اللَّهَ﴾","﴿فِي اللَّهِ﴾","﴿قُلِ اللَّهُ﴾","﴿مِنَ اللَّهِ﴾"],"answer":0,"why":"النون المشددة في ﴿إنَّ﴾ مفتوحة وليست ساكنةً في آخرها."},{"type":"tfr","q":"عند وصل ﴿الم﴾ بأول آل عمران ﴿اللَّهُ لَا إِلَٰهَ إِلَّا هُوَ﴾ تُحرّك الميم بالفتح للتخلص من التقاء الساكنين.","answer":true,"reasons":["تُحرّك بالكسر","تُحذف الميم","وتُمدّ الياء قبلها إما ٦ حركات (اعتدادًا بالأصل) أو حركتين (اعتدادًا بالفتح العارض)"],"reason":2},{"type":"tfr","q":"همزة الوصل في بداية الكلمة الثانية تُسقط في الدَّرْج (الوصل) مما يؤدي لالتقاء الساكنين.","answer":true,"reasons":["مثل «الـ» التعريف فتسقط همزة الوصل وتلتقي اللام الساكنة بآخر الكلمة الأولى","تُثبت همزة الوصل دائمًا","تُحذف الكلمة الأولى"],"reason":0},{"type":"tfr","q":"حركة التخلص من التقاء الساكنين في ﴿أَوِ انقُصْ﴾ هي الضم.","answer":false,"reasons":["تُحذف الواو","حركتها الكسر على الأصل ﴿أَوِ انقُصْ﴾ لأنها ليست واو جمع بل حرف عطف","نعم الضم"],"reason":1},{"type":"essay","q":"قارن بين التقاء الساكنين في «كلمة واحدة» (الدرس السابق) والتقاء الساكنين في «كلمتين» (هذا الدرس) من حيث الحكم.","model":"في كلمة واحدة: جائز ومُغتفر (في المد اللازم ٦ حركات، وعند الوقف في العارض واللين والساكن الصحيح). في كلمتين: لا يُغتفر عند الوصل ونتخلّص منه بحذف حرف المد لفظًا أو تحريك الساكن الصحيح."},{"type":"essay","q":"بيّن كيف تقرأ الآية: ﴿فَإِنِ انْتَهَوْا فَإِنَّ اللَّهَ غَفُورٌ رَّحِيمٌ﴾ مع تحديد موضع التقاء الساكنين وطريقة التخلص.","model":"في ﴿فَإِنِ انْتَهَوْا﴾: التقت نون «إنْ» الساكنة بنون «انتهوا» الساكنة بعد سقوط همزة الوصل، فتخلّصنا منه بكسر نون «فَإِنِ» على الأصل."},{"type":"essay","q":"أعطِ مثالين من حفظك للقرآن على التخلص من التقاء الساكنين بالحذف، ومثالين بالتحريك.","model":"بالحذف: ﴿فِي الْأَرْضِ﴾، ﴿إِذَا الشَّمْسُ﴾. بالتحريك: ﴿قُلِ اللَّهُمَّ﴾ (كسر)، ﴿مِنَ اللَّهِ﴾ (فتح) أو ﴿لَهُمُ الْبُشْرَىٰ﴾ (ضم)."}]}},
  {"id":"g9-islamic-1-u3-2","grade":"g9","subject":"islamic","term":1,"unit":3,"no":2,"title":"سورة الحِجر (٨٧–٩٩) — تفسير","summary":"شرح متحرك بـ SVG لدرس سورة الحِجر (٨٧–٩٩) — تفسير للصف التاسع (سلطنة عُمان)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.","page":"lesson-surah-al-hijr-87-99.html","video":"","pdf":"","notes":["السبع المثاني: سورة الفاتحة (سبع آيات تُكرّر في كل ركعة)، وهي أعظم من متاع الدنيا.","﴿واخفض جناحك للمؤمنين﴾: أمر بالتواضع والرفق وحسن المعاملة.","﴿فاصدع بما تؤمر﴾: الجهر بالحق وتبليغه بوضوح، مع كفاية الله للمستهزئين.","علاج ضيق الصدر: التسبيح بحمد الله والسجود والصلاة، والمداومة على العبادة حتى اليقين (الموت)."],"exercises":["ما معنى المفردات الآتية: السبع المثاني، عِضِين، فاصدع، اليقين؟","استخرج من الآيتين ٩٧–٩٨ وصفةً عمليةً لعلاج ضيق الصدر.","لماذا نهى الله عن مدّ العين إلى ما مُتّع به غيرنا من زينة الدنيا؟"],"levels":{"easy":[{"type":"mcq","q":"المقصود بـ«السَّبع المثاني» في سورة الحجر هو:","options":["سورة الإخلاص","سورة الفاتحة","سورة الناس","سورة الكوثر"],"answer":1,"why":"الفاتحة سبع آيات تُثنّى في كل صلاة."},{"type":"mcq","q":"معنى «فَاصْدَعْ بِمَا تُؤْمَرُ» هو:","options":["سافر ليلًا","اسكت عن الحق","اجهر بالحق وأعلنه بوضوح","أخفِ الدعوة"],"answer":2,"why":"الصدع هو الإعلان الصريح الواضح للحق."},{"type":"mcq","q":"معنى «عِضِين» في قوله ﴿الذين جعلوا القرآن عضين﴾ هو:","options":["نورًا مبينًا","كتابًا واحدًا","حفظةً للقرآن","أجزاءً متفرقةً يؤمنون ببعضه ويكفرون ببعضه"],"answer":3,"why":"جعلوه أعضاءً وأجزاءً متفرقةً بالانتقاء أو الافتراء."},{"type":"mcq","q":"المقصود بـ«اليقين» في قوله ﴿واعبد ربك حتى يأتيك اليقين﴾ هو:","options":["الموت","السفر","النجاح","الشيخوخة"],"answer":0,"why":"العبادة مستمرة طوال حياة المسلم حتى الموت."}],"medium":[{"type":"mcq","q":"لماذا قرن الله النهي عن مدّ العين لزينة الدنيا ببيان نعمة «السبع المثاني والقرآن العظيم»؟","options":["لا علاقة بين الآيتين","لأن من أُعطي القرآن فقد أُعطي أعظم كنز يُغنيه عن التعلق بمتاع الدنيا الزائل","لأن الفقير لا يقرأ القرآن","لأن الدنيا أهم من القرآن"],"answer":1,"why":"القرآن أعظم نعمة تملأ القلب غنىً وقناعةً."},{"type":"mcq","q":"الآية ﴿ولقد نعلم أنك يضيق صدرك بما يقولون﴾ تدل على:","options":["الرد بالمثل والشتم","أن النبي لا يشعر بضيق أبدًا","مواساة الله وتأنيسه لنبيه ﷺ وإقرار أن التأثر النفسي بالكلام المؤذي أمر بشري طبيعي","ترك الدعوة عند الأذى"],"answer":2,"why":"المواساة الإلهية تسبق التوجيه العملي للعلاج."},{"type":"mcq","q":"الردّ الأمثل على من يظن أن الإنسان إذا بلغ منزلةً عاليةً في الإيمان سقطت عنه الصلاة والعبادة هو قوله تعالى:","options":["﴿فاصدع بما تؤمر﴾","﴿واخفض جناحك﴾","﴿إنا كفيناك المستهزئين﴾","﴿واعبد ربك حتى يأتيك اليقين﴾"],"answer":3,"why":"العبادة لا تسقط عن المكلف العاقل أبدًا حتى الموت."},{"type":"tfr","q":"سُمّيت سورة الفاتحة بـ«المثاني» لأنها تُثنّى وتُكرّر قراءتها في كل ركعة من الصلاة.","answer":true,"reasons":["لأنها آيتان فقط","لأنها تُقرأ مرتين في السنة فقط","وهي سبع آيات مباركات لا تصح الصلاة إلا بها"],"reason":2},{"type":"tfr","q":"يجوز للمسلم أن يأخذ من أحكام القرآن ما يوافق هواه ويترك ما لا يعجبه.","answer":false,"reasons":["هذا من فعل «المقتسمين الذين جعلوا القرآن عضين» المذموم في الآيات","نعم يجوز الانتقاء","لا بأس بترك بعض الأحكام"],"reason":0},{"type":"essay","q":"اذكر ثلاثة توجيهات ربانية في خواتيم سورة الحجر (٨٧–٩٩) لبناء شخصية المؤمن القوية.","model":"١) الغنى بالقرآن وعدم التعلق بمظاهر الدنيا. ٢) التواضع ولين الجانب مع المؤمنين والصدع بالحق. ٣) اللجوء للتسبيح والسجود عند ضيق الصدر والمداومة على العبادة حتى الموت."},{"type":"essay","q":"كيف يعالج التسبيح والسجود ضيق الصدر نفسيًا وروحيًا؟","model":"يربطان القلب بالله القوي الرحيم، ويصرفان التفكير عن أذى الناس، ويملآن النفس سكينةً وثقةً برعاية الله."}],"hard":[{"type":"mcq","q":"قوله تعالى ﴿إنا كفيناك المستهزئين﴾ يبثّ في نفس الداعي والمصلح:","options":["الثقة بنصر الله وحمايته وعدم الانشغال بالردود العقيمة على الساخرين","التوقف عن قول الحق","الانشغال بالانتقام","الخوف من الناس"],"answer":0,"why":"وعد الله بالكفاية يفرّغ قلب المؤمن للعمل البنّاء."},{"type":"mcq","q":"ما دلالة تقديم «التسبيح بالحمد» ثم «السجود» في الآية ٩٨؟","options":["السجود بلا ذكر","الجمع بين الذكر القلبي واللساني وبين العبادة العملية (الصلاة) التي هي أقرب موضع للعبد من ربه","التسبيح مرة واحدة","الاختيار بينهما فقط"],"answer":1,"why":"أقرب ما يكون العبد من ربه وهو ساجد، فيجتمع الذكر والقرب."},{"type":"mcq","q":"التحذير في قوله ﴿فوربك لنسألنهم أجمعين عما كانوا يعملون﴾ يغرس في النفس:","options":["اليأس","اللامبالاة","استشعار المسؤولية الفردية والمحاسبة أمام الله عن كل قول وعمل","إلقاء اللوم على الآخرين"],"answer":2,"why":"كل إنسان مسؤول أمام الله عن عمله يوم القيامة."},{"type":"mcq","q":"في حياتك المدرسية، متى تحتاج لتطبيق ﴿وأعرض عن المشركين﴾ (بمعنى الإعراض عن الجاهلين والمستهزئين)؟","options":["عندما يسألك زميلك عن درس","عندما ينصحك معلمك","عند نصيحة والديك","عندما يحاول أحد استفزازك بالسخرية لتعطيلك عن دراستك أو التزامك"],"answer":3,"why":"الإعراض الحليم عن المستفزين يحفظ وقتك ووقارك."},{"type":"tfr","q":"تُظهر الآية ٨٨ أن النعم المادية في الدنيا لا تُقارن بنعمة الهداية والقرآن الكريم.","answer":true,"reasons":["المال أعظم من القرآن","فقد نهاه عن مدّ عينيه لمتاع الدنيا بعد أن امتنّ عليه بالسبع المثاني والقرآن العظيم","لا فرق بينهما"],"reason":1},{"type":"tfr","q":"الصدع بالحق يعني القسوة والغلظة في معاملة المؤمنين.","answer":false,"reasons":["الصدع يعني الصراخ دائمًا","التواضع يمنع الصدع بالحق","بل جمع الله بين «واخفض جناحك للمؤمنين» بالرفق واللين وبين «فاصدع بما تؤمر» بالوضوح والثبات"],"reason":2},{"type":"tfr","q":"أجمع المفسرون أن «اليقين» في قوله ﴿واعبد ربك حتى يأتيك اليقين﴾ هو الموت.","answer":true,"reasons":["ومنه قوله تعالى ﴿وكنا نكذب بيوم الدين حتى أتانا اليقين﴾","المقصود به السفر","المقصود به التخرج من المدرسة"],"reason":0},{"type":"essay","q":"اشرح كيف توازن بين «الصدع بالحق» و«خفض الجناح» في تعاملك مع زملائك.","model":"أكون واضحًا وثابتًا في مبادئي وأقول الحق بأدب دون مجاملة على باطل، وفي الوقت نفسه أتعامل مع زملائي بتواضع ولطف ورحمة بلا تعالٍ."},{"type":"essay","q":"استنبط من الآيات (٨٧–٩٩) أربع صفات للقرآن الكريم أو واجبات تجاهه.","model":"١) عظمته ومكانته (والقرآن العظيم). ٢) تكرار الفاتحة في الصلاة. ٣) أخذه كاملًا وعدم تجزئته. ٤) الاستغناء به عن حسد أهل الدنيا."},{"type":"essay","q":"اكتب خطة قصيرة من ٣ خطوات لتطبيق وصية ﴿واعبد ربك حتى يأتيك اليقين﴾ طوال العام الدراسي والعطلة.","model":"١) المحافظة على الصلوات الخمس في أوقاتها دائمًا. ٢) ورد يومي ثابت من القرآن والتسبيح لا ينقطع. ٣) تجديد النية في الدراسة وبر الوالدين لتكون كلها عبادة."}]}},
  {"id":"g9-islamic-1-u3-3","grade":"g9","subject":"islamic","term":1,"unit":3,"no":3,"title":"أكبر الكبائر (حديث شريف)","summary":"شرح متحرك بـ SVG لدرس أكبر الكبائر (حديث شريف) للصف التاسع (سلطنة عُمان)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.","page":"lesson-greatest-major-sins.html","video":"","pdf":"","notes":["الحديث عن أبي بكرة: «ألا أنبئكم بأكبر الكبائر؟ الإشراك بالله، وعقوق الوالدين، ألا وقول الزور وشهادة الزور».","الإشراك بالله أعظم الذنوب لأنه اعتداء على حق الخالق، وعقوق الوالدين اعتداء على حق الأسرة.","جلس النبي ﷺ وكرّر التحذير من قول وشهادة الزور لكثرة تساهل الناس فيها وعظم أثرها في ضياع الحقوق والعدالة.","من صور الزور المعاصرة: تزوير الشهادات والتواقيع، والشهادة الكاذبة لمجاملة قريب، وفبركة الشائعات الرقمية."],"exercises":["علّل: جلس النبي ﷺ وكرّر «ألا وقول الزور» رغم أن الشرك بالله أعظم منها.","اذكر ثلاث صور لعقوق الوالدين وثلاث صور لبرّهما في حياة الطالب.","عدّد صورتين معاصرتين لقول وشهادة الزور وكيف تحاربهما."],"levels":{"easy":[{"type":"mcq","q":"راوي حديث «أكبر الكبائر» هو الصحابي:","options":["أبو بكرة نفيع بن الحارث رضي الله عنه","أنس بن مالك","أبو هريرة","ابن عباس"],"answer":0,"why":"روى الحديث أبو بكرة رضي الله عنه في الصحيحين."},{"type":"mcq","q":"أكبر الذنوب وأعظم الظلم على الإطلاق هو:","options":["قلة المال","الإشراك بالله","التأخر عن الموعد","النسيان"],"answer":1,"why":"قال تعالى: ﴿إن الشرك لظلم عظيم﴾."},{"type":"mcq","q":"تُسمّى الإدلاء بشهادة كاذبة لتضييع حق بريء:","options":["التواضع","الشهادة العادلة","شهادة الزور","الإجمال"],"answer":2,"why":"شهادة الزور من أكبر الكبائر."},{"type":"mcq","q":"الحق الذي يحفظه النهي عن «عقوق الوالدين» هو حق:","options":["الطرق","المحاكم فقط","التجارة","الأسرة والوالدين"],"answer":3,"why":"برّ الوالدين أساس تماسك الأسرة ورضا الله."}],"medium":[{"type":"mcq","q":"قول الصحابة «حتى قلنا ليته سكت» يدل على:","options":["شدة شفقتهم ومحبتهم للنبي ﷺ لما رأوه من تأثره وغضبه لله","رغبتهم في الانصراف","عدم اهتمامهم","ضيقهم من سماع العلم"],"answer":0,"why":"أشفقوا عليه ﷺ من شدة انفعاله واهتمامه بتحذير الأمة."},{"type":"mcq","q":"طالب شهد زورًا لصالح صديقه الذي كسر جهاز المختبر لكي لا يُعاقب؛ هذا السلوك:","options":["أمر بسيط مباح","شهادة زور محرّمة ومن أكبر الكبائر ولا تجوز لمجاملة صديق","شجاعة","وفاء للصداقة"],"answer":1,"why":"الصداقة الحقيقية لا تكون بالباطل ولا بتضييع الحقوق."},{"type":"mcq","q":"كيف يُصلح من شهد زورًا توبته؟","options":["بإنكار شهادته فقط","لا توبة له","بالندم والاستغفار، والرجوع عن شهادته الكاذبة، وردّ الحق للمظلوم","بالاستغفار سرًا مع بقاء الظلم"],"answer":2,"why":"التوبة من حقوق العباد تشترط ردّ المظلمة لأهلها."},{"type":"tfr","q":"الكبائر تُكفّر بالوضوء وحده دون حاجة إلى التوبة النصوح.","answer":false,"reasons":["نعم يكفي الوضوء","الكبائر تحتاج إلى توبة نصوح صادقة وردّ الحقوق إن تعلّقت بالعباد","لا تحتاج توبة"],"reason":1},{"type":"tfr","q":"جمع الحديث الشريف بين حفظ حق الله (التوحيد) وحق الأسرة (الوالدين) وحق المجتمع (العدل والصدق).","answer":true,"reasons":["ذكر حق الله فقط","ذكر حقوق المال فقط","لأن هذه الحقوق الثلاثة هي أعمدة صلاح الدنيا والآخرة"],"reason":2},{"type":"essay","q":"بيّن الحكمة من الأسلوب التعليمي للنبي ﷺ في حديث «أكبر الكبائر» (السؤال، التكرار، الجلوس).","model":"السؤال «ألا أنبئكم» يشد الانتباه، والتكرار يؤكد عظم الأمر، والانتقال من الاتكاء إلى الجلوس مع تكرار الزور يبرز خطورته الشديدة ويحفر التحذير في القلوب."},{"type":"essay","q":"اذكر أربعة مظاهر عملية لبرّ الوالدين يحرص عليها طالب الصف التاسع يوميًا.","model":"١) طاعتهما في المعروف وخفض الصوت أمامهما. ٢) تلبية ندائهما فورًا وترك الهاتف عند حديثهما. ٣) مساعدتهما في شؤون البيت. ٤) الدعاء لهما وشكرهما."}],"hard":[{"type":"mcq","q":"لماذا قد يقع بعض الناس في شهادة الزور أكثر من وقوعهم في الشرك الصريح؟","options":["لأن الزور حلال","لأن الزور لا يضر أحدًا","لأن الشرك أسهل","لأن الشرك تنفر منه فطرة المسلم، بينما قد تغلب العاطفة أو القرابة أو الطمع فيُتساهل في الكذب والزور"],"answer":3,"why":"وهذا هو سرّ تأكيد النبي ﷺ الشديد وتكراره للتحذير من الزور."},{"type":"mcq","q":"استخدام برامج التعديل لفبركة محادثة أو صورة مسيئة عن شخص بريء ونشرها يُعد:","options":["صورةً رقميةً خطيرةً لقول وشهادة الزور والبهتان","أمرًا عاديًا","مهارة إيجابية","مزاحًا تقنيًا مباحًا"],"answer":0,"why":"تزوير الأدلة الرقمية أذى عظيم وزور محرّم."},{"type":"mcq","q":"قال تعالى: ﴿كونوا قوامين بالقسط شهداء لله ولو على أنفسكم أو الوالدين والأقربين﴾. ماذا تقرر هذه الآية؟","options":["جواز الكذب لأجل القريب","وجوب الصدق والعدل في الشهادة حتى لو كانت ضد قريب أو صديق","ترك الشهادة دائمًا","عقوق الوالدين"],"answer":1,"why":"العدل والصدق في الشهادة فوق كل مجاملة أو قرابة."},{"type":"mcq","q":"ما أثر انتشار شهادة الزور وتزوير الشهادات على المجتمع؟","options":["زيادة الأمان","تطور الاقتصاد","انهيار الثقة والعدالة، وتولّي غير الأكفاء، وضياع حقوق المظلومين","قوة القضاء"],"answer":2,"why":"الزور يهدم العدل ويفسد مؤسسات المجتمع."},{"type":"tfr","q":"لا يُعد «تزوير توقيع ولي الأمر» على ورقة مدرسية من صور الزور لأنه أمر بسيط.","answer":false,"reasons":["بل هو تزوير وكذب متعمد يدخل في عموم الزور المحرم ويفسد الأمانة","نعم جائز للطلاب","ليس كذبًا"],"reason":0},{"type":"tfr","q":"طاعة الوالدين واجبة في كل معروف، ولا طاعة لمخلوق في معصية الخالق (كشهادة الزور) مع بقاء الإحسان واللطف بهما.","answer":true,"reasons":["نطيعهما في الحرام","لقوله تعالى ﴿وصاحبهما في الدنيا معروفًا﴾ فلا نطيعهما في الحرام لكن نبقى بارّين لطيفين بهما","نغلظ لهما القول"],"reason":1},{"type":"tfr","q":"استشعار مراقبة الله في السر والعلن هو أعظم وازع يمنع المسلم من الوقوع في الكبائر الثلاث.","answer":true,"reasons":["لا أثر للتقوى","الرقابة البشرية وحدها تكفي","فالتقوى تحفظ التوحيد وتدفع لبر الوالدين وتمنع الكذب والزور"],"reason":2},{"type":"essay","q":"قارن بين أثر «التوحيد وبر الوالدين والصدق» وأثر «الشرك والعقوق والزور» على استقرار المجتمع.","model":"الأولى تبني مجتمعًا متماسكًا عادلًا مطمئنًا تسوده الرحمة والثقة؛ والثانية تهدم القيم وتفكك الأسر وتضيع الحقوق وتنشر الظلم."},{"type":"essay","q":"لو طلب منك صديق مقرب أن تشهد معه بكلام غير صحيح ضد زميل آخر، كيف تردّ عليه بأدب وحزم؟","model":"أعتذر له بوضوح ولطف وأذكّره أن شهادة الزور من أكبر الكبائر، وأن الصداقة الحقيقية تعني أن أنصحه بالحق لا أن أعينه على الظلم."},{"type":"essay","q":"اذكر شروط التوبة النصوح من الكبائر مع بيان الشرط الإضافي إذا تعلّقت بحقوق الناس.","model":"١) الإقلاع فورًا عن الذنب. ٢) الندم الصادق. ٣) العزم على عدم العودة. والشرط الرابع الخاص بحقوق العباد: ردّ الحقوق لأصحابها أو طلب المسامحة منهم."}]}},
  {"id":"g9-islamic-1-u3-4","grade":"g9","subject":"islamic","term":1,"unit":3,"no":4,"title":"من مصادر التشريع الإسلامي (٢) — فقه","summary":"شرح متحرك بـ SVG لدرس من مصادر التشريع الإسلامي (٢) — فقه للصف التاسع (سلطنة عُمان)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.","page":"lesson-sources-of-islamic-law-2.html","video":"","pdf":"","notes":["الإجماع: اتفاق جميع المجتهدين من أمة محمد ﷺ بعد وفاته على حكم شرعي، وهو حجة قاطعة.","من أمثلة الإجماع: جمع القرآن الكريم في مصحف واحد، وميراث الجدة السدس.","القياس: إلحاق فرع لم يرد فيه نص بأصل ورد فيه نص في الحكم لاشتراكهما في العلة.","أركان القياس الأربعة: الأصل، الفرع، حكم الأصل، والعلة (مثل قياس المخدرات على الخمر بعلة الإسكار)."],"exercises":["عرّف كلًا من الإجماع والقياس مع مثال واحد لكل منهما.","حدّد أركان القياس الأربعة في مثال: «قياس تحريم الإجارة وقت النداء الثاني لصلاة الجمعة على تحريم البيع».","علّل: يُعد القياس دليلًا على صلاحية الشريعة الإسلامية لكل زمان ومكان."],"levels":{"easy":[{"type":"mcq","q":"اتفاق جميع المجتهدين من الأمة بعد وفاة النبي ﷺ على حكم شرعي يُسمّى:","options":["الاجتهاد الفردي","القياس","الاستحسان","الإجماع"],"answer":3,"why":"هذا هو التعريف الدقيق للإجماع."},{"type":"mcq","q":"إلحاق مسألة جديدة بمسألة منصوص عليها في الحكم لاشتراكهما في العلة يُسمّى:","options":["القياس","التجويد","الإجماع","التواتر"],"answer":0,"why":"القياس ينقل حكم الأصل للفرع بسبب العلة المشتركة."},{"type":"mcq","q":"عدد أركان القياس هو:","options":["ستة أركان","أربعة أركان (أصل، فرع، حكم، علّة)","ركنان فقط","ثلاثة أركان"],"answer":1,"why":"أركان القياس أربعة."},{"type":"mcq","q":"في قياس تحريم المخدرات على الخمر، تُعد «المخدرات»:","options":["حكم الأصل","الأصل","الفرع","العلّة"],"answer":2,"why":"المسألة الجديدة غير المنصوص عليها تُسمى الفرع."}],"medium":[{"type":"mcq","q":"في قياس تحريم المخدرات على الخمر، تُعد «الخمر»:","options":["الفرع","النتيجة","العلّة","الأصل"],"answer":3,"why":"الأصل هو المقيس عليه الذي ورد فيه النص الشرعي."},{"type":"mcq","q":"ما الدليل النبوي على حجّية الإجماع؟","options":["«إن أمتي لا تجتمع على ضلالة»","«أجملوا في الطلب»","«صلّوا كما رأيتموني أصلي»","«الحياء شعبة من الإيمان»"],"answer":0,"why":"هذا الحديث يدل على عصمة الأمة من الاجتماع على خطأ."},{"type":"mcq","q":"لماذا يُشترط أن يكون الإجماع «بعد وفاة النبي ﷺ»؟","options":["لأن الصحابة لم يكونوا علماء","لأن الوحي في حياته ﷺ كان نازلًا فهو المرجع المباشر للأحكام","لا سبب لذلك","لأن القرآن لم ينزل بعد"],"answer":1,"why":"في حياة النبي ﷺ يُرجع إليه مباشرة لا للإجماع."},{"type":"tfr","q":"يجوز لأي شخص غير متخصص في الفقه أن يُصدر قياسًا شرعيًا في المسائل المستجدة.","answer":false,"reasons":["القياس والاجتهاد من اختصاص العلماء المجتهدين المؤهلين والمجامع الفقهية المعتبرة","نعم يجوز لأي طالب","لا يحتاج إلى علم"],"reason":0},{"type":"tfr","q":"يستند الإجماع الصحيح دائمًا إلى دليل شرعي من القرآن الكريم أو السنة النبوية.","answer":true,"reasons":["يخالف القرآن","فالإجماع لا يُنشئ دينًا من الهوى، بل يكشف عن حكم له مستند شرعي","يستند للهوى فقط"],"reason":1},{"type":"essay","q":"حدّد أركان القياس الأربعة في مثال «تحريم المخدرات قياسًا على الخمر».","model":"الأصل: الخمر. الفرع: المخدرات. حكم الأصل: التحريم. العلة: الإسكار وإذهاب العقل."},{"type":"essay","q":"اذكر مثالين على دور الإجماع والقياس في حل القضايا المعاصرة اليوم.","model":"١) قياس المخدرات المصنّعة الحديثة على الخمر في التحريم. ٢) إجماع المجامع الفقهية على أحكام قضايا طبية ومالية مستجدة كالتأمين التكافلي والتبرع بالأعضاء بضوابطه."}],"hard":[{"type":"mcq","q":"الترتيب الصحيح لمصادر التشريع الإسلامي الأربعة المتفق عليها هو:","options":["القياس ← الإجماع ← السنة ← القرآن","الإجماع ← القرآن ← القياس ← السنة","القرآن ← السنة ← الإجماع ← القياس","السنة ← القياس ← القرآن ← الإجماع"],"answer":2,"why":"يُبدأ بالقرآن ثم السنة ثم الإجماع ثم القياس."},{"type":"mcq","q":"إذا ورد نصّ صريح واضح في القرآن الكريم بحكم مسألة، هل نلجأ إلى القياس لتغيير ذلك الحكم؟","options":["نقدّم القياس على القرآن","نختار بينهما","نعم دائمًا","لا؛ فلا قياس مع وجود النص الصريح"],"answer":3,"why":"القياس يُلجأ إليه في المسائل التي لم يرد فيها نص صريح."},{"type":"mcq","q":"ما العلّة في قياس «منع الموصى له من الوصية إذا قتل الموصي» على «منع الوارث القاتل من الميراث»؟","options":["استعجال الشيء قبل أوانه بوسيلة محرّمة (فيُعاقب بحرمانه)","كثرة المال","القرابة فقط","كبر السن"],"answer":0,"why":"نفس العلة (استعجال الاستحقاق بالقتل) توجب نفس الحكم (الحرمان)."},{"type":"mcq","q":"ما دور «المجامع الفقهية الدولية» في العصر الحديث في تفعيل مبدأ الإجماع والاجتهاد الجماعي؟","options":["منع الاجتهاد","جمع كبار علماء الأمة مع خبراء الطب والاقتصاد والتقنية لدراسة النوازل وإصدار قرارات موثوقة","العمل الفردي المنعزل","إلغاء القرآن"],"answer":1,"why":"الاجتهاد الجماعي يجمع الخبرة الشرعية والعلمية المعاصرة."},{"type":"tfr","q":"يندرج «التجارة الإلكترونية والبيع عبر التطبيقات وقت النداء الثاني لصلاة الجمعة» في نفس حكم النهي عن البيع قياسًا عليه.","answer":true,"reasons":["القياس لا يشمل التقنية","لأنه بيع إلكتروني فلا ينطبق عليه الحكم","لاشتراكهما في نفس العلة وهي الإشغال عن السعي لصلاة الجمعة"],"reason":2},{"type":"tfr","q":"لا يجري القياس في «العبادات المحضة» التي لا تُدرك علتها التفصيلية كعدد ركعات الصلوات.","answer":true,"reasons":["لأن العبادات توقيفية نلتزم بها كما جاءت عن النبي ﷺ دون زيادة أو نقصان","كل العبادات بالقياس","يمكن قياس صلاة الفجر على الظهر لتصبح ٤ ركعات"],"reason":0},{"type":"tfr","q":"يصحّ الإجماع إذا اتفق ثلاثة علماء فقط وخالفهم سائر مجتهدي الأمة.","answer":false,"reasons":["يكفي عالم واحد","يُشترط اتفاق جميع المجتهدين المعتبرين في ذلك العصر، أما اتفاق بعضهم فليس إجماعًا","نعم يكفي ثلاثة"],"reason":1},{"type":"essay","q":"قارن بين «الإجماع» و«القياس» من حيث التعريف والطبيعة ومثال واحد لكل منهما.","model":"الإجماع: اتفاق جميع المجتهدين في عصر بعد النبي ﷺ (مثل جمع القرآن الكريم). القياس: إلحاق فرع بأصل في الحكم لاشتراكهما في العلة (مثل قياس المخدرات على الخمر)."},{"type":"essay","q":"اشرح كيف تبرهن للآخرين من خلال «القياس» أن الإسلام دين صالح لكل زمان ومكان.","model":"لأن القياس يتيح للعلماء استنباط أحكام كل المستجدات الطبية والتقنية والمالية عبر العلل والمقاصد الشرعية الثابتة في القرآن والسنة."},{"type":"essay","q":"طبّق أركان القياس الأربعة على مثال: «قياس تحريم شتم أو ضرب الوالدين على تحريم قول (أفٍّ) لهما».","model":"الأصل: قول أفٍّ للوالدين. الفرع: الضرب أو الشتم. حكم الأصل: التحريم. العلة: الإيذاء (وهو في الفرع أشد وأولى بالتحريم — قياس الأولى)."}]}},
  {"id":"g9-islamic-1-u3-5","grade":"g9","subject":"islamic","term":1,"unit":3,"no":5,"title":"المجلس النبويّ (سيرة)","summary":"شرح متحرك بـ SVG لدرس المجلس النبويّ (سيرة) للصف التاسع (سلطنة عُمان)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.","page":"lesson-prophetic-gathering.html","video":"","pdf":"","notes":["صفات المجلس النبوي: مجلس حلم وحياء وأمانة وعلم، بلا صخب ولا مراء ولا غيبة.","آداب الجلوس: الجلوس حيث ينتهي المجلس، والتفسّح للقادمين، وعدم إقامة أحد من مكانه.","آداب الحديث: الإنصات، عدم المقاطعة، إعطاء كل جليس نصيبه من الاهتمام، والتصحيح اللطيف («ما بال أقوام»).","حفظ الأمانة: «المجالس بالأمانة»، وختم المجلس بـ«دعاء كفارة المجلس»."],"exercises":["اذكر أربع صفات تميّز بها المجلس النبوي الشريف.","اكتب دعاء كفارة المجلس وبيّن فائدته.","كيف تطبّق قاعدة «المجالس بالأمانة» في عصر الهواتف والتصوير؟"],"levels":{"easy":[{"type":"mcq","q":"من أبرز صفات المجلس النبوي الشريف:","options":["التمييز بين الجلساء","الغيبة والسخرية","الحلم والحياء والأمانة وعدم رفع الأصوات","الصخب والجدال"],"answer":2,"why":"وُصف المجلس النبوي بأنه مجلس حلم وحياء وصبر وأمانة."},{"type":"mcq","q":"معنى «المراء» الذي كان المجلس النبوي خاليًا منه:","options":["الابتسامة","الإنصات","المصافحة","الجدال العقيم لإظهار الغلبة"],"answer":3,"why":"المراء هو الجدال المذموم الذي يثير الشحناء."},{"type":"mcq","q":"نهى النبي ﷺ في آداب المجالس عن:","options":["إقامة الرجل من مجلسه ثم الجلوس مكانه","الجلوس حيث ينتهي المجلس","إلقاء السلام","التفسّح للقادم الجديد"],"answer":0,"why":"قال ﷺ: «لا يُقيمنّ أحدكم الرجل من مجلسه ثم يجلس فيه، ولكن تفسّحوا وتوسّعوا»."},{"type":"mcq","q":"يُقال دعاء كفارة المجلس عند:","options":["النوم فقط","القيام من المجلس والانتهاء منه","دخول السوق","الأكل فقط"],"answer":1,"why":"يُختم به المجلس ليكون كفارةً للغو أو طابعًا للخير."}],"medium":[{"type":"mcq","q":"لماذا كان كل جليس في المجلس النبوي يظن أنه «أكرم الناس وأحبهم» إلى النبي ﷺ؟","options":["لأنه كان يمدحهم بالمبالغة","لأنه كان يعطيهم أموالًا في كل جلسة","لحسن إقباله وعدله في النظر والابتسامة والاهتمام بكل جليس","لأنه كان يكلّم واحدًا فقط"],"answer":2,"why":"العدل في الاهتمام والبشاشة يأسر القلوب."},{"type":"mcq","q":"تصوير جلسة خاصة أو تسجيل صوت زميل في مجلس دون علمه وإرساله للآخرين يُعد مخالفةً لقاعدة:","options":["إفشاء السلام","التفسّح في المجالس","خفض الصوت","«المجالس بالأمانة»"],"answer":3,"why":"التسجيل والتصوير دون إذن خيانة لأمانة المجلس."},{"type":"mcq","q":"قول النبي ﷺ: «ما بال أقوام...» عند معالجة خطأ في المجتمع يُعلّمنا:","options":["النصح العام بالستر واللطف دون تجريح أو تشهير","التشهير بالمخطئ","السكوت عن المنكر","الغضب السريع"],"answer":0,"why":"يجمع بين تصحيح الخطأ وحفظ ماء وجه المخطئ."},{"type":"tfr","q":"كان النبي ﷺ يخصّص لنفسه مقعدًا مرتفعًا فاخرًا يميّزه عن سائر أصحابه في المجلس.","answer":false,"reasons":["نعم كان له عرش مرتفع","كان يجلس وحده","بل كان يجلس بتواضع بين أصحابه حتى لا يميّزه الغريب إلا بالسؤال"],"reason":2},{"type":"tfr","q":"الإنصات للمتحدث وعدم مقاطعته حتى يكمل فكرته من أبرز آداب المجلس النبوي.","answer":true,"reasons":["فقد كان ﷺ لا يقطع على أحد حديثه حتى يفرغ منه","الإنصات غير مهم","المقاطعة تدل على الذكاء"],"reason":0},{"type":"essay","q":"اذكر أربعة آداب للمجلس النبوي يمكنك تطبيقها في اجتماع صفي أو مجلس عائلي.","model":"١) إلقاء السلام والتفسح للقادم الجديد. ٢) الإنصات للمتحدث وعدم مقاطعته أو رفع الصوت. ٣) حفظ أسرار المجلس وعدم التصوير دون إذن. ٤) الختام بدعاء كفارة المجلس."},{"type":"essay","q":"كيف تعامل المجلس النبوي مع فئات المجتمع المختلفة (الكبير، الصغير، ذي الحاجة، والغريب)؟","model":"بتوقير الكبير، ورحمة الصغير، وإيثار ذي الحاجة ومساعدته، وإكرام الغريب وحفظه وإشعاره بالأمن والمودة."}],"hard":[{"type":"mcq","q":"ما الأثر التربوي لقوله تعالى ﴿يا أيها الذين آمنوا إذا قيل لكم تفسّحوا في المجالس فافسحوا يفسح الله لكم﴾؟","options":["ترك المجالس","زرع روح الإيثار والمحبة وإشعار كل قادم بالترحيب والاحترام","التزاحم والتنافر","الجلوس في الطرقات"],"answer":1,"why":"الجزاء من جنس العمل: من وسّع لإخوانه وسّع الله له في رزقه وقلبه."},{"type":"mcq","q":"إذا دخلت مجلسًا فرأيت اثنين يتحدثان حديثًا خاصًا، فما الأدب النبوي الصحيح؟","options":["تسجيل كلامهما","الجلوس بينهما فورًا","عدم الجلوس بينهما إلا بإذنهما وعدم التنصّت عليهما","السؤال عمّا يقولان"],"answer":2,"why":"نهى النبي ﷺ أن يُفرّق بين اثنين إلا بإذنهما."},{"type":"mcq","q":"ما العلاقة بين «دعاء كفارة المجلس» وبين «الوعي الذاتي للمسلم»؟","options":["يُبيح الغيبة في المجلس","يُقال في المسجد فقط","لا معنى له","يُذكّر المسلم بمحاسبة نفسه على كلامه في المجلس وتجديد التوبة والاستغفار قبل انصرافه"],"answer":3,"why":"يجعل نهاية كل لقاء فرصةً للذكر والمراجعة والتوبة."},{"type":"mcq","q":"في مجموعة دردشة مدرسية (مجلس إلكتروني)، أي سلوك يخالف هدي المجلس النبوي؟","options":["نشر لقطة شاشة (Screenshot) لمحادثة خاصة دون إذن أصحابها","استئذان المشرف قبل النشر","استخدام كلمات مهذبة","مشاركة ملخص نافع"],"answer":0,"why":"المحادثات الخاصة مجالس لها أمانتها ولا يجوز تسريبها."},{"type":"tfr","q":"لا يُعدّ المجلس الخالي من ذكر الله مجلسًا مباركًا كاملًا، لذا يُستحب ذكر الله فيه وختمه بكفارة المجلس.","answer":true,"reasons":["ذكر الله في المسجد فقط","فقد حثّ النبي ﷺ على ذكر الله في المجالس وحذّر من قيام قوم من مجلس لا يذكرون الله فيه","لا يُستحب الذكر في المجالس"],"reason":1},{"type":"tfr","q":"توقير الكبير في المجلس يعني ألا يُسمح للصغير بالمشاركة أو إبداء الرأي الصحيح أبدًا.","answer":false,"reasons":["لا دور للشباب","يُمنع الصغير من الكلام","بل كان النبي ﷺ يرحم الصغير ويستمع لرأيه ويشجّعه مع توقير الكبير (كما مع ابن عباس رضي الله عنهما)"],"reason":2},{"type":"tfr","q":"أسلوب «ما بال أقوام» في التصحيح يزيل العناد من نفس المخطئ ويدفعه للإصلاح برضا.","answer":true,"reasons":["لأنه يصون كرامته أمام الناس فلا يضطر للدفاع عن خطئه بعناد","لا فائدة منه","يزيد العناد"],"reason":0},{"type":"essay","q":"قارن بين «المجلس النبوي» و«المجلس الذي يسوده الصخب والغيبة» من حيث الأثر على القلوب والمجتمع.","model":"المجلس النبوي ينشر العلم والمودة والطمأنينة والثقة؛ أما مجلس الصخب والغيبة فيورث التوتر والعداوة وفقدان الثقة وقسوة القلب."},{"type":"essay","q":"اشرح كيف تطبّق «آداب المجلس النبوي» في مجموعات الواتساب ووسائل التواصل.","model":"باستئذان قبل نقل أي رسالة خاصة (أمانة المجلس)، وترك الجدال العقيم (المراء) والغيبة، والتحدث بأدب ولطف، ونشر ما ينفع الناس."},{"type":"essay","q":"علّل: لماذا جمع وصف المجلس النبوي بين «الحلم» و«الحياء» و«الصبر» و«الأمانة»؟","model":"لأن الحلم يمنع الغضب، والحياء يمنع الكلام القبيح، والصبر يعين على حسن الإنصات وتحمّل الجلساء، والأمانة تحفظ أسرار المجلس؛ فبها يكتمل رقيّ الاجتماع الإنساني."}]}},
  {"id":"g9-islamic-1-u3-6","grade":"g9","subject":"islamic","term":1,"unit":3,"no":6,"title":"سماحة المؤمن (قيم وأخلاق)","summary":"شرح متحرك بـ SVG لدرس سماحة المؤمن (قيم وأخلاق) للصف التاسع (سلطنة عُمان)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.","page":"lesson-tolerance-of-the-believer.html","video":"","pdf":"","notes":["السماحة: السهولة واليسر وكرم النفس في المعاملة، وترك التشدد والمشاحة.","الحديث (رواه البخاري): «رحم الله رجلًا سمحًا إذا باع، وإذا اشترى، وإذا اقتضى».","مجالاتها: في البيع (صدق وسعر عادل وتيسير)، وفي الشراء (عدم البخس)، وفي الاقتضاء (اللين وإمهال المعسر)، وفي الأسرة والمدرسة.","السماحة كرم وقوة نفسية لا تعني السذاجة ولا قبول الغش."],"exercises":["اشرح صور السماحة الثلاث الواردة في الحديث الشريف.","فرّق بين «السماحة» و«الضعف أو السذاجة» بمثال عملي.","اذكر ثلاث ثمرات للسماحة على الفرد والمجتمع."],"levels":{"easy":[{"type":"mcq","q":"معنى «السماحة» في الإسلام هو:","options":["الغش في البيع","السهولة واليسر وكرم النفس في المعاملة","التفريط في الدين","التشدد والعناد"],"answer":1,"why":"السماحة تعني اللين والتيسير وكرم النفس."},{"type":"mcq","q":"راوي حديث «رحم الله رجلًا سمحًا إذا باع وإذا اشترى وإذا اقتضى» هو:","options":["أبو بكر الصديق","خالد بن الوليد","جابر بن عبد الله رضي الله عنهما","بلال بن رباح"],"answer":2,"why":"رواه البخاري عن جابر بن عبد الله رضي الله عنهما."},{"type":"mcq","q":"من صور سماحة «البائع»:","options":["العبوس في وجه المشتري","استغلال حاجة الناس","إخفاء عيوب السلعة","الصدق في وصف السلعة والرفق بالمشتري وقبول الإقالة عند الندم"],"answer":3,"why":"البائع السمح صادق وبشوش وميسّر."},{"type":"mcq","q":"التوجيه القرآني لصاحب الدَّين إذا كان المدين معسرًا هو:","options":["﴿فنظرة إلى ميسرة﴾ (إمهاله حتى يتيسّر حاله)","الاعتداء عليه","مضاعفة الدَّين بالربا","التشهير به"],"answer":0,"why":"إمهال المعسر من أرفع صور السماحة والتكافل."}],"medium":[{"type":"mcq","q":"قبول البائع إعادة سلعة سليمة اشتراها زبون ثم ندم لظرف طارئ يُسمّى في الفقه:","options":["الاحتكار","الإقالة (وهي من أرقى صور السماحة)","الغش","الربا"],"answer":1,"why":"من أقال مسلمًا بيعته أقال الله عثرته يوم القيامة."},{"type":"mcq","q":"هل الخطاب بلفظ «رجلًا» في الحديث يعني أن السماحة خاصة بالرجال فقط؟","options":["لا يشمل الطلاب","نعم للرجال فقط","لا، بل يشمل الرجل والمرأة على حد سواء لأن الخطاب في الشرع يعمّ الجنسين","خاص بالتجار الكبار فقط"],"answer":2,"why":"الأحكام والآداب الشرعية عامة للرجال والنساء إلا بدليل تخصيص."},{"type":"mcq","q":"في المقصف المدرسي أو السوق، أي سلوك يخالف السماحة عند الشراء؟","options":["الالتزام بالدور","السؤال بلطف عن السعر","شكر البائع","ازدراء السلعة والجدال العنيف مع البائع على بيسات معدودة"],"answer":3,"why":"التشدد والخشونة والجدال المؤذي يناقضان السماحة."},{"type":"tfr","q":"السماحة تقتصر على المعاملات المالية في الأسواق ولا دخل لها بالعلاقات الأسرية والمدرسية.","answer":false,"reasons":["نعم في السوق فقط","بل تشمل كل تعاملات الإنسان: في البيت والمدرسة والطريق والعمل بجانب السوق","لا تدخل في الأسرة"],"reason":1},{"type":"tfr","q":"مماطلة المدين القادر على السداد في ردّ الدَّين لصاحبه ظلم يناقض السماحة.","answer":true,"reasons":["المماطلة مباحة","لا بأس بالتأخير مع القدرة","لقوله ﷺ «مطل الغني ظلم»، فالسماحة متبادلة بين الدائن والمدين"],"reason":2},{"type":"essay","q":"اذكر أربعة مواقف يومية يمكن لطالب الصف التاسع أن يطبّق فيها خُلق السماحة.","model":"١) التجاوز عن خطأ غير مقصود من زميل في الصف. ٢) الرفق والبشاشة عند الشراء من المقصف أو السوق. ٣) إفساح المكان أو الدور لكبير السن. ٤) اللطف مع الإخوة في البيت عند الخلاف البسيط."},{"type":"essay","q":"كيف تنعكس سماحة البائع والمشتري على بركة التجارة وثقة السوق؟","model":"تجذب الثقة والسمعة الطيبة وتزيد الإقبال على التاجر الصادق السمح، وتقلّل النزاعات والشكاوى، وتنزل البركة والرحمة في الأموال."}],"hard":[{"type":"mcq","q":"تاجر يرفض غشّ المشتري، لكنه يرفض أيضًا أن يخدعه مورد ببضاعة فاسدة؛ هل يُعد ذلك مناقضًا للسماحة؟","options":["لا، لأن السماحة لا تعني قبول الغش أو السذاجة، بل حفظ الحقوق بعدل مع اللين واليسر","السماحة تعني عدم الفحص","يجب أن يقبل البضاعة الفاسدة","نعم يناقض السماحة"],"answer":0,"why":"المؤمن السمح كيس فطن لا يظلم ولا يقبل الغش."},{"type":"mcq","q":"ما أثر انتشار خُلق السماحة على «المحاكم والقضايا اليومية» في المجتمع؟","options":["يلغي القوانين","يقلّل كثيرًا من الخصومات والقضايا البسيطة لأن الناس يحلّون خلافاتهم بالتفاهم والتسامح","يزيد عدد القضايا","لا أثر له"],"answer":1,"why":"السماحة والعفو يحلان كثيرًا من الخلافات وديًا قبل تصاعدها."},{"type":"mcq","q":"قال النبي ﷺ: «ألا أخبركم بمن يحرم على النار؟ كل هيّن ليّن سهل قريب من الناس». كيف يتصل هذا الحديث بدرسنا؟","options":["يدعو للعزلة","يدعو للتشدد","يؤكّد أن السماحة والسهولة واللين مع الناس سبب للنجاة من النار ونيل رحمة الله","لا صلة بينهما"],"answer":2,"why":"الهيّن الليّن السهل هو عين الإنسان السمح."},{"type":"mcq","q":"في التجارة الإلكترونية الحديثة، ما أبرز مظهر لسماحة المتجر الإلكتروني؟","options":["عرض صور مخالفة للواقع","إخفاء رسوم التوصيل","رفض الرد على الزبائن","الشفافية في عرض المواصفات والأسعار وتسهيل الاستبدال والإرجاع العادل وخدمة العملاء بلطف"],"answer":3,"why":"تُطبَّق سماحة البيع في المتاجر التقليدية والإلكترونية بنفس المبادئ."},{"type":"tfr","q":"التغافل اللطيف عن الهفوات الصغيرة بين الإخوة والأصدقاء من أجمل صور السماحة التي تديم المحبة.","answer":true,"reasons":["فمن دقّق في كل صغيرة تعب وأتعب من حوله، والتغافل يحفظ الود","التغافل ضعف","التدقيق والمحاسبة على كل كلمة أفضل"],"reason":0},{"type":"tfr","q":"يجوز للدائن أن يأخذ فائدةً ماليةً إضافيةً مقابل إمهال المدين المعسر.","answer":false,"reasons":["تُعد سماحة","تلك الزيادة «ربا» محرم، أما السماحة الشرعية فهي الإمهال دون زيادة أو التصدق ببعض الدين","نعم الفائدة جائزة"],"reason":1},{"type":"tfr","q":"السماحة في السياقة وإعطاء الأولوية للآخرين برحابة صدر تقلل الحوادث والتوتر في الشوارع.","answer":true,"reasons":["تزيد الزحام","لا علاقة لها بالأخلاق","فهي تطبيق عملي لخلق السماحة واليسر في المرافق العامة"],"reason":2},{"type":"essay","q":"قارن بين أثر «السماحة» و«المشاحة والتشدد» في العلاقات الإنسانية والبيئة التجارية.","model":"السماحة تجلب البركة والرحمة والمحبة وراحة البال وسهولة التعامل؛ أما المشاحة والتشدد فتولّد الغضب والخصومات وفقدان الثقة ونفور الناس."},{"type":"essay","q":"اكتب حوارًا قصيرًا من ٤ أسطر بين بائع سمح ومشترٍ سمح في سوق عُماني يظهر فيه تطبيق الحديث.","model":"المشتري: السلام عليكم، هل هذه التمور طازجة؟ البائع: وعليكم السلام، نعم تفضل ذُقها قبل الشراء، والسعر ٣ ريالات. المشتري: جزاك الله خيرًا، بارك الله في رزقك. البائع: وفيك بارك، وتفضل هذه الزيادة هديةً مني."},{"type":"essay","q":"لماذا جمع الحديث بين «البيع والشراء والاقتضاء» بالتحديد؟","model":"لأنها أكثر المواقف التي يحتك فيها الناس بالمال فتثور فيها الأنانية والشحّ؛ فمن ضبط نفسه بالسماحة عند المال كان أسمح في سائر أمور حياته."}]}},
  {"id":"g9-islamic-1-u4-1","grade":"g9","subject":"islamic","term":1,"unit":4,"no":1,"title":"سورة يوسف (٩٤–١٠١) — تفسير","summary":"شرح متحرك بـ SVG لدرس سورة يوسف (٩٤–١٠١) — تفسير للصف التاسع (سلطنة عُمان)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.","page":"lesson-surah-yusuf-94-101.html","video":"","pdf":"","notes":["﴿فصلت العير﴾: خرجت القافلة؛ ﴿تفنّدون﴾: تسفّهون رأيي؛ ﴿فاطر السماوات﴾: خالقهما ومبدعهما.","تحققت رؤيا يوسف واجتمع شمله بأهله، وأكرم أبويه برفعهما على العرش برًّا وتواضعًا.","من رقيّ عفو يوسف: ذكر السجن دون البئر ونسب الفتنة لنزغ الشيطان حفظًا لمودة إخوته.","ختم يوسف في قمة ملكه بشكر الله ونسبة الفضل إليه والدعاء بحسن الخاتمة ﴿توفني مسلمًا وألحقني بالصالحين﴾."],"exercises":["ما معنى: فصلت العير، تفنّدون، نزغ الشيطان، فاطر السماوات والأرض؟","استخرج من الآية ١٠٠ دليلين على رقيّ أدب يوسف عليه السلام وعفوه عن إخوته.","كيف نطبّق قيمة «التواضع ونسبة الفضل لله عند النجاح» في حياتنا الدراسية؟"],"levels":{"easy":[{"type":"mcq","q":"معنى «فَصَلَتِ الْعِيرُ» في الآية ٩٤ هو:","options":["خرجت القافلة وغادرت مصر","توقفت الرياح","وصلت السفينة","نزل المطر"],"answer":0,"why":"العير هي القافلة، وفصلت أي خرجت وغادرت."},{"type":"mcq","q":"معنى «فَاطِرَ السَّمَاوَاتِ وَالْأَرْضِ» في الآية ١٠١ هو:","options":["أرض خصبة","خالقهما ومبدعهما على غير مثال سابق","حافظهما فقط","سماء واسعة"],"answer":1,"why":"فاطر السماوات أي مبدعهما وخالقهما أول مرة."},{"type":"mcq","q":"السجود المذكور في قوله ﴿وَخَرُّوا لَهُ سُجَّدًا﴾ كان:","options":["جائزًا في الإسلام","سجود سهو","سجود تحية وإكرام جائزًا في شريعتهم (وليس سجود عبادة)","سجود عبادة ليوسف"],"answer":2,"why":"كان تحية إكرام في شريعة يعقوب، ونسخه الإسلام ليُخصّ الله وحده بالسجود."},{"type":"mcq","q":"تأخير يعقوب عليه السلام للاستغفار في قوله ﴿سوف أستغفر لكم ربي﴾ كان لـ:","options":["النسيان","الغضب","رفض العفو عنهم","تحرّي وقت السحر ليكون أرجى للإجابة"],"answer":3,"why":"قال العلماء أخّره لوقت السحر المبارك."}],"medium":[{"type":"mcq","q":"كيف تعامل يوسف عليه السلام مع والديه عند لقائهما في مصر رغم كونه عزيز مصر؟","options":["آواهما وأكرمهما ورفعهما على العرش برًّا وتواضعًا","لم يستقبلهما","تركهما في آخر المجلس","تفاخر عليهما بملكه"],"answer":0,"why":"مهما ارتفع منصب الإنسان يبقى بارًّا متواضعًا لوالديه."},{"type":"mcq","q":"تقديم يوسف شكر الله على «الملك والعلم» في الآية ١٠١ قبل الدعاء يدل على:","options":["نسيان الدعاء","أدب الدعاء والثناء على الله ونسبة النعم إليه قبل المسألة","الاكتفاء بالملك","التفاخر بالعلم"],"answer":1,"why":"الثناء على الله وشكر نعمه من أعظم آداب الدعاء."},{"type":"mcq","q":"نسبة يوسف الخلاف إلى «نزغ الشيطان» في قوله ﴿من بعد أن نزغ الشيطان بيني وبين إخوتي﴾ تُعلّمنا:","options":["تبرئة الظالم دون توبة","لوم الناس دائمًا","تطييب الخواطر وعدم تجديد الجراح عند الصلح والعفو","استمرار القطيعة"],"answer":2,"why":"لطف العبارة يحفظ المودة العائلية بعد التوبة والصلح."},{"type":"tfr","q":"يجوز للمسلم أن يطلب تعجيل الموت لضرّ أصابه تأسّيًا بدعاء يوسف ﴿توفني مسلمًا﴾.","answer":false,"reasons":["يوسف لم يطلب تعجيل الموت، بل سأل الله أن يثبته على الإسلام حتى يتوفاه عليه؛ وقد نهى النبي ﷺ عن تمني الموت لضر","نعم يجوز تمني الموت","يوسف كان يائسًا"],"reason":0},{"type":"tfr","q":"قوله تعالى ﴿إن ربي لطيف لما يشاء﴾ يعني أن الله يدبّر الأمور بدقة وخفاء ورحمة حتى يأتي الفرج من حيث لا يُحتسب.","answer":true,"reasons":["يعني أنه سريع الغضب","فقد ساق البئر ثم السجن ثم العرش ليحقق لطفه وحكمته بيوسف وأهله","لا علاقة له بالتدبير"],"reason":1},{"type":"essay","q":"اذكر أربع قيم أخلاقية بارزة في خواتيم سورة يوسف (٩٤–١٠١).","model":"١) برّ الوالدين وإكرامهما. ٢) العفو الكريم دون معايرة. ٣) التواضع ونسبة الفضل لله عند النجاح. ٤) الحرص على حسن الخاتمة وصحبة الصالحين."},{"type":"essay","q":"ما الدروس المستفادة من اعتراف إخوة يوسف ﴿إنا كنا خاطئين﴾ وطلبهم الاستغفار؟","model":"أن الشجاعة الحقيقية في الاعتراف بالخطأ والاعتذار وطلب المسامحة، وعدم المكابرة على الذنب."}],"hard":[{"type":"mcq","q":"أي اسم من أسماء الله الحسنى ختم به يوسف ثناءه في الآية ١٠٠ بعد استعراض رحلته من السجن إلى العرش؟","options":["المانع فقط","المنتقم فقط","المتكبر","اللطيف العليم الحكيم"],"answer":3,"why":"﴿إن ربي لطيف لما يشاء إنه هو العليم الحكيم﴾."},{"type":"mcq","q":"لماذا يُعدّ قول يوسف ﴿آتيتني من الملك﴾ بحرف التبعيض (مِن) دليلًا على عمق تواضعه؟","options":["لأنه أقرّ بأن ما أوتيه جزء يسير جدًّا من ملك الله الواسع، وأن الملك الكامل لله وحده","لأنه يطلب زيادة الملك","لأنه لم يحكم شيئًا","لأنه خطأ لغوي"],"answer":0,"why":"استخدام «مِن» التبعيضية قمة الأدب والتواضع أمام ملك الله المطلق."},{"type":"mcq","q":"ربط يوسف عليه السلام في الآية ١٠١ بين «أنت وليّي في الدنيا والآخرة» وبين «ألحقني بالصالحين» لبيان أن:","options":["الصالحين لا يحكمون","ولاية الله وحفظه وصحبة الصالحين هما أمان المؤمن في حياته وبعد مماته","الآخرة منفصلة عن الدنيا","المناصب تدوم بعد الموت"],"answer":1,"why":"ولاية الله تشمل الدنيا والآخرة وتثمر مرافقة الصالحين."},{"type":"mcq","q":"عندما يتصالح شقيقان بعد خلاف قديم، أي أسلوب يستلهمانِه من موقف يوسف مع إخوته؟","options":["تذكير الآخر بفضله عليه","المقاطعة المستمرة","فتح صفحة جديدة وعدم التذكير بالخطأ القديم ونسبة الفتنة لنزغ الشيطان","ترديد الخطأ في كل جلسة"],"answer":2,"why":"الصفح الجميل يطوي صفحة الماضي بالكامل."},{"type":"tfr","q":"تُثبت قصة يوسف أن الصبر الجميل والثقة بفرج الله يحوّلان المحن إلى مِنح ورفعة.","answer":true,"reasons":["الصبر لا يغير شيئًا","يوسف لم يُبتلَ","فقد انتقل من البئر والسجن إلى خزائن الأرض واجتماع الشمل بالصبر والتقوى"],"reason":2},{"type":"tfr","q":"قول يعقوب لأبنائه ﴿ألم أقل لكم إني أعلم من الله ما لا تعلمون﴾ كان لتذكيرهم بصدق وعد الله وثمرات حسن الظن به.","answer":true,"reasons":["فلم ييأس من روح الله طوال سنين الفراق، فتحقق ما وثق به من ربه","كان للتشفي بهم","كان لليأس"],"reason":0},{"type":"tfr","q":"لم تتحقّق الرؤيا التي رآها يوسف في طفولته في أول السورة.","answer":false,"reasons":["تحققت نصفها فقط","بل تحققت تمامًا في الآية ١٠٠: ﴿هذا تأويل رؤياي من قبل قد جعلها ربي حقًا﴾","كانت أضغاث أحلام"],"reason":1},{"type":"essay","q":"قارن بين أسلوب يوسف في التعامل مع «الابتلاء في السجن» وتعامله مع «التمكين في العرش».","model":"في الابتلاء: صبر وعفة وثبات ودعوة للتوحيد. وفي التمكين: عفو وتواضع وبرّ بوالديه وشكر لله وطلب لحسن الخاتمة. وفي الحالتين كان عبدًا مخلصًا لله."},{"type":"essay","q":"بيّن أثر استحضار اسم الله «اللطيف» في تهدئة نفس المسلم عند الأزمات.","model":"يجعله يوقن أن الله يدبّر له الخير بلطف خفي حتى من داخل الصعاب، فيطمئن قلبه ويحسن ظنه بربه."},{"type":"essay","q":"اكتب دعاءً قصيرًا مستوحًى من الآية ١٠١ تدعو به لنفسك عند نجاحك في دراستك.","model":"ربّ لك الحمد على ما أنعمت به عليّ من العلم والتوفيق، أنت وليّي في الدنيا والآخرة، ثبّتني على طاعتك، وتوفّني مسلمًا وألحقني بالصالحين."}]}},
  {"id":"g9-islamic-1-u4-2","grade":"g9","subject":"islamic","term":1,"unit":4,"no":2,"title":"المستظلّون بظلّ الله (حديث شريف)","summary":"شرح متحرك بـ SVG لدرس المستظلّون بظلّ الله (حديث شريف) للصف التاسع (سلطنة عُمان)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.","page":"lesson-shaded-by-allah.html","video":"","pdf":"","notes":["الحديث (متفق عليه عن أبي هريرة): «سبعة يظلّهم الله في ظله يوم لا ظلّ إلا ظله...».","الأصناف السبعة: الإمام العادل، الشاب الناشئ في عبادة الله، المعلّق قلبه بالمساجد، المتحابّان في الله، العفيف عند الفتنة، المتصدّق في الخفاء، والذاكر لله خاليًا ففاضت عيناه.","الحديث يشمل الرجال والنساء، والعدل يشمل كل صاحب مسؤولية في عمله وأسرته.","تجمع الأصناف السبعة قيمة الإخلاص ومجاهدة النفس ومراقبة الله."],"exercises":["اذكر الأصناف السبعة الواردة في الحديث الشريف.","لماذا خصّ الحديث «الشاب الناشئ في عبادة الله» بالذكر دون الشيخ؟","كيف تطبّق «صدقة الخفاء» و«المحبة في الله» في واقعك المدرسي؟"],"levels":{"easy":[{"type":"mcq","q":"معنى «يوم لا ظلّ إلا ظله» هو:","options":["وقت الليل","فصل الشتاء","يوم العيد","يوم القيامة حيث يظلّ الله عباده بظل عرشه"],"answer":3,"why":"يوم القيامة تدنو الشمس ويشتد الكرب فلا ظل إلا ظل عرش الله."},{"type":"mcq","q":"مثال على «المحبة في الله»:","options":["صديقان يتعاونان على الصلاة وطلب العلم والأخلاق الحسنة","صداقة لأجل مصلحة مالية فقط","مجاملة مؤقتة","رفقة على الغيبة وإضاعة الوقت"],"answer":0,"why":"المحبة في الله خالصة نقية تجمع على طاعة الله."},{"type":"mcq","q":"كناية «حتى لا تعلم شماله ما تنفق يمينه» تدل على:","options":["تصوير الصدقة ونشرها","كمال الإخلاص وإخفاء الصدقة","ترك الصدقة","البخل"],"answer":1,"why":"الإخفاء يبعد الرياء ويصون كرامة الفقير."},{"type":"mcq","q":"السبب الذي منع الصنف الخامس من الوقوع في الفاحشة هو:","options":["المرض","خوفه من الكاميرات فقط","خوفه من الله ومراقبته له («إني أخاف الله»)","عدم القدرة"],"answer":2,"why":"الوازع الإيماني ومراقبة الله هما حصن العفة."}],"medium":[{"type":"mcq","q":"لماذا يُعد «الشاب الناشئ في عبادة الله» أعظم أجرًا وأشد مجاهدةً؟","options":["لأن الكبار لا يُقبل عملهم","لأن الشباب بلا واجبات","لأن العبادة للشباب فقط","لأن مرحلة الشباب تمتلئ بالقوة والمغريات، فالثبات على الطاعة فيها دليل صدق وإرادة قوية"],"answer":3,"why":"مجاهدة الهوى في زمن القوة والفتوّة ترفع الدرجات."},{"type":"mcq","q":"هل يدخل «المدير العادل والمعلم العادل والأب العادل» في معنى «الإمام العادل»؟","options":["نعم؛ لأن كل من تولّى مسؤوليةً وعدل فيها له نصيب من هذا الفضل العظيم","لا، للحاكم الأعلى فقط","العدل في المحكمة فقط","لا يدخل المعلم"],"answer":0,"why":"كلكم راعٍ وكلكم مسؤول عن رعيته، والعدل مطلوب في كل ولاية."},{"type":"mcq","q":"ما الأثر الاجتماعي لتطبيق «صدقة الخفاء»؟","options":["قلة الصدقة","صون كرامة الفقير وعدم إحراجه، ونشر التكافل بنية صافية","شعور الفقير بالإهانة","تفاخر الأغنياء"],"answer":1,"why":"إخفاء الصدقة يحمي نفسية المحتاج من الحرج والمنّ."},{"type":"tfr","q":"لا يجوز إعلان الصدقة مطلقًا حتى لو كان بقصد تشجيع الناس على التبرع لحملة خيرية.","answer":false,"reasons":["الإعلان حرام دائمًا","الإخفاء ممنوع","الأصل الإخفاء لكونه أبعد عن الرياء، لكن يجوز الإظهار أحيانًا بنية صالحة لتشجيع الناس والقدوة الحسنة ﴿إن تبدوا الصدقات فنعما هي وإن تخفوها وتؤتوها الفقراء فهو خير لكم﴾"],"reason":2},{"type":"tfr","q":"الذكر والبكاء في الخلوة دليل على صدق الإخلاص لانتفاء وجود من يُرائيه الإنسان.","answer":true,"reasons":["في الخلوة لا يراه إلا الله، فتكون دمعته خالصةً صادقةً","البكاء أمام الناس فقط أخلص","لا أجر للذكر سرًا"],"reason":0},{"type":"essay","q":"اذكر أربعةً من الأصناف السبعة في الحديث يستطيع طالب الصف التاسع التنافس فيها منذ اليوم.","model":"١) شاب نشأ في عبادة الله. ٢) قلب معلّق بالمساجد والمحافظة على الصلاة. ٣) المحبة في الله مع صديق صالح. ٤) صدقة الخفاء وذكر الله في الخلوة والعفة."},{"type":"essay","q":"قارن بين «الصداقة في الله» و«صداقة المصالح الدنيوية» من حيث الاستمرار والأثر.","model":"الصداقة في الله تدوم في الدنيا وتثمر الخير وتظل أصحابها يوم القيامة؛ أما صداقة المصالح فتنتهي بانتهاء المصلحة ولا تنفع في الآخرة."}],"hard":[{"type":"mcq","q":"لماذا بدأ النبي ﷺ الحديث بـ«الإمام العادل» قبل سائر الأصناف الستة؟","options":["للترتيب العشوائي","لأنه الأسهل","لأن نفعه متعدٍّ يعمّ الأمة كلها؛ بعدله يستقر الأمن وتُحفظ الحقوق وتُعمر المساجد","لأن الباقين لا يهمون"],"answer":2,"why":"صلاح الراعي وعدله يعمّ خيره المجتمع كله."},{"type":"mcq","q":"في عصر الهواتف الذكية، كيف يطبّق الشاب صفة الصنف الخامس («إني أخاف الله» — العفة)؟","options":["بإغلاق الهاتف أمام الناس فقط","بترك الدراسة التقنية","لا صلة بالهاتف","بغض البصر وحفظ نفسه في خلوته من المحتوى المحرّم استشعارًا لمراقبة الله"],"answer":3,"why":"مراقبة الله في الخلوة أمام الشاشة هي عين «إني أخاف الله» اليوم."},{"type":"mcq","q":"هل العدد «سبعة» في الحديث يعني أنه لا يستظل بظل الله غيرهم أبدًا؟","options":["لا، بل وردت أحاديث صحيحة أخرى تذكر أصنافًا أخرى (كإنظار المعسر وإعانة المجاهد والغارم) فالعدد ليس للحصر المطلق","لا يدخل غيرهم أبدًا","نعم سبعة أشخاص فقط في التاريخ","يقتصر على ٧ أعمال فقط"],"answer":0,"why":"الأحاديث الأخرى بيّنت خصالًا إضافية تظلّ صاحبها بظل الله."},{"type":"mcq","q":"ما أثر انتشار الأصناف السبعة في المجتمع العُماني؟","options":["تراجع العمل","عدالة في المؤسسات، شباب مستقيم ومنتج، صداقات نقية، وتكافل خفي يحفظ الكرامة","انعزال عن الحياة","كثرة الخلافات"],"answer":1,"why":"هذه الأصناف السبع تصنع مجتمعًا متكاملًا في العدل والأخلاق والتكافل."},{"type":"tfr","q":"يمكن لمسلم واحد أن يجتهد فيجمع عدة صفات من السبعة في حياته.","answer":true,"reasons":["يُسمح بصفة واحدة فقط","فيكون شابًا طائعًا وقلبه بالمساجد ومحبًا في الله ومتصدقًا في خفاء وذاكرًا في خلوته","تتعارض الصفات مع بعضها"],"reason":1},{"type":"tfr","q":"تصوير وجه فقير أثناء تسليمه طردًا غذائيًا ونشره للمباهاة يتعارض مع روح «صدقة الخفاء».","answer":true,"reasons":["لا بأس بذلك للمباهاة","هذا هو الإخفاء","لأنه يجرح كرامة الفقير ويُدخل الرياء في العمل"],"reason":2},{"type":"tfr","q":"المحبة في الله تعني مجاملة الصديق والسكوت عن أخطائه حتى لا يغضب.","answer":false,"reasons":["المحب في الله ينصح صديقه بلطف ويدلّه على الخير ويمنعه من الضرر","لا يُنصح الصديق","نعم المجاملة على الخطأ واجبة"],"reason":0},{"type":"essay","q":"استخلص من الحديث الشريف كيف يوازن الإسلام بين «العبادة الفردية الخفية» و«المسؤولية الاجتماعية».","model":"ففي الحديث عبادات خفية (ذكر الخلوة، صدقة الخفاء، العفة)، وبجانبها مسؤوليات اجتماعية عامة (عدل الإمام، عمارة المساجد، المحبة في الله)، وبذلك يصلح الفرد والمجتمع معًا."},{"type":"essay","q":"ضع لنفسك خطةً عمليةً أسبوعيةً لتطبيق ثلاث صفات من حديث السبعة.","model":"١) المحافظة على الصلوات الخمس في أوقاتها وفي المسجد. ٢) التصدق بمبلغ بسيط من مصروفي في خفاء. ٣) تخصيص ٥ دقائق يوميًا للذكر وتدبر القرآن في هدوء وخلوة."},{"type":"essay","q":"اشرح الحكمة التربوية في قول النبي ﷺ «شاب نشأ في عبادة الله» بكلمة «نشأ».","model":"تدل «نشأ» على الاستمرار والتربية المبكرة على الطاعة منذ الصغر حتى تصبح العبادة والأخلاق جزءًا أصيلًا من شخصيته."}]}},
  {"id":"g9-islamic-1-u4-3","grade":"g9","subject":"islamic","term":1,"unit":4,"no":3,"title":"دعوة إبراهيم عليه السلام (عقيدة)","summary":"شرح متحرك بـ SVG لدرس دعوة إبراهيم عليه السلام (عقيدة) للصف التاسع (سلطنة عُمان)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.","page":"lesson-call-of-prophet-ibrahim.html","video":"","pdf":"","notes":["إبراهيم عليه السلام خليل الله وأبو الأنبياء ومن أولي العزم الخمسة.","تميّزت دعوته بالرفق مع أبيه («يا أبتِ»)، وبالحجة العقلية الهادئة مع عبدة الكواكب والأصنام ومع الملك النمرود.","أنجاه الله من النار بقوله ﴿يا نار كوني بردًا وسلامًا على إبراهيم﴾ لتوكله التام.","رفع قواعد الكعبة مع ابنه إسماعيل عليهما السلام ودعا بتواضع ﴿ربنا تقبل منا﴾."],"exercises":["اذكر ثلاثة أساليب حوارية استخدمها إبراهيم عليه السلام في دعوته.","ما الدلالة التربوية لقول إبراهيم وإسماعيل ﴿ربنا تقبل منا﴾ أثناء بنائهما الكعبة؟","كيف تطبّق منهج إبراهيم في الحوار الهادئ عند اختلافك في الرأي مع زميلك؟"],"levels":{"easy":[{"type":"mcq","q":"يُلقّب نبي الله إبراهيم عليه السلام بـ:","options":["ذو النون","كليم الله","خليل الله وأبو الأنبياء","روح الله"],"answer":2,"why":"اتخذ الله إبراهيم خليلًا وجعل النبوة في ذريته."},{"type":"mcq","q":"معنى «الآفلين» في قصة إبراهيم مع الكواكب هو:","options":["المضيئين دائمًا","المسافرين","القائمين بالليل","الغائبين الزائلين عن الأنظار"],"answer":3,"why":"الأفول هو الغياب والزوال، وهو صفة المخلوق لا الخالق."},{"type":"mcq","q":"النداء اللطيف الذي كرّره إبراهيم عليه السلام عند حواره مع أبيه هو:","options":["«يا أبتِ»","«يا عدو»","«يا جاهل»","«يا شيخ»"],"answer":0,"why":"كرّر «يا أبتِ» أربع مرات تلطفًا وبرًّا رغم شرك أبيه."},{"type":"mcq","q":"بنى إبراهيم عليه السلام قواعد الكعبة المشرفة بمساعدة ابنه:","options":["نوح عليه السلام","إسماعيل عليه السلام","يوسف عليه السلام","موسى عليه السلام"],"answer":1,"why":"﴿وإذ يرفع إبراهيم القواعد من البيت وإسماعيل﴾."}],"medium":[{"type":"mcq","q":"ما الحكمة من وصف النار في الآية بـ«بردًا وسلامًا» ولم يقل «بردًا» فقط؟","options":["للتكرار فقط","لأنها تحولت لثلج","لأن البرد الشديد وحده قد يؤذي ويهلك، فقرنه بالسلام ليكون بردًا لطيفًا آمنًا لا يضرّه","لأنها لم تُشعل"],"answer":2,"why":"دقة التعبير القرآني: بردًا لا يحرق وسلامًا لا يؤذي ببرده."},{"type":"mcq","q":"ما دلالة دعاء إبراهيم وإسماعيل ﴿ربنا تقبل منا﴾ وهما يقومان بأعظم عمل (بناء الكعبة)؟","options":["عدم رغبتهما في البناء","الخوف من الناس","طلب المال","كمال التواضع والخشية وعدم العُجب بالعمل الصالح"],"answer":3,"why":"المؤمن يعمل أعظم الصالحات ثم يسأل الله القبول بتواضع."},{"type":"mcq","q":"لماذا لجأ قوم إبراهيم إلى «إلقائه في النار» بعد حواره معهم حول الأصنام؟","options":["لأنهم عجزوا عن الرد على حجته العقلية فلجأوا للقوة والعنف","لأن حجتهم كانت أقوى","لاختبار النار","لأنه اعتدى عليهم"],"answer":0,"why":"العنف والغضب حيلة العاجز عن البرهان."},{"type":"tfr","q":"حوار إبراهيم عليه السلام مع عبدة الكواكب لم يكن شكًّا منه في ربه، بل أسلوب مناظرة لإقناعهم ببطلان عبادتها.","answer":true,"reasons":["نعم كان يشك في البداية","فقد كان على الفطرة والتوحيد وأراد استدراجهم بالعقل ليدركوا أن الآفل لا يصلح إلهًا","كان يعبد الشمس"],"reason":1},{"type":"tfr","q":"قابل إبراهيم عليه السلام تهديد أبيه له بالرجم بالشتم والعقوق.","answer":false,"reasons":["قاطعه قبل أن يدعوه","نعم غضب عليه وشتمه","بل قابله بالسلام واللطف والوعد بالاستغفار ما دام لم يتبين له نهايته"],"reason":2},{"type":"essay","q":"اذكر ثلاثة مواقف تُبرز «القوة العقلية والحجة الهادئة» في دعوة إبراهيم عليه السلام.","model":"١) إبطال عبادة الكواكب والقمر والشمس بدليل الأفول والغياب. ٢) ترك كبير الأصنام ليقرّ القوم بعجزها. ٣) تحدّي النمرود بتغيير شروق الشمس من المشرق إلى المغرب."},{"type":"essay","q":"ما القيم التي نتعلّمها من موقف إبراهيم عليه السلام مع أبيه في سورة مريم؟","model":"الرفق ولين الخطاب («يا أبتِ»)، والإشفاق على الأهل، ومخاطبة العقل بأدب، والصبر على الأذى وعدم رد الإساءة بمثلها."}],"hard":[{"type":"mcq","q":"عندما ادّعى النمرود أنه «يحيي ويميت» بقتل بريء وإطلاق سجين، انتقل إبراهيم فورًا لحجة «الشمس»؛ لماذا؟","options":["لأنه عجز عن الرد","لذكائه الحواري في عدم إضاعة الوقت بالجدل اللفظي والانتقال لبرهان قاطع لا يقبل المغالطة","لأنه نسي الحجة الأولى","لأنه وافقه"],"answer":1,"why":"أروع مهارة في الحوار: تجاوز المغالطات والانتقال لدليل حاسم لا جدال فيه."},{"type":"mcq","q":"يصف القرآن إبراهيم عليه السلام بأنه «كان أمةً قانتًا لله حنيفًا»؛ ما معنى «كان أمةً»؟","options":["كان يسكن وحده","كان ملكًا","إمامًا وقدوةً جامعًا لخصال الخير يعادل وحده أمةً كاملةً في الثبات والإيمان","كان له أمة واحدة"],"answer":2,"why":"رجل واحد صادق على الحق قد يساوي أمةً في أثره وفضله."},{"type":"mcq","q":"ما الكلمة العظيمة التي قالها إبراهيم عليه السلام حين أُلقي في النار؟","options":["«لا حول» فقط","استغاث بقومه","طلب العفو من النمرود","«حسبي الله ونعم الوكيل»"],"answer":3,"why":"ثبت في البخاري عن ابن عباس أن إبراهيم قال «حسبي الله ونعم الوكيل» حين ألقي في النار."},{"type":"mcq","q":"كيف يرتبط «دعاء إبراهيم عليه السلام لمكة بالأمن والرزق وبعثة نبي» بتاريخ الإسلام؟","options":["استجاب الله دعاءه فصارت مكة بلدًا آمنًا مباركًا وبُعث فيها النبي محمد ﷺ من ذرية إسماعيل","دعا للمال فقط","لم يُستجب الدعاء","دعا لبابل فقط"],"answer":0,"why":"قال ﷺ: «أنا دعوة أبي إبراهيم»."},{"type":"tfr","q":"الجمع بين «الدليل العقلي» و«الخلق الحسن» هو أقوى وسيلة لإقناع الآخرين بالحق.","answer":true,"reasons":["وهذا هو جوهر مدرسة إبراهيم عليه السلام في الدعوة والحوار","العقل لا دور له في الإيمان","الصراخ أقوى من الدليل"],"reason":0},{"type":"tfr","q":"تعلّمنا قصة بناء الكعبة أن مشاركة الأبناء للآباء في أعمال الخير تربيهم على الإيمان والمسؤولية.","answer":true,"reasons":["بنى إبراهيم الكعبة وحده","فقد أشرك إبراهيم ابنه إسماعيل في رفع القواعد والدعاء","الأبناء لا يشاركون في الخير"],"reason":1},{"type":"tfr","q":"الحنيفية تعني التشدد والتضييق على الناس في الدين.","answer":false,"reasons":["تعني عبادة الكواكب","نعم تعني التشدد","الحنيفية السمحة تعني الإخلاص لله والميل عن الشرك إلى التوحيد بيسر وسماحة"],"reason":2},{"type":"essay","q":"قارن بين أسلوب «نوح عليه السلام» وأسلوب «إبراهيم عليه السلام» في الدعوة إلى الله، مبيّنًا القاسم المشترك بينهما.","model":"نوح ركّز على الصبر الطويل ٩٥٠ سنة وتنويع الأوقات سرًا وجهارًا والتذكير بآيات الكون؛ وإبراهيم تميّز بالمناظرة العقلية الحاسمة مع أبيه وقومه والملك والبرهان العملي؛ وكلاهما يجمعهما التوحيد الخالص والصبر والرفق والثبات."},{"type":"essay","q":"كيف تستخدم مهارة «الحجة الهادئة» من مناظرة إبراهيم مع النمرود عندما يجادلك أحد بغير حق في المدرسة؟","model":"لا أغضب ولا أرفع صوتي ولا أنجرّ لمغالطات جانبية، بل أقدّم دليلًا واضحًا مباشرًا بلطف واحترام، وأنهي الجدل العقيم بأدب."},{"type":"essay","q":"اذكر ثلاث نعم استجاب الله بها لدعاء إبراهيم عليه السلام في القرآن الكريم.","model":"١) جعل مكة بلدًا آمنًا مباركًا تُجبى إليه الثمرات. ٢) بعثة النبي محمد ﷺ من ذرية إسماعيل. ٣) قبول عمله في بناء الكعبة وإقبال قلوب المؤمنين إليها في الحج والعمرة."}]}},
  {"id":"g9-islamic-1-u4-4","grade":"g9","subject":"islamic","term":1,"unit":4,"no":4,"title":"الأيمان (فقه)","summary":"شرح متحرك بـ SVG لدرس الأيمان (فقه) للصف التاسع (سلطنة عُمان)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.","page":"lesson-oaths-in-islam.html","video":"","pdf":"","notes":["اليمين: توكيد أمر بذكر اسم الله أو صفة من صفاته، ويحرم الحلف بغير الله.","أنواع الأيمان: (١) اللغو (بلا قصد — لا كفارة)، (٢) المنعقدة (بقصد على مستقبل — تجب الكفارة عند الحنث)، (٣) الغموس (كذب متعمد — كبيرة وتوبة وردّ حقوق).","كفارة اليمين (المائدة: ٨٩): التخيير بين إطعام ١٠ مساكين أو كسوتهم أو تحرير رقبة؛ وعند العجز فقط صيام ٣ أيام.","من حلف على ترك خير فليأتِ الخير وليكفّر عن يمينه."],"exercises":["قارن في جدول بين أنواع الأيمان الثلاثة (اللغو، المنعقدة، الغموس) من حيث التعريف والحكم.","حلف طالب مقتدر ماليًا ألا يكلم صديقه ثم تصالح معه، فأراد صيام ٣ أيام ككفارة؛ ما رأيك الفقهي؟","ما حكم الحلف بغير الله مع الدليل النبوي؟"],"levels":{"easy":[{"type":"mcq","q":"اليمين التي يحلفها الشخص كاذبًا متعمّدًا على أمر ماضٍ تُسمّى:","options":["اليمين المنعقدة","اليمين الغموس","يمين الصدق","يمين اللغو"],"answer":1,"why":"اليمين الغموس هي الحلف الكاذب المتعمد."},{"type":"mcq","q":"عدد المساكين الذين يُطعمون أو يُكسون في كفارة اليمين هو:","options":["مسكين واحد","ستون مسكينًا","عشرة مساكين","ثلاثة مساكين"],"answer":2,"why":"﴿فكفارته إطعام عشرة مساكين... أو كسوتهم﴾."},{"type":"mcq","q":"حكم الحلف بغير الله (كالحلف بالأب أو بالشرف):","options":["مستحب","واجب","مباح","محرّم لا يجوز"],"answer":3,"why":"لا يُحلف إلا بالله تعالى أو صفة من صفاته."},{"type":"mcq","q":"إذا حلف المسلم يمينًا منعقدةً ولم يفِ بها (حنث)، وجب عليه:","options":["إخراج كفارة اليمين","لا شيء عليه","إعادة الوضوء فقط","الحج فورًا"],"answer":0,"why":"الحنث في اليمين المنعقدة يوجب الكفارة."}],"medium":[{"type":"mcq","q":"رجل غني حنث في يمين منعقدة، فصام ثلاثة أيام بدل إطعام عشرة مساكين؛ ما حكم كفارته؟","options":["تجزئه تمامًا","لا تجزئه لأن الصيام للعاجز فقط، ويجب عليه إطعام أو كسوة عشرة مساكين","يكفي يوم واحد","لا كفارة على الغني"],"answer":1,"why":"الترتيب في الآية واضح: ﴿فمن لم يجد فصيام ثلاثة أيام﴾."},{"type":"mcq","q":"حلف شاب في لحظة غضب قائلًا: «والله لن أزور خالي أبدًا»، ثم هدأ وندم. ما التصرف الشرعي الصحيح؟","options":["يحلف مرة أخرى","لا يزوره ولا يكفّر","يصل رحمه ويزور خاله، ويُخرج كفارة اليمين","يستمر في قطيعة خاله وفاءً ليمينه"],"answer":2,"why":"لا يجوز جعل اليمين مانعًا من صلة الرحم؛ فيأتي الخير ويكفّر."},{"type":"mcq","q":"السورة القرآنية التي فصّلت كفارة اليمين في الآية ٨٩ هي:","options":["سورة الإخلاص","سورة العصر","سورة الفاتحة","سورة المائدة"],"answer":3,"why":"وردت تفاصيل كفارة اليمين في سورة المائدة، الآية ٨٩."},{"type":"tfr","q":"تجوز «يمين اللغو» ولا كفارة فيها، لكن يُستحب تعويد اللسان على حفظ اسم الله وعدم الإكثار من الحلف.","answer":true,"reasons":["تعظيمًا لاسم الله وعملًا بقوله تعالى ﴿واحفظوا أيمانكم﴾","لأن الإكثار من الحلف مستحب","لأن اللغو فيها كفارة"],"reason":0},{"type":"tfr","q":"قول المسلم «والله لأذاكرنّ الليلة» بقصد وعزم يُعدّ يمينًا منعقدةً.","answer":true,"reasons":["تُعد يمين غموس","لأنها حلف مقصود على فعل أمر في المستقبل، فإذا لم يفعل وجبت الكفارة","تُعد يمين لغو"],"reason":1},{"type":"essay","q":"اذكر أنواع الأيمان الثلاثة مع مثال واحد لكل نوع.","model":"١) اللغو: قول «لا والله» في الكلام العادي بلا قصد. ٢) المنعقدة: «والله لأتصدقن غدًا» بقصد وعزم. ٣) الغموس: «والله لم أسرق الكتاب» وهو يعلم أنه سرقه."},{"type":"essay","q":"رتّب خصال كفارة اليمين كما وردت في سورة المائدة (آية ٨٩) مبيّنًا ما فيه تخيير وما فيه ترتيب.","model":"أولًا التخيير بين ثلاث: إطعام عشرة مساكين، أو كسوتهم، أو تحرير رقبة. ثانيًا الترتيب عند العجز عن الثلاث: صيام ثلاثة أيام."}],"hard":[{"type":"mcq","q":"طالب لم يملك مالًا كافيًا لإطعام عشرة مساكين ولا كسوتهم بعد حنثه في يمين منعقدة؛ ما كفارته؟","options":["صيام ثلاثة أيام","الاستغفار فقط دون صيام","إطعام مسكين واحد فقط","لا شيء عليه"],"answer":0,"why":"للعاجز ماليًا ينتقل للبديل الشرعي وهو صيام ثلاثة أيام."},{"type":"mcq","q":"إذا قال الشخص في يمينه المنعقدة: «والله لأزورنّك غدًا إن شاء الله»، ثم لم يستطع زيارته؛ هل تجب عليه كفارة؟","options":["يحرم عليه الكلام","لا تجب عليه كفارة لأنه استثنى بمشيئة الله («إن شاء الله»)","تجب عليه كفارتان","يُعد يمين غموس"],"answer":1,"why":"ثبت في الحديث أن من حلف فقال «إن شاء الله» لم يحنث."},{"type":"mcq","q":"ما الحكمة الشرعية من تشريع «كفارة اليمين» على المسلم إذا حنث؟","options":["تشجيع الحلف","التشديد بلا حكمة","تربية المسلم على تعظيم اسم الله واحترام كلمته، مع فتح باب التيسير للرجوع إلى الخير ومساعدة الفقراء","منع الصدقة"],"answer":2,"why":"الكفارة توازن بين هيبة القَسَم والرحمة بالمساكين والتيسير."},{"type":"mcq","q":"ما حكم الحلف الكاذب في البيع والشراء لترويج السلعة؟","options":["يزيد البركة","مباح في التجارة","مكروه فقط","محرّم وممحوق البركة ويدخل في اليمين الغموس؛ قال ﷺ «الحلف منفقة للسلعة ممحقة للبركة»"],"answer":3,"why":"الحلف الكاذب في السوق يمحق البركة ويوقع في الإثم."},{"type":"tfr","q":"من حلف على أمر ماضٍ «ظانًّا صدق نفسه» ثم تبيّن له أنه أخطأ، لا يُعدّ ذلك يمينًا غموسًا لأنه لم يتعمّد الكذب.","answer":true,"reasons":["يُعد غموسًا دائمًا","لا فرق بين الخطأ والعمد","فيمين الغموس يُشترط فيها تعمّد الكذب مع العلم بالحال"],"reason":2},{"type":"tfr","q":"حفظ الأيمان يعني عدم الحلف إلا للضرورة، والوفاء بها إن كانت في خير، والكفارة إن حنث.","answer":true,"reasons":["وهذه هي المعاني الثلاثة لقوله تعالى ﴿واحفظوا أيمانكم﴾","يعني كتابتها في دفتر فقط","يعني ترك الكفارة"],"reason":0},{"type":"tfr","q":"يجوز دفع قيمة إطعام عشرة مساكين لشخص واحد غني ككفارة يمين.","answer":false,"reasons":["يكفي إعطاء صديقك","الآية نصّت على «عشرة مساكين» فلا تُعطى لغني","نعم يجوز لغني"],"reason":1},{"type":"essay","q":"قارن بين «اليمين المنعقدة» و«اليمين الغموس» من حيث الزمن والقصد والحكم.","model":"المنعقدة: تتعلق بالمستقبل وتُقصد، ويجب الوفاء بها في الخير، والحنث فيها يوجب الكفارة. الغموس: تتعلق بالماضي أو الحاضر مع تعمّد الكذب، وهي من الكبائر وتوجب التوبة النصوح وردّ الحقوق."},{"type":"essay","q":"بمَ تنصح زميلًا اعتاد أن يقول «والله» في كل جملة يمزح بها أو يحلف أحيانًا بحياة والديه؟","model":"أنصحه بلطف بتعظيم اسم الله وعدم كثرة الحلف إلا للحاجة، وأذكّره بالحديث النبوي أن الحلف لا يجوز بغير الله «من كان حالفًا فليحلف بالله أو ليصمت»."},{"type":"essay","q":"اشرح كيف يظهر «التكافل الاجتماعي» في أحكام كفارة اليمين.","model":"جعل الله الكفارة إطعامًا أو كسوةً لعشرة مساكين، فيتحول خطأ الحنث إلى باب خير يسد حاجة الفقراء ويقوي التكافل في المجتمع."}]}},
  {"id":"g9-islamic-1-u4-5","grade":"g9","subject":"islamic","term":1,"unit":4,"no":5,"title":"القعقاع بن عمرو التميمي (سيرة)","summary":"شرح متحرك بـ SVG لدرس القعقاع بن عمرو التميمي (سيرة) للصف التاسع (سلطنة عُمان)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.","page":"lesson-al-qaqaa-ibn-amr.html","video":"","pdf":"","notes":["القعقاع بن عمرو التميمي صحابي جليل وقائد وشاعر؛ قال عنه أبو بكر: «لصوت القعقاع في الجيش خير من ألف رجل».","شارك في حروب الردة واليرموك وفتح دمشق والقادسية والمدائن وجلولاء.","أبرز خططه الذكية في القادسية: دخول الكتائب متتابعة لرفع المعنويات، وإلباس الإبل براقع مخيفة، والتصدي للفيلة.","اتصف بالتواضع والطاعة للقيادة، والسعي الحكيم للإصلاح وحقن الدماء بين المسلمين."],"exercises":["اذكر خطتين عسكريتين ذكيتين طبّقهما القعقاع بن عمرو في معركة القادسية.","ماذا يعني قول أبي بكر الصديق: «لصوت القعقاع في الجيش خير من ألف رجل»؟","كيف تطبّق صفات القعقاع (المبادرة، التفكير الإبداعي، الإصلاح) في مدرستك؟"],"levels":{"easy":[{"type":"mcq","q":"الصحابي الذي قال عنه أبو بكر الصديق «لصوته في الجيش خير من ألف رجل» هو:","options":["القعقاع بن عمرو التميمي","بلال بن رباح","سلمان الفارسي","أبو هريرة"],"answer":0,"why":"هذه الشهادة الشهيرة لأبي بكر في حق القعقاع رضي الله عنه."},{"type":"mcq","q":"المعركة الكبرى في العراق التي برزت فيها عبقرية القعقاع التكتيكية ضد الفيلة هي:","options":["غزوة بدر","معركة القادسية","صلح الحديبية","غزوة أحد"],"answer":1,"why":"كان للقعقاع دور حاسم في نصر القادسية سنة ١٥ هـ."},{"type":"mcq","q":"الخليفة الذي أرسل القعقاع مددًا إلى سعد بن أبي وقاص في القادسية هو:","options":["عمر بن عبد العزيز","أبو بكر الصديق","عمر بن الخطاب رضي الله عنه","معاوية بن أبي سفيان"],"answer":2,"why":"وقعت القادسية في خلافة عمر بن الخطاب رضي الله عنه."},{"type":"mcq","q":"من أبرز الصفات الأخلاقية للقعقاع بجانب شجاعته:","options":["إثارة الفتن","رفض أوامر القائد","التكبر على الجنود","الذكاء والتواضع والفصاحة وحب الإصلاح بين المسلمين"],"answer":3,"why":"جمع بين الشجاعة والذكاء والتواضع وحب الإصلاح."}],"medium":[{"type":"mcq","q":"ما الهدف النفسي من إدخال القعقاع جنوده إلى القادسية في كتائب صغيرة متتابعة؟","options":["رفع معنويات المسلمين وإيهام العدو بوصول إمدادات ضخمة لا تتوقف","إراحة الخيول فقط","إخفاء عدد القتلى","إبطاء المعركة"],"answer":0,"why":"الحرب النفسية ورفع المعنويات عامل حاسم في النصر."},{"type":"mcq","q":"على ماذا يدل نجاح القعقاع في تقريب وجهات النظر بين الصحابة قبل موقعة الجمل؟","options":["على ضعف شخصيته","على حكمته ومكانته الموثوقة لدى الجميع وحرصه على وحدة الأمة وحقن الدماء","على انعزاله","على حبه للقتال فقط"],"answer":1,"why":"الثقة به من جميع الأطراف تدل على نزاهته وحكمته."},{"type":"mcq","q":"كيف واجه القعقاع تفوّق الفرس في «الفيلة المدرعة»؟","options":["بالانتظار دون خطة","بالهرب للخلف","بالتفكير الإبداعي (الإبل المبرقعة) والجرأة في شلّ الفيل القائد","بالاستسلام"],"answer":2,"why":"يُظهر ذلك أن العقل والتخطيط يتغلبان على القوة المادية الغاشمة."},{"type":"tfr","q":"لم يقتصر تميّز القعقاع بن عمرو على القوة البدنية، بل جمع معها الذكاء القيادي والفصاحة الشعرية.","answer":true,"reasons":["لم يكن يعرف الشعر","كان مقاتلًا بلا خطط","فقد كان شاعرًا فصيحًا يلهب الحماس ومخططًا عسكريًا ذكيًا"],"reason":2},{"type":"tfr","q":"سعى القعقاع لإشعال الفتنة بين المسلمين بعد وفاة عثمان بن عفان رضي الله عنه.","answer":false,"reasons":["بل سعى بحكمة ومروءة للإصلاح وحقن دماء المسلمين","لم يشارك في الإصلاح","نعم أشعل الفتنة"],"reason":0},{"type":"essay","q":"اشرح كيف يمكن لطالب واحد في الصف أن يكون «كألف» في أثره الإيجابي قياسًا على شهادة أبي بكر في القعقاع.","model":"بأن يكون مبادرًا للخير، متفائلًا يرفع همة زملائه، مبدعًا في حل مشكلات المشاريع، وحريصًا على الإصلاح والتعاون بدل السلبية والتذمر."},{"type":"essay","q":"اذكر أربع معارك أو فتوحات بارزة شارك فيها القعقاع بن عمرو التميمي.","model":"حروب الردة، ومعركة اليرموك (وفتح دمشق)، ومعركة القادسية، وفتح المدائن (ومعركة جلولاء)."}],"hard":[{"type":"mcq","q":"ما الدرس الإداري والقيادي الذي نستفيده من إرسال عمر بن الخطاب للقعقاع استجابةً لطلب سعد بن أبي وقاص مددًا؟","options":["أن القيادة غير مهمة","أن العدد هو كل شيء","أن عمر رفض إرسال مدد","أن الكفاءة والنوعية والقيادة الملهمة قد تفوق الكثرة العددية وحدها"],"answer":3,"why":"الكفاءة والهمة العالية تضاعف أثر الفريق بأكمله."},{"type":"mcq","q":"التزام القعقاع بالعمل تحت إمرة سعد بن أبي وقاص في القادسية رغم مكانته وبطولته يُعلّمنا قيمة:","options":["العمل بروح الفريق والانضباط المؤسسي وعدم التنافس الأناني على الزعامة","ضعف الشخصية","الاستقلال عن الجماعة","ترك النصيحة للقائد"],"answer":0,"why":"الجندي والقائد الناجح يقدّم مصلحة الأمة على الأنا."},{"type":"mcq","q":"لماذا يُعدّ دور القعقاع في الإصلاح بين المسلمين لا يقل شجاعةً عن بطولته في القادسية؟","options":["لأنه لا علاقة له بالشجاعة","لأن إطفاء الفتنة وحقن الدماء يحتاج حكمةً وصدقًا وشجاعةً أدبيةً عاليةً في أوقات التوتر","لأن الإصلاح سهل دائمًا","لأنه لم يفعل شيئًا"],"answer":1,"why":"الإصلاح بين المتخاصمين من أعظم القربات ومواقف البطولة."},{"type":"mcq","q":"ما القيمة المشتركة بين «ذكاء القعقاع في القادسية» وبين «تعاملنا مع التحديات الدراسية الصعبة»؟","options":["الاعتماد على الحظ","الغضب","عدم الاستسلام للعائق، بل تحليله وابتكار حلول ذكية وخطوات متدرّجة للتغلب عليه","ترك المادة الصعبة"],"answer":2,"why":"التفكير الإبداعي والمثابرة هما مفتاح تجاوز الصعاب."},{"type":"tfr","q":"الشجاعة الحقيقية في الإسلام تكون مقترنةً بالعقل والرحمة والعدل لا بالتهور والظلم.","answer":true,"reasons":["لا علاقة للشجاعة بالعقل","وهكذا كانت سيرة القعقاع: ذكاء في التخطيط، وإقدام في الحق، وسعي للصلح","الشجاعة هي التهور فقط"],"reason":1},{"type":"tfr","q":"قراءة سير الأبطال والصحابة كالقعقاع بن عمرو تغرس في نفوس الشباب الثقة والاعتزاز بالتاريخ الإسلامي.","answer":true,"reasons":["السير للماضي فقط","لا فائدة من دراسة السير","وتقدّم قدوات حقيقية تجمع بين الإيمان والعلم والشجاعة والأخلاق"],"reason":2},{"type":"tfr","q":"انتهت مشاركات القعقاع بن عمرو بانتهاء حروب الردة ولم يشهد القادسية.","answer":false,"reasons":["بل كان بطلًا رئيسيًا في اليرموك والقادسية والمدائن وجلولاء","لم يشهد اليرموك","لم يشارك في العراق"],"reason":0},{"type":"essay","q":"قارن بين أثر «القوة المادية» وأثر «الروح المعنوية والتخطيط الذكي» كما ظهرا في معركة القادسية.","model":"امتلك الفرس الفيلة والعدد الضخم (قوة مادية)، لكن القعقاع والمسلمين تفوقوا بالإيمان ورفع المعنويات والتخطيط الذكي (الكراديس المتتابعة وشلّ الفيل القائد)، فانتصروا."},{"type":"essay","q":"اكتب ثلاث صفات قيادية للقعقاع بن عمرو وبيّن كيف تطبقها عندما تكون قائدًا لمجموعة مشروع مدرسي.","model":"١) رفع المعنويات والتشجيع الإيجابي. ٢) التفكير الإبداعي لتجاوز العقبات. ٣) التواضع والإصلاح عند حدوث خلاف بين أعضاء المجموعة."},{"type":"essay","q":"لماذا أثنى أبو بكر الصديق على «صوت» القعقاع تحديدًا في الجيش؟","model":"لأن صوته الجهوري الواثق بالتكبير والحماس والشعر كان يبعث الشجاعة في قلوب المؤمنين ويدخل الرهبة في قلوب أعدائهم."}]}},
  {"id":"g9-islamic-1-u4-6","grade":"g9","subject":"islamic","term":1,"unit":4,"no":6,"title":"النَّزاهة (قيم وأخلاق)","summary":"شرح متحرك بـ SVG لدرس النَّزاهة (قيم وأخلاق) للصف التاسع (سلطنة عُمان)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.","page":"lesson-integrity-and-honesty.html","video":"","pdf":"","notes":["النزاهة: الاستقامة والأمانة والشفافية والبعد عن كل صور الفساد والغش والرشوة في السر والعلن.","مجالاتها: النزاهة العلمية (ترك الغش وتوثيق المصادر)، النزاهة الوظيفية (الإتقان والعدل)، وصون المال العام.","حرّم الإسلام الغش («من غشّنا فليس منّا») والرشوة وتطفيف الميزان.","يتكامل الوازع الديني والضمير الحي مع الجهات الرقابية (كجهاز الرقابة المالية والإدارية للدولة) لحماية النزاهة."],"exercises":["اذكر ثلاث صور عملية للنزاهة يمكنك تطبيقها داخل مدرستك.","قارن بين أثر «النزاهة» وأثر «الرشوة والمحسوبية» على تكافؤ الفرص في المجتمع.","ما العلاقة بين قوله تعالى ﴿إن خير من استأجرت القوي الأمين﴾ وبين النزاهة الوظيفية؟"],"levels":{"easy":[{"type":"mcq","q":"التزام الصدق والأمانة والعدل والبعد عن الغش والرشوة في السر والعلن يُسمّى:","options":["التطفيف","المراء","المحسوبية","النزاهة"],"answer":3,"why":"هذا هو المفهوم الشامل للنزاهة."},{"type":"mcq","q":"قول النبي ﷺ: «من غشّنا فليس منّا» يُرسّخ قيمة:","options":["النزاهة والأمانة في الدراسة والتجارة","الكسل","الاحتكار","الرشوة"],"answer":0,"why":"الحديث يحرّم جميع صور الغش."},{"type":"mcq","q":"الحفاظ على أجهزة مختبر الحاسوب ومقاعد الصف المدرسي يدخل في باب:","options":["الإسراف","صون المال العام والنزاهة","الملكية الفردية","الأمر غير المهم"],"answer":1,"why":"ممتلكات المدرسة مال عام يجب صونه ورعايته."},{"type":"mcq","q":"الآية ﴿إن خير من استأجرت القوي الأمين﴾ تجمع بين شرطين أساسيين للوظيفة هما:","options":["السن والطول","القرابة والمال","الكفاءة (القوة) والنزاهة (الأمانة)","السرعة فقط"],"answer":2,"why":"الكفاءة مع النزاهة هما معيار اختيار الموظف الصالح."}],"medium":[{"type":"mcq","q":"نسخ طالب مقالًا كاملًا من الإنترنت وكتابة اسمه عليه كأنه من تأليفه يُعدّ:","options":["مهارة بحثية ممتازة","إبداعًا","تعاونًا مباحًا","إخلالًا بالنزاهة العلمية (سرقة علمية)"],"answer":3,"why":"النزاهة العلمية تتطلب القراءة وإعادة الصياغة بأسلوبك وتوثيق المصادر."},{"type":"mcq","q":"ما أثر «الرشوة والمحسوبية» في التوظيف على المجتمع؟","options":["تولّي غير الأكفاء وظلم المجتهدين وضعف جودة الخدمات العامة","زيادة الإبداع","تحقيق العدل","ارتفاع كفاءة المؤسسات"],"answer":0,"why":"المحسوبية تقتل الحافز للتميز وتضعف أداء المؤسسات."},{"type":"mcq","q":"الجهة الوطنية في سلطنة عُمان التي تُعنى بحماية المال العام وتعزيز النزاهة هي:","options":["شركات السياحة","جهاز الرقابة المالية والإدارية للدولة","اتحاد كرة القدم","الأندية الخاصة"],"answer":1,"why":"يتولى جهاز الرقابة حماية المال العام وتعزيز الشفافية والنزاهة."},{"type":"tfr","q":"يكفي وجود القوانين والعقوبات وحدها للقضاء على الفساد دون الحاجة إلى الوازع الديني والضمير.","answer":false,"reasons":["لا حاجة للقانون","القانون ضروري، لكن الوازع الديني والتربية على النزاهة هما الرقيب الداخلي في الخلوة حين لا يراك أحد","نعم القانون وحده يكفي دائمًا"],"reason":1},{"type":"tfr","q":"التنافس الشريف في المسابقات المدرسية والفوز بالجهد الصادق تطبيق عملي لخُلق النزاهة.","answer":true,"reasons":["النزاهة للوظائف فقط","الغش في المسابقات مقبول","حيث يلتزم الطالب بالقواعد ولا يتحايل على اللجان أو يأخذ عمل غيره"],"reason":2},{"type":"essay","q":"اذكر أربعة مجالات لتطبيق النزاهة مع مثال عملي واحد لكل مجال.","model":"١) الدراسة: عدم الغش وتوثيق المصادر. ٢) المال العام: حفظ مرافق المدرسة والحدائق. ٣) العمل: إتقان المهام والالتزام بالدوام والعدل. ٤) التجارة: الصدق وترك الغش والتطفيف."},{"type":"essay","q":"كيف يسهم طالب الصف التاسع اليوم في تحقيق محور النزاهة ضمن رؤية عُمان ٢٠٤٠؟","model":"ببناء نفسه على الأمانة في دراسته ومشاريعه، واحترام القوانين والوقت، وصون الممتلكات العامة، ورفض أي سلوك غش أو محسوبية."}],"hard":[{"type":"mcq","q":"طبيب أو مهندس حصل على شهادته الجامعية بالغش طوال دراسته؛ ما الخطر المجتمعي لذلك؟","options":["يصير أكثر إبداعًا","لا خطر لأنه يملك شهادة ورقية","تعريض أرواح الناس ومشاريع الوطن للخطر بسبب ضعف كفاءته الحقيقية","يزيد ثقة الناس"],"answer":2,"why":"الغش الدراسي اليوم يتحول إلى خطر حقيقي على المجتمع غدًا."},{"type":"mcq","q":"لماذا لعن النبي ﷺ «الراشي والمرتشي والرائش (الوسيط)» معًا؟","options":["لأن الراشي وحده مخطئ","لأن الرشوة هدية","لأن الوسيط بريء","لأنهم جميعًا شركاء في هدم العدالة وإفساد الذمم وتضييع حقوق الناس"],"answer":3,"why":"تجريم جميع أطراف الرشوة يسدّ أبواب الفساد من جذورها."},{"type":"mcq","q":"متى تصبح «الهدية» لموظف عام صورةً محرّمةً من صور الرشوة؟","options":["إذا قُدّمت له بسبب منصبه للتأثير على قراره أو مجاملته على حساب القانون والآخرين","إذا كانت لفقير","إذا كانت بين أخوين في العيد","إذا كانت لطالب متفوق من أبيه"],"answer":0,"why":"هدايا العمال والموظفين بسبب المنصب تُعد غلولًا ورشوةً محرّمة."},{"type":"mcq","q":"ما القاسم المشترك بين «حديث أكبر الكبائر (ترك الزور)» و«درس النزاهة»؟","options":["كلاهما خاص بالأسواق","كلاهما يصون الحقوق والعدالة ويبني مجتمعًا قائمًا على الصدق والأمانة والشفافية","كلاهما خاص بالتجويد","لا رابط بينهما"],"answer":1,"why":"القيم الإسلامية متكاملة في بناء الفرد الصالح والمجتمع العادل."},{"type":"tfr","q":"الالتزام بالشفافية والإفصاح الصادق في المعاملات المالية يقلّل فرص الشك والفساد.","answer":true,"reasons":["فالوضوح والشفافية من أهم أدوات النزاهة المؤسسية والفردية","الغموض أفضل في المال العام","الشفافية تضعف الثقة"],"reason":0},{"type":"tfr","q":"ترك صنبور الماء مفتوحًا أو إتلاف ممتلكات الحديقة العامة يُعدّ اعتداءً على المال العام يخلّ بالنزاهة.","answer":true,"reasons":["ليست مالًا عامًا","لأن الماء والمرافق العامة ثروة وطنية مشتركة تجب حمايتها","لا بأس بذلك لأنه مجاني"],"reason":1},{"type":"tfr","q":"تتعارض النزاهة والعدل مع محبة الأقارب وصلة الرحم.","answer":false,"reasons":["النزاهة تمنع زيارة الأقارب","يجب تفضيل القريب ولو لم يكن كفؤًا","صلة الرحم تكون من مالك وجهدك الخاص، لا بإعطائهم حقوق الآخرين أو وظائف بغير استحقاق"],"reason":2},{"type":"essay","q":"قارن بين «القوة بلا أمانة» و«الأمانة بلا قوة» و«اجتماع القوة والأمانة» في ضوء الآية ﴿إن خير من استأجرت القوي الأمين﴾.","model":"القوة بلا أمانة قد تستغل الكفاءة في الفساد؛ والأمانة بلا قوة تعجز عن إنجاز العمل بإتقان؛ أما اجتماع القوة (الكفاءة) والأمانة (النزاهة) فهو سرّ النجاح والنهضة."},{"type":"essay","q":"صمّم ميثاق «النزاهة الطلابية» من ٤ بنود يُعلّق في صفك الدراسي.","model":"١) أعتمد على جهدي في الاختبارات وأرفض الغش تمامًا. ٢) أوثّق مصادر بحوثي بأمانة علمية. ٣) أحافظ على ممتلكات مدرستي كأنها ملكي. ٤) ألتزم بالصدق والعدل في التعامل مع زملائي."},{"type":"essay","q":"اشرح كيف يحفظ «الضمير الحي ومراقبة الله» النزاهة في المواقف التي تغيب فيها الكاميرات والرقابة البشرية.","model":"لأن المؤمن يوقن أن الله مطّلع على سره وعلنه وأنه مسؤول أمامه يوم القيامة، فيستقيم سلوكه ويمتنع عن الغش والفساد حتى لو كان وحده تمامًا."}]}},
  {"id":"g9-islamic-2-u1-1","grade":"g9","subject":"islamic","term":2,"unit":1,"no":1,"title":"علم التفسير (علوم القرآن)","summary":"شرح متحرك بـ SVG لدرس علم التفسير (علوم القرآن) (الصف التاسع - الفصل الثاني)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.","page":"lesson-science-of-tafsir.html","video":"","pdf":"","notes":["علم التفسير: بيان معاني القرآن واستخراج أحكامه وحكمه.","أنواعه: بالمأثور (قرآن بقرآن، بسنة، بأقوال الصحابة) وبالرأي (المحمود بالعلم، والمذموم بالهوى).","شروط المفسّر: العقيدة الصحيحة، إتقان العربية، معرفة السنة وأسباب النزول، والإخلاص."],"exercises":["عرّف علم التفسير اصطلاحًا واذكر نوعيه الرئيسين.","اذكر أربعة شروط يجب توفرها في المفسّر.","قارن بين التفسير بالمأثور والتفسير بالرأي المحمود مع مثال لكل منهما."],"levels":{"easy":[{"type":"mcq","q":"ما المقصود بـ«التفسير بالمأثور»؟","options":["تفسير القرآن بالقرآن أو بالسنة أو بأقوال الصحابة والتابعين","التفسير بالخيال الشخصي","تفسير الأحلام فقط","ترجمة الكلمات فقط"],"answer":0,"why":"المأثور ما نُقل عن الوحي والصحابة والتابعين."},{"type":"mcq","q":"أي طريق يُعد «أول وأصح» طرق التفسير بالمأثور؟","options":["التفسير بالرأي المذموم","تفسير القرآن بالقرآن","التخمين اللغوي","آراء غير المتخصصين"],"answer":1,"why":"تفسير القرآن بالقرآن أعلى مراتب التفسير لأن الله أعلم بمراده."},{"type":"mcq","q":"الفرق بين التفسير بالرأي المحمود والمذموم هو:","options":["كلاهما محرّم","لا فرق بينهما","المحمود مبني على علم باللغة والشرع بلا هوى، والمذموم بجهل وهوى","كلاهما مباح للجميع"],"answer":2,"why":"العلم والضوابط الشرعية هما الفارق بين المحمود والمذموم."},{"type":"mcq","q":"من أبرز الصحابة الذين اشتهروا بعلم التفسير (ترجمان القرآن):","options":["النجاشي","أبو لهب","سهيل بن عمرو","عبد الله بن عباس رضي الله عنهما"],"answer":3,"why":"دعا له النبي ﷺ: «اللهم فقهه في الدين وعلّمه التأويل»."}],"medium":[{"type":"mcq","q":"أي شرط مما يلي أساسي في المفسّر؟","options":["إتقان علوم اللغة العربية والسنة النبوية وأسباب النزول مع صحة العقيدة","امتلاك المال فقط","حفظ الشعر فقط دون السنة","السرعة في الكلام"],"answer":0,"why":"التفسير يحتاج أدوات لغوية وشرعية متكاملة."},{"type":"mcq","q":"كتاب «جواهر التفسير» من التفاسير العُمانية المعاصرة لمؤلفه:","options":["الإمام البخاري","سماحة الشيخ أحمد بن حمد الخليلي","سيبويه","ابن خلدون"],"answer":1,"why":"جواهر التفسير من أبرز مؤلفات التفسير العُمانية المعاصرة."},{"type":"mcq","q":"تفسير النبي ﷺ لقوله تعالى ﴿الظلم﴾ في آية الأنعام بـ«الشرك» مثال على:","options":["القياس الفقهي","التفسير بالرأي المذموم","تفسير القرآن بالسنة النبوية","علم التجويد"],"answer":2,"why":"بيّن النبي ﷺ المراد بالظلم في الآية أنه الشرك."},{"type":"tfr","q":"يُعد النبي ﷺ هو المفسّر والمبيّن الأول للقرآن الكريم.","answer":true,"reasons":["لم يفسر النبي أي آية","لقوله تعالى ﴿وأنزلنا إليك الذكر لتبين للناس ما نزل إليهم﴾","بدأ التفسير بعد قرنين"],"reason":1},{"type":"tfr","q":"يجوز لأي شخص تفسير القرآن الكريم برأيه الشخصي دون معرفة اللغة العربية أو السنة.","answer":false,"reasons":["لا شروط للتفسير","نعم يجوز للجميع","التفسير بالجهل والهوى محرم؛ وللمفسر شروط علمية وشرعية دقيقة"],"reason":2},{"type":"essay","q":"عرّف علم التفسير اصطلاحًا واذكر نوعيه الرئيسين.","model":"علم يُفهم به كتاب الله وبيان معانيه واستخراج أحكامه. نوعاه: التفسير بالمأثور، والتفسير بالرأي (المحمود والمذموم)."},{"type":"essay","q":"اذكر أربعة شروط يجب توفرها في المفسّر.","model":"١) صحة العقيدة والإخلاص. ٢) إتقان اللغة العربية وعلومها. ٣) معرفة السنة وأسباب النزول والناسخ والمنسوخ. ٤) البعد عن الهوى."}],"hard":[{"type":"mcq","q":"ما حكم القول في تفسير القرآن الكريم بالهوى وبغير علم؟","options":["واجب","مباح للجميع","مستحب","محرّم ومنهي عنه بشدة"],"answer":3,"why":"قال تعالى ﴿وأن تقولوا على الله ما لا تعلمون﴾."},{"type":"mcq","q":"من أشهر كتب «التفسير بالمأثور» عبر التاريخ:","options":["جامع البيان للطبري وتفسير ابن كثير","الأغاني للأصفهاني","كتاب العين","المقدمة لابن خلدون"],"answer":0,"why":"الطبري وابن كثير من أمهات كتب التفسير بالمأثور."},{"type":"mcq","q":"معرفة «أسباب النزول» تفيد المفسّر في:","options":["تغيير نص الآية","فهم سياق الآية والمراد الدقيق منها ودفع الإشكال","حذف الآية","تجاهل اللغة العربية"],"answer":1,"why":"سبب النزول يكشف ملابسات الخطاب القرآني بوضوح."},{"type":"mcq","q":"أفضل خطوة لطالب الصف التاسع إذا أشكل عليه معنى آية قرآنية هي:","options":["تجاهل الآية","تأليف معنى من عنده","الرجوع إلى تفسير موثوق كالتفسير الميسّر أو سؤال معلمه","أخذ أي منشور مجهول"],"answer":2,"why":"التثبت من المصادر الموثوقة يحفظ الفهم الصحيح."},{"type":"tfr","q":"التفسير بالرأي المحمود مقبول إذا التزم بضوابط اللغة والشرع ولم يخالف النصوص.","answer":true,"reasons":["وهو اجتهاد علمي منضبط لاستخراج المعاني واللطائف","كل تفسير بالرأي حرام مطلقًا","لا وجود للرأي المحمود"],"reason":0},{"type":"tfr","q":"تفسير القرآن بالقرآن يعني أن ما جاء مجملًا في آية قد يُفصّل في آية أخرى.","answer":true,"reasons":["لا تفسّر الآيات بعضها","وهو أصح طرق التفسير بالمأثور","يتعارض مع السنة"],"reason":1},{"type":"tfr","q":"علم التفسير يعين المسلم على التدبّر والعمل الصحيح بأحكام القرآن.","answer":true,"reasons":["لا يفيد في التدبر","للمتخصصين فقط بلا أثر عملي","فالفهم السليم هو الجسر بين التلاوة والتطبيق العملي"],"reason":2},{"type":"essay","q":"قارن بين التفسير بالمأثور والتفسير بالرأي المحمود مع مثال لكل منهما.","model":"بالمأثور: يعتمد على القرآن والسنة وأقوال الصحابة (تفسير الطبري وابن كثير). بالرأي المحمود: اجتهاد عالم متمكن بالضوابط اللغوية والشرعية."},{"type":"essay","q":"اذكر مثالًا لتفسير القرآن بالقرآن ومثالًا لتفسير القرآن بالسنة.","model":"بالقرآن: تفسير الكلمات التي تلقاها آدم بـ﴿ربنا ظلمنا أنفسنا﴾. بالسنة: تفسير «القوة» بالرمي و«الظلم» بالشرك."},{"type":"essay","q":"لماذا حذّر الإسلام من التفسير بالهوى وبغير علم؟","model":"لأنه افتراء على الله وتحريف لمعاني كتابه وإضلال للناس عن الفهم الصحيح للدين."}]}},
  {"id":"g9-islamic-2-u1-2","grade":"g9","subject":"islamic","term":2,"unit":1,"no":2,"title":"سورة الفتح (٢٨–٢٩) — تفسير","summary":"شرح متحرك بـ SVG لدرس سورة الفتح (٢٨–٢٩) — تفسير (الصف التاسع - الفصل الثاني)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.","page":"lesson-surah-al-fath-28-29.html","video":"","pdf":"","notes":["الآية ٢٨ تبشّر بظهور الإسلام بالهدى ودين الحق.","الآية ٢٩ تصف المؤمنين: أشداء على المعتدين، رحماء بينهم، ركعًا سجدًا، مخلصين، وسيما الخشوع في وجوههم.","مثلهم في الإنجيل كزرع أخرج شطأه فآزره: دلالة على النمو والتكامل والتعاون."],"exercises":["استخرج خمس صفات للصحابة والمؤمنين من الآية ٢٩ من سورة الفتح.","اشرح مَثَل «الزرع» في الآية ٢٩ وبيّن وجه الشبه بينه وبين المجتمع المسلم.","ما معنى: شطأه، فآزره، استوى على سوقه، سيماهم؟"],"levels":{"easy":[{"type":"mcq","q":"ما معنى «شَطْأَه» في قوله تعالى ﴿كزرع أخرج شطأه فآزره﴾؟","options":["أوراقه اليابسة","فراخه وفروعه التي تنبت حوله فتقوّيه","جذوره المقطوعة","الماء المالح"],"answer":1,"why":"الشطء هو الفروع والنباتات الصغيرة التي تخرج بجانب الزرع وتقوّيه."},{"type":"mcq","q":"ما معنى «سِيماهم في وجوههم» في الآية ٢٩ من سورة الفتح؟","options":["كثرة أموالهم","لون بشرتهم","علامتهم الواضحة من النور والوقار والسكينة من أثر الطاعة والخشوع","ملابسهم الفاخرة"],"answer":2,"why":"السيما هي العلامة الدالة على الخشوع وحسن السمت والإيمان."},{"type":"mcq","q":"ما المقصود بـ«الهدى» و«دين الحق» في الآية ٢٨؟","options":["الشعر والخطابة","المال والجاه","السفر والتجارة","العلم النافع والقرآن، والشريعة العادلة والعمل الصالح"],"answer":3,"why":"الهدى هو العلم الصحيح، ودين الحق هو العمل والشريعة."},{"type":"mcq","q":"ما معنى «فَآزَرَهُ» في مَثَل الزرع بالآية ٢٩؟","options":["قوّاه وشدّه وأعانه","قطعه","أيبسه","أحرقه"],"answer":0,"why":"المؤازرة هي التقوية والمعاونة."}],"medium":[{"type":"mcq","q":"بمَ تصف الآية ٢٩ تعامل المؤمنين فيما بينهم؟","options":["القسوة والشدة","﴿رحماء بينهم﴾ أي تسودهم المودة والعطف والتكافل","التنافس العدائي","القطيعة"],"answer":1,"why":"الرحمة والتآلف أبرز صفة داخل المجتمع المسلم."},{"type":"mcq","q":"ما الغاية التي يطلبها المؤمنون من ركوعهم وسجودهم كما في الآية؟","options":["المال الدنيوي","مدح الناس وشهرتهم","﴿يبتغون فضلًا من الله ورضوانًا﴾ (الإخلاص لله وحده)","المباهاة"],"answer":2,"why":"إخلاص النية لابتغاء فضل الله ورضوانه."},{"type":"mcq","q":"مَثَل «الزرع الذي أخرج شطأه فآزره» ورد في وصفهم في:","options":["الأمثال الشعبية","الشعر الجاهلي","التاريخ اليوناني","الإنجيل"],"answer":3,"why":"قالت الآية: ﴿ومثلهم في الإنجيل كزرع أخرج شطأه...﴾."},{"type":"tfr","q":"تجمع الآية ٢٩ من سورة الفتح جميع حروف اللغة العربية في آية واحدة، وتصف جيل الصحابة بأرقى الصفات.","answer":true,"reasons":["آية قصيرة جدًّا","لا تصف الصحابة","فهي آية عظيمة المبنى والمعنى في وصف الصحابة الكرام"],"reason":2},{"type":"tfr","q":"معنى «رحماء بينهم» يوجب اللين والعفو والتكافل بين المسلمين في الأسرة والمدرسة والمجتمع.","answer":true,"reasons":["فالرحمة المتبادلة أساس تماسك الأمة","تعني القسوة على الإخوة","خاصة بالحرب فقط"],"reason":0},{"type":"essay","q":"استخرج خمس صفات للصحابة والمؤمنين من الآية ٢٩ من سورة الفتح.","model":"١) أشداء على المعتدين. ٢) رحماء بينهم. ٣) كثرة الركوع والسجود. ٤) الإخلاص وابتغاء رضوان الله. ٥) سيما الخشوع والوقار، والتكامل كالزرع."},{"type":"essay","q":"اشرح مَثَل «الزرع» في الآية ٢٩ وبيّن وجه الشبه بينه وبين المجتمع المسلم.","model":"بدأ الزرع صغيرًا ثم أخرج فروعًا قوّته حتى استوى قويًا يعجب الزراع؛ وكذلك بدأ الإسلام بقلة ثم تآزر المؤمنون وتعاونوا حتى صاروا أمة عظيمة."}],"hard":[{"type":"mcq","q":"معنى «فَاسْتَوَىٰ عَلَىٰ سُوقِهِ» في الآية ٢٩ هو:","options":["استقام واعتدل قائمًا على سيقانه قويًا ناضجًا","سقط على الأرض","ذبل وجفّ","اقتُلع من التربة"],"answer":0,"why":"السوق جمع ساق، أي استقام قويًا مثمرًا."},{"type":"mcq","q":"تختم الآية ٢٩ ببيان أن الوعد بالمغفرة والأجر العظيم مشروط بـ:","options":["النسب فقط","الإيمان الصادق والعمل الصالح","القول بلا عمل","المال الكثير"],"answer":1,"why":"﴿وعد الله الذين آمنوا وعملوا الصالحات منهم مغفرة وأجرًا عظيمًا﴾."},{"type":"mcq","q":"ما الدلالة التربوية لمَثَل الزرع وفروعه التي تقوّيه في حياتنا المدرسية؟","options":["التنافس الأناني","العمل الفردي المنعزل","أهمية التعاون والعمل الجماعي والتكافل ليقوى المجتمع ويزدهر","إهمال الضعفاء"],"answer":2,"why":"تكامل الأفراد يبني مجتمعًا قويًا مثمرًا."},{"type":"mcq","q":"ما الفائدة من وصف المؤمنين بالشدة مع المعتدين والرحمة فيما بينهم؟","options":["القسوة على الأهل","الشدة في كل الأحوال","الضعف أمام المعتدي","الجمع بين القوة والعزة لحماية الحق، واللين والرحمة لبناء الأخوة والمجتمع"],"answer":3,"why":"التوازن بين العزة والرحمة من كمال الشخصية الإسلامية."},{"type":"tfr","q":"المقصود بـ«سيماهم في وجوههم» هو عبوس الوجه وتجهمه.","answer":false,"reasons":["نعم العبوس","بل النور والسكينة والوقار والبشاشة والسمت الحسن من أثر العبادة","الغضب الدائم"],"reason":1},{"type":"tfr","q":"ضرب الله مثل الزرع في الآية ٢٩ لبيان تدرّج نمو الإسلام وتعاظم قوته بتعاون أهله.","answer":true,"reasons":["للحديث عن الزراعة فقط","لبيان ضعف الزرع","فقد بدأ قليلًا ثم قوّى بعضه بعضًا حتى استوى قويًا"],"reason":2},{"type":"tfr","q":"تعد الآية ٢٨ بظهور دين الإسلام وعلو حجته على سائر الأديان.","answer":true,"reasons":["﴿ليظهره على الدين كله وكفى بالله شهيدًا﴾","تتحدث عن انحصاره","تتحدث عن الميراث"],"reason":0},{"type":"essay","q":"ما معنى: شطأه، فآزره، استوى على سوقه، سيماهم؟","model":"شطأه: فروعه وفراخه. فآزره: قوّاه. استوى على سوقه: استقام على سيقانه قويًا. سيماهم: علامتهم من النور والوقار."},{"type":"essay","q":"كيف تطبّق صفة «رحماء بينهم» في تعاملك مع زملائك في المدرسة؟","model":"بمساعدة المحتاج للفهم، والعفو عن الهفوات، وترك السخرية والتنمر، وإدخال السرور عليهم."},{"type":"essay","q":"بيّن أهمية «الإخلاص» كما ورد في قوله ﴿يبتغون فضلًا من الله ورضوانًا﴾.","model":"الإخلاص يجعل الصلاة والعمل خالصًا لله وحده بعيدًا عن الرياء، وهو شرط قبول العمل ونيل رضوان الله."}]}},
  {"id":"g9-islamic-2-u1-3","grade":"g9","subject":"islamic","term":2,"unit":1,"no":3,"title":"العدل في الخصومة (حديث شريف)","summary":"شرح متحرك بـ SVG لدرس العدل في الخصومة (حديث شريف) (الصف التاسع - الفصل الثاني)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.","page":"lesson-justice-in-disputes.html","video":"","pdf":"","notes":["العدل واجب حتى مع الخصم والمخالف ﴿اعدلوا هو أقرب للتقوى﴾.","الفجور في الخصومة (الكذب، الشتم، إفشاء الأسرار) من علامات النفاق.","من أصول العدل: سماع الطرفين قبل الحكم، وقبول الحق، والمبادرة بالصلح."],"exercises":["ما المقصود بالفجور في الخصومة؟ واذكر ثلاث صور له يجب اجتنابها.","اذكر أربعة ضوابط إسلامية للعدل في الخصومة.","اشرح كيف تطبّق وصية النبي ﷺ لعلي بن أبي طالب في سماع الطرفين داخل المدرسة أو البيت."],"levels":{"easy":[{"type":"mcq","q":"ما معنى قوله ﷺ في علامات النفاق: «وإذا خاصم فجر»؟","options":["عفى عن خصمه","صلّى الفجر جماعة","مال عن الحق وتجاوز الحد بالكذب أو الشتم أو الظلم عند الخلاف","سكت عن الباطل"],"answer":2,"why":"الفجور في الخصومة هو الانحراف عن الحق والعدوان بالقول أو الفعل."},{"type":"mcq","q":"ما القاعدة النبوية الذهبية لمن يحكم أو يُصلح بين متخاصمين؟","options":["لا يسمع لأحد","يحكم للأول فورًا","يحكم لصديقه دائمًا","لا يحكم لأحدهما حتى يسمع كلام الطرف الآخر بنفس الإنصاف"],"answer":3,"why":"سماع الطرفين أساس العدالة في القضاء والإصلاح."},{"type":"mcq","q":"ما المقصود بـ«شَنَآنُ قَوْمٍ» في الآية ﴿ولا يجرمنكم شنآن قوم على ألا تعدلوا﴾؟","options":["بُغض قوم وعداوتهم لا يحملكم على ظلمهم","محبة قوم","سفر قوم","كثرة مالهم"],"answer":0,"why":"الشنآن هو البغض والعداوة، ولا يبرر الظلم أبدًا."},{"type":"mcq","q":"أفشى طالب سرًّا قديمًا لصديقه السابق بعد خلاف بينهما؛ هذا السلوك يُعدّ:","options":["حقًا مشروعًا","من الفجور في الخصومة المحرّم","شجاعةً","عدلاً"],"answer":1,"why":"استغلال الأسرار السابقة عند الخلاف من أبشع صور الفجور."}],"medium":[{"type":"mcq","q":"ما الحد الأقصى المسموح به للهجر بين مسلمين متخاصمين في الحديث الشريف؟","options":["سنة كاملة","شهر كامل","ثلاث ليالٍ، وخيرهما الذي يبدأ بالسلام","لا حد له"],"answer":2,"why":"لا يحل لمسلم أن يهجر أخاه فوق ثلاث ليالٍ."},{"type":"mcq","q":"عند الخلاف مع زميل في الرأي داخل الصف، المنهج الإسلامي الصحيح هو:","options":["رفع الصوت عليه","السخرية منه","مقاطعته للأبد","مناقشة الفكرة بأدب وإنصاف دون تجريح شخصه"],"answer":3,"why":"الإنصاف يفصل بين الفكرة والشخص ويحفظ الاحترام."},{"type":"mcq","q":"قوله تعالى ﴿اعدلوا هو أقرب للتقوى﴾ يدل على أن العدل مع الخصم:","options":["واجب شرعي ومن أعظم علامات التقوى","أمر اختياري ثانوي","خاص بالأقارب فقط","يُترك عند الغضب"],"answer":0,"why":"العدل واجب مع القريب والبعيد والمحب والخصم."},{"type":"tfr","q":"يجوز للمسلم أن يذكر عيوب خصمه أو يفشي أسراره القديمة إذا أغضبه.","answer":false,"reasons":["هذا من الفجور في الخصومة المذموم الذي حذّر منه النبي ﷺ","نعم يجوز عند الغضب","لا بأس بإفشاء السر"],"reason":0},{"type":"tfr","q":"أمر النبي ﷺ القاضي والمصلح بسماع كلام الطرفين قبل إصدار أي حكم.","answer":true,"reasons":["يكفي سماع الأول","لأن سماع طرف واحد فقط قد يوقع في الظلم والخطأ","يحكم بحسب القرابة"],"reason":1},{"type":"essay","q":"ما المقصود بالفجور في الخصومة؟ واذكر ثلاث صور له يجب اجتنابها.","model":"تجاوز الحق والعدوان عند الخلاف. صوره: الكذب على الخصم، والشتم والتشهير، وإفشاء أسراره السابقة."},{"type":"essay","q":"اذكر أربعة ضوابط إسلامية للعدل في الخصومة.","model":"١) سماع الطرفين قبل الحكم. ٢) ضبط اللسان وترك السب. ٣) حفظ الأسرار السابقة. ٤) الاعتراف بالحق والمبادرة بالصلح."}],"hard":[{"type":"mcq","q":"ما الموقف الصحيح إذا تبيّن لك أثناء الخلاف أن «الحق مع خصمك»؟","options":["الاستمرار في العناد","الاعتراف بالحق والاعتذار بشجاعة وردّ الحق إليه","إخفاء الحقيقة","إلقاء اللوم على غيرك"],"answer":1,"why":"الرجوع إلى الحق فضيلة وشجاعة أخلاقية."},{"type":"mcq","q":"من ثمرات الالتزام بالعدل في الخصومة داخل المجتمع:","options":["ضياع الحقوق","زيادة الكراهية","منع تفاقم العداوات وبقاء جسور الصلح والثقة","ضعف القضاء"],"answer":2,"why":"الإنصاف يطفئ نار الخصومة ويسهّل الصلح."},{"type":"mcq","q":"العدل في الشهادة يعني أن تشهد بالحق:","options":["لا تشهد أبدًا","لصالح صديقك فقط","ضد خصمك دائمًا","ولو على نفسك أو قريبك أو لصالح من تختلف معه"],"answer":3,"why":"﴿كونوا قوامين بالقسط شهداء لله﴾."},{"type":"mcq","q":"كيف يتصرف قائد مجموعة مدرسية عند خلاف بين عضوين؟","options":["يستمع لكل منهما على حدة بعدل وهدوء ثم يصلح بينهما بإنصاف","يعاقب أحدهما فورًا","يطردهما من المجموعة","يتجاهل الخلاف"],"answer":0,"why":"سماع الطرفين والإنصاف يحلان الخلاف بعدل."},{"type":"tfr","q":"العدل واجب حتى مع من تكرهه أو تختلف معه لقوله تعالى ﴿ولا يجرمنكم شنآن قوم على ألا تعدلوا﴾.","answer":true,"reasons":["لا عدل مع الخصم","العدل للأصدقاء فقط","فالعدل قيمة مطلقة لا تتغير بالحب أو البغض"],"reason":2},{"type":"tfr","q":"المبادرة بالسلام والصلح بعد الخلاف دليل ضعف في الشخصية.","answer":false,"reasons":["بل دليل قوة نفسية وشرف؛ قال ﷺ «وخيرهما الذي يبدأ بالسلام»","نعم دليل ضعف","الهجر الطويل أفضل"],"reason":0},{"type":"tfr","q":"إقرارك بالحق لخصمك عند خطئك يرفع قدرك عند الله وعند الناس.","answer":true,"reasons":["يقلل من شأنك","فالرجوع إلى الحق فضيلة وشجاعة أخلاقية عالية","العناد أفضل"],"reason":1},{"type":"essay","q":"اشرح كيف تطبّق وصية النبي ﷺ لعلي بن أبي طالب في سماع الطرفين داخل المدرسة أو البيت.","model":"إذا جاءني أخ أو زميل يشكو آخر، لا أحكم فورًا ولا أغضب، بل أستمع للطرف الثاني بهدوء وإنصاف ثم أصلح بينهما بالحق."},{"type":"essay","q":"استدل بآية قرآنية وحديث شريف على وجوب العدل في الخصومة.","model":"الآية: ﴿ولا يجرمنكم شنآن قوم على ألا تعدلوا اعدلوا هو أقرب للتقوى﴾. الحديث: آية المنافق «وإذا خاصم فجر»."},{"type":"essay","q":"قارن بين أثر «العدل في الخصومة» وأثر «الفجور في الخصومة» على العلاقات الإنسانية.","model":"العدل يحفظ الحقوق ويبقي باب الصلح مفتوحًا ويكسب الاحترام؛ أما الفجور فيحوّل الخلاف العابر لعداوة دائمة وظلم وفساد."}]}},
  {"id":"g9-islamic-2-u1-4","grade":"g9","subject":"islamic","term":2,"unit":1,"no":4,"title":"الله المُحصي (عقيدة)","summary":"شرح متحرك بـ SVG لدرس الله المُحصي (عقيدة) (الصف التاسع - الفصل الثاني)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.","page":"lesson-allah-al-muhsi.html","video":"","pdf":"","notes":["المُحصي: الذي أحاط علمه بكل شيء وأحصاه عددًا وحفظ أعمال العباد بدقة.","أدلته: ﴿وأحصى كل شيء عددًا﴾ و﴿لا يغادر صغيرة ولا كبيرة إلا أحصاها﴾.","ثماره: المراقبة الذاتية، عدم احتقار الخير الصغير، محاسبة النفس والتوبة، وتنظيم الوقت."],"exercises":["عرّف اسم الله «المُحصي» واستدل بآيتين من القرآن الكريم.","اذكر أربعة آثار عملية للإيمان باسم الله «المُحصي» في حياة الطالب.","كيف يجمع اسم الله المُحصي بين بثّ «الأمل» و«الحذر» في قلب المؤمن؟"],"levels":{"easy":[{"type":"mcq","q":"ما معنى اسم الله «المُحصي»؟","options":["الذي يغفر دون حساب","الذي يخلق الألوان فقط","الذي يرزق فقط","الذي أحاط علمه بجميع المخلوقات والأعمال وأحصى كل شيء عددًا دون نسيان"],"answer":3,"why":"المُحصي يشمل الإحاطة التامة والعدّ الدقيق والحفظ لكل شيء."},{"type":"mcq","q":"ما الآية الدالة مباشرةً على إحاطة الله وإحصائه لكل أعمال العباد صغيرةً وكبيرة؟","options":["﴿لا يغادر صغيرة ولا كبيرة إلا أحصاها﴾","﴿إنا أعطيناك الكوثر﴾","﴿قل أعوذ برب الفلق﴾","﴿تبت يدا أبي لهب﴾"],"answer":0,"why":"سورة الكهف: ٤٩ تبيّن دقة إحصاء كتاب الأعمال."},{"type":"mcq","q":"ما أثر الإيمان باسم الله «المُحصي» على سلوك الطالب في الخلوة؟","options":["التساهل في الخلوة","الاستقامة ومراقبة الله وترك المعاصي والغش حتى دون رقيب بشري","نسيان الصلاة","الإساءة للآخرين"],"answer":1,"why":"اليقين بأن الله محصٍ لكل فعل يزرع الرقابة الذاتية."},{"type":"mcq","q":"كيف يشجّع الإيمان بالمُحصي على فعل الأعمال الصالحة الصغيرة؟","options":["لأن الكبار فقط يُكتب عملهم","لأن الصغيرة لا تُكتب","لأن المؤمن يوقن أن مثقال ذرة من الخير محفوظ ومحصى ومثاب عليه عند الله","لا يشجع"],"answer":2,"why":"لا يضيع عند الله أي معروف مهما بدا صغيرًا."}],"medium":[{"type":"mcq","q":"ما معنى قوله تعالى ﴿أَحْصَاهُ اللَّهُ وَنَسُوهُ﴾؟","options":["تُمحى تلقائيًا بلا توبة","نسي الله أعمالهم","لا يُحاسبون عليها","حفظ الله أعمالهم بدقة في كتابهم حتى لو نسوها مع مرور الزمن"],"answer":3,"why":"النسيان البشري لا يُسقط الإحصاء الإلهي الدقيق."},{"type":"mcq","q":"كيف نُعالج ما أُحصي علينا من ذنوب وزلّات؟","options":["بالتوبة النصوح والاستغفار وإتباع السيئة الحسنة تمحها","بإنكارها","باليأس من رحمة الله","بالاستمرار فيها"],"answer":0,"why":"التوبة الصادقة تمحو الذنوب برحمة الله."},{"type":"mcq","q":"من الآثار السلوكية الإيجابية لمعرفة اسم الله المُحصي في الدراسة والعمل:","options":["الفوضى والعشوائية","تنظيم الوقت ومحاسبة النفس وإتقان العمل بدقة","تأجيل الواجبات","الغش"],"answer":1,"why":"التنظيم وحفظ الوقت من ثمرات استشعار الإحصاء."},{"type":"tfr","q":"يشمل إحصاء الله تعالى الأقوال والأفعال والنيات الخفية وجميع ذرات الكون.","answer":true,"reasons":["يشمل الأفعال الظاهرة فقط","لا يغيب عن علمه مثقال ذرة في السماوات ولا في الأرض","لا يشمل النيات"],"reason":1},{"type":"tfr","q":"إذا نسي الإنسان ذنبًا فعله قبل سنوات فإنه يُمحى تلقائيًا دون توبة.","answer":false,"reasons":["لا يُكتب أصلًا","نعم يُمحى بالنسيان","قال تعالى ﴿أحصاه الله ونسوه﴾، ولا يُمحى إلا بالتوبة الصادقة والاستغفار"],"reason":2},{"type":"essay","q":"عرّف اسم الله «المُحصي» واستدل بآيتين من القرآن الكريم.","model":"المُحصي: الذي أحاط علمه بكل شيء وأحصاه عددًا وحفظه بدقة. الأدلة: ﴿وأحصى كل شيء عددًا﴾، ﴿لا يغادر صغيرة ولا كبيرة إلا أحصاها﴾."},{"type":"essay","q":"اذكر أربعة آثار عملية للإيمان باسم الله «المُحصي» في حياة الطالب.","model":"١) المراقبة الذاتية وترك الغش في السر والعلن. ٢) المبادرة لصغائر الخير وعدم احتقارها. ٣) محاسبة النفس يوميًا والتوبة. ٤) تنظيم الوقت والدقة في العمل."}],"hard":[{"type":"mcq","q":"مَن يتولى كتابة وإحصاء أعمال العباد بأمر الله تعالى؟","options":["لا أحد يكتبها","البشر فقط","الملائكة الكرام الكاتبون","النجوم"],"answer":2,"why":"﴿وإن عليكم لحافظين كرامًا كاتبين﴾."},{"type":"mcq","q":"قوله تعالى ﴿وما تسقط من ورقة إلا يعلمها﴾ يدل على:","options":["محدودية العلم","أن العلم للأشجار فقط","أن الورق لا يسقط","شمول علم الله وإحصائه لأدق تفاصيل الكون والمخلوقات"],"answer":3,"why":"سقوط ورقة شجرة في غابة بعيدة محصى في علم الله."},{"type":"mcq","q":"طالب ساعد زميله في الخفاء ولم يشكره أحد، لكنه فرح واطمأن لأن:","options":["الله المُحصي يعلم عمله وأحصاه له في ميزان حسناته","لا فائدة من العمل","سيغضب من زميله","ضاع أجره"],"answer":0,"why":"الإخلاص واليقين بإحصاء الله يغنيان عن مدح الناس."},{"type":"mcq","q":"التوازن السليم في الإيمان بالمُحصي يجمع بين:","options":["اليأس والخوف فقط","الخشية من إحصاء السيئات (فتُتجنّب) والرجاء في إحصاء الحسنات ومضاعفتها","الأمن التام والغفلة","ترك العمل"],"answer":1,"why":"الجمع بين الخوف والرجاء يدفع للاستقامة."},{"type":"tfr","q":"استشعار اسم الله المُحصي يحفّز المسلم على عدم احتقار أي معروف صغير كالابتسامة والكلمة الطيبة.","answer":true,"reasons":["لأن كل مثقال ذرة من خير محفوظ ومضاعف عند الله","الأعمال الصغيرة لا تُحصى","الكبيرة فقط تُحصى"],"reason":0},{"type":"tfr","q":"الإيمان باسم الله المُحصي يورث العشوائية وعدم التخطيط.","answer":false,"reasons":["نعم يورث العشوائية","بل يربي المسلم على محاسبة نفسه وتنظيم وقته وإتقان عمله","لا أثر له في التنظيم"],"reason":1},{"type":"tfr","q":"التوبة النصوح تمحو ما كُتب على العبد من ذنوب بفضل الله ورحمته.","answer":true,"reasons":["التوبة لا تغير الكتاب","لا تُمحى الذنوب أبدًا","فالله المُحصي هو أيضًا الغفور الرحيم التواب"],"reason":2},{"type":"essay","q":"كيف يجمع اسم الله المُحصي بين بثّ «الأمل» و«الحذر» في قلب المؤمن؟","model":"يبث الأمل لأن كل حسنة صغيرة محفوظة ومضاعفة لا تضيع، ويبث الحذر والورع لأن كل سيئة وكلمة مسجّلة ومحاسَب عليها."},{"type":"essay","q":"اشرح كيف تطبّق «محاسبة النفس» قبل النوم يوميًا في ضوء هذا الدرس.","model":"أراجع يومي في دقيقتين: أحمد الله على الطاعات والإنجازات، وأستغفر وأتوب من أي تقصير أو كلمة مؤذية، وأخطط ليوم الغد."},{"type":"essay","q":"علّل: لماذا لا يحزن المؤمن المخلص إذا لم يره الناس أو لم يشكروه على خير فعله؟","model":"لأنه يوقن أن الله المُحصي قد رآه وأحصى عمله ونيته، وأجره محفوظ عند الله وحده."}]}},
  {"id":"g9-islamic-2-u1-5","grade":"g9","subject":"islamic","term":2,"unit":1,"no":5,"title":"يوم العُسرَة (سيرة)","summary":"شرح متحرك بـ SVG لدرس يوم العُسرَة (سيرة) (الصف التاسع - الفصل الثاني)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.","page":"lesson-expedition-of-tabuk.html","video":"","pdf":"","notes":["وقعت غزوة تبوك (يوم العسرة) في رجب سنة ٩ هـ لردع الروم، وشارك فيها ٣٠ ألف مقاتل.","سُمّيت العسرة لشدة الحر وبُعد المسافة وقلة الزاد وموسم الثمار.","بذل فيها عثمان وأبو بكر وعمر وأبو عقيل، وبرز صدق البكائين وكعب بن مالك.","انتهت بنصر سياسي وعسكري بلا قتال ومعاهدات سلمية في الشمال."],"exercises":["اذكر أربعة أسباب لتسمية غزوة تبوك بـ«يوم العسرة».","اذكر ثلاثة نماذج مشرقة للبذل والإنفاق في تجهيز جيش العسرة.","قارن بين موقف «البكّائين» وموقف «المنافقين» في غزوة تبوك."],"levels":{"easy":[{"type":"mcq","q":"في أي سنة هجرية وقعت غزوة تبوك (يوم العسرة)؟","options":["السنة التاسعة للهجرة (٩ هـ)","السنة الثانية للهجرة","السنة الخامسة للهجرة","السنة الأولى للهجرة"],"answer":0,"why":"كانت غزوة تبوك في رجب سنة ٩ هـ وهي آخر غزوات النبي ﷺ."},{"type":"mcq","q":"مَن الصحابي الذي جهّز ثلث جيش العسرة فقال عنه النبي ﷺ «ما ضرّ عثمان ما عمل بعد اليوم»؟","options":["أبو هريرة","عثمان بن عفان رضي الله عنه","بلال بن رباح","خالد بن الوليد"],"answer":1,"why":"أنفق عثمان ٣٠٠ بعير بأحلاسها وأقتابها و١٠٠٠ دينار لتجهيز الجيش."},{"type":"mcq","q":"لماذا سُمّيت غزوة تبوك بـ«يوم العسرة»؟","options":["لقرب المسافة جدًّا","لسقوط الثلوج","لاشتداد الحرّ وبُعد المسافة وقلة الزاد والرواحل ووقت نضج الثمار","لكثرة الأموال"],"answer":2,"why":"اجتمعت ظروف اقتصادية ومناخية وجغرافية صعبة."},{"type":"mcq","q":"ما الدرس الأعظم من قصة الصحابي «كعب بن مالك» وصاحبيه في غزوة تبوك؟","options":["أن التخلّف بلا عذر مقبول","أن الكذب ينجي","أن التوبة مغلقة","أن الصدق في الاعتراف بالخطأ منجاة وسبب لمغفرة الله"],"answer":3,"why":"نجّى الله الثلاثة وتاب عليهم لصدقهم وتركهم الأعذار الكاذبة."}],"medium":[{"type":"mcq","q":"من هم «البكّاؤون» في غزوة تبوك؟","options":["فقراء من الصحابة بكوا حزنًا لأنهم لم يجدوا رواحل يخرجون عليها مع النبي ﷺ","المنافقون","جيش الروم","التجار"],"answer":0,"why":"أثنى الله على صدق نيتهم في سورة التوبة."},{"type":"mcq","q":"ما النتيجة العسكرية والسياسية لغزوة تبوك؟","options":["هزيمة المسلمين","انسحب الروم دون قتال وعقد المسلمون معاهدات سلم وعزّزوا هيبة الدولة","استمرار القتال شهرًا","احتلال المدينة"],"answer":1,"why":"تحقق الردع والنصر السياسي دون إراقة دماء."},{"type":"mcq","q":"كم كان عدد جيش المسلمين تقريبًا في غزوة تبوك؟","options":["١٠٠٠ مقاتل","٣١٣ مقاتلًا","نحو ٣٠ ألف مقاتل","١٠٠ مقاتل"],"answer":2,"why":"كان أكبر جيش خرج به النبي ﷺ في حياته."},{"type":"tfr","q":"كانت غزوة تبوك (سنة ٩ هـ) آخر غزوة غزاها النبي ﷺ بنفسه.","answer":true,"reasons":["وقعت قبل الهجرة","كانت أول غزوة","وخرج فيها في نحو ٣٠ ألف مقاتل وعاد منتصرًا بلا قتال"],"reason":2},{"type":"tfr","q":"سارع المنافقون للإنفاق في تجهيز جيش العسرة وأثنوا على صدقة الفقراء.","answer":false,"reasons":["بل تخاذلوا واختلقوا الأعذار وسخروا من صدقة الفقراء كأبي عقيل","نعم أنفقوا بسخاء","خرجوا جميعًا"],"reason":0},{"type":"essay","q":"اذكر أربعة أسباب لتسمية غزوة تبوك بـ«يوم العسرة».","model":"١) شدة الحرّ صيفًا. ٢) بُعد المسافة (نحو ٧٠٠ كم). ٣) قلة المال والزاد والرواحل. ٤) تزامنها مع موسم نضج الثمار وحصادها."},{"type":"essay","q":"اذكر ثلاثة نماذج مشرقة للبذل والإنفاق في تجهيز جيش العسرة.","model":"١) عثمان بن عفان (ثلث الجيش: ٣٠٠ بعير و١٠٠٠ دينار). ٢) أبو بكر الصديق (ماله كله) وعمر بن الخطاب (نصف ماله). ٣) أبو عقيل الأنصاري (صاع تمر كسبه بعرق جبينه)."}],"hard":[{"type":"mcq","q":"تصدّق الصحابي الفقير «أبو عقيل» بصاع من تمر سهر ليلةً لكسبه، فسخر المنافقون منه؛ فماذا يعلّمنا موقفه؟","options":["أن التمر لا يُتصدق به","أن القليل لا يُقبل","أن الإنفاق للأغنياء فقط","أن قيمة العطاء عند الله بصدق النية والجهد لا بكثرة المال فقط"],"answer":3,"why":"أنزل الله آيةً تذم الساخرين وتثني على المتصدقين بجهدهم."},{"type":"mcq","q":"أعلن النبي ﷺ وجهة غزوة تبوك صراحةً قبل الخروج (بخلاف عادته في الغزوات) بسبب:","options":["بُعد المسافة وشدة الحرّ وحاجة الناس للاستعداد الجيد بالزاد والماء","عدم وجود أسرار","قصر المسافة","طلب الروم"],"answer":0,"why":"حتى يتجهّز الناس بالزاد والرواحل الكافية للطريق الطويل."},{"type":"mcq","q":"كيف قابل النبي ﷺ اعتراف كعب بن مالك الصادق بتخلّفه بلا عذر؟","options":["عفا عنه فورًا في نفس الدقيقة","قال «أما هذا فقد صدق»، وأمر بهجره حتى ينزل الله فيه حكمه، فتاب الله عليهم بعد ٥٠ يومًا","طرده من المدينة","لم يسمع له"],"answer":1,"why":"الصدق ميّزهم عن المنافقين الكاذبين فأكرمهم الله بالتوبة في القرآن."},{"type":"mcq","q":"في أي سورة قرآنية نزلت آيات غزوة تبوك وتوبة الثلاثة الذين خُلّفوا؟","options":["سورة الفيل","سورة الفاتحة","سورة التوبة","سورة الضحى"],"answer":2,"why":"فصّلت سورة التوبة أحداث العسرة والبكائين والثلاثة الذين خلفوا."},{"type":"tfr","q":"أثبتت قصة كعب بن مالك أن الصدق منجاة عند الله وإن بدا صعبًا في بدايته.","answer":true,"reasons":["الكذب كان أنفع له","فقد أراحه الصدق وأنزل الله توبته تُتلى في القرآن إلى يوم القيامة","لم يتب الله عليه"],"reason":1},{"type":"tfr","q":"تأثير الصدقة القليلة الصادقة (كصاع أبي عقيل) عظيم عند الله بجانب صدقة الأغنياء (كعثمان).","answer":true,"reasons":["الأجر للأغنياء فقط","لا تُقبل الصدقة القليلة","لأن الميزان عند الله هو الإخلاص والبذل حسب الاستطاعة"],"reason":2},{"type":"tfr","q":"التحم المسلمون والروم في معركة دامية استمرت أسبوعًا في تبوك.","answer":false,"reasons":["لم يحدث قتال لأن الروم تفرّقوا وانسحبوا هيبةً لجيش المسلمين","نعم استمرت أسبوعًا","استمرت شهرًا"],"reason":0},{"type":"essay","q":"قارن بين موقف «البكّائين» وموقف «المنافقين» في غزوة تبوك.","model":"البكاؤون كانوا فقراء صادقين حزنوا وبكوا لعجزهم عن الخروج؛ والمنافقون كانوا قادرين لكنهم اختلقوا الأعذار الكاذبة وتخاذلوا وسخروا من المنفقين."},{"type":"essay","q":"ما الدروس المستفادة من قصة كعب بن مالك وصاحبيه في سورة التوبة؟","model":"١) الصدق منجاة مهما كان صعبًا. ٢) عدم تأجيل العمل الصالح والتسويف. ٣) سعة رحمة الله وباب التوبة المفتوح للصادقين."},{"type":"essay","q":"كيف نطبّق روح «التكافل يوم العسرة» في مجتمعنا العُماني عند الأزمات (كالأنواء المناخية)؟","model":"بالتطوّع والمبادرة لمساعدة المتضررين، والإنفاق كلٌّ حسب قدرته دون استصغار القليل، والتكاتف الوطني بصدق وإخلاص."}]}},
  {"id":"g9-islamic-2-u1-6","grade":"g9","subject":"islamic","term":2,"unit":1,"no":6,"title":"الأمن الفكريّ (قيم وأخلاق)","summary":"شرح متحرك بـ SVG لدرس الأمن الفكريّ (قيم وأخلاق) (الصف التاسع - الفصل الثاني)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.","page":"lesson-intellectual-security.html","video":"","pdf":"","notes":["الأمن الفكري: سلامة العقل من الغلو والشائعات والأفكار المنحرفة بالعلم والوسطية.","مهدّداته: التطرف، الشائعات، المصادر المجهولة، والتقليد الأعمى.","وسائل حمايته: التثبت قبل النشر، سؤال أهل العلم، الحوار، والتفكير الناقد."],"exercises":["عرّف الأمن الفكري، واذكر ثلاثة من أبرز مهدّداته في العصر الرقمي.","اذكر أربع وسائل عملية لتعزيز الأمن الفكري لدى طلاب الصف التاسع.","استدل بآية قرآنية وحديث شريف على وجوب التثبت من الأخبار."],"levels":{"easy":[{"type":"mcq","q":"ما المقصود بـ«الأمن الفكري»؟","options":["منع القراءة والتعلم","سلامة العقل والفكر من التطرف والشائعات والأفكار المنحرفة مع وعي وتفكير ناقد","إغلاق المدارس","حفظ الأموال فقط"],"answer":1,"why":"الأمن الفكري يحصّن العقل بالعلم الصحيح والوسطية."},{"type":"mcq","q":"ما القاعدة القرآنية الذهبية في التعامل مع الأخبار والشائعات؟","options":["تصديق أي حساب مجهول","نشر كل ما نسمع فورًا","﴿إن جاءكم فاسق بنبأ فتبيّنوا﴾ (التثبّت قبل التصديق والنشر)","الجدال بلا علم"],"answer":2,"why":"التبيّن والتثبت يمنعان انتشار الشائعات والأذى."},{"type":"mcq","q":"ما معنى قول النبي ﷺ: «كفى بالمرء كذبًا أن يحدّث بكل ما سمع»؟","options":["أن الكذب مباح في الرسائل","منع التحدث مع الناس","وجوب نقل كل الشائعات","التحذير من تناقل الأخبار والرسائل دون تحقق من صحتها"],"answer":3,"why":"نقل الأخبار دون تثبّت يُوقع الإنسان في الكذب والإضرار بالناس."},{"type":"mcq","q":"أي مما يلي يُعد من أبرز «مهدّدات» الأمن الفكري في عصرنا؟","options":["الغلو والتطرف، والشائعات الرقمية، وأخذ الدين والعلم من مجهولين","الحوار الأسري الهادئ","القراءة في المكتبة","التسامح"],"answer":0,"why":"هذه أبرز المخاطر التي تستهدف عقول الشباب."}],"medium":[{"type":"mcq","q":"ما دور «الأسرة والمدرسة» في تعزيز الأمن الفكري للأبناء؟","options":["منع الأبناء من طرح الأسئلة","فتح باب الحوار الهادئ، والإجابة عن التساؤلات بالعلم، وغرس الوسطية","تركهم لمواقع مجهولة","القسوة في النقاش"],"answer":1,"why":"الحوار الواعي يحمي الشباب من المصادر المضلّلة."},{"type":"mcq","q":"أي قيمة إسلامية تمثّل خط الدفاع الأكبر ضد «الغلو والتطرف»؟","options":["الإقصاء","التعصب الأعمى","الوسطية والاعتدال والتسامح","الجهل"],"answer":2,"why":"الإسلام دين الوسطية والرحمة."},{"type":"mcq","q":"طالب قرأ منشورًا يثير الكراهية والفتنة من حساب مجهول؛ ما التصرف الواعي؟","options":["العمل به فورًا","إعادة إرساله لكل المجموعات","الدخول في سباب","عدم تصديقه أو نشره والتبليغ عنه والرجوع للمصادر الرسمية الموثوقة"],"answer":3,"why":"إيقاف الشائعة عندك مسؤولية دينية ووطنية."},{"type":"tfr","q":"إعادة إرسال خبر غير موثّق عبر الهاتف دون تثبّت يخالف منهج الإسلام في الأمن الفكري.","answer":true,"reasons":["لقوله ﷺ «كفى بالمرء كذبًا أن يحدّث بكل ما سمع»","لا بأس ما دمت لم تكتبه بنفسك","الشائعات لا تضر"],"reason":0},{"type":"tfr","q":"الأمن الفكري يعني منع الشباب من التفكير أو طرح الأسئلة العلمية.","answer":false,"reasons":["نعم يمنع الأسئلة","بل يشجّع التفكير الناقد والحوار العلمي الهادف والرجوع لأهل الاختصاص","يلغي العقل"],"reason":1},{"type":"essay","q":"عرّف الأمن الفكري، واذكر ثلاثة من أبرز مهدّداته في العصر الرقمي.","model":"سلامة العقل والفكر من الانحراف والتطرف والشائعات. المهددات: الغلو والتعصب، الشائعات الرقمية، وأخذ العلم من مصادر مجهولة غير موثوقة."},{"type":"essay","q":"اذكر أربع وسائل عملية لتعزيز الأمن الفكري لدى طلاب الصف التاسع.","model":"١) التثبت من المصادر قبل النشر. ٢) تلقّي العلم من أهله الموثوقين. ٣) الحوار الهادئ في الأسرة والمدرسة. ٤) التمسك بالوسطية والتفكير الناقد."}],"hard":[{"type":"mcq","q":"كيف يسهم «التفكير الناقد» في حماية الأمن الفكري؟","options":["يمكّن الطالب من فحص المصدر والدليل والهدف قبل قبول أي فكرة","يجعل الطالب يقبل كل شيء بلا تفكير","يمنع البحث العلمي","يسبب التعصب"],"answer":0,"why":"التفكير الناقد يميّز الحقائق من التضليل."},{"type":"mcq","q":"منهج الإسلام في حفظ الأمن الفكري يرتبط بأحد الضرورات الخمس الكبرى وهو:","options":["إهمال العقل","حفظ الدين وحفظ العقل","ترك العلم","التقليد الأعمى"],"answer":1,"why":"حفظ الدين والعقل من أعظم مقاصد الشريعة."},{"type":"mcq","q":"من ثمرات الأمن الفكري على الوطن:","options":["تراجع التعليم","انتشار القلق والخلافات","تعزيز الوحدة الوطنية والاستقرار وتوجيه طاقات الشباب للابتكار والبناء","ضعف الاقتصاد"],"answer":2,"why":"استقرار الفكر يصنع استقرار المجتمع ونهضته."},{"type":"mcq","q":"أفضل جهة للرجوع إليها عند وجود سؤال شرعي دقيق هي:","options":["الشائعات","حسابات مجهولة الاسم","التخمين الشخصي","العلماء والمؤسسات الدينية الرسمية الموثوقة ومعلم التربية الإسلامية"],"answer":3,"why":"﴿فاسألوا أهل الذكر إن كنتم لا تعلمون﴾."},{"type":"tfr","q":"الوسطية والتسامح العُماني نموذج عملي ناجح في صون الأمن الفكري والوحدة الوطنية.","answer":true,"reasons":["لا علاقة للوسطية بالأمن","التعصب أفضل للأمن","حيث يسود التعايش والاحترام المتبادل والحوار الهادئ"],"reason":2},{"type":"tfr","q":"تلقّي الفتاوى والأفكار من حسابات مجهولة على الإنترنت من أخطر مهدّدات الأمن الفكري.","answer":true,"reasons":["لجهالة مصدرها واحتمال تضمنها غلوًا أو تضليلًا متعمدًا","الحسابات المجهولة موثوقة دائمًا","لا خطر منها"],"reason":0},{"type":"tfr","q":"الحوار المفتوح داخل الأسرة والمدرسة يحصّن الشباب من الانجراف وراء الأفكار المتطرفة.","answer":true,"reasons":["الحوار يضر الأمن الفكري","لأنه يشبع تساؤلاتهم بالعلم الصحيح في بيئة آمنة محبة","يجب تجاهل أسئلة الشباب"],"reason":1},{"type":"essay","q":"استدل بآية قرآنية وحديث شريف على وجوب التثبت من الأخبار.","model":"الآية: ﴿إن جاءكم فاسق بنبأ فتبيّنوا﴾. الحديث: «كفى بالمرء كذبًا أن يحدّث بكل ما سمع»."},{"type":"essay","q":"ما الأسئلة الثلاثة التي يطرحها الطالب الواعي قبل تصديق أي منشور مثير على وسائل التواصل؟","model":"١) مَن المصدر وهل هو رسمي وموثوق؟ ٢) ما الدليل العلمي أو الشرعي؟ ٣) ما الهدف من نشر هذا المحتوى؟"},{"type":"essay","q":"بيّن العلاقة بين الأمن الفكري واستقرار وتنمية سلطنة عُمان.","model":"تحصين عقول الشباب من التطرف والشائعات يحفظ الوحدة الوطنية والأمن الاجتماعي ويوجّه الطاقات نحو العلم والإبداع والبناء."}]}},
  {"id":"g9-islamic-2-u2-1","grade":"g9","subject":"islamic","term":2,"unit":2,"no":1,"title":"الرسم القرآنيّ (تجويد)","summary":"شرح متحرك بـ SVG لدرس الرسم القرآنيّ (تجويد) (الصف التاسع - الفصل الثاني)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.","page":"lesson-quranic-orthography.html","video":"","pdf":"","notes":["الرسم العثماني: الهيئة التوقيفية التي كُتب بها المصحف، ويحوي قواعد الحذف والزيادة والبدل والوصل والفصل.","الصفر المستدير = لا يُنطق مطلقًا؛ الصفر المستطيل = يُنطق وقفًا فقط.","فوائده: احتواء القراءات، ثبات المصحف، وحفظ التلقي والمشافهة."],"exercises":["اذكر ثلاث ظواهر من ظواهر الرسم العثماني مع مثال قرآني لكل ظاهرة.","قارن بين دلالة «الصفر المستدير» و«الصفر المستطيل» في ضبط المصحف مع مثال لكل منهما.","اذكر ثلاث فوائد للالتزام بالرسم العثماني في كتابة المصحف."],"levels":{"easy":[{"type":"mcq","q":"ما المقصود بـ«الرسم العثماني»؟","options":["الخط الكوفي المزخرف فقط","الإملاء المدرسي الحديث","الهيئة الخاصة التي كُتبت بها كلمات القرآن في مصاحف عهد عثمان بن عفان رضي الله عنه","الكتابة بدون نقط فقط"],"answer":2,"why":"هو الرسم التوقيفي المعتمد للمصحف الشريف."},{"type":"mcq","q":"ماذا يعني وضع «الصفر المستدير» فوق حرف في المصحف (مثل الواو في ﴿أُولَٰئِكَ﴾)؟","options":["أنه يُنطق وصلًا فقط","أنه يُمدّ ٦ حركات","أنه حرف مقلقل","أن الحرف زائد في الرسم ولا يُنطق لا وصلًا ولا وقفًا"],"answer":3,"why":"الصفر المستدير علامة زيادة الحرف خطًا وسقوطه لفظًا."},{"type":"mcq","q":"ما إحدى أعظم فوائد الالتزام بالرسم العثماني في طباعة المصاحف؟","options":["احتمال الكلمة الواحدة للقراءات القرآنية المتواترة (مثل ﴿مَٰلِكِ﴾)","تسهيل تغيير الكلمات","إلغاء الحاجة للمعلم","اختصار عدد السور"],"answer":0,"why":"حذف الألف في ﴿مَٰلِكِ﴾ يجمع قراءتي «مَلِك» و«مَالِك»."},{"type":"mcq","q":"كيف نقف على كلمة ﴿رَحْمَتَ﴾ المرسومة بتاء مفتوحة في المصحف؟","options":["نقف عليها بالهاء (رَحْمَهْ)","نقف عليها بالتاء الساكنة (رَحْمَتْ)","نحذف التاء","نمدّها ٦ حركات"],"answer":1,"why":"يُتبع الرسم عند الوقف: المفتوحة بالتاء والمربوطة بالهاء."}],"medium":[{"type":"mcq","q":"كتابة كلمة ﴿الصَّلَوٰة﴾ بالواو بدل الألف في المصحف مثال على قاعدة:","options":["الحذف فقط","الزيادة","البدل","الإخفاء"],"answer":2,"why":"أُبدلت الألف واوًا في الرسم العثماني وتُنطق ألفًا."},{"type":"mcq","q":"كتابة كلمة ﴿الرَّحْمَٰن﴾ بدون ألف ممدودة في المصحف مثال على قاعدة:","options":["القلب","الزيادة","البدل","الحذف (مع إثبات النطق بالألف الخنجرية)"],"answer":3,"why":"حُذفت الألف خطًا وتُثبت لفظًا."},{"type":"mcq","q":"ماذا يعني وضع «الصفر المستطيل القائم» فوق ألف ﴿أَنَا۠﴾ في المصحف؟","options":["تُثبت الألف عند الوقف وتُحذف لفظًا عند الوصل","تُحذف وقفًا ووصلًا","تُمدّ ٦ حركات","تُنطق واوًا"],"answer":0,"why":"الألفات السبع (ومنها أنا) تثبت وقفًا وتسقط وصلًا."},{"type":"tfr","q":"الرسم العثماني للمصحف الشريف توقيفي أجمعت الأمة على الالتزام به في طباعة المصاحف.","answer":true,"reasons":["يمكن تغييره بحرية","حفظًا للقرآن ووحدته واحتوائه للقراءات المتواترة","أُحدث في القرن العشرين"],"reason":1},{"type":"tfr","q":"يُنطق الحرف الذي فوقه «صفر مستدير» في المصحف عند الوقف عليه.","answer":false,"reasons":["يُنطق دائمًا","نعم يُنطق وقفًا","لا يُنطق لا وصلًا ولا وقفًا، أما الذي يُثبت وقفًا فقط ففوقه صفر مستطيل كـ ﴿أَنَا۠﴾"],"reason":2},{"type":"essay","q":"اذكر ثلاث ظواهر من ظواهر الرسم العثماني مع مثال قرآني لكل ظاهرة.","model":"١) الحذف: ﴿الرَّحْمَٰن﴾. ٢) الزيادة: ﴿أُولَٰئِكَ﴾. ٣) البدل: ﴿الصَّلَوٰة﴾ (أو التاء المفتوحة: ﴿رَحْمَتَ﴾)."},{"type":"essay","q":"قارن بين دلالة «الصفر المستدير» و«الصفر المستطيل» في ضبط المصحف مع مثال لكل منهما.","model":"الصفر المستدير: يسقط الحرف لفظًا وصلًا ووقفًا (الواو في ﴿أُولَٰئِكَ﴾). الصفر المستطيل: يسقط الحرف وصلًا ويثبت وقفًا (الألف في ﴿أَنَا۠﴾)."}],"hard":[{"type":"mcq","q":"هل يجوز طباعة المصحف الكامل بالرسم الإملائي الحديث وترك الرسم العثماني؟","options":["نعم يجب تغييره كل عام","لا، أجمع العلماء على وجوب الالتزام بالرسم العثماني في طباعة المصحف","مباح تغييره للأسهل","لا أهمية للرسم"],"answer":1,"why":"الرسم العثماني إجماع للأمة لحفظ المصحف ووحدته."},{"type":"mcq","q":"الألف الخنجرية الصغيرة فوق الحرف في المصحف تدل على:","options":["سكون الحرف","حرف لا يُنطق","وجود ألف مدية محذوفة في الرسم يجب نطقها في التلاوة","وجوب الوقف"],"answer":2,"why":"الألف الخنجرية علامة ضبط تُرشد القارئ لنطق الألف المحذوفة رسمًا."},{"type":"mcq","q":"في كلمة ﴿وَلَا تَقُولَنَّ لِشَايْءٍ﴾ (سورة الكهف)، الألف بعد الشين فوقها صفر مستدير، إذن حكمها:","options":["تُكسر","تُمدّ حركتين","تُثبت وقفًا فقط","لا تُنطق مطلقًا لا وصلًا ولا وقفًا"],"answer":3,"why":"وجود الصفر المستدير يعني زيادة الحرف رسمًا دون لفظ."},{"type":"mcq","q":"كيف يستفيد الطالب من «قائمة مصطلحات الضبط» في آخر المصحف الشريف؟","options":["يتعرّف معاني العلامات (كالصفر المستدير والمستطيل والألف الخنجرية) فيقرأ بلا أخطاء","لا فائدة منها","تحوي معاني الكلمات فقط","تحتوي أسماء السور فقط"],"answer":0,"why":"قائمة مصطلحات الضبط دليل عملي ممتاز للقارئ."},{"type":"tfr","q":"الفرق بين ﴿نِعْمَتَ﴾ بالتاء المفتوحة و﴿نِعْمَةَ﴾ بالمربوطة يظهر عند الوقف (تاء مقابل هاء).","answer":true,"reasons":["فتتبع التلاوة رسم المصحف عند الوقف الاختباري أو الاضطراري","لا فرق عند الوقف","كلاهما بالهاء"],"reason":0},{"type":"tfr","q":"إضافة النقط والتشكيل وعلامات الضبط لاحقًا غيّرت حروف الرسم العثماني.","answer":false,"reasons":["نعم غيّرت الكلمات","بقيت حروف الرسم العثماني كما هي، وجاء الضبط لتسهيل القراءة الصحيحة على الناس","حذفت حروفًا"],"reason":1},{"type":"tfr","q":"من فوائد الرسم العثماني أنه يدفع القارئ لتلقي القرآن بالمشافهة عن المعلمين لا بالاعتماد على الخط وحده.","answer":true,"reasons":["يغني عن المعلم","يمنع القراءة","فيحفظ الأداء الصوتي الصحيح المتصل بالسند إلى النبي ﷺ"],"reason":2},{"type":"essay","q":"اذكر ثلاث فوائد للالتزام بالرسم العثماني في كتابة المصحف.","model":"١) احتواء القراءات المتواترة. ٢) ثبات رسم المصحف ووحدته عبر العصور. ٣) حفظ التلقي والمشافهة عن أهل القرآن."},{"type":"essay","q":"كيف نقف على كل من ﴿رَحْمَتَ﴾ و﴿رَحْمَةَ﴾ في التلاوة؟ ولماذا؟","model":"نقف على ﴿رَحْمَتَ﴾ بالتاء الساكنة، وعلى ﴿رَحْمَةَ﴾ بالهاء الساكنة، التزامًا برسم المصحف العثماني."},{"type":"essay","q":"ما الفرق بين الرسم القرآني (العثماني) والرسم الإملائي (القياسي)؟","model":"الإملائي يطابق النطق وفق قواعد الإملاء المتعارف عليها، أما العثماني فرسم توقيفي خاص بالمصحف فيه قواعد حذف وزيادة وبدل لحكم علمية وقرائية."}]}},
  {"id":"g9-islamic-2-u2-2","grade":"g9","subject":"islamic","term":2,"unit":2,"no":2,"title":"سورة الشعراء (١٧٦–١٩٠) — تفسير","summary":"شرح متحرك بـ SVG لدرس سورة الشعراء (١٧٦–١٩٠) — تفسير (الصف التاسع - الفصل الثاني)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.","page":"lesson-surah-ash-shuara-176-190.html","video":"","pdf":"","notes":["شعيب عليه السلام دعا أصحاب الأيكة للتقوى وإيفاء الكيل والوزن بالقسطاس المستقيم وترك البخس والفساد.","كذّبوه واستعجلوا العذاب فأهلكهم الله بعذاب يوم الظلة.","ترسّخ الآيات النزاهة الاقتصادية وحماية حقوق الناس في السوق والعمل."],"exercises":["اذكر ثلاث قواعد اقتصادية أخلاقية أمر بها شعيب عليه السلام قومه في الآيات ١٨١–١٨٣.","ما معنى المفردات الآتية: الأيكة، المخسرين، القسطاس، كِسفًا؟","اشرح كيف يرتبط «الفساد الاقتصادي والغش» بانهيار المجتمعات في ضوء قصة أصحاب الأيكة."],"levels":{"easy":[{"type":"mcq","q":"من هو النبي الذي أُرسل إلى «أصحاب الأيكة»؟","options":["صالح عليه السلام","يونس عليه السلام","نوح عليه السلام","شعيب عليه السلام"],"answer":3,"why":"دعا شعيب عليه السلام أهل مدين وأصحاب الأيكة."},{"type":"mcq","q":"ما معنى «القسطاس المستقيم» في الآية ١٨٢؟","options":["الميزان العدل الدقيق الذي لا يميل ولا ينقص","الطريق الطويل","السوق الكبير","النهر الجاري"],"answer":0,"why":"القسطاس هو الميزان، والمستقيم أي العادل السوي."},{"type":"mcq","q":"ما معنى «ولا تَبْخَسُوا الناس أشياءهم»؟","options":["لا تبيعوا للناس","لا تنقصوا الناس حقوقهم ولا تظلموهم في أثمان سلعهم وأوزانها","لا تشتروا من السوق","ارفعوا الأسعار"],"answer":1,"why":"البخس هو النقص والظلم في الحقوق والأثمان."},{"type":"mcq","q":"ما العذاب الذي أهلك الله به أصحاب الأيكة بعد تكذيبهم واستعجالهم العذاب؟","options":["الريح الصرصر","الغرق في البحر","عذاب يوم الظُّلّة (سحابة أظلّتهم ثم أمطرتهم نارًا)","الحجارة فقط"],"answer":2,"why":"﴿فأخذهم عذاب يوم الظلة إنه كان عذاب يوم عظيم﴾."}],"medium":[{"type":"mcq","q":"ما معنى «الأيكة» في قوله تعالى ﴿كذّب أصحاب الأيكة المرسلين﴾؟","options":["الجزيرة البحرية","الجبل العالي","الصحراء القاحلة","الغيضة والشجر الكثير الملتف"],"answer":3,"why":"سمّوا بأصحاب الأيكة لكثرة الشجر الملتف في ديارهم."},{"type":"mcq","q":"ما معنى «كِسَفًا من السماء»؟","options":["قطعًا من العذاب تسقط من السماء","مطرًا باردًا","نجومًا مضيئة","طيورًا"],"answer":0,"why":"تحدّوا شعيبًا بسقوط قطع العذاب من السماء عنادًا."},{"type":"mcq","q":"ما القيمتان اللتان ربط بينهما شعيب عليه السلام في دعوته؟","options":["الشعر والقتال","تقوى الله وطاعته، والنزاهة والعدل في المعاملات الاقتصادية","العزلة والرهبانية","البيع بلا ضوابط"],"answer":1,"why":"الدين يربط التوحيد بأمانة السوق وعدالة الاقتصاد."},{"type":"tfr","q":"أُرسل نبي الله شعيب عليه السلام إلى أصحاب الأيكة فدعاهم للتوحيد وإيفاء الكيل والميزان.","answer":true,"reasons":["دعاهم للتجارة فقط","أرسل إليهم هود","فجمع بين إصلاح العقيدة وإصلاح المعاملات الاقتصادية"],"reason":2},{"type":"tfr","q":"معنى «القسطاس المستقيم» هو الميزان العادل الدقيق.","answer":true,"reasons":["وهو رمز للعدالة والشفافية في كل المعاملات","معناه الشجر الملتف","معناه السحابة"],"reason":0},{"type":"essay","q":"اذكر ثلاث قواعد اقتصادية أخلاقية أمر بها شعيب عليه السلام قومه في الآيات ١٨١–١٨٣.","model":"١) إيفاء الكيل وعدم التطفيف. ٢) الوزن بالقسطاس المستقيم (الميزان العدل). ٣) عدم بخس الناس أشياءهم وترك الفساد في الأرض."},{"type":"essay","q":"ما معنى المفردات الآتية: الأيكة، المخسرين، القسطاس، كِسفًا؟","model":"الأيكة: الشجر الكثير الملتف. المخسرين: المنقصين للمكيال والميزان. القسطاس: الميزان العدل. كسفًا: قطعًا من العذاب."}],"hard":[{"type":"mcq","q":"بائع يُخفي عيبًا في هاتف مستعمل ليبيعه بسعر مرتفع؛ أي نهي في الآيات خالفه؟","options":["أمر الصيام","أمر السفر","﴿ولا تبخسوا الناس أشياءهم ولا تعثوا في الأرض مفسدين﴾","لا مخالفة"],"answer":2,"why":"إخفاء العيوب غشّ وبخس لحق المشتري."},{"type":"mcq","q":"معنى «ولا تَعْثَوْا في الأرض مفسدين»:","options":["لا تتاجروا","لا تزرعوا الأرض","لا تمشوا في الأرض","لا تسعوا وتتمادوا في نشر الفساد والظلم"],"answer":3,"why":"العَثْي هو أشد الفساد والتعدي."},{"type":"mcq","q":"تختم الآية ١٩٠ بقوله ﴿وإن ربك لهو العزيز الرحيم﴾ لتجمع بين:","options":["عزة الله وقدرته على معاقبة المفسدين، ورحمته بعباده المؤمنين والتائبين","الرحمة فقط دون عدل","العقاب فقط","لا دلالة لها"],"answer":0,"why":"اقتران العزيز بالرحيم يوازن بين الهيبة والرجاء."},{"type":"mcq","q":"كيف تطبّق «إيفاء الكيل» في حياتك الدراسية كطالب؟","options":["بتقليل الجهد عمدًا","بإتمام واجباتك ومهامك بأمانة وإتقان دون تقصير أو غش","بالنقل من زميلك","بإهمال الوقت"],"answer":1,"why":"الإيفاء والعدل مبدأ يشمل السوق والدراسة والوظيفة."},{"type":"tfr","q":"يجوز إنقاص الوزن أو الغش قليلًا إذا كان المشتري لا ينتبه.","answer":false,"reasons":["نعم يجوز قليلًا","نهى الله بشدة عن التطفيف والبخس سواء انتبه المشتري أم لا لأن الله رقيب عليم","لا بأس في التجارة"],"reason":1},{"type":"tfr","q":"أخذ الله أصحاب الأيكة بعذاب يوم الظلة بعد إصرارهم على الكفر والفساد.","answer":true,"reasons":["آمنوا جميعًا","أُهلكوا بالطوفان","وكان ذلك جزاءً عادلًا بعد إنذار شعيب وإقامة الحجة عليهم"],"reason":2},{"type":"tfr","q":"حماية المستهلك ومراقبة الموازين في الأسواق اليوم تطبيق عملي لتوجيهات سورة الشعراء.","answer":true,"reasons":["لأنها تمنع الغش والبخس وتحفظ حقوق البائع والمشتري","لا علاقة لها بالآيات","تضر التجارة"],"reason":0},{"type":"essay","q":"اشرح كيف يرتبط «الفساد الاقتصادي والغش» بانهيار المجتمعات في ضوء قصة أصحاب الأيكة.","model":"انتشار الغش والبخس يضيع الثقة والحقوق ويظلم الضعفاء ويجلب غضب الله ومحق البركة وزوال النعم."},{"type":"essay","q":"اذكر ثلاث صور معاصرة لـ«بخس الناس أشياءهم» يجب أن يحذر منها المجتمع.","model":"١) إخفاء عيوب السلعة في البيع التقليدي أو الإلكتروني. ٢) التلاعب في وزن العبوات أو صلاحيتها. ٣) تأخير حقوق العمال أو تقصير الموظف في عمله."},{"type":"essay","q":"ما الدلالة الإيمانية لختام القصة بقوله ﴿وإن ربك لهو العزيز الرحيم﴾؟","model":"عزيز لا يعجزه الانتقام من المفسدين المكذبين، ورحيم بالمؤمنين الصادقين والتائبين الذين يلتزمون العدل والأمانة."}]}},
  {"id":"g9-islamic-2-u2-3","grade":"g9","subject":"islamic","term":2,"unit":2,"no":3,"title":"التفقّه في الدين (حديث شريف)","summary":"شرح متحرك بـ SVG لدرس التفقّه في الدين (حديث شريف) (الصف التاسع - الفصل الثاني)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.","page":"lesson-understanding-the-religion.html","video":"","pdf":"","notes":["الحديث (متفق عليه): «من يرد الله به خيرًا يفقّهه في الدين».","التفقه فرض عين في أساسيات العبادة والعمل، وفرض كفاية في التخصص والاجتهاد.","ثمراته: صحة العبادة، الأمن الفكري، ورفعة الدرجات."],"exercises":["فرّق بين «فرض العين» و«فرض الكفاية» في التفقّه في الدين مع مثالين لكل منهما.","اذكر أربع ثمرات للتفقّه في الدين على الفرد والمجتمع.","ما آداب طالب العلم عند التفقه في دينه؟ اذكر أربعة آداب."],"levels":{"easy":[{"type":"mcq","q":"ما العلامة التي ذكرها النبي ﷺ لإرادة الله الخير بعبده؟","options":["أن يفقّهه الله في الدين (يرزقه الفهم الصحيح والعمل به)","أن يكثر ماله فقط","أن يترك العمل","أن يجادل الناس"],"answer":0,"why":"«من يرد الله به خيرًا يفقّهه في الدين»."},{"type":"mcq","q":"ما حكم تعلّم المسلم أحكام الطهارة والصلاة والصيام التي تلزمه يوميًا؟","options":["فرض كفاية فقط","فرض عين على كل مسلم ومسلمة","مكروه","للعلماء فقط"],"answer":1,"why":"كل ما لا تصح العبادة الواجبة إلا به فتعلّمه فرض عين."},{"type":"mcq","q":"ما حكم التخصّص العميق في أصول الفقه والاجتهاد والإفتاء؟","options":["حرام","فرض عين على كل طفل","فرض كفاية على الأمة","غير مطلوب"],"answer":2,"why":"يكفي أن يتخصص فيه طائفة مؤهلة من الأمة."},{"type":"mcq","q":"معنى «التفقّه في الدين» في الحديث الشريف يشمل:","options":["ترك علوم الدنيا","حفظ الكلمات بلا فهم","الجدال العقيم","الفهم العميق لأحكام العقيدة والعبادات والأخلاق والمعاملات والعمل بها"],"answer":3,"why":"الفقه هو الفهم الدقيق المقرون بالتطبيق."}],"medium":[{"type":"mcq","q":"تاجر يريد فتح محل تجاري؛ ما حكم تعلّمه لأحكام البيع والشراء الحلال والحرام؟","options":["فرض عين عليه ليتجنّب الغش والربا والمحرمات في عمله","فرض كفاية فقط","غير مهم","مكروه"],"answer":0,"why":"يجب على كل صاحب مهنة تعلّم أحكام الشرع المتعلقة بمهنته."},{"type":"mcq","q":"راوي حديث «من يرد الله به خيرًا يفقّهه في الدين» هو الصحابي:","options":["سلمان الفارسي","معاوية بن أبي سفيان رضي الله عنهما","أبو ذر","زيد بن ثابت"],"answer":1,"why":"الحديث متفق عليه عن معاوية رضي الله عنهما."},{"type":"mcq","q":"كيف يحمي التفقّه في الدين صاحبه من التطرف والغلو؟","options":["لا علاقة له بالتطرف","لأنه يشجع التشدد","لأن الفهم الصحيح لمقاصد الشريعة ويسرها يمنع الفهم السطحي المتشدد","لأنه يمنع القراءة"],"answer":2,"why":"الجهل بالدين أصل الغلو، والفقه الصحيح أصل الوسطية."},{"type":"tfr","q":"تعلّم أحكام الوضوء والصلاة التي تصح بها العبادة فرض عين على كل مسلم بالغ عاقل.","answer":true,"reasons":["لأن ما لا يتم الواجب إلا به فهو واجب","فرض كفاية فقط","للعلماء فقط"],"reason":0},{"type":"tfr","q":"التفقّه في الدين يمنع المسلم من التخصص في الطب أو الهندسة أو البرمجة.","answer":false,"reasons":["نعم يمنعه","بل يجمع المسلم بين فرض العين من دينه وبين إتقان العلوم النافعة لخدمة أمته ووطنه","لا يجتمعان"],"reason":1},{"type":"essay","q":"فرّق بين «فرض العين» و«فرض الكفاية» في التفقّه في الدين مع مثالين لكل منهما.","model":"فرض العين: يلزم كل مسلم بعينه (كأحكام العقيدة والصلاة والصيام وأحكام مهنته). فرض الكفاية: التخصص الدقيق في الفقه والإفتاء والقضاء إذا قام به البعض سقط عن الباقين."},{"type":"essay","q":"اذكر أربع ثمرات للتفقّه في الدين على الفرد والمجتمع.","model":"١) صحة العبادات وقبولها. ٢) الحماية من التطرف والشبهات. ٣) رفعة الدرجات عند الله. ٤) استقامة الأخلاق والمعاملات في المجتمع."}],"hard":[{"type":"mcq","q":"أي نية تُعدّ صحيحةً عند طلب العلم الشرعي؟","options":["استصغار الآخرين","التفاخر ومجادلة الزملاء","طلب الشهرة فقط","رفع الجهل عن النفس والعمل بالعلم ونفع الناس ابتغاء وجه الله"],"answer":3,"why":"الإخلاص أساس بركة العلم وقبوله."},{"type":"mcq","q":"منهج التعلّم الصحيح في التفقه في الدين يقوم على:","options":["التدرّج وتلقّي العلم عن أهله الموثوقين مع التواضع","أخذ الفتاوى من مجهولين","العجلة والغرور","رفض سؤال العلماء"],"answer":0,"why":"التدرّج والأخذ عن الثقات يبني علمًا راسخًا."},{"type":"mcq","q":"كيف يجمع طالب الصف التاسع بين «التفقّه في الدين» و«دراسة العلوم والبرمجة»؟","options":["يترك العلوم الدنيوية تمامًا","يتعلم فرض العين من دينه ليصحّ إسلامه وأخلاقه، ويتقن علومه الدنيوية ليبني وطنه","يترك الدين تمامًا","لا يمكن الجمع بينهما"],"answer":1,"why":"الإسلام يشجّع التفوق في علوم الدنيا مع الفقه في الدين."},{"type":"mcq","q":"أي عبارة تلخّص علاقة العلم بالعمل في التفقّه؟","options":["العمل غير مرتبط بالعلم","يكفي الحفظ للامتحان فقط","لا يكتمل التفقه إلا بالعمل بما علمت وتطبيقه في العبادة والأخلاق","العلم للتفاخر"],"answer":2,"why":"العمل هو ثمرة العلم الحقيقية."},{"type":"tfr","q":"الفقه في الدين يحصّن الشباب من الشبهات والأفكار المتطرفة.","answer":true,"reasons":["لا علاقة له بالأمن الفكري","يزيد الشبهات","لأنه يمنحهم البصيرة والفهم الوسطي المتوازن لمقاصد الشريعة"],"reason":2},{"type":"tfr","q":"الحديث «من يرد الله به خيرًا يفقّهه في الدين» متفق عليه (رواه البخاري ومسلم).","answer":true,"reasons":["وهو دليل عظيم على فضل العلم الشرعي والعمل به","حديث ضعيف","لا أصل له"],"reason":0},{"type":"tfr","q":"المراد بـ«الفقه» في الحديث هو مجرد حفظ نصوص دون فهم أو تطبيق.","answer":false,"reasons":["نعم الحفظ فقط","الفقه لغةً وشرعًا هو الفهم الدقيق العميق المقرون بالخشية والعمل","لا يحتاج فهمًا"],"reason":1},{"type":"essay","q":"ما آداب طالب العلم عند التفقه في دينه؟ اذكر أربعة آداب.","model":"١) إخلاص النية لله. ٢) التلقي من العلماء والمصادر الموثوقة. ٣) التواضع والتدرج. ٤) العمل بما يتعلمه."},{"type":"essay","q":"كيف تردّ على من يقول: «يكفي أن أصلّي كما أرى الناس دون حاجة لتعلم أحكام الصلاة»؟","model":"أبيّن له أن التقليد بلا علم قد يوقع في أخطاء تبطل الصلاة، وأن تعلّم أحكام الصلاة فرض عين ومن علامات إرادة الله الخير بعبده."},{"type":"essay","q":"اذكر ثلاث وسائل متاحة لك في عُمان اليوم للتفقّه في دينك بطريقة موثوقة.","model":"١) دروس التربية الإسلامية ومعلموها. ٢) الدروس والمحاضرات الموثوقة في المساجد ووزارة الأوقاف. ٣) الكتب والمواقع العلمية المعتمدة."}]}},
  {"id":"g9-islamic-2-u2-4","grade":"g9","subject":"islamic","term":2,"unit":2,"no":4,"title":"دعوة هود عليه السلام (عقيدة)","summary":"شرح متحرك بـ SVG لدرس دعوة هود عليه السلام (عقيدة) (الصف التاسع - الفصل الثاني)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.","page":"lesson-call-of-prophet-hud.html","video":"","pdf":"","notes":["أُرسل هود عليه السلام إلى قوم عاد بالأحقاف (جنوب الجزيرة) فدعاهم للتوحيد وشكر النعمة والاستغفار.","اغترّوا بقوتهم وكذبوه فأهلكهم الله بالريح الصرصر ٧ ليالٍ و٨ أيام ونجّى هودًا والمؤمنين.","القوة والعمران يحفظهما الشكر والتواضع والتوكل على الله."],"exercises":["اذكر ثلاث نعم منحها الله لقوم عاد وكيف قابلوها.","بيّن كيف تعامل هود عليه السلام مع اتهامات قومه وتهديدهم له.","ما الدرس الذي تستفيده الأمم والأفراد اليوم من مصير قوم عاد؟"],"levels":{"easy":[{"type":"mcq","q":"ما المنطقة التي سكنها قوم عاد (قوم نبي الله هود عليه السلام)؟","options":["الشام","الأحقاف (جنوب الجزيرة العربية)","مصر","العراق"],"answer":1,"why":"ذكر القرآن إرسال هود إلى قومه بالأحقاف."},{"type":"mcq","q":"ما العذاب الذي أهلك الله به قوم عاد بعد تكذيبهم واستكبارهم؟","options":["عذاب يوم الظلة","الطوفان","ريح صرصر عاتية (سبع ليال وثمانية أيام حسومًا)","الغرق في اليم"],"answer":2,"why":"سخّرها عليهم سبع ليال وثمانية أيام متتابعة."},{"type":"mcq","q":"ما الخطأ القاتل الذي وقع فيه قوم عاد رغم ما أوتوه من قوة وعمران؟","options":["السفر","بناء البيوت فقط","الزراعة","الشرك بالله والغرور بقوتهم ﴿من أشد منا قوة﴾ والظلم وعدم شكر النعمة"],"answer":3,"why":"الكفر والطغيان والغرور هي سبب الهلاك."},{"type":"mcq","q":"ماذا ظنّ قوم عاد عندما رأوا السحابة السوداء مقبلةً على أوديتهم؟","options":["ظنوها سحابة مطر ورحمة («هذا عارض ممطرنا»)","عرفوا فورًا أنها ريح عذاب","ظنوها جيشًا","لم يروها"],"answer":0,"why":"فرحوا بها ظانين أنها المطر بعد الجفاف، فكانت ريح العذاب."}],"medium":[{"type":"mcq","q":"بمَ وعد هود عليه السلام قومه إذا استغفروا الله وتابوا؟","options":["يقلّ مالهم","يرسل السماء عليهم مدرارًا ويزيدهم قوةً إلى قوتهم","تضعف قوتهم","يتوقف المطر"],"answer":1,"why":"الاستغفار سبب لنزول الغيث وزيادة القوة والبركة."},{"type":"mcq","q":"ما معنى «ريح صرصر عاتية»؟","options":["مطر خفيف","نسيم عليل هادئ","شديدة البرودة والصوت والعصف والقوة","سحاب أبيض"],"answer":2,"why":"الصرصر شديدة الصوت والبرد، والعاتية شديدة العصف."},{"type":"mcq","q":"ما معنى «حُسومًا» في قوله ﴿سبع ليال وثمانية أيام حسومًا﴾؟","options":["هادئة","متفرقة خلال سنة","ساعة واحدة","متتابعة لا تنقطع"],"answer":3,"why":"حسومًا أي متواصلة متتابعة بلا توقف."},{"type":"tfr","q":"أهلك الله قوم عاد بريح صرصر عاتية استمرت سبع ليال وثمانية أيام متتابعة.","answer":true,"reasons":["أُهلكوا بالطوفان","وأنجى الله هودًا والذين آمنوا معه برحمته","استمرت يومًا واحدًا"],"reason":1},{"type":"tfr","q":"سكن قوم عاد في منطقة الأحقاف جنوب الجزيرة العربية وكانوا أصحاب قوة وعمران.","answer":true,"reasons":["كانوا ضعفاء البنية","سكنوا في مصر","ولكنهم كفروا واغترّوا بقوتهم فقالوا من أشد منا قوة"],"reason":2},{"type":"essay","q":"اذكر ثلاث نعم منحها الله لقوم عاد وكيف قابلوها.","model":"القوة الجسدية العظيمة، والعمران والقصور والمصانع، والأموال والأراضي؛ وقابلوها بالشرك والكبر والغرور والظلم وعدم الشكر."},{"type":"essay","q":"بيّن كيف تعامل هود عليه السلام مع اتهامات قومه وتهديدهم له.","model":"ردّ بأدب ولطف نافيًا السفاهة ومؤكدًا أنه ناصح أمين، وواجه تهديدهم بثبات وتوكّل مطلق على الله وحده."}],"hard":[{"type":"mcq","q":"بمَ واجه هود عليه السلام تهديد قومه له بآلهتهم؟","options":["بالتوكّل المطلق على الله والثبات ﴿إني توكلت على الله ربي وربكم﴾","بالخوف والتراجع","بطلب المال منهم","بترك الدعوة"],"answer":0,"why":"قوة التوكل تملأ قلب المؤمن شجاعةً وثباتًا."},{"type":"mcq","q":"قوله تعالى ﴿أولم يروا أن الله الذي خلقهم هو أشد منهم قوة﴾ يردّ على:","options":["ضعف أجسامهم","غرور قوم عاد بقوتهم الجسدية والعمرانية","قلة أموالهم","خوفهم من الله"],"answer":1,"why":"الخالق القادر أشد قوة من كل مخلوق."},{"type":"mcq","q":"ما الدلالة في وصف هود نفسه بـ«ناصح أمين»؟","options":["طلب الأجر المادي","الشدة والغلظة","أن أساس الدعوة والإصلاح هو النصيحة الصادقة المحبّة والأمانة","العزلة"],"answer":2,"why":"هود نصح قومه بأمانة وإشفاق عليهم."},{"type":"mcq","q":"هل يذم الإسلام البناء والعمران القوي؟","options":["يمنع العمل","نعم يحرم البناء","يمنع القوة البدنية","لا، بل يشجعه ما دام مقترنًا بشكر الله والتواضع والعدل، ويذم التفاخر والظلم"],"answer":3,"why":"الذم وقع على الكبر والطغيان ونسيان المنعم."},{"type":"tfr","q":"يذم الإسلام امتلاك القوة وبناء الحضارة حتى لو شكر أصحابها الله.","answer":false,"reasons":["المذموم هو الكبر والطغيان ونسيان المنعم، أما القوة مع الشكر والعدل فممدوحة","نعم يذم كل بناء","القوة حرام"],"reason":0},{"type":"tfr","q":"أخبر هود عليه السلام قومه أن الاستغفار والتوبة يزيدانهم قوةً إلى قوتهم.","answer":true,"reasons":["يضعفان القوة","﴿ويا قوم استغفروا ربكم ثم توبوا إليه يرسل السماء عليكم مدرارًا ويزدكم قوة إلى قوتكم﴾","لا أثر للاستغفار"],"reason":1},{"type":"tfr","q":"سلك هود عليه السلام منهج التوكّل المطلق على الله في مواجهة تهديد قومه.","answer":true,"reasons":["استعان بآلهتهم","خاف وتراجع","فلم يرهب آلهتهم الباطلة ولا جموعهم لثقته المطلقة بربه"],"reason":2},{"type":"essay","q":"ما الدرس الذي تستفيده الأمم والأفراد اليوم من مصير قوم عاد؟","model":"أن القوة المادية والعمران لا تحمي أصحابها إذا طغوا وظلموا وكفروا بنعمة الله، وأن دوام النعم يكون بالشكر والتواضع والعدل."},{"type":"essay","q":"اشرح أثر «الاستغفار» كما جاء في دعوة هود عليه السلام.","model":"يجلب الغيث المدرار، ويزيد المؤمن قوةً وبركةً في بدنه ومجتمعه، ويدفع العذاب."},{"type":"essay","q":"قارن بين مصير «هود ومن آمن معه» ومصير «المكذبين من عاد».","model":"نجّى الله هودًا والمؤمنين برحمته وخلّد ذكرهم، وأهلك المكذبين بالريح الصرصر العاتية سبع ليال وثمانية أيام حسومًا."}]}},
  {"id":"g9-islamic-2-u2-5","grade":"g9","subject":"islamic","term":2,"unit":2,"no":5,"title":"أحكام اللُّقطة والضّالّة (فقه)","summary":"شرح متحرك بـ SVG لدرس أحكام اللُّقطة والضّالّة (فقه) (الصف التاسع - الفصل الثاني)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.","page":"lesson-lost-and-found-rulings.html","video":"","pdf":"","notes":["اللقطة للمال الضائع والضالة للحيوان الضائع.","ذو القيمة يُعرّف سنةً (أو يُسلّم للإدارة/الشرطة)، ولقطة الحرم لا تُملك أبدًا.","ضالة الإبل تُترك (تقوى على حفظ نفسها)، وضالة الغنم تُحفظ وتُعرّف."],"exercises":["قارن بين أحكام «اليسير التافه» و«ذي القيمة» و«لقطة الحرم المكي».","فرّق بين حكم «ضالة الإبل» وحكم «ضالة الغنم» مع بيان الحكمة النبوية.","اذكر ثلاث خطوات عملية تتبعها إذا وجدت محفظة نقود في مجمع تجاري في عُمان."],"levels":{"easy":[{"type":"mcq","q":"ما الفرق بين «اللُّقطة» و«الضّالّة» في الفقه الإسلامي؟","options":["اللقطة للذهب فقط والضالة للكتب","كلاهما للحيوانات فقط","اللقطة للمال والمتاع الضائع، والضالة للحيوان الضائع","لا فرق بينهما"],"answer":2,"why":"يُخصّ لفظ الضالة بالحيوان الضائع واللقطة بباقي الأموال."},{"type":"mcq","q":"كم مدة التعريف الواجبة للُّقطة ذات القيمة؟","options":["عشر سنوات","يوم واحد فقط","أسبوع واحد","سنة كاملة"],"answer":3,"why":"أمر النبي ﷺ بتعريف اللقطة ذات القيمة حَوْلًا كاملًا (سنة)."},{"type":"mcq","q":"ما حكم «ضالّة الإبل» كما ورد في الحديث النبوي؟","options":["تُترك ولا تُلتقط للتملك لأنها تقوى على حفظ نفسها (معها سقاؤها وحذاؤها) حتى يجدها صاحبها","تُذبح فورًا","تُباع في نفس اليوم","تُملك مباشرة"],"answer":0,"why":"الإبل تمتنع عن صغار السباع وتصبر على العطش حتى يلقاها ربها."},{"type":"mcq","q":"ما حكم «لُقطة الحرم المكي»؟","options":["تُملك بعد أسبوع","لا يجوز تملّكها أبدًا حتى بعد سنة، بل تُعرّف دائمًا أو تُسلّم لمكتب المفقودات بالحرم","تُملك بعد سنة","تُترك في الأرض"],"answer":1,"why":"للحرم المكي خصوصية فلا تُلتقط لقطته إلا لمُعرِّف."}],"medium":[{"type":"mcq","q":"وجد طالب هاتفًا ثمينًا في ساحة المدرسة؛ ما التصرف الشرعي الأمثل؟","options":["بيعه","أخذه للمنزل واستخدامه","تسليمه فورًا لإدارة المدرسة مع حفظ أوصافه وعدم كشف تفاصيله","تركه يُكسر"],"answer":2,"why":"تسليمه للإدارة يحفظ الأمانة ويسهل وصول صاحبه إليه."},{"type":"mcq","q":"لماذا لا نذكر الأوصاف الدقيقة للُّقطة عند الإعلان عنها؟","options":["لأسباب جمالية","لأننا ننسى أوصافها","لإخفائها عن صاحبها","لكي نتحقّق من صدق صاحبها الحقيقي عندما يصفها بنفسه"],"answer":3,"why":"ذكر المالك للأوصاف الخفية يثبت ملكيته الحقيقية."},{"type":"mcq","q":"ما حكم «الشيء التافه اليسير» جدًّا (مثل قلم رصاص بسيط أو تمرة في الطريق)؟","options":["يجوز أخذه والانتفاع به دون تعريف سنة (مع رده إن جاء صاحبه)","يجب تعريفه عشر سنوات","يحرم لمسه","يُسلم للشرطة فورًا"],"answer":0,"why":"الشريعة ميسّرة فلا توجب تعريف سنة في الشيء اليسير الذي لا يلتفت له صاحبه."},{"type":"tfr","q":"تُعدّ اللقطة ذات القيمة أمانةً في يد الملتقط يجب تعريفها سنةً كاملةً أو تسليمها للجهات المختصة.","answer":true,"reasons":["تُعرّف يومًا واحدًا","تُملك فور العثور عليها","حفظًا لأموال الناس وتطبيقًا لأمر النبي ﷺ"],"reason":2},{"type":"tfr","q":"لقطة الحرم المكي تُملك بعد مرور سنة كاملة كسائر اللقطات.","answer":false,"reasons":["لا تُملك لقطة الحرم المكي أبدًا بل تُعرّف دائمًا أو تُسلّم لمكتب مفقودات الحرم","نعم تُملك بعد سنة","تُملك بعد شهر"],"reason":0},{"type":"essay","q":"قارن بين أحكام «اليسير التافه» و«ذي القيمة» و«لقطة الحرم المكي».","model":"اليسير: ينتفع به بلا تعريف سنة. ذو القيمة: يُعرف سنة كاملة (أو يُسلم للجهة المختصة) ثم ينتفع به مع الضمان إن ظهر صاحبه. لقطة الحرم: لا تُملك أبدًا بل للتعريف والتسليم للمفقودات."},{"type":"essay","q":"فرّق بين حكم «ضالة الإبل» وحكم «ضالة الغنم» مع بيان الحكمة النبوية.","model":"الإبل: تُترك (ولا تُتملك) لأنها قوية تمتنع عن صغار السباع وتصبر حتى يجدها صاحبها. الغنم: تُحفظ وتُعرّف لأنها ضعيفة معرضة للهلاك والسباع."}],"hard":[{"type":"mcq","q":"ما حكم أخذ «ضالّة الغنم» (الشاة الضائعة في الصحراء)؟","options":["تُترك للذئب","تُؤخذ وتُحفظ وتُعرّف لصاحبها لأنها لا تمتنع من الذئب والسباع","يحرم إنقاذها","تُترك بلا تعريف"],"answer":1,"why":"قال ﷺ في الشاة: «هي لك أو لأخيك أو للذئب»."},{"type":"mcq","q":"ماذا يجب على الملتقط إذا انتفع باللقطة بعد مرور سنة، ثم ظهر صاحبها الحقيقي لاحقًا؟","options":["يعطيه نصفها فقط","لا يردّ شيئًا","يجب عليه ردّها له أو ردّ قيمتها","ينكر وجودها"],"answer":2,"why":"حق المالك الأصلي محفوظ فيضمن له الملتقط قيمتها إن ظهر."},{"type":"mcq","q":"متى «يحرم» على الشخص التقاط اللقطة؟","options":["إذا أراد تسليمها للشرطة","إذا كان طالبًا","إذا وجدها في النهار","إذا علم من نفسه أنه غير أمين وسيأخذها لنفسه دون تعريف"],"answer":3,"why":"لا يجوز أخذ مال الغير بنية تملكه أو إخفائه."},{"type":"mcq","q":"معنى «العِفاص والوِكاء» في حديث اللقطة هما:","options":["الوعاء (الكيس/المحفظة) والخيط الذي يُربط به — أي أوصافها المميزة","ثمن السلعة فقط","مكان البيع","اسم الملتقط"],"answer":0,"why":"أمر ﷺ بحفظ أوصاف اللقطة (عفاصها ووكائها) للتحقق من مالكها."},{"type":"tfr","q":"التقاط الشاة الضائعة في البرية لحفظها وتعريفها أفضل من تركها للذئب.","answer":true,"reasons":["يجب تركها للذئب","لقوله ﷺ في الشاة «هي لك أو لأخيك أو للذئب»","الشاة كالإبل"],"reason":1},{"type":"tfr","q":"تسليم المفقودات الثمينة لمكتب الأمن في المركز التجاري أو لشرطة عُمان السلطانية يحقّق مقصود الشرع في التعريف والحفظ.","answer":true,"reasons":["يجب إخفاؤها في البيت","لا يجوز تسليمها للشرطة","لأنها جهات رسمية يرجع إليها أصحاب المفقودات بسهولة وأمان"],"reason":2},{"type":"tfr","q":"إذا ظهر صاحب اللقطة بعد سنتين وأثبت أوصافها الدقيقة، لا يحق له استرجاع قيمتها.","answer":false,"reasons":["يحق له استرجاعها إن بقيت أو قيمتها إن استُهلكت لأن حق الملكية لا يسقط","نعم يسقط حقه بعد سنة","يأخذ ربعها فقط"],"reason":0},{"type":"essay","q":"اذكر ثلاث خطوات عملية تتبعها إذا وجدت محفظة نقود في مجمع تجاري في عُمان.","model":"١) لا أفتحها للعبث بل أحفظ أوصافها. ٢) أسلّمها فورًا لمكتب الأمن بالمجمع أو لمركز الشرطة وآخذ إيصالًا. ٣) لا أكشف تفاصيلها لغير الجهة المختصة."},{"type":"essay","q":"ما الحكمة من أمر النبي ﷺ بمعرفة «العفاص والوكاء» عند التقاط اللقطة؟","model":"للتحقق من صدق من يدّعي ملكيتها فإذا طابقت أوصافه أوصافها أُعطيت له، وإلا حُفظت من المدّعين الكاذبين."},{"type":"essay","q":"بيّن أثر تطبيق أحكام اللقطة والضالة على الثقة والأمان في المجتمع.","model":"ينشر الأمانة والطمأنينة في الأسواق والمدارس، ويشعر المواطن والزائر أن ماله المفقود محفوظ وسيعود إليه."}]}},
  {"id":"g9-islamic-2-u2-6","grade":"g9","subject":"islamic","term":2,"unit":2,"no":6,"title":"الإخلاص للوطن (قيم وأخلاق)","summary":"شرح متحرك بـ SVG لدرس الإخلاص للوطن (قيم وأخلاق) (الصف التاسع - الفصل الثاني)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.","page":"lesson-loyalty-to-homeland.html","video":"","pdf":"","notes":["حب الوطن فطرة أقرّها الإسلام ودعا به الأنبياء (إبراهيم لمكة ومحمد ﷺ للمدينة).","الإخلاص للوطن عمل وإتقان لا شعارات: التفوق العلمي، حفظ المرافق، احترام القوانين، التطوع، والوحدة الوطنية."],"exercises":["اذكر أربع صور عملية تعبّر بها كطالب عن إخلاصك لوطنك سلطنة عُمان.","استدل من القرآن الكريم والسنة النبوية على مشروعية حب الوطن والدعاء له.","بيّن كيف يسهم «إتقان العمل والنزاهة» في نهضة الوطن وتقدّمه."],"levels":{"easy":[{"type":"mcq","q":"بمَ استدل العلماء من السيرة النبوية على أن حب الوطن فطرة مشروعة؟","options":["بالعزلة عن الناس","بترك البناء","بمنع السفر","بثناء النبي ﷺ على مكة ودعائه بالبركة والأمن للمدينة المنورة"],"answer":3,"why":"أظهر النبي ﷺ محبته لمكة ودعا للمدينة بالحب والبركة والأمن."},{"type":"mcq","q":"ما أعظم صورة عملية لإخلاص «طالب الصف التاسع» لوطنه عُمان اليوم؟","options":["الاجتهاد في طلب العلم وإتقانه والمحافظة على مدرسته وقيمه","ترديد الشعارات مع إهمال الدراسة","إتلاف مقاعد الصف","السهر وإضاعة الوقت"],"answer":0,"why":"بناء العقل والعلم والإتقان هو الاستثمار الحقيقي للوطن."},{"type":"mcq","q":"المحافظة على نظافة الأفلاج والشواطئ والحدائق والمدارس تُعدّ من مظاهر:","options":["التدخل في شؤون الآخرين","الإخلاص للوطن وصون المال العام","الأمور الثانوية","الإسراف"],"answer":1,"why":"المرافق والبيئة ملك للجميع وصونها واجب وطني وشرعي."},{"type":"mcq","q":"الحديث النبوي «إن الله يحب إذا عمل أحدكم عملًا أن يتقنه» يدعم قيمة:","options":["الغش في العمل","السرعة دون جودة","الإخلاص للوطن عبر الإتقان والجودة في الدراسة والعمل","ترك العمل"],"answer":2,"why":"إتقان العمل عبادة وخدمة مباشرة للوطن."}],"medium":[{"type":"mcq","q":"ما أثر «احترام قوانين المرور والأنظمة العامة» على الوطن؟","options":["زيادة الحوادث","تعطيل المصالح","لا أثر له","حفظ الأرواح والممتلكات ونشر الأمن والنظام"],"answer":3,"why":"الالتزام بالقانون يحمي الأرواح ويعكس تحضّر المجتمع."},{"type":"mcq","q":"يُعدّ تكاتف المواطنين والمبادرات التطوعية أثناء الأنواء المناخية في عُمان مثالًا على:","options":["الإخلاص للوطن والتكافل الاجتماعي","اللامبالاة","الفردية والأنانية","التنافس الضار"],"answer":0,"why":"العمل التطوعي أصدق برهان عملي على محبة الوطن."},{"type":"mcq","q":"كيف يحمي الشاب وطنه في «الفضاء الرقمي»؟","options":["بنشر الشائعات","بتمثيل عُمان بأخلاق راقية، ونشر المعرفة النافعة، والتصدي للشائعات","بالإساءة للآخرين","بإهمال القوانين الرقمية"],"answer":1,"why":"التمثيل المشرف ومحاربة الشائعات واجب وطني رقمي."},{"type":"tfr","q":"حب الوطن فطرة إنسانية أصيلة أقرّها الإسلام ومارسها النبي ﷺ بالقول والدعاء والعمل.","answer":true,"reasons":["فقد أحب مكة ودعا للمدينة بالأمن والبركة","الإسلام يمنع حب الوطن","مجرد شعارات"],"reason":0},{"type":"tfr","q":"يتحقّق الإخلاص للوطن بالأقوال والشعارات وحدها دون حاجة للعمل والإتقان.","answer":false,"reasons":["نعم الشعارات تكفي","بل بالعمل المخلص وإتقان الدراسة والمهنة وحفظ المرافق واحترام القانون","لا علاقة له بالعمل"],"reason":1},{"type":"essay","q":"اذكر أربع صور عملية تعبّر بها كطالب عن إخلاصك لوطنك سلطنة عُمان.","model":"١) الاجتهاد والتفوق في الدراسة. ٢) المحافظة على ممتلكات المدرسة والمرافق العامة وترشيد الماء والكهرباء. ٣) احترام القوانين والسمت العُماني. ٤) المشاركة في التطوع والتصدي للشائعات."},{"type":"essay","q":"استدل من القرآن الكريم والسنة النبوية على مشروعية حب الوطن والدعاء له.","model":"القرآن: دعاء إبراهيم ﴿رب اجعل هذا بلدًا آمنًا وارزق أهله من الثمرات﴾. السنة: قول النبي ﷺ لمكة «إنك لأحب أرض الله إليّ»، ودعاؤه للمدينة بالحب والبركة."}],"hard":[{"type":"mcq","q":"ما معنى «ترشيد استهلاك الماء والكهرباء» في سياق الإخلاص للوطن؟","options":["إهدار الموارد","حرمان النفس من الحاجة","حفظ ثروات الوطن وموارده للأجيال القادمة وترك الإسراف","لا علاقة له بالوطن"],"answer":2,"why":"حفظ الموارد الوطنية والبيئية ركيزة للتنمية المستدامة."},{"type":"mcq","q":"أي سلوك يناقض الإخلاص للوطن؟","options":["الدعاء للوطن","التطوع لخدمة المجتمع","التفوق العلمي","العبث بالمرافق العامة أو الغش الوظيفي أو نشر الشائعات"],"answer":3,"why":"الإضرار بالممتلكات العامة أو الفساد يناقض الوطنية الصادقة."},{"type":"mcq","q":"هل يتعارض «حب الوطن» مع «الأخوّة الإسلامية والإنسانية»؟","options":["لا يتعارض أبدًا؛ فالإخلاص للوطن جزء من الوفاء والإحسان ويقوّي دور الوطن في خدمة الأمة والإنسانية","نعم يتعارض دائمًا","يجب ترك أحدهما","يمنع التعاون الدولي"],"answer":0,"why":"الوطن القوي المخلص يكون سندًا لأمته والعالم."},{"type":"mcq","q":"من أدعية الأنبياء للوطن في القرآن الكريم دعاء إبراهيم عليه السلام لمكة:","options":["لم يدعُ لبلده","﴿ربّ اجعل هذا بلدًا آمنًا وارزق أهله من الثمرات﴾","دعا على أهله","دعا بالخراب"],"answer":1,"why":"الدعاء للوطن بالأمن والرزق سنة الأنبياء."},{"type":"tfr","q":"الكتابة على جدران المدرسة أو إتلاف ممتلكات الحدائق العامة يتنافى مع الإخلاص للوطن.","answer":true,"reasons":["أمر بسيط لا يهم","تعبير فني مقبول","لأنها اعتداء على المال العام وتشويه لصورة الوطن"],"reason":2},{"type":"tfr","q":"الدعاء للوطن بالأمن والاستقرار والرخاء سنة الأنبياء كما في دعاء إبراهيم عليه السلام.","answer":true,"reasons":["﴿رب اجعل هذا بلدًا آمنًا وارزق أهله من الثمرات﴾","لا يُشرع الدعاء للوطن","خاص بمكة فقط"],"reason":0},{"type":"tfr","q":"التطوع وخدمة المجتمع يرسّخان الإخلاص للوطن ويقوّيان الوحدة الوطنية.","answer":true,"reasons":["التطوع مضيعة للوقت","كما يظهر في تكافل أهل عُمان ومبادراتهم التطوعية الرائدة","لا يفيد الوطن"],"reason":1},{"type":"essay","q":"بيّن كيف يسهم «إتقان العمل والنزاهة» في نهضة الوطن وتقدّمه.","model":"يرفع جودة التعليم والصحة والاقتصاد، ويمنع الفساد والهدر، ويحقق أهداف رؤية عُمان ٢٠٤٠."},{"type":"essay","q":"كيف تحافظ على صورة وطنك المشرّفة عند السفر أو عبر وسائل التواصل الاجتماعي؟","model":"بالالتزام بالقوانين والسمت العُماني الراقي، والكلمة الطيبة، والتعريف بثقافة عُمان وتسامحها، وتجنب الإساءة والشائعات."},{"type":"essay","q":"لماذا تُعدّ «الوحدة الوطنية» أغلى ثروة يجب على الجميع صونها؟","model":"لأنها أساس الأمن والاستقرار الذي تقوم عليه كل المشاريع والنهضة، وبدونها تتعطل التنمية ويضيع الأمان."}]}},
  {"id":"g9-islamic-2-u3-1","grade":"g9","subject":"islamic","term":2,"unit":3,"no":1,"title":"ما يُراعى لحفص (تجويد)","summary":"شرح متحرك بـ SVG لدرس ما يُراعى لحفص (تجويد) (الصف التاسع - الفصل الثاني)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.","page":"lesson-hafs-recitation-rules.html","video":"","pdf":"","notes":["السكت (وقفة لطيفة بلا تنفس): ٤ مواضع واجبة لحفص (عوجا، مرقدنا، من راق، بل ران).","الإمالة الكبرى: ﴿مجرىها﴾ (هود). التسهيل: ﴿ءاعجمي﴾ (فصلت). الإشمام: ﴿تأمنا﴾ (يوسف).","الصاد والسين: يبصط/بصطة (سين فقط)، المصيطرون (وجهان)، بمصيطر (صاد فقط)."],"exercises":["اذكر السكتات الأربع الواجبة لحفص مع اسم السورة لكل سكتة.","فرّق بين الإمالة والتسهيل والإشمام مع ذكر موضع كل منها لحفص.","بيّن حكم الصاد والسين عند حفص في: ﴿يبصط﴾، ﴿بصطة﴾، ﴿المصيطرون﴾، ﴿بمصيطر﴾."],"levels":{"easy":[{"type":"mcq","q":"ما تعريف «السَّكت» في علم التجويد؟","options":["قطع الصوت زمنًا يسيرًا (نحو حركتين) دون تنفس بنية استئناف القراءة","الوقف الطويل مع أخذ نفس عميق","المدّ ٦ حركات","إدغام الحرفين"],"answer":0,"why":"السكت وقفة لطيفة بلا تنفس وعلامتها (س) صغيرة."},{"type":"mcq","q":"ما الموضع الوحيد الذي فيه «إمالة كبرى» في رواية حفص عن عاصم؟","options":["﴿تَأْمَنَّا﴾ في سورة يوسف","﴿مَجْرٜىٰهَا﴾ في سورة هود","﴿ءَا۬عْجَمِيٌّ﴾ في سورة فصلت","﴿بَلْ ۜ رَانَ﴾ في المطففين"],"answer":1,"why":"ليس لحفص إمالة كبرى إلا في ﴿مجرىها﴾ (هود: ٤١)."},{"type":"mcq","q":"ما الحكم الخاص الذي يُراعى لحفص في كلمة ﴿ءَا۬عْجَمِيٌّ﴾ (فصلت: ٤٤)؟","options":["السكت الواجب","الإمالة الكبرى","التسهيل في الهمزة الثانية (بين الهمزة والألف)","الإقلاب"],"answer":2,"why":"الهمزة الثانية مسهّلة وعلامتها نقطة سوداء مطموسة."},{"type":"mcq","q":"كيف يقرأ حفص كلمة ﴿تَأْمَنَّا﴾ في سورة يوسف؟","options":["بإظهار نونين مفتوحتين","بالإمالة الكبرى","بالسكت","بالإدغام مع الإشمام (ضم الشفتين دون صوت) أو الاختلاس"],"answer":3,"why":"الإشمام يشير لحركة الضمة الأصلية في النون الأولى."}],"medium":[{"type":"mcq","q":"أي مجموعة تمثّل «السكتات الأربع الواجبة» لحفص عند الوصل؟","options":["عِوَجَا (الكهف)، مَرْقَدِنَا (يس)، مَنْ رَاقٍ (القيامة)، بَلْ رَانَ (المطففين)","الفاتحة والإخلاص فقط","مجرىها وتأمنا","يبصط وبصطة"],"answer":0,"why":"هذه هي المواضع الأربعة الواجبة للسكت عند حفص."},{"type":"mcq","q":"كيف يقرأ حفص كلمتَي ﴿وَيَبْصُۜطُ﴾ (البقرة) و﴿بَصْۜطَةً﴾ (الأعراف)؟","options":["بالصاد فقط","بالسين الخالصة فقط","بالتسهيل","بالإمالة"],"answer":1,"why":"توضع سين صغيرة فوق الصاد فيقرؤها حفص بالسين فقط."},{"type":"mcq","q":"كيف يقرأ حفص كلمة ﴿بِمُصَيْطِرٍ﴾ في سورة الغاشية؟","options":["بالإمالة","بالسين فقط","بالصاد الخالصة فقط","بالتسهيل"],"answer":2,"why":"﴿بمصيطر﴾ بالصاد فقط، بينما ﴿المصيطرون﴾ بالطور يجوز فيها الوجهان."},{"type":"tfr","q":"الفرق بين السكت والوقف أن السكت يكون «بدون تنفس» لزمن يسير، بينما الوقف يكون مع التنفس.","answer":true,"reasons":["كلاهما مع التنفس","وهذا هو الفارق الأساسي بين السكت والوقف في التجويد","السكت أطول من الوقف"],"reason":1},{"type":"tfr","q":"يقرأ حفص كلمة ﴿مَجْرٜىٰهَا﴾ في سورة هود بالإمالة الكبرى، ولا يوجد غيرها في القرآن لحفص.","answer":true,"reasons":["تقرأ بالفتح الخالص","توجد مئة كلمة بالإمالة لحفص","فهي الموضع الوحيد للإمالة الكبرى في رواية حفص من طريق الشاطبية"],"reason":2},{"type":"essay","q":"اذكر السكتات الأربع الواجبة لحفص مع اسم السورة لكل سكتة.","model":"١) ﴿عوجا ۜ قيما﴾ (الكهف). ٢) ﴿مرقدنا ۜ هذا﴾ (يس). ٣) ﴿من ۜ راق﴾ (القيامة). ٤) ﴿بل ۜ ران﴾ (المطففين)."},{"type":"essay","q":"فرّق بين الإمالة والتسهيل والإشمام مع ذكر موضع كل منها لحفص.","model":"الإمالة: تقريب الفتحة للكسرة والألف للياء في ﴿مجرىها﴾ (هود). التسهيل: نطق الهمزة الثانية بين الهمزة والألف في ﴿ءاعجمي﴾ (فصلت). الإشمام: ضم الشفتين بلا صوت إشارة للضمة في ﴿تأمنا﴾ (يوسف)."}],"hard":[{"type":"mcq","q":"ما العلامة الموضوعة في المصحف للدلالة على موضع «السكت» الواجب؟","options":["معيّن صغير","صفر مستدير","نقطة مطموسة","حرف سين صغيرة (س) فوق آخر الكلمة"],"answer":3,"why":"حرف (س) الصغير يشير لموضع السكت."},{"type":"mcq","q":"ما فائدة السكت في قوله تعالى ﴿مَنْ ۜ رَاقٍ﴾ و﴿بَلْ ۜ رَانَ﴾؟","options":["منع الإدغام الكامل حتى لا يلتبس اللفظ والمعنى (مَرّاق / بَرّان)","تطويل النفس","تغيير المعنى","الوقف التام"],"answer":0,"why":"السكت يمنع الإدغام ويحفظ وضوح الكلمتين والمعنى."},{"type":"mcq","q":"ما الوجهان الجائزان لحفص في كلمة ﴿ضَعْفٍ﴾ بسورة الروم (آية ٥٤)؟","options":["كسر الضاد فقط","فتح الضاد (ضَعْف) أو ضمها (ضُعْف) مع توحيد الوجه","إمالة الضاد","حذف الضاد"],"answer":1,"why":"يجوز الفتح (المقدم) أو الضم بشرط التوحيد في الآية."},{"type":"mcq","q":"ما الطريقة الصحيحة لتعلّم نطق الإمالة والإشمام والتسهيل؟","options":["القراءة السريعة","التخمين دون سماع","التلقي والمشافهة من معلم قرآن متقن","تجاهل العلامات"],"answer":2,"why":"الأداء الصوتي الدقيق لا يُضبط إلا بالتلقي والمشافهة."},{"type":"tfr","q":"في ﴿الْمُصَۜيْطِرُونَ﴾ بسورة الطور يجوز لحفص القراءة بالصاد أو بالسين.","answer":true,"reasons":["أما ﴿بمصيطر﴾ بالغاشية فبالصاد فقط، و﴿يبصط/بصطة﴾ بالسين فقط","بالسين فقط","بالصاد فقط"],"reason":0},{"type":"tfr","q":"الإشمام في ﴿تَأْمَنَّا﴾ هو صوت عالٍ يُسمع من بعيد.","answer":false,"reasons":["نعم صوت عالٍ","الإشمام حركة بصرية للشفتين فقط (ضم الشفتين للأمام دون صوت) إشارةً للضمة","حركة للسان فقط"],"reason":1},{"type":"tfr","q":"السكت في ﴿عِوَجَا ۜ قَيِّمًا﴾ (الكهف) يمنع توهّم أن «قيمًا» صفة لـ«عوجًا» فيحفظ المعنى الدقيق.","answer":true,"reasons":["يُدمج الكلمتين","لا أثر له في المعنى","بل المعنى: لم يجعل له عوجًا، وجعله كتابًا قيمًا"],"reason":2},{"type":"essay","q":"بيّن حكم الصاد والسين عند حفص في: ﴿يبصط﴾، ﴿بصطة﴾، ﴿المصيطرون﴾، ﴿بمصيطر﴾.","model":"يبصط وبصطة: بالسين فقط. المصيطرون: بالوجهين (صاد أو سين). بمصيطر: بالصاد فقط."},{"type":"essay","q":"قارن بين السكت والوقف من حيث الزمن والتنفس والعلامة في المصحف.","model":"السكت: زمن يسير نحو حركتين بلا تنفس وعلامته (س). الوقف: زمن أطول مع التنفس وعلاماته (قلى، صلى، م، ج)."},{"type":"essay","q":"علّل: لماذا لا يُغني الشرح المكتوب وحده عن المشافهة في إتقان درس «ما يُراعى لحفص»؟","model":"لأن الإمالة والإشمام والتسهيل ظواهر صوتية وحركية دقيقة لا تُضبط إلا بالسماع المباشر من معلم متقن وتصحيح النطق."}]}},
  {"id":"g9-islamic-2-u3-2","grade":"g9","subject":"islamic","term":2,"unit":3,"no":2,"title":"سورة الأعراف (٥٥–٥٨) — تفسير","summary":"شرح متحرك بـ SVG لدرس سورة الأعراف (٥٥–٥٨) — تفسير (الصف التاسع - الفصل الثاني)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.","page":"lesson-surah-al-araf-55-58.html","video":"","pdf":"","notes":["آداب الدعاء (الأعراف ٥٥–٥٦): تضرعًا، خفية، خوفًا وطمعًا، وترك الاعتداء.","النهي عن الإفساد في الأرض يشمل الفساد الديني والأخلاقي والبيئي.","إحياء الأرض الميتة بالمطر برهان على البعث، ومثل البلد الطيب والخبيث يصف استجابة القلوب للوحي."],"exercises":["اذكر أربعةً من آداب الدعاء المستفادة من الآيتين ٥٥ و٥٦ من سورة الأعراف.","اشرح كيف استدلّت الآية ٥٧ بظاهرة المطر على إمكان البعث يوم القيامة.","وضّح التشبيه القرآني في الآية ٥٨ بين «البلد الطيب والبلد الخبيث» وبين قلوب الناس."],"levels":{"easy":[{"type":"mcq","q":"ما الآداب الثلاثة للدعاء المذكورة في الآيتين ٥٥ و٥٦ من سورة الأعراف؟","options":["الصراخ والرياء","التضرع، والخفية، والخوف والطمع مع ترك الاعتداء","الدعاء بالإثم","العجلة والغفلة"],"answer":1,"why":"أمر الله بالدعاء تضرعًا وخفية وخوفًا وطمعًا ونهى عن الاعتداء."},{"type":"mcq","q":"ما معنى «الاعتداء في الدعاء» المنهي عنه في الآية ٥٥؟","options":["الدعاء بالخير للمسلمين","تكرار الدعاء بخشوع","مجاوزة الحد كالدعاء بإثم أو قطيعة رحم أو رفع الصوت بالصراخ","الدعاء في السجود"],"answer":2,"why":"الاعتداء يشمل الصراخ غير المشروع والدعاء بالمحرمات."},{"type":"mcq","q":"ما البرهان الكوني على «البعث بعد الموت» في الآية ٥٧؟","options":["تقلب الفصول فقط","حركة السفن فقط","بناء القصور","إحياء الأرض الميتة القاحلة بماء المطر وإخراج الثمرات منها"],"answer":3,"why":"﴿كذلك نخرج الموتى لعلكم تذكرون﴾."},{"type":"mcq","q":"ما معنى «نَكِدًا» في قوله تعالى ﴿والذي خبث لا يخرج إلا نكدًا﴾؟","options":["قليلًا عسيرًا لا خير فيه ولا بركة","كثيرًا مباركًا","سريع النمو","حلو الطعم"],"answer":0,"why":"الأرض السبخة الخبيثة لا تنبت إلا زرعًا ضعيفًا عسيرًا."}],"medium":[{"type":"mcq","q":"ما المقصود بمَثَل «البلد الطيب» و«البلد الخبيث» في الآية ٥٨؟","options":["المطر والريح","القلب المؤمن الطيب الذي ينتفع بالوحي، مقابل القلب المعاند الذي لا ينتفع","البحر والصحراء","الليل والنهار"],"answer":1,"why":"الوحي كالمطر والقلوب كالأرض في قبولها وانتفاعها به."},{"type":"mcq","q":"ما معنى «بُشْرًا بين يدي رحمته»؟","options":["سحب جافة","عواصف مدمرة","مبشّرات بقدوم المطر (الرحمة)","حر شديد"],"answer":2,"why":"الرياح اللطيفة تبشّر الناس بقرب نزول الغيث."},{"type":"mcq","q":"لمن تكون «رحمة الله قريبةً» كما بشّرت الآية ٥٦؟","options":["للمتكبرين","للمفسدين","للمعتدين","للمحسنين (المتقنين لعبادة الله والإحسان لخلقه)"],"answer":3,"why":"﴿إن رحمت الله قريب من المحسنين﴾."},{"type":"tfr","q":"يُعدّ الدعاء على أخيك المسلم بالشر أو بقطيعة الرحم من «الاعتداء في الدعاء» المحرّم.","answer":true,"reasons":["لا حرج فيه","يجوز عند الغضب","لقوله تعالى ﴿إنه لا يحب المعتدين﴾"],"reason":2},{"type":"tfr","q":"إحياء الأرض الميتة بنزول المطر وإخراج الثمرات دليل حسي وعقلي على قدرة الله على البعث.","answer":true,"reasons":["﴿كذلك نخرج الموتى لعلكم تذكرون﴾","لا علاقة له بالبعث","يحدث بالصدفة"],"reason":0},{"type":"essay","q":"اذكر أربعةً من آداب الدعاء المستفادة من الآيتين ٥٥ و٥٦ من سورة الأعراف.","model":"١) التضرع والخشوع. ٢) الخفية والإخلاص. ٣) الجمع بين الخوف والرجاء (الطمع). ٤) اجتناب الاعتداء في الدعاء."},{"type":"essay","q":"اشرح كيف استدلّت الآية ٥٧ بظاهرة المطر على إمكان البعث يوم القيامة.","model":"أرسل الله الرياح تسوق السحاب الثقال لأرض ميتة قاحلة فأنزل الماء وأخرج منها الثمرات؛ والقادر على إحياء الأرض الميتة قادر على إحياء الموتى يوم القيامة."}],"hard":[{"type":"mcq","q":"يدخل في النهي ﴿ولا تفسدوا في الأرض بعد إصلاحها﴾:","options":["الشرك والظلم وتلويث البيئة وتخريب الممتلكات العامة","الزراعة والتشجير","تنظيف الأودية","طلب العلم"],"answer":0,"why":"النهي يشمل الفساد الديني والأخلاقي والبيئي."},{"type":"mcq","q":"لماذا كان الدعاء «خُفية» (سرًا) من أعظم آداب الدعاء؟","options":["لأن الله لا يسمع الجهر","لأنه أبعد عن الرياء وأقرب للإخلاص والخشوع والصدق مع الله","لإخفاء الخير دائمًا","لأنه أسرع كلامًا"],"answer":1,"why":"الإسرار بالدعاء يصفي القلب من الرياء ويزيد الخشوع."},{"type":"mcq","q":"الجمع بين «الخوف والطمع» في الدعاء يعني:","options":["الطمع في أموال الناس","الخوف من الناس","الخوف من عقاب الله وتقصيرنا، والرجاء في رحمته وفضله","اليأس من الرحمة"],"answer":2,"why":"الخوف والرجاء يتوازنان في قلب المؤمن."},{"type":"mcq","q":"أُعيد تذكير الناس بالشكر في ختام الآية ٥٨ ﴿لقوم يشكرون﴾ لأن:","options":["الشكر للأغنياء فقط","الشكر باللسان فقط","لا أحد يشكر","الشاكرين هم الذين يتفكّرون في آيات الله وينتفعون بها"],"answer":3,"why":"الشكر يفتح أبواب التفكر وزيادة النعم."},{"type":"tfr","q":"النهي عن الإفساد في الأرض في الآية ٥٦ يشمل التلوث البيئي وتخريب المرافق العامة بجانب المعاصي.","answer":true,"reasons":["يقتصر على الشرك فقط","فالآية عامة في حفظ صلاح الأرض الديني والبيئي والاجتماعي","لا يشمل البيئة"],"reason":1},{"type":"tfr","q":"الأرض الطيبة في الآية ٥٨ ترمز للمؤمن الذي يستقبل القرآن بالإيمان والعمل الصالح.","answer":true,"reasons":["ترمز للبحر","ترمز للتجارة فقط","فيخرج منه الخير والبركة بإذن الله كما يخرج النبات من الأرض الخصبة"],"reason":2},{"type":"tfr","q":"يجب رفع الصوت بالصراخ الشديد أثناء الدعاء لأن ذلك من التضرع.","answer":false,"reasons":["بل أرشد الله إلى التضرع والخفية وخفض الصوت، ونهى عن الاعتداء","نعم الصراخ أفضل","الخفية مكروهة"],"reason":0},{"type":"essay","q":"وضّح التشبيه القرآني في الآية ٥٨ بين «البلد الطيب والبلد الخبيث» وبين قلوب الناس.","model":"الوحي كالمطر النازل من السماء؛ فالقلب المؤمن الطيب كالأرض الخصبة يثمر خيرًا وأخلاقًا بإذن الله، والقلب المعاند كالأرض السبخة لا ينتفع بالهدى."},{"type":"essay","q":"اذكر ثلاث صور للإفساد في الأرض يجب تجنبها وثلاث صور للإصلاح في بيئتنا العُمانية.","model":"الإفساد: التلوث البيئي، الظلم والغش، وتخريب المرافق. الإصلاح: التشجير، نظافة الأودية والشواطئ، والعدل والأمانة."},{"type":"essay","q":"ما معنى: تضرعًا، خُفية، السحاب الثقال، نكدًا؟","model":"تضرعًا: تذللًا وخشوعًا. خفية: سرًا بصوت منخفض. السحاب الثقال: المحملة بالماء الكثير. نكدًا: قليلًا عسيرًا بلا بركة."}]}},
  {"id":"g9-islamic-2-u3-3","grade":"g9","subject":"islamic","term":2,"unit":3,"no":3,"title":"مكانة المؤمن عند الله (حديث قدسي)","summary":"شرح متحرك بـ SVG لدرس مكانة المؤمن عند الله (حديث قدسي) (الصف التاسع - الفصل الثاني)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.","page":"lesson-status-of-believer.html","video":"","pdf":"","notes":["الحديث القدسي: معناه من الله ولفظه من النبي ﷺ ولا يُقرأ في الصلاة.","طريق محبة الله: إتقان الفرائض أولًا ثم المداومة على النوافل.","ثمرات محبة الله: تسديد الجوارح (السمع والبصر واليد والرجل)، وإجابة الدعاء، والحفظ والإعاذة."],"exercises":["قارن بين القرآن الكريم والحديث القدسي في ثلاث نقاط.","اذكر خطوتين أساسيتين للوصول إلى محبة الله كما بيّنهما الحديث القدسي.","اذكر ثلاث ثمرات ينالها العبد إذا أحبّه الله تعالى وفق الحديث القدسي."],"levels":{"easy":[{"type":"mcq","q":"ما الفرق بين «القرآن الكريم» و«الحديث القدسي»؟","options":["الحديث القدسي معجز في لفظه كالقرآن","لا فرق بينهما","القرآن لفظه ومعناه من الله ويُتعبّد بتلاوته، أما الحديث القدسي فمعناه من الله ولفظه من النبي ﷺ ولا يُقرأ في الصلاة","القرآن من لفظ النبي"],"answer":2,"why":"هذا هو الفارق العلمي الدقيق بين القرآن والحديث القدسي."},{"type":"mcq","q":"من هو «وليّ الله» المذكور في الحديث القدسي؟","options":["صاحب المال الكثير فقط","شخص واحد فقط في كل قرن","من يترك الصلاة","كل مؤمن تقي يطيع الله ويجتنب معاصيه"],"answer":3,"why":"﴿ألا إن أولياء الله... الذين آمنوا وكانوا يتقون﴾."},{"type":"mcq","q":"ما أحبّ شيء يتقرّب به العبد إلى الله تعالى كما جاء في الحديث القدسي؟","options":["أداء الفرائض التي افترضها الله عليه","النوافل مع ترك الفرائض","الانعزال عن الناس","السهر الطويل"],"answer":0,"why":"«وما تقرّب إليّ عبدي بشيء أحب إليّ مما افترضت عليه»."},{"type":"mcq","q":"ما الطريق الذي يصل به المؤمن إلى «محبة الله تعالى» بعد أداء الفرائض؟","options":["إهمال السنن","المداومة على التقرب إلى الله بالنوافل","الجدال مع الناس","ترك العمل"],"answer":1,"why":"«وما يزال عبدي يتقرب إليّ بالنوافل حتى أحبّه»."}],"medium":[{"type":"mcq","q":"ما معنى قوله تعالى في الحديث: «كنت سمعه الذي يسمع به وبصره الذي يبصر به»؟","options":["فقدان السمع والبصر","الحلول والاتحاد حاشا لله","توفيق الله وتسديده وحفظه لجوارح عبده فلا يستخدمها إلا في طاعته والخير","التوقف عن الكلام"],"answer":2,"why":"معناه التسديد والتوفيق الإلهي في سمعه وبصره ويده ورجله."},{"type":"mcq","q":"ما معنى «فقد آذنتُه بالحرب» في أول الحديث القدسي؟","options":["سامحته فورًا","أذنت له في القتال","تركته وشأنه","أعلمته وأخبرته بأن الله ينتقم لأوليائه ويدافع عنهم"],"answer":3,"why":"تحذير شديد من إيذاء المؤمنين الصالحين ومعاداتهم."},{"type":"mcq","q":"من ثمرات محبة الله لعبده في ختام الحديث القدسي:","options":["إجابة دعائه («لأعطينّه») وحفظه من الشر («لأعيذنّه»)","كثرة المشاكل فقط","ترك الدعاء","الغنى الفوري فقط"],"answer":0,"why":"الله يعطيه إذا سأله ويعيذه ويحميه إذا استعاذ به."},{"type":"tfr","q":"تُعدّ الفرائض (كالصلوات الخمس وبر الوالدين) أحبّ إلى الله من النوافل.","answer":true,"reasons":["لقوله تعالى في الحديث القدسي «ما تقرّب إليّ عبدي بشيء أحب إليّ مما افترضت عليه»","النوافل أهم من الفرائض","كلاهما سواء"],"reason":0},{"type":"tfr","q":"معنى «وليّ الله» يشمل كل مؤمن تقي محافظ على طاعة الله.","answer":true,"reasons":["لفئة نادرة فقط","وليس حكرًا على فئة غامضة؛ فكل من آمن واتقى فهو من أولياء الله","للأنبياء فقط"],"reason":1},{"type":"essay","q":"قارن بين القرآن الكريم والحديث القدسي في ثلاث نقاط.","model":"١) القرآن لفظه ومعناه من الله، والقدسي معناه من الله ولفظه من النبي ﷺ. ٢) القرآن معجز ومتواتر، والقدسي ليس معجزًا ومنه الصحيح وغيره. ٣) القرآن يُتعبّد بتلاوته في الصلاة دون القدسي."},{"type":"essay","q":"اذكر خطوتين أساسيتين للوصول إلى محبة الله كما بيّنهما الحديث القدسي.","model":"١) إتقان وأداء الفرائض أولًا (الصلاة، الصيام، بر الوالدين، ترك المحرمات). ٢) المداومة على النوافل (السنن، القرآن، الذكر، الصدقة)."}],"hard":[{"type":"mcq","q":"طالب يسهر في تلاوة نافلة ثم ينام ويُضيّع صلاة الفجر الفريضة؛ ما الخطأ في فعله؟","options":["أصاب تمامًا","قدّم النافلة على الفريضة، بينما الفرائض هي أحب الأعمال إلى الله وأولاها","النافلة أهم من الفريضة","لا فرق بينهما"],"answer":1,"why":"الأولوية دائمًا لإتقان الفرائض ثم الإكثار من النوافل."},{"type":"mcq","q":"ما دلالة الفعل «وما يزال» في قوله «وما يزال عبدي يتقرّب إليّ بالنوافل»؟","options":["فعله في رمضان فقط","فعله مرة واحدة في السنة","الاستمرار والمداومة على العمل الصالح وإن كان قليلًا","التوقف بعد أسبوع"],"answer":2,"why":"المداومة والاستمرار هي سر نيل محبة الله."},{"type":"mcq","q":"ما معنى «لئن استعاذني لأعيذنّه»؟","options":["لا يجوز الاستعاذة","إذا سافر أعطيته مالًا","إذا أخطأ تركته","إذا لجأ إليّ طالبًا الحماية من شر أو مكروه حفظته وأجرته منه"],"answer":3,"why":"الاستعاذة هي اللجوء لله، والإعاذة هي الحماية والحفظ."},{"type":"mcq","q":"أين ورد هذا الحديث القدسي العظيم؟","options":["في صحيح البخاري عن أبي هريرة رضي الله عنه","في كتب التاريخ فقط","في شعر العرب","حديث غير معروف"],"answer":0,"why":"رواه الإمام البخاري في صحيحه عن أبي هريرة."},{"type":"tfr","q":"يجوز التلاوة بالحديث القدسي بدل سورة الفاتحة في الصلاة.","answer":false,"reasons":["لا فرق بينهما","نعم يجوز","الحديث القدسي لا يُتعبّد بتلاوته في الصلاة؛ القرآن وحده هو الذي يُقرأ في الصلاة"],"reason":2},{"type":"tfr","q":"من ثمرات محبة الله للعبد تسديد جوارحه (السمع والبصر واليد والرجل) وإجابة دعائه وحفظه.","answer":true,"reasons":["وهي أعظم كرامة ومكانة ينالها المؤمن في الدنيا والآخرة","لا ثمرة لها في الدنيا","تقتصر على المال"],"reason":0},{"type":"tfr","q":"إيذاء المؤمنين الصالحين والسخرية من التزامهم يدخل في التحذير الشديد بأول الحديث.","answer":true,"reasons":["السخرية مباحة","لقوله تعالى «من عادى لي وليًا فقد آذنته بالحرب»","لا علاقة لها بالحديث"],"reason":1},{"type":"essay","q":"اذكر ثلاث ثمرات ينالها العبد إذا أحبّه الله تعالى وفق الحديث القدسي.","model":"١) توفيق الله وتسديده في سمعه وبصره ويده ورجله. ٢) إجابة دعائه («لأعطينّه»). ٣) حفظه وحمايته من الشرور («لأعيذنّه»)."},{"type":"essay","q":"فسّر معنى قوله تعالى: «كنت سمعه الذي يسمع به وبصره الذي يبصر به» تفسيرًا صحيحًا.","model":"أي يسدده الله ويوفقه فيحفظ سمعه وبصره وجوارحه فلا يستعملها إلا في ما يرضي الله تعالى."},{"type":"essay","q":"ضع لنفسك برنامجًا يوميًا يجمع بين «الفرائض» و«ثلاث نوافل يسيرة» لتنال محبة الله.","model":"الفرائض: الصلوات الخمس في أوقاتها وبر الوالدين والصدق. النوافل: ركعتا سنة الفجر (أو الضحى)، صفحة قرآن يوميًا، وأذكار الصباح والمساء."}]}},
  {"id":"g9-islamic-2-u3-4","grade":"g9","subject":"islamic","term":2,"unit":3,"no":4,"title":"أحكام الوديعة (فقه)","summary":"شرح متحرك بـ SVG لدرس أحكام الوديعة (فقه) (الصف التاسع - الفصل الثاني)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.","page":"lesson-deposit-rulings.html","video":"","pdf":"","notes":["الوديعة: مال يُترك عند أمين لحفظه بلا مقابل ورده عند طلبه.","لا يجوز استعمال الوديعة إلا بإذن صاحبها، وتُحفظ في حرز مثلها.","القاعدة: لا ضمان على المودَع إلا إذا تعدّى أو فرّط."],"exercises":["عرّف الوديعة واذكر أركانها الأربعة.","وضّح قاعدة الضمان في الوديعة مع مثال لحالة «لا ضمان فيها» وحالة «يجب فيها الضمان».","اذكر ثلاثة واجبات يجب على المودَع الالتزام بها تجاه الوديعة."],"levels":{"easy":[{"type":"mcq","q":"ما تعريف «الوديعة» في الفقه الإسلامي؟","options":["هدية لا تُرد","مال ضاع في الطريق","بيع سلعة بالتقسيط","مال يتركه صاحبه عند غيره ليحفظه له أمانةً بلا مقابل ويردّه عند طلبه"],"answer":3,"why":"الوديعة عقد أمانة للحفظ والرد عند الطلب."},{"type":"mcq","q":"متى «يضمن» المودَع (الحافظ) قيمة الوديعة إذا تلفت أو ضاعت؟","options":["إذا تعدّى عليها (كاستعمالها بلا إذن) أو فرّط في حفظها","في جميع الأحوال حتى بالكوارث","لا يضمن أبدًا حتى لو أتلفها عمدًا","إذا حفظها في حرز آمن"],"answer":0,"why":"الأمين لا يضمن إلا بالتعدي أو التفريط."},{"type":"mcq","q":"هل يجوز للمودَع استعمال ساعة أو هاتف أودعه زميله عنده دون إذنه؟","options":["نعم يجوز دائمًا","لا يجوز؛ فإن استعملها وتلفت ضمنها لأنه متعدٍّ","يجوز يومًا واحدًا","واجب استعمالها"],"answer":1,"why":"الوديعة للحفظ فقط، واستعمالها بلا إذن تعدٍّ يوجب الضمان."},{"type":"mcq","q":"أودع طالب كتابه عند زميله فحفظه في حقيبته المغلقة، ثم سُرقت الحقيبة كلها رغم حرصه؛ هل يضمن الكتاب؟","options":["يأثم","يضمن ضعفي الثمن","لا يضمن لأنه لم يتعدَّ ولم يفرّط في الحفظ","يضمن دائمًا"],"answer":2,"why":"لا ضمان على الأمين المحسن عند غياب التعدي والتفريط."}],"medium":[{"type":"mcq","q":"ما الموقف الخالد في السيرة النبوية الذي يبرز تعظيم ردّ الودائع حتى للمخالفين؟","options":["بناء الكعبة","صلح الحديبية","غزوة تبوك","ترك النبي ﷺ علي بن أبي طالب ليلة الهجرة في مكة ليردّ ودائع قريش إلى أهلها"],"answer":3,"why":"ردّ النبي ﷺ ودائع المشركين رغم إخراجهم له من مكة!"},{"type":"mcq","q":"ما معنى «حفظ الوديعة في حرز مثلها»؟","options":["وضعها في المكان الآمن المعتاد لحفظ أمثالها (كالخزانة للنقود)","تركها في الشارع","وضعها في الماء","إعطاؤها لغريب"],"answer":0,"why":"حرز المثل هو المكان المناسب لأمان هذا النوع من المال."},{"type":"mcq","q":"ما حكم قبول الوديعة لمن يثق في أمانته وقدرته على الحفظ؟","options":["حرام","مستحب لما فيه من التعاون وقضاء حاجة المسلم","مكروه","غير جائز"],"answer":1,"why":"الإعانة على حفظ مال المسلم عمل خير مستحب."},{"type":"tfr","q":"لا يضمن الأمين المودَع تلف الوديعة إذا حفظها في حرز مثلها ولم يتعدَّ ولم يفرّط.","answer":true,"reasons":["يضمن في كل الحالات","لقوله تعالى ﴿ما على المحسنين من سبيل﴾، ولأن يده يد أمانة","لا يضمن حتى لو كسرها عمدًا"],"reason":1},{"type":"tfr","q":"يجوز للحافظ أن يستعمل الوديعة (كالهاتف أو الدراجة) دون إذن صاحبها ما دام سيردّها.","answer":false,"reasons":["هذا حقه مقابل الحفظ","نعم يجوز الاستعمال بلا إذن","لا يجوز استعمالها إلا بإذن صاحبها، وإلا كان متعديًا وضامنًا لها"],"reason":2},{"type":"essay","q":"عرّف الوديعة واذكر أركانها الأربعة.","model":"مال يتركه صاحبه عند غيره ليحفظه أمانةً بلا مقابل ويردّه عند طلبه. أركانها: المودِع، المودَع، الوديعة، والصيغة."},{"type":"essay","q":"وضّح قاعدة الضمان في الوديعة مع مثال لحالة «لا ضمان فيها» وحالة «يجب فيها الضمان».","model":"لا ضمان إلا بتعدٍّ أو تفريط. لا ضمان: حفظ المال بخزانة مقفلة فوقع حريق قاهر. ضمان: استعمل هاتف زميله دون إذنه فكسره."}],"hard":[{"type":"mcq","q":"متى «يحرم» على الإنسان قبول الوديعة؟","options":["إذا كانت الوديعة كتابًا","إذا كان طالبًا","إذا علم من نفسه العجز عن حفظها أو عدم الأمانة","في يوم الجمعة"],"answer":2,"why":"قبول الأمانة مع العجز عن حفظها يعرّض مال الغير للضياع."},{"type":"mcq","q":"ما حكم جحود الوديعة وإنكارها عند طلب صاحبها؟","options":["جائز بين الأصدقاء","مباح إذا طال الوقت","مكروه فقط","محرّم ومن خيانة الأمانة الكبيرة"],"answer":3,"why":"جحود الأمانة من علامات النفاق وخيانة عظمى."},{"type":"mcq","q":"ماذا يفعل ورثة المودَع إذا تُوفي وعنده وديعة لأحد الناس؟","options":["يردّونها فورًا إلى صاحبها ولا تُقسّم ضمن التركة لأنها أمانة وليست ملكًا للمتوفى","يقسّمونها بينهم كميراث","يبيعونها","يحتفظون بها سنة"],"answer":0,"why":"الودائع تُردّ لأصحابها قبل قسمة التركة."},{"type":"mcq","q":"عقد الوديعة من حيث اللزوم يُعدّ عقدًا:","options":["لازمًا لا يُفسخ أبدًا","جائزًا (يحق لصاحبها استردادها متى شاء، وللحافظ ردّها عند العذر)","ممنوعًا","بيعًا مؤجلًا"],"answer":1,"why":"ينتهي العقد متى طلب المالك وديعته."},{"type":"tfr","q":"ترك النبي ﷺ عليًا رضي الله عنه في مكة ليلة الهجرة ليردّ ودائع أهل مكة رغم عداوتهم له.","answer":true,"reasons":["لأن الأمانة خُلق ثابت لا يتغيّر حتى مع المخالفين","أخذ الودائع معه للمدينة","لم تكن عنده ودائع"],"reason":0},{"type":"tfr","q":"إذا فرّط الحافظ وترك مال الوديعة في مكان مكشوف فسُرق، وجب عليه الضمان.","answer":true,"reasons":["لا يضمن أبدًا","لأن التفريط والإهمال يُحوّل يده من أمانة إلى ضمان","يتحمل المالك الخسارة"],"reason":1},{"type":"tfr","q":"تُعد الوديعة جزءًا من تركة المودَع إذا مات فيرثها أبناؤه.","answer":false,"reasons":["تُعطى للدولة","نعم يرثها أبناؤه","الوديعة ملك لصاحبها الأصلي ويجب على الورثة ردّها له فورًا"],"reason":2},{"type":"essay","q":"اذكر ثلاثة واجبات يجب على المودَع الالتزام بها تجاه الوديعة.","model":"١) حفظها في حرز مثلها. ٢) عدم استعمالها أو إقراضها إلا بإذن صاحبها. ٣) ردّها فورًا عند طلب صاحبها دون مماطلة."},{"type":"essay","q":"ماذا نتعلّم من موقف النبي ﷺ في ردّ ودائع قريش ليلة الهجرة؟","model":"أن الأمانة مبدأ إسلامي مطلق لا يُترك حتى مع المخالفين والمعتدين، وهو ما أكسب الإسلام احترام الجميع."},{"type":"essay","q":"ما الفرق بين «اللُّقطة» (الدرس السابق) و«الوديعة» (هذا الدرس)؟","model":"اللقطة مال ضائع يعثر عليه شخص دون علم صاحبه ويحتاج تعريفًا؛ أما الوديعة فمال يسلمه صاحبه برضاه لأمين معروف ليحفظه ويرده عند طلبه."}]}},
  {"id":"g9-islamic-2-u3-5","grade":"g9","subject":"islamic","term":2,"unit":3,"no":5,"title":"رملة بنت أبي سفيان رضي الله عنها (سيرة)","summary":"شرح متحرك بـ SVG لدرس رملة بنت أبي سفيان رضي الله عنها (سيرة) (الصف التاسع - الفصل الثاني)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.","page":"lesson-ramlah-bint-abi-sufyan.html","video":"","pdf":"","notes":["رملة بنت أبي سفيان (أم المؤمنين أم حبيبة) أسلمت مبكرًا وهاجرت للحبشة وثبتت على دينها بعد ارتداد زوجها وموته.","أكرمها الله بالزواج من النبي ﷺ عبر النجاشي، وروت نحو ٦٥ حديثًا منها حديث السنن الرواتب (١٢ ركعة).","برزت بتعظيم النبي ﷺ (موقف الفراش) والالتزام الدقيق بالسنة النبوية."],"exercises":["لخّص قصة ثبات أم حبيبة رضي الله عنها في الحبشة وكيف أكرمها الله بعد صبرها.","اذكر الحديث الشهير الذي روته أم حبيبة عن السنن الرواتب وبيّن كيف طبّقته.","ما الدلالات التربوية من موقفها مع أبيها أبي سفيان حين طوت فراش النبي ﷺ؟"],"levels":{"easy":[{"type":"mcq","q":"بمَ تُكنّى السيدة رملة بنت أبي سفيان رضي الله عنها؟","options":["أم حبيبة (أم المؤمنين)","أم سلمة","أم أيمن","أم الفضل"],"answer":0,"why":"تُكنّى بأم حبيبة نسبةً لابنتها حبيبة."},{"type":"mcq","q":"ما الابتلاء العظيم الذي صبرت عليه أم حبيبة في هجرتها إلى الحبشة؟","options":["فقدان قافلة تجارية فقط","ارتداد زوجها عن الإسلام وموته وبقاؤها وحيدةً في الغربة فثبتت على دينها","تأخر السفر","لم تهاجر للحبشة"],"answer":1,"why":"ثبتت على الإسلام رغم الغربة وارتداد زوجها فكرمها الله بالزواج من النبي ﷺ."},{"type":"mcq","q":"مَن الذي تولّى عقد زواجها من النبي ﷺ وإمهرها ٤٠٠ دينار في الحبشة؟","options":["سهيل بن عمرو","أبو جهل","النجاشي ملك الحبشة","كسرى"],"answer":2,"why":"أرسل النبي ﷺ للنجاشي فخطبها وأمهرها عن النبي ﷺ وأرسلها للمدينة."},{"type":"mcq","q":"ما الحديث الشهير الذي روته أم حبيبة رضي الله عنها في فضل «السنن الرواتب»؟","options":["«المجالس بالأمانة»","«إنما الأعمال بالنيات»","«أجملوا في الطلب»","«من صلّى اثنتي عشرة ركعةً في يوم وليلة بُني له بهن بيت في الجنة»"],"answer":3,"why":"روت هذا الحديث العظيم في صحيح مسلم وحافظت على تطبيقه طوال حياتها."}],"medium":[{"type":"mcq","q":"ماذا فعلت أم حبيبة حين أراد أبوها أبو سفيان (قبل إسلامه) الجلوس على فراش النبي ﷺ؟","options":["طوت الفراش عنه تعظيمًا لمقام رسول الله ﷺ","تركته يجلس عليه","أهدته الفراش","أخرجته بقسوة"],"answer":0,"why":"أظهرت غيرتها وتعظيمها لمقام النبوة بأدب وحزم."},{"type":"mcq","q":"ما الأثر الاجتماعي والسياسي لزواج النبي ﷺ من أم حبيبة رضي الله عنها؟","options":["زيادة العداوة فقط","تكريمها وجبر خاطرها، وتأليف قلب أبي سفيان وقريش مما مهّد لإسلامهم يوم الفتح","لا أثر له","قطع العلاقة بالحبشة"],"answer":1,"why":"كان للزواج حكمة إنسانية ودعوية وسياسية عظيمة."},{"type":"mcq","q":"عندما تُوفي أبوها أبو سفيان، التزمت أم حبيبة بحداد ٣ أيام فقط ثم تطيّبت في اليوم الرابع؛ ماذا يثبت ذلك؟","options":["نسيانها للأحكام","عدم حزنها على أبيها","تمسّكها الشديد بتطبيق السنة النبوية وتعليمها للناس عمليًا","مخالفتها للشرع"],"answer":2,"why":"قالت: مالي بالطيب من حاجة، ولكني سمعت النبي ﷺ ينهى عن الإحداد فوق ثلاث إلا على زوج."},{"type":"tfr","q":"ثبتت أم حبيبة رضي الله عنها على إسلامها في الحبشة رغم ارتداد زوجها وبقائها غريبةً، فعوّضها الله بالزواج من النبي ﷺ.","answer":true,"reasons":["لم تهاجر للحبشة","رجعت عن الإسلام","وهذا يثبت أن من صبر وثبت على دينه عوضه الله خيرًا منه"],"reason":2},{"type":"tfr","q":"روت أم حبيبة رضي الله عنها حديث فضل السنن الرواتب (١٢ ركعة في اليوم والليلة).","answer":true,"reasons":["والتزمت بأدائها طوال حياتها ولم تتركها أبدًا","لم تروِ أي حديث","السنن الرواتب ٤ ركعات فقط"],"reason":0},{"type":"essay","q":"لخّص قصة ثبات أم حبيبة رضي الله عنها في الحبشة وكيف أكرمها الله بعد صبرها.","model":"هاجرت للحبشة فارتد زوجها ومات وبقيت وحيدة مع طفلتها، لكنها ثبتت على إسلامها، فخطبها النبي ﷺ عبر النجاشي وأصبحت أم المؤمنين."},{"type":"essay","q":"اذكر الحديث الشهير الذي روته أم حبيبة عن السنن الرواتب وبيّن كيف طبّقته.","model":"«من صلّى اثنتي عشرة ركعة في يوم وليلة بُني له بهن بيت في الجنة»، وقالت: فما تركتهن منذ سمعتهن من رسول الله ﷺ."}],"hard":[{"type":"mcq","q":"كم عدد الأحاديث التي روتها أم حبيبة رضي الله عنها تقريبًا؟","options":["ألف حديث","حديث واحد فقط","لم تروِ أي حديث","نحو ٦٥ حديثًا نبويًا"],"answer":3,"why":"كانت من العالمات الراويات للسنة النبوية."},{"type":"mcq","q":"تُوفيت أم المؤمنين رملة بنت أبي سفيان رضي الله عنها في المدينة عام:","options":["٤٤ هـ","١٠ هـ","١٠٠ هـ","٢ هـ"],"answer":0,"why":"تُوفيت رضي الله عنها سنة ٤٤ هـ."},{"type":"mcq","q":"ما الدرس الأبرز من ثبات أم حبيبة في الحبشة للشاب والفتاة عند السفر للدراسة بالخارج؟","options":["الذوبان في عادات تخالف الدين","الاعتزاز بالهوية الإسلامية والثبات على الصلاة والأخلاق حتى في الغربة","ترك الدراسة بالخارج","الانعزال التام"],"answer":1,"why":"الغربة اختبار للثبات على القيم والهوية."},{"type":"mcq","q":"قالت أم حبيبة عند سماع حديث السنن الرواتب «فما تركتهن منذ سمعتهن من رسول الله ﷺ»؛ هذا يدل على:","options":["ترك السنن","حفظ الحديث بلا عمل","المبادرة الفورية للعمل بالعلم والمداومة عليه مدى الحياة","فعله مرة واحدة"],"answer":2,"why":"العلم النافع يقترن فورًا بالتطبيق والمداومة."},{"type":"tfr","q":"طَيّ أم حبيبة لفراش النبي ﷺ عن أبيها قبل إسلامه كان دليلًا على تعظيمها لمقام النبوة وتقديم حب الله ورسوله.","answer":true,"reasons":["كان عقوقًا لوالدها","ولم يمنعها ذلك من احترام والدها وإسلامه لاحقًا","حدث بعد إسلام أبيها"],"reason":1},{"type":"tfr","q":"لم يكن للمرأة المسلمة دور في رواية الحديث النبوي وتعليم السنة في عهد الصحابة.","answer":false,"reasons":["اقتصر على الرجال","نعم لم يروين شيئًا","بل كانت أمهات المؤمنين كعائشة وأم سلمة وأم حبيبة من كبار راويات السنة ومعلمات الأمة"],"reason":2},{"type":"tfr","q":"التزام أم حبيبة بتطبيق حديث الإحداد (٣ أيام فقط على غير الزوج) نموذج عملي لتقديم السنة على العادات.","answer":true,"reasons":["فقد أظهرت الطيب في اليوم الرابع لتعلّم الناس الحكم الشرعي عمليًا","أحدّت سنة كاملة","خالفت السنة"],"reason":0},{"type":"essay","q":"ما الدلالات التربوية من موقفها مع أبيها أبي سفيان حين طوت فراش النبي ﷺ؟","model":"تعظيم مقام النبي ﷺ، وتقديم الولاء لله ورسوله على كل اعتبار، والشجاعة الأدبية في إعلان الحق بأدب وحزم."},{"type":"essay","q":"اذكر ثلاث صفات بارزة من شخصية رملة بنت أبي سفيان تقتدي بها الفتاة والشاب اليوم.","model":"١) الثبات على العقيدة والقيم في الغربة. ٢) الحرص على طلب العلم وتطبيق السنة والمداومة عليها. ٣) الصبر وحسن الظن بالله."},{"type":"essay","q":"بيّن الحكمة الاجتماعية والسياسية من زواج النبي ﷺ بأم حبيبة رضي الله عنها.","model":"جبر خاطرها وتكريمها في غربتها، وتأليف قلب أبي سفيان وقريش وتقليل حدة عدائهم مما مهّد لفتح مكة وإسلامهم."}]}},
  {"id":"g9-islamic-2-u3-6","grade":"g9","subject":"islamic","term":2,"unit":3,"no":6,"title":"الترويح عن النفس (قيم وأخلاق)","summary":"شرح متحرك بـ SVG لدرس الترويح عن النفس (قيم وأخلاق) (الصف التاسع - الفصل الثاني)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.","page":"lesson-recreation-in-islam.html","video":"","pdf":"","notes":["الترويح المباح مشروع لتجديد النشاط («ساعة وساعة») وبنية صالحة يُؤجر عليه.","ضوابطه: لا يُلهي عن الفرائض، يخلو من المحرمات والكذب والقمار، لا يؤذي أحدًا، وبالاعتدال في الوقت والمال."],"exercises":["اذكر أربعة ضوابط شرعية وأخلاقية للترويح المباح عن النفس.","اذكر ثلاث صور للترويح والرياضة وردت في السيرة النبوية الشريفة.","كيف تطبّق ضوابط الترويح الشرعي على استخدامك للألعاب الإلكترونية في الإجازة؟"],"levels":{"easy":[{"type":"mcq","q":"ما دلالة قول النبي ﷺ لحنظلة رضي الله عنه: «يا حنظلة ساعةً وساعةً»؟","options":["ترك الصلاة ساعة","مشروعية التوازن بين الجدّ والعبادة وبين الراحة والترويح المباح مع الأهل","اللعب طوال اليوم","تحريم الترويح"],"answer":1,"why":"الإسلام دين الفطرة والتوازن الذي يراعي حاجة النفس للراحة المباحة."},{"type":"mcq","q":"ما الضابط الأول والأهم لأي نشاط ترويحي أو لعبة إلكترونية؟","options":["أن يكون مكلفًا جدًّا","أن يكون طوال الليل","ألا يُلهي عن الفرائض (كالصلاة) ولا يشتمل على حرام أو أذى","أن يؤذي الآخرين"],"answer":2,"why":"ضوابط الترويح: حفظ الفرائض، خلوه من الحرام والأذى، والاعتدال."},{"type":"mcq","q":"كيف كان مزاح النبي ﷺ وترويحه مع أصحابه؟","options":["لم يمزح أبدًا","كان يكذب ليضحك الناس","كان يسخر من الناس","كان يمزح ولا يقول إلا حقًا وصدقًا دون كذب أو ترويع"],"answer":3,"why":"المزاح الصادق اللطيف دون كذب أو إيذاء من الهدي النبوي."},{"type":"mcq","q":"ما حكم «المقالب الخطيرة» التي تُفزع الآخرين أو تؤذيهم بهدف الإضحاك؟","options":["محرّمة؛ قال ﷺ «لا يحل لمسلم أن يروّع مسلمًا»","مباحة لأنها مزاح","ترويح محمود","مستحبة"],"answer":0,"why":"ترويع الناس وإيذاؤهم ليس ترويحًا بل أذى محرّم."}],"medium":[{"type":"mcq","q":"من أنواع الرياضة البدنية التي شجّع عليها الإسلام للترفيه وبناء القوة:","options":["السهر حتى الفجر","السباحة والرماية وركوب الخيل والسباق","التفحيط بالسيارات","الجلوس بلا حركة"],"answer":1,"why":"الرياضة البدنية تبني الجسم السليم وتجدد النشاط."},{"type":"mcq","q":"إذا جعل طالب «الترفيه والألعاب» يأخذ معظم يومه ويؤثر على دراسته وصلاته، فأي ضابط أخلّ به؟","options":["ضابط السياحة","ضابط الرياضة","ضابط الاعتدال وحفظ الوقت والواجبات","لم يخلّ بشيء"],"answer":2,"why":"الترويح وسيلة لتجديد النشاط وليس غاية تبتلع العمر."},{"type":"mcq","q":"من فوائد الترويح المباح على التحصيل الدراسي للطالب:","options":["زيادة التوتر","إضعاف الذاكرة","نسيان الدروس","تجديد الطاقة الذهنية وإزالة الملل ورفع التركيز عند العودة للمذاكرة"],"answer":3,"why":"الراحة المنظمة ترفع كفاءة العقل والإنتاجية."},{"type":"tfr","q":"يشجّع الإسلام على الترويح المباح والرياضة لتجديد نشاط العقل والجسد.","answer":true,"reasons":["بضوابطه الشرعية كحفظ الفرائض والاعتدال وترك الأذى","الإسلام يحرم اللعب مطلقًا","الترويح يضيع الإيمان"],"reason":0},{"type":"tfr","q":"يجوز الكذب في المزاح والنكات ما دام القصد إضحاك الأصدقاء فقط.","answer":false,"reasons":["نعم الكذب مباح في المزاح","حذّر النبي ﷺ من الكذب لإضحاك الناس، وكان يمزح ولا يقول إلا حقًا","لا حرج فيه"],"reason":1},{"type":"essay","q":"اذكر أربعة ضوابط شرعية وأخلاقية للترويح المباح عن النفس.","model":"١) ألا يُلهي عن الفرائض والواجبات. ٢) خلوّه من المحرمات والقمار والكذب. ٣) عدم إيذاء الآخرين أو ترويعهم. ٤) الاعتدال في الوقت والمال دون إسراف."},{"type":"essay","q":"اذكر ثلاث صور للترويح والرياضة وردت في السيرة النبوية الشريفة.","model":"١) مسابقة النبي ﷺ للسيدة عائشة رضي الله عنها. ٢) تشجيع السباحة والرماية وركوب الخيل. ٣) المزاح الصادق اللطيف وفرح العيد المباح."}],"hard":[{"type":"mcq","q":"ما حكم الألعاب الإلكترونية التي تتضمن «قمارًا ومراهنات مالية»؟","options":["محرّمة شرعًا ولا تدخل في الترويح المباح","مباحة للتسلية","مستحبة","لا بأس بها"],"answer":0,"why":"الميسر والقمار محرم بنص القرآن في الواقع وفي الألعاب."},{"type":"mcq","q":"كيف يتحوّل الترويح المباح (كالرياضة والرحلة العائلية) إلى عمل «يُؤجر عليه المسلم»؟","options":["بترك الصلاة","بإخلاص النية (تقوية البدن لطاعة الله، إدخال السرور على الأسرة، وتجديد الهمة للعلم)","بالإسراف في الطعام","بالمباهاة"],"answer":1,"why":"النية الصالحة تحوّل العادات المباحة إلى عبادات مأجورة."},{"type":"mcq","q":"أي من الآتي يُعد ترويحًا عائليًا مثاليًا في عطلة نهاية الأسبوع بعُمان؟","options":["إزعاج الجيران بالصوت العالي","ترك القمامة في الوادي","رحلة لشاطئ أو وادٍ مع الأسرة مع المحافظة على الصلاة ونظافة المكان","تضييع صلاة العصر"],"answer":2,"why":"يجمع بين المتعة والترابط الأسري والالتزام الشرعي والبيئي."},{"type":"mcq","q":"الفرق بين «الترفيه المتوازن» و«الإدمان الرقمي» هو:","options":["كلاهما حرام","لا فرق بينهما","الإدمان أفضل","المتوازن محدد الوقت ويزيد النشاط والاجتماعية، والإدمان يسيطر على الوقت ويعزل الشخص ويضر صحته ودراسته"],"answer":3,"why":"التحكم في الوقت والمحتوى يصنع الفارق."},{"type":"tfr","q":"ترويع الزملاء بمقالب مخيفة أو خطيرة حرام شرعًا ولا يُعدّ ترويحًا مباحًا.","answer":true,"reasons":["يزيد المحبة","مباح بين الأصدقاء","لقوله ﷺ «لا يحل لمسلم أن يروّع مسلمًا»"],"reason":2},{"type":"tfr","q":"بالنية الصالحة (كتقوية الجسم أو إدخال السرور على الأسرة) يُؤجر المسلم على الترويح المباح.","answer":true,"reasons":["فتنقلب العادة المباحة إلى طاعة مأجورة","لا أجر في أي ترويح","الأجر في المسجد فقط"],"reason":0},{"type":"tfr","q":"الإسراف في ساعات الألعاب الإلكترونية حتى تضييع الصلاة والنوم والدراسة مخالف لضوابط الترويح.","answer":true,"reasons":["لا بأس ما دامت اللعبة مباحة","فالترويح وسيلة متزنة لا يجوز أن تطغى على الواجبات","لا ضابط للوقت"],"reason":1},{"type":"essay","q":"كيف تطبّق ضوابط الترويح الشرعي على استخدامك للألعاب الإلكترونية في الإجازة؟","model":"أختار ألعابًا آمنة خالية من القمار والمحرمات، وأحدد وقتًا قصيرًا بعد أداء الصلاة والواجبات، وأوازن بينها وبين الرياضة والجلوس مع الأسرة."},{"type":"essay","q":"ما أثر الترويح المتوازن على صحة الطالب النفسية وتحصيله الدراسي؟","model":"يزيل الإرهاق والملل، ويقوّي الجسم والروابط الأسرية، ويعيد العقل أكثر نشاطًا وتركيزًا للمذاكرة."},{"type":"essay","q":"فرّق بين «المزاح النبوي المحمود» و«المزاح المذموم».","model":"المحمود: صادق بلا كذب، لطيف بلا سخرية أو ترويع أو أذى. المذموم: فيه كذب أو استهزاء أو مقالب مؤذية أو إسراف يذهب الوقار."}]}},
  {"id":"g9-islamic-2-u4-1","grade":"g9","subject":"islamic","term":2,"unit":4,"no":1,"title":"سورة النور (٣٥–٣٨) — تفسير","summary":"شرح متحرك بـ SVG لدرس سورة النور (٣٥–٣٨) — تفسير (الصف التاسع - الفصل الثاني)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.","page":"lesson-surah-an-nur-35-38.html","video":"","pdf":"","notes":["آية النور (٣٥): مثل بديع لاجتماع نور الفطرة ونور الوحي في قلب المؤمن (نور على نور).","عمارة المساجد حسية (بناء ونظافة) ومعنوية (صلاة وذكر وعلم).","عمّار المساجد يعملون ويتاجرون لكن لا تلهيهم الدنيا عن الصلاة والزكاة، فجزاهم الله أحسن الجزاء وزادهم من فضله."],"exercises":["وضّح باختصار المَثَل القرآني في آية النور (المشكاة، الزجاجة، المصباح، والزيت المبارك).","قارن بين «العمارة الحسية» و«العمارة المعنوية» للمساجد مع مثالين لكل منهما.","كيف تردّ من خلال الآية ٣٧ على من يظن أن التدين يعني ترك التجارة والعمل الدنيوي؟"],"levels":{"easy":[{"type":"mcq","q":"ما معنى «المشكاة» في آية النور (سورة النور: ٣٥)؟","options":["السفينة","الكتاب المفتوح","الكُوّة (الفتحة غير النافذة في الجدار) التي تجمع الضوء وتقوّيه","الشجرة"],"answer":2,"why":"المشكاة هي الكوة في الحائط التي يوضع فيها المصباح."},{"type":"mcq","q":"ما المقصود بـ«الغدوّ والآصال» في قوله ﴿يسبّح له فيها بالغدو والآصال﴾؟","options":["البر والبحر","الشتاء والصيف","الشرق والغرب","أول النهار (الصباح) وآخره (المساء)"],"answer":3,"why":"الغدوّ أول النهار والآصال آخره كناية عن دوام الذكر."},{"type":"mcq","q":"ما نوعا «عمارة المساجد» المستفادان من الآية ٣٦؟","options":["عمارة حسية (البناء والنظافة والصيانة) وعمارة معنوية (الصلاة والذكر والعلم)","البيع والشراء داخلها","العمارة الحسية فقط بلا صلاة","النوم فيها فقط"],"answer":0,"why":"لا تكتمل عمارة المسجد إلا بالبناء والصيانة وبإقامة الصلاة والذكر فيه."},{"type":"mcq","q":"ما دلالة وصف الله لعمّار المساجد بـ﴿لا تلهيهم تجارة ولا بيع عن ذكر الله﴾؟","options":["أنهم لا يعملون ولا يتاجرون أبدًا","أنهم يعملون ويتاجرون بالحلال لكنهم يقدّمون الصلاة والذكر فور دخول وقتهما","أن التجارة حرام","أنهم يغلقون الأسواق للأبد"],"answer":1,"why":"يجمع المؤمن بين السعي في الدنيا وتقديم حق الله عند وقته."}],"medium":[{"type":"mcq","q":"ما المقصود بـ«البيوت» في قوله تعالى ﴿في بيوت أذن الله أن تُرفع ويُذكر فيها اسمه﴾؟","options":["القصور","الأسواق","المساجد","القلاع"],"answer":2,"why":"المساجد هي بيوت الله التي أمر بتعظيمها ورفع شأنها."},{"type":"mcq","q":"ما معنى «نور على نور» في قلب المؤمن؟","options":["البرق والرعد","مصباحان في الشارع","الشمس والقمر فقط","اجتماع نور الفطرة والعقل السليم مع نور القرآن والوحي الإلهي"],"answer":3,"why":"يزداد قلب المؤمن هدايةً وضياءً باجتماع الفطرة والوحي."},{"type":"mcq","q":"ما الدافع الإيماني الذي يجعل عمّار المساجد لا ينشغلون بالتجارة عن الصلاة؟","options":["﴿يخافون يومًا تتقلب فيه القلوب والأبصار﴾ (خشية يوم القيامة)","الخوف من الخسارة المالية","عدم وجود زبائن","حب الراحة فقط"],"answer":0,"why":"استحضار يوم القيامة يضبط أولويات المؤمن."},{"type":"tfr","q":"تجمع الآية ٣٧ بين السعي في التجارة والعمل وبين تقديم الصلاة والذكر عند دخول وقتهما.","answer":true,"reasons":["الإسلام يمنع التجارة","فالإسلام لا يعارض العمل بل يمنع أن يلهي العمل عن طاعة الله","العمل أهم من الصلاة"],"reason":1},{"type":"tfr","q":"تقتصر عمارة المساجد على بنائها وزخرفتها دون الحاجة لإقامة الصلاة والذكر فيها.","answer":false,"reasons":["النظافة غير مهمة","نعم البناء يكفي","العمارة الحقيقية تشمل العمارة الحسية (البناء والنظافة) والعمارة المعنوية (الصلاة والذكر والعلم)"],"reason":2},{"type":"essay","q":"وضّح باختصار المَثَل القرآني في آية النور (المشكاة، الزجاجة، المصباح، والزيت المبارك).","model":"المشكاة (الكوة) والزجاجة الصافية والمصباح الموقد بزيت زيتون نقي تمثل صفاء قلب المؤمن وفطرته التي يجتمع فيها نور القرآن فيصبح «نورًا على نور»."},{"type":"essay","q":"قارن بين «العمارة الحسية» و«العمارة المعنوية» للمساجد مع مثالين لكل منهما.","model":"الحسية: البناء والصيانة والنظافة وتوفير الماء والتكييف. المعنوية: إقامة الصلوات الجماعية، وحلقات تحفيظ القرآن، والدروس العلمية والذكر."}],"hard":[{"type":"mcq","q":"ما الجزاء الذي وعد الله به عمّار المساجد الصادقين في الآية ٣٨؟","options":["يعطيهم أقل من عملهم","يجزيهم أحسن ما عملوا ويزيدهم من فضله ويرزقهم بغير حساب","يقل رزقهم","لا جزاء لهم في الآخرة"],"answer":1,"why":"﴿ليجزيهم الله أحسن ما عملوا ويزيدهم من فضله والله يرزق من يشاء بغير حساب﴾."},{"type":"mcq","q":"في حياة طالب الصف التاسع اليوم، ما الموقف الذي يطبّق الآية ٣٧؟","options":["ترك الدراسة تمامًا","تأخير الصلاة حتى انتهاء اللعبة","ترك الهاتف أو المباراة فور سماع الأذان لأداء الصلاة في وقتها","رفع الصوت في المسجد"],"answer":2,"why":"تقديم الصلاة على الملهيات هو عين تطبيق الآية."},{"type":"mcq","q":"ما المقصود بـ«الكوكب الدُرّي» في الآية ٣٥؟","options":["الشجرة اليابسة","الحجر الأسود","السحاب الداكن","الكوكب المضيء الصافي اللامع كالدرّ (اللؤلؤ)"],"answer":3,"why":"شُبّهت الزجاجة الصافية بلمعان الكوكب الدري."},{"type":"mcq","q":"أي تصرف يخلّ بآداب المسجد وتعظيمه ﴿أذن الله أن تُرفع﴾؟","options":["ترك رنين الهاتف مرتفعًا أو رمي المناديل أو رفع الصوت باللغو","صلاة تحية المسجد","تلاوة القرآن بهدوء","تنظيف المسجد"],"answer":0,"why":"تعظيم المسجد يقتضي نظافته وهدوءه وصيانته."},{"type":"tfr","q":"وصف الله الشجرة المباركة في آية النور بأنها شجرة الزيتون لصفاء زيتها وشدة إضاءته.","answer":true,"reasons":["﴿يوقد من شجرة مباركة زيتونة... يكاد زيتها يضيء ولو لم تمسسه نار﴾","شجرة التفاح","لا توجد شجرة في الآية"],"reason":0},{"type":"tfr","q":"حفظ المسجد نظيفًا وهادئًا وصامت الهاتف من صور تعظيم بيوت الله.","answer":true,"reasons":["لا يؤثر رنين الهاتف","وهو داخل في قوله ﴿في بيوت أذن الله أن ترفع﴾","المسجد للعب"],"reason":1},{"type":"tfr","q":"ترك التجارة لحظة الأذان للصلاة ينقص الرزق ويضيّع البركة.","answer":false,"reasons":["يضيع المال","نعم ينقص الرزق","بل وعد الله عمّار المساجد بالزيادة والرزق بغير حساب في الآية ٣٨"],"reason":2},{"type":"essay","q":"كيف تردّ من خلال الآية ٣٧ على من يظن أن التدين يعني ترك التجارة والعمل الدنيوي؟","model":"الآية مدحت رجالًا يعملون في التجارة والبيع، لكنها أثنت عليهم بأن عملهم لا يلهيهم عن ذكر الله وإقام الصلاة وإيتاء الزكاة؛ فالمؤمن يعمل ويتقن ويقدم حق الله."},{"type":"essay","q":"اذكر أربعة آداب يحرص عليها المسلم عند دخول المسجد.","model":"١) دخول باليمنى ودعاء الدخول وصلاة تحية المسجد. ٢) وضع الهاتف على الصامت. ٣) خفض الصوت وترك اللغو. ٤) المحافظة على نظافة المسجد."},{"type":"essay","q":"ما المعنى الإيماني لقوله تعالى ﴿تتقلّب فيه القلوب والأبصار﴾ في الآية ٣٧؟","model":"يصف شدة هول يوم القيامة فتضطرب القلوب وتزيغ الأبصار من الرهبة، واستحضار ذلك اليوم يحفظ المؤمن من الغفلة."}]}},
  {"id":"g9-islamic-2-u4-2","grade":"g9","subject":"islamic","term":2,"unit":4,"no":2,"title":"المجاهرة بالمعصية (حديث شريف)","summary":"شرح متحرك بـ SVG لدرس المجاهرة بالمعصية (حديث شريف) (الصف التاسع - الفصل الثاني)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.","page":"lesson-publicizing-sins.html","video":"","pdf":"","notes":["الحديث (متفق عليه): «كل أمتي معافى إلا المجاهرين».","المجاهرة تكون بفعل الذنب علنًا أو التحدث به ونشره رقميًا بعد ستر الله.","الاستفتاء والتوبة والعلاج ليست مجاهرة؛ وتوبة المجاهر تشمل الندم وحذف ما نشره."],"exercises":["اذكر صورتَي المجاهرة بالمعصية كما دلّ عليهما الحديث الشريف مع مثال لكل صورة.","اذكر ثلاثة أضرار للمجاهرة بالمعصية على الفرد والمجتمع.","فرّق بين «المجاهرة المذمومة» و«الذكر المشروع للخطأ» (كالاستفتاء والتوبة)."],"levels":{"easy":[{"type":"mcq","q":"ما معنى «المجاهرون» في الحديث الشريف «كل أمتي معافى إلا المجاهرين»؟","options":["الذين يستترون ويتوبون","الذين يجهرون بقراءة القرآن في الصلاة","الذين ينصحون بالخير","الذين يعلنون معاصيهم أمام الناس أو يتحدثون بها تفاخرًا بعد أن سترهم الله"],"answer":3,"why":"المجاهرة هي إظهار المعصية أو التحدث بها وهتك ستر الله."},{"type":"mcq","q":"لماذا تُعدّ المجاهرة بالمعصية أخطر من الوقوع فيها سرًا؟","options":["لأنها استهانة بحق الله، وكفر بنعمة الستر، وإشاعة للمعصية وتشجيع على تقليدها","لأن ذنب السر حلال","لأن الناس لا يرونها","لا فرق بينهما"],"answer":0,"why":"المجاهرة تضيف إلى الذنب ذنب الإشاعة والقدوة السيئة وهتك الستر."},{"type":"mcq","q":"ما أبرز صورة معاصرة للمجاهرة بالمعصية اليوم؟","options":["الاستغفار في الخلوة","تصوير المخالفات والمعاصي ونشرها على وسائل التواصل لجمع المشاهدات","سؤال عالم عن كفارة ذنب","حفظ أسرار الناس"],"answer":1,"why":"النشر الرقمي يحوّل الذنب الخاص إلى مجاهرة يراها الآلاف."},{"type":"mcq","q":"شاب وقع في خطأ سرًا فذهب يسأل عالمًا ثقةً عن كيفية التوبة والكفارة؛ هل يُعدّ هذا مجاهرةً؟","options":["لا يجوز سؤال العلماء","نعم مجاهرة محرّمة","لا، لأن قصده التوبة وتصحيح خطئه وليس التفاخر أو الاستهانة","يأثم على السؤال"],"answer":2,"why":"الاستفتاء بقصد التوبة والعلاج مشروع وليس من المجاهرة."}],"medium":[{"type":"mcq","q":"ماذا يجب على من وقع في ذنب سرًا وستر الله عليه؟","options":["أن يستمر فيه","أن يخبر أصدقاءه في المدرسة","أن يصوّره وينشره","أن يستتر بستر الله، ولا يخبر أحدًا، ويسارع للتوبة الصادقة وردّ الحقوق إن وُجدت"],"answer":3,"why":"حفظ ستر الله والمبادرة بالتوبة هما طريق العفو والمغفرة."},{"type":"mcq","q":"ما الشرط الإضافي المهم في توبة من «جاهر بمعصية ونشرها على الإنترنت»؟","options":["حذف المنشورات والمقاطع المسيئة فورًا حتى لا تستمر كسيئة جارية","تركها على حسابه","نشر مقطع آخر","إغلاق الهاتف يومًا فقط"],"answer":0,"why":"إزالة أثر المنشور السيئ جزء أساسي من صدق التوبة."},{"type":"mcq","q":"ما معنى «معافى» في قوله ﷺ «كل أمتي معافى إلا المجاهرين»؟","options":["سليم من الأمراض البدنية فقط","يُرجى له العفو والمغفرة وستر الله في الدنيا والآخرة","غني بالمال","لا يخطئ أبدًا"],"answer":1,"why":"العفو والمغفرة والستر من الله تعالى."},{"type":"tfr","q":"يُعدّ التباهي بالذنوب القديمة أمام الأصدقاء للإضحاك من صور المجاهرة المذمومة في الحديث.","answer":true,"reasons":["يُعد صراحة محمودة","لا بأس ما دامت قديمة","لأنه يكشف ستر الله عنه ويهوّن الذنب في أعين السامعين"],"reason":2},{"type":"tfr","q":"سؤال العالم أو الأخصائي سرًا بنية التوبة والعلاج يُعدّ مجاهرةً محرّمة.","answer":false,"reasons":["الاستفتاء وطلب العلاج بنية صادقة جائز ومشروع وليس مجاهرة","نعم مجاهرة","يحرم السؤال عن الذنب"],"reason":0},{"type":"essay","q":"اذكر صورتَي المجاهرة بالمعصية كما دلّ عليهما الحديث الشريف مع مثال لكل صورة.","model":"١) فعل المعصية علنًا أمام الناس بلا حياء. ٢) فعلها سرًا ثم التحدث بها أو نشرها تفاخرًا بعد أن ستر الله عليه."},{"type":"essay","q":"اذكر ثلاثة أضرار للمجاهرة بالمعصية على الفرد والمجتمع.","model":"١) هتك ستر الله والاستهانة بحرماته. ٢) إزالة الحياء وتهوين الذنب في أعين الناس. ٣) إشاعة الفساد وتحمّل وزر المقلّدين."}],"hard":[{"type":"mcq","q":"إذا رأيت زلةً من زميلك في المدرسة، ما التصرف الإسلامي الصحيح؟","options":["السخرية منه أمام الصف","تصويره ونشره في المجموعة","ستره ومناصحته سرًا بلطف وعدم تصويره أو التشهير به","تشجيعه على الخطأ"],"answer":2,"why":"«من ستر مسلمًا ستره الله في الدنيا والآخرة»."},{"type":"mcq","q":"قوله ﷺ «وقد بات يستره ربه، ويصبح يكشف ستر الله عنه» يبيّن:","options":["أن الليل للمعاصي","فضل التحدث بالذنوب","أن الستر غير مهم","قبح التحدث بالمعاصي الخفية التي سترها الله على العبد"],"answer":3,"why":"الستر نعمة عظيمة وهتكه بالحديث عنه جحود للنعمة."},{"type":"mcq","q":"أي خُلق عظيم يضعف ويموت في قلب المجاهر بالمعصية؟","options":["خُلق الحياء من الله ومن الناس","خُلق الشجاعة","خُلق الكرم","خُلق التنظيم"],"answer":0,"why":"المجاهرة تقتل الحياء في الفرد والمجتمع."},{"type":"mcq","q":"راوي حديث «كل أمتي معافى إلا المجاهرين» هو الصحابي:","options":["أبو بكرة","أبو هريرة رضي الله عنه","معاوية بن أبي سفيان","القعقاع بن عمرو"],"answer":1,"why":"الحديث متفق عليه عن أبي هريرة رضي الله عنه."},{"type":"tfr","q":"المجاهرة بالمعصية على وسائل التواصل قد تجعل صاحبها يتحمّل وزر من قلّده بسبب نشره.","answer":true,"reasons":["لا يتحمل أي وزر","فهي قدوة سيئة وإشاعة للفساد يجب التوبة منها وحذفها فورًا","المشاهدات تمحو الذنب"],"reason":1},{"type":"tfr","q":"باب التوبة مفتوح حتى للمجاهر إذا ندم بصدق وأقلع وأزال أثر مجاهرته.","answer":true,"reasons":["يُرفض استغفاره","لا توبة للمجاهر أبدًا","لأن رحمة الله واسعة وتقبل التوبة من جميع الذنوب"],"reason":2},{"type":"tfr","q":"ستر عيوب المسلمين ومناصحتهم سرًا يسهم في طهارة المجتمع ونشر المودة.","answer":true,"reasons":["بخلاف التشهير الذي يشيع الفاحشة ويحطّم الحياء","التشهير بالناس أفضل","الستر يشجع الخطأ"],"reason":0},{"type":"essay","q":"فرّق بين «المجاهرة المذمومة» و«الذكر المشروع للخطأ» (كالاستفتاء والتوبة).","model":"المجاهرة إعلان للذنب للتفاخر أو الاستهانة أو التسلية؛ أما ذكره لعالم للاستفتاء أو لطبيب للعلاج أو لقاضٍ لرد الحق فمشروع بنية الإصلاح."},{"type":"essay","q":"كيف تنصح زميلًا اعتاد تصوير مخالفات أو ألفاظ غير لائقة ونشرها على حسابه لجمع الإعجابات؟","model":"أنصحه سرًا بلطف وأذكّره بحديث «كل أمتي معافى إلا المجاهرين»، وبأن النشر يبقى سيئةً جاريةً ويهتك ستر الله، وأشجعه على حذفها وتقديم محتوى نافع."},{"type":"essay","q":"ما العلاقة بين «حفظ ستر الله عليك» و«سترك لعيوب الآخرين»؟","model":"الجزاء من جنس العمل: فمن ستر نفسه بالتوبة وستر إخوانه مع نصحهم سرًا، ستره الله في الدنيا والآخرة."}]}},
  {"id":"g9-islamic-2-u4-3","grade":"g9","subject":"islamic","term":2,"unit":4,"no":3,"title":"دعوة يونس عليه السلام (عقيدة)","summary":"شرح متحرك بـ SVG لدرس دعوة يونس عليه السلام (عقيدة) (الصف التاسع - الفصل الثاني)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.","page":"lesson-call-of-prophet-yunus.html","video":"","pdf":"","notes":["أُرسل يونس عليه السلام (ذو النون) إلى أهل نينوى (> ١٠٠ ألف)، فلما تابوا بصدق كشف الله عنهم العذاب.","في ظلمات ثلاث (الليل، البحر، بطن الحوت) دعا: ﴿لا إله إلا أنت سبحانك إني كنت من الظالمين﴾.","أنقذه الله لتسبيحه في الرخاء والشدة، وأنبت عليه اليقطين، وبشّر الأمة: ﴿وكذلك ننجي المؤمنين﴾."],"exercises":["اذكر الأركان الثلاثة لدعاء يونس عليه السلام وبيّن سرّ عظمته.","استخلص أربعة دروس تربوية وإيمانية من قصة يونس عليه السلام.","ما الحكمة الإلهية في إنبات شجرة «اليقطين» على يونس عليه السلام بعد خروجه من بطن الحوت؟"],"levels":{"easy":[{"type":"mcq","q":"ما الاسم الذي لُقّب به نبي الله يونس عليه السلام في القرآن الكريم؟","options":["ذو النون (صاحب الحوت)","خليل الله","كليم الله","أبو الأنبياء"],"answer":0,"why":"النون هو الحوت، فسُمّي ذا النون وصاحب الحوت."},{"type":"mcq","q":"ما الدعوة العظيمة التي دعا بها يونس عليه السلام في الظلمات؟","options":["﴿رب اشرح لي صدري﴾","﴿لا إله إلا أنت سبحانك إني كنت من الظالمين﴾","﴿رب اجعل هذا بلدًا آمنًا﴾","﴿رب هب لي حكمًا﴾"],"answer":1,"why":"تجمع بين التوحيد والتسبيح والاعتراف بالخطأ."},{"type":"mcq","q":"ما هي «الظلمات الثلاث» التي نادى فيها يونس عليه السلام ربه؟","options":["ظلمة السجن فقط","ظلمة الغابة والصحراء والجبل","ظلمة الليل، وظلمة البحر، وظلمة بطن الحوت","ظلمة الغيوم فقط"],"answer":2,"why":"في أعماق هذه الظلمات الثلاث سمع الله نداءه وأنجاه."},{"type":"mcq","q":"ما السبب الذي ذكره القرآن لنجاة يونس من البقاء في بطن الحوت؟","options":["بسبب السفينة","لأنه كان يجيد السباحة","لأن الحوت كان صغيرًا","أنه كان من المسبّحين لله في الرخاء والشدة ﴿فلولا أنه كان من المسبحين﴾"],"answer":3,"why":"التسبيح والعمل الصالح في الرخاء رصيد عظيم وقت الشدة."}],"medium":[{"type":"mcq","q":"ما الذي ميّز «قوم يونس (أهل نينوى)» عن سائر الأمم المكذّبة السابقة؟","options":["أنهم آمنوا وتابوا بصدق قبل نزول العذاب فرفع الله عنهم العذاب","أنهم هلكوا بالطوفان","أن عددهم كان عشرة فقط","أنهم لم يؤمنوا أبدًا"],"answer":0,"why":"﴿إلا قوم يونس لما آمنوا كشفنا عنهم عذاب الخزي﴾."},{"type":"mcq","q":"ما الشجرة التي أنبتها الله على يونس عليه السلام بعد خروجه من بطن الحوت؟","options":["شجرة الصبّار","شجرة اليقطين (القرع)","شجرة الزيتون","شجرة الرمان"],"answer":1,"why":"﴿وأنبتنا عليه شجرة من يقطين﴾ لتظله وتغذيه وتطرد الحشرات."},{"type":"mcq","q":"ما الخطأ الذي وقع فيه يونس عليه السلام فعاتبه الله عليه؟","options":["عدم دعوته لقومه","تركه للتسبيح","عجلته ومغادرته قريته غاضبًا قبل أن يأذن الله له بذلك","عبادته للأصنام حاشاه"],"answer":2,"why":"خرج مغاضبًا قبل إذن الله، فأدّبه الله وربّاه على الصبر."},{"type":"tfr","q":"دعاء ذي النون ﴿لا إله إلا أنت سبحانك إني كنت من الظالمين﴾ من أعظم أدعية تفريج الكروب.","answer":true,"reasons":["ويجمع بين التوحيد والتسبيح والاعتراف بالتقصير، وقد صحّ فضله في السنة","خاص بالبحر فقط","لا يُدعى به اليوم"],"reason":0},{"type":"tfr","q":"أهلك الله قوم يونس (أهل نينوى) بالعذاب كما أهلك قوم عاد.","answer":false,"reasons":["نعم هلكوا جميعًا","بل تابوا وآمنوا بصدق قبل نزول العذاب فكشف الله عنهم العذاب ومتّعهم إلى حين","أُهلكوا بالريح"],"reason":1},{"type":"essay","q":"اذكر الأركان الثلاثة لدعاء يونس عليه السلام وبيّن سرّ عظمته.","model":"١) التوحيد الخالص (لا إله إلا أنت). ٢) التسبيح والتنزيه (سبحانك). ٣) الاعتراف بالخطأ والتواضع لله (إني كنت من الظالمين)."},{"type":"essay","q":"استخلص أربعة دروس تربوية وإيمانية من قصة يونس عليه السلام.","model":"١) الصبر وعدم العجلة والغضب. ٢) المداومة على التسبيح في الرخاء. ٣) الاعتراف بالخطأ وعدم اليأس في أشد الكروب. ٤) التوبة الصادقة ترفع البلاء."}],"hard":[{"type":"mcq","q":"ما البشارة العامة للمؤمنين في قوله تعالى ﴿وَكَذَٰلِكَ نُنجِي الْمُؤْمِنِينَ﴾؟","options":["خاص بأهل نينوى فقط","أنه خاص بيونس فقط","لا يُنجى أحد غيره","أن نجاة الله وتفريجه للكرب ليس خاصًا بيونس، بل سنة باقية لكل مؤمن يدعو بصدق"],"answer":3,"why":"وعد إلهي متجدد بتفريج كرب كل مؤمن صادق."},{"type":"mcq","q":"كم كان عدد أهل نينوى (قوم يونس عليه السلام) كما ورد في سورة الصافات؟","options":["مئة ألف أو يزيدون","ألف فقط","مئة فقط","مليار"],"answer":0,"why":"﴿وأرسلناه إلى مئة ألف أو يزيدون﴾."},{"type":"mcq","q":"ما الأركان الثلاثة التي اشتمل عليها دعاء ذي النون؟","options":["الشكوى والغضب فقط","التوحيد (لا إله إلا أنت)، والتنزيه والتسبيح (سبحانك)، والاعتراف بالتقصير (إني كنت من الظالمين)","طلب المال فقط","العتاب فقط"],"answer":1,"why":"هذه الأركان الثلاثة هي سر قوة إجابة دعاء ذي النون."},{"type":"mcq","q":"كيف نطبّق قوله تعالى لنبينا ﷺ ﴿فاصبر لحكم ربك ولا تكن كصاحب الحوت﴾ في حياتنا؟","options":["بالغضب السريع","بترك العمل عند أول صعوبة","بضبط النفس عند الغضب والصبر في الدراسة والإصلاح وعدم الاستعجال","باليأس"],"answer":2,"why":"الصبر وضبط النفس مفتاح النجاح وتجنب الندم."},{"type":"tfr","q":"التسبيح والعمل الصالح في أوقات الرخاء ينفع الإنسان ويكون سببًا لنجاته في أوقات الشدة.","answer":true,"reasons":["التسبيح للشدة فقط","لا ينفع إلا دعاء الشدة فقط","لقوله تعالى ﴿فلولا أنه كان من المسبحين للبث في بطنه إلى يوم يبعثون﴾"],"reason":2},{"type":"tfr","q":"تُظهر قصة شجرة اليقطين لطف الله ورحمته بعبده يونس بعد نجاته من بطن الحوت.","answer":true,"reasons":["فقد ظللته بأوراقها العريضة وغذّته وحمته حتى استعاد صحته","كانت شجرة شوكية","لم ينبت الله شيئًا"],"reason":0},{"type":"tfr","q":"قوله تعالى ﴿وكذلك ننجي المؤمنين﴾ يؤكد أن الفرج بعد الشدة سنة إلهية عامة لكل مؤمن صادق.","answer":true,"reasons":["خاص بالأنبياء فقط","وليس خاصًا بنبي الله يونس عليه السلام وحده","لا يتكرر اليوم"],"reason":1},{"type":"essay","q":"ما الحكمة الإلهية في إنبات شجرة «اليقطين» على يونس عليه السلام بعد خروجه من بطن الحوت؟","model":"أوراقها عريضة ناعمة تظله من الشمس، وثمارها طرية مغذية سهلة الأكل، ورائحتها تطرد الذباب والحشرات عن جسده المرهق — رحمةً ولطفًا به."},{"type":"essay","q":"اشرح كيف يطبّق المسلم قاعدة «تعرّف إلى الله في الرخاء يعرفك في الشدة» في ضوء قصة يونس.","model":"بالمحافظة على الصلاة والتسبيح والذكر في أوقات الصحة والنجاح، فتكون رصيدًا نورانيًا يثبّته ويفرّج كربه وقت الأزمات."},{"type":"essay","q":"لماذا نجا أهل نينوى من العذاب بخلاف قوم نوح وعاد؟","model":"لأنهم بادروا بالإيمان والتوبة النصوح الصادقة جميعًا قبل أن يقع عليهم العذاب، فرحمهم الله وكشفه عنهم."}]}},
  {"id":"g9-islamic-2-u4-4","grade":"g9","subject":"islamic","term":2,"unit":4,"no":4,"title":"صلاة الجنازة (فقه)","summary":"شرح متحرك بـ SVG لدرس صلاة الجنازة (فقه) (الصف التاسع - الفصل الثاني)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.","page":"lesson-funeral-prayer.html","video":"","pdf":"","notes":["صلاة الجنازة فرض كفاية، أجرها قيراط للصلاة وقيراطان مع الدفن.","تُؤدّى قيامًا بلا ركوع ولا سجود في ٤ تكبيرات: فاتحة ← إبراهيميّة ← دعاء للميت ← دعاء وتسليم.","يقف الإمام مقابل رأس الرجل ووسط المرأة، وتشترط الطهارة والقبلة."],"exercises":["صف كيفية أداء صلاة الجنازة بالترتيب من التكبيرة الأولى حتى التسليم.","اذكر أربعة شروط لصحة صلاة الجنازة.","ما معنى «فرض كفاية»؟ وما الأجر الذي بشّر به النبي ﷺ لمن شهد الجنازة؟"],"levels":{"easy":[{"type":"mcq","q":"ما حكم صلاة الجنازة في الإسلام؟","options":["سنة مؤكدة فقط","فرض كفاية","فرض عين على كل فرد في العالم","مباحة فقط"],"answer":1,"why":"إذا أداها بعض المسلمين سقط الإثم عن الباقين."},{"type":"mcq","q":"كم عدد التكبيرات في صلاة الجنازة؟ وهل فيها ركوع أو سجود؟","options":["خمس تكبيرات وسجدتان","ركعتان بركوع وسجود","أربع تكبيرات قيامًا بلا ركوع ولا سجود","تكبيرتان فقط"],"answer":2,"why":"صلاة الجنازة ٤ تكبيرات قيامًا دون ركوع أو سجود."},{"type":"mcq","q":"ماذا يُقرأ بعد «التكبيرة الأولى» وبعد «التكبيرة الثانية» في صلاة الجنازة على الترتيب؟","options":["سورة الإخلاص فقط","الدعاء للميت ثم الفاتحة","التسليم ثم الفاتحة","سورة الفاتحة، ثم الصلاة الإبراهيمية"],"answer":3,"why":"١: الفاتحة، ٢: الصلاة الإبراهيمية، ٣: الدعاء للميت، ٤: دعاء وتسليم."},{"type":"mcq","q":"أين يقف الإمام من السنة عند الصلاة على «الرجل» وعند الصلاة على «المرأة»؟","options":["مقابل رأس الرجل، ومقابل وسط المرأة","مقابل قدمي الرجل ورأس المرأة","خلف المصلين","لا فرق أبدًا"],"answer":0,"why":"هذه هي السنة الثابتة عن النبي ﷺ في موضع وقوف الإمام."}],"medium":[{"type":"mcq","q":"ما الأجر العظيم لمن صلّى على الجنازة وتبعها حتى تُدفن كما ورد في الحديث؟","options":["قيراط واحد فقط","قيراطان من الأجر (مثل الجبلين العظيمين)","درهم واحد","لا أجر للدفن"],"answer":1,"why":"الصلاة قيراط، واتباعها حتى الدفن قيراطان."},{"type":"mcq","q":"ماذا يُفعل بعد «التكبيرة الثالثة» في صلاة الجنازة؟","options":["الركوع","قراءة سورة الفاتحة","الدعاء الخالص للميت بالمغفرة والرحمة والجنة","التسليم فورًا"],"answer":2,"why":"التكبيرة الثالثة مخصّصة للدعاء للميت بإخلاص."},{"type":"mcq","q":"هل يُشترط «الوضوء والطهارة واستقبال القبلة» لصحة صلاة الجنازة؟","options":["تصلى بدون طهارة","لا يُشترط الوضوء","لا تُستقبل القبلة","نعم، فهي شروط أساسية لصحتها كسائر الصلوات"],"answer":3,"why":"صلاة الجنازة صلاة شرعية تشترط الطهارة والقبلة وستر العورة."},{"type":"tfr","q":"تؤدّى صلاة الجنازة أربع تكبيرات قيامًا دون ركوع أو سجود.","answer":true,"reasons":["فيها ركوع واحد","مع قراءة الفاتحة والصلاة الإبراهيمية والدعاء للميت ثم التسليم","فيها سجدتان"],"reason":1},{"type":"tfr","q":"لا يُشترط الوضوء لصلاة الجنازة لأنه لا يوجد فيها ركوع ولا سجود.","answer":false,"reasons":["يشترط للمرأة فقط","نعم لا يشترط الوضوء","يُشترط الوضوء والطهارة واستقبال القبلة وستر العورة لصحتها كسائر الصلوات"],"reason":2},{"type":"essay","q":"صف كيفية أداء صلاة الجنازة بالترتيب من التكبيرة الأولى حتى التسليم.","model":"١) التكبيرة الأولى: قراءة الفاتحة. ٢) التكبيرة الثانية: الصلاة الإبراهيمية. ٣) التكبيرة الثالثة: الدعاء للميت بالمغفرة والرحمة. ٤) التكبيرة الرابعة: دعاء عام للمسلمين ثم التسليم."},{"type":"essay","q":"اذكر أربعة شروط لصحة صلاة الجنازة.","model":"١) الطهارة (الوضوء). ٢) استقبال القبلة وستر العورة والنية. ٣) إسلام الميت. ٤) تغسيل الميت وتكفينه قبل الصلاة عليه."}],"hard":[{"type":"mcq","q":"إذا كان الميت «طفلًا صغيرًا»، بمَ يُدعى له بعد التكبيرة الثالثة؟","options":["يُدعى له بأن يجعله الله فرطًا وسلفًا وذخرًا وشفيعًا لوالديه","يُدعى عليه","لا يُصلّى عليه","يُترك الدعاء"],"answer":0,"why":"لأن الطفل بلا ذنوب فيُدعى لوالديه بالأجر والشفاعة."},{"type":"mcq","q":"ما التصرف الصحيح للمسبوق الذي أدرك الإمام في التكبيرة الثالثة لصلاة الجنازة؟","options":["يسلّم مع الإمام دون قضاء","يكبّر معه وتكون أولى له، وبعد تسليم الإمام يتمّ التكبيرتين الباقيتين سريعًا ويسلّم","لا يدخل في الصلاة","يعيد الصلاة بعد يوم"],"answer":1,"why":"يقضي المسبوق ما فاته من التكبيرات قبل رفع الجنازة."},{"type":"mcq","q":"من آداب التعزية ومواساة أهل الميت في السنة والمجتمع العُماني:","options":["تكلّف أهل الميت بولائم ضخمة للضيوف","رفع الصوت والضوضاء","الدعاء للميت وأهله بصبر وأجر، وصنع الطعام لأهل الميت، وتخفيف العبء عنهم","الجدال في المقبرة"],"answer":2,"why":"قال ﷺ «اصنعوا لآل جعفر طعامًا فقد أتاهم ما يشغلهم»."},{"type":"mcq","q":"الحكمة الإيمانية من تشريع صلاة الجنازة وتشييعها هي:","options":["لا حكمة منها","مجرد عادة اجتماعية","التفاخر بكثرة الحضور","أداء حق الأخوّة بالدعاء للميت، ومواساة أهله، وتذكّر الآخرة والاستعداد لها"],"answer":3,"why":"تجمع بين الدعاء للميت، وجبر خاطر أهله، وتذكير الأحياء بالآخرة."},{"type":"tfr","q":"صلاة الجنازة فرض كفاية، وفضلها قيراط للصلاة وقيراطان للصلاة مع الدفن.","answer":true,"reasons":["والقيراط مثل الجبل العظيم من الأجر في الحديث المتفق عليه","فرض عين على الجميع","لا أجر للدفن"],"reason":0},{"type":"tfr","q":"من السنة أن يقف الإمام مقابل رأس الرجل ومقابل وسط المرأة عند صلاة الجنازة.","answer":true,"reasons":["عكس ذلك تمامًا","ويُستحب صفّ المصلين ثلاثة صفوف فأكثر","لا سنة في موضع الوقوف"],"reason":1},{"type":"tfr","q":"إعداد الطعام لأهل الميت ومواساتهم وتخفيف العبء عنهم من هديه ﷺ.","answer":true,"reasons":["لا يُزار أهل الميت","يجب على أهل الميت طبخ ولائم للناس","لقوله ﷺ «اصنعوا لآل جعفر طعامًا فقد أتاهم ما يشغلهم»"],"reason":2},{"type":"essay","q":"ما معنى «فرض كفاية»؟ وما الأجر الذي بشّر به النبي ﷺ لمن شهد الجنازة؟","model":"فرض كفاية: إذا قام به البعض سقط الإثم عن الباقين. الأجر: قيراط (كالجبل العظيم) لمن صلى عليها، وقيراطان لمن صلى وتبعها حتى تُدفن."},{"type":"essay","q":"كيف يصلي «المسبوق» صلاة الجنازة إذا فاتته تكبيرتان مع الإمام؟","model":"يدخل مع الإمام فورًا ويقرأ الفاتحة ثم الصلاة الإبراهيمية، وبعد تسليم الإمام يأتي بالتكبيرتين الباقيتين (الدعاء للميت ثم دعاء قصير) ويسلّم سريعًا قبل رفع الجنازة."},{"type":"essay","q":"اذكر ثلاثة آداب إسلامية عند التعزية وتشييع الجنازة.","model":"١) الخشوع والصمت وتذكّر الآخرة. ٢) الدعاء للميت ومواساة أهله بكلمات طيبة. ٣) صنع الطعام لأهل الميت وتجنب إرهاقهم."}]}},
  {"id":"g9-islamic-2-u4-5","grade":"g9","subject":"islamic","term":2,"unit":4,"no":5,"title":"البيت النبويّ (سيرة)","summary":"شرح متحرك بـ SVG لدرس البيت النبويّ (سيرة) (الصف التاسع - الفصل الثاني)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.","page":"lesson-prophetic-household.html","video":"","pdf":"","notes":["البيت النبوي قدوة الأسرة السعيدة: تواضع ومساعدة («في مهنة أهله»)، ولطف («خيركم خيركم لأهله»).","قام على الرحمة بالأطفال، والشورى والحوار بلا عنف، والإحسان للخدم والضيوف.","تطبيقه يبدأ من بر الوالدين ومساعدة الأسرة والرفق بالإخوة."],"exercises":["اذكر أربع سمات بارزة للبيت النبوي الشريف مع دليل أو موقف لكل سمة.","ماذا تستفيد من شهادة السيدة عائشة رضي الله عنها: «كان يكون في مهنة أهله فإذا حضرت الصلاة خرج إلى الصلاة»؟","كيف نطبّق هدي البيت النبوي في التعامل مع «الإخوة الصغار» و«العاملين في المنزل»؟"],"levels":{"easy":[{"type":"mcq","q":"ما معنى قول السيدة عائشة رضي الله عنها عن النبي ﷺ: «كان يكون في مهنة أهله»؟","options":["كان يعمل بالتجارة داخل البيت فقط","كان يترك بيته دائمًا","كان يساعد أهله ويشاركهم في خدمة وأعمال البيت بتواضع","كان يأمرهم ولا يساعدهم"],"answer":2,"why":"المهنة هي الخدمة، وكان ﷺ يشارك في شؤون بيته حتى يحضر وقت الصلاة."},{"type":"mcq","q":"ما المعيار النبوي لـ«خيرية الإنسان وحسن خلقه» كما في الحديث؟","options":["كبر مساحة البيت","حسن الكلام مع الغرباء وسوء الخلق في البيت","كثرة المال","«خيركم خيركم لأهله، وأنا خيركم لأهلي»"],"answer":3,"why":"المقياس الصادق للخلق هو تعاملك مع أهلك داخل البيت."},{"type":"mcq","q":"كم سنةً خدم أنس بن مالك رضي الله عنه النبي ﷺ، وماذا شهد عن معاملته؟","options":["عشر سنوات، ولم يقل له «أفٍّ» قط ولم يعنّفه أبدًا","سنة واحدة","كان يعاقبه يوميًا","لم يخدمه"],"answer":0,"why":"شهادة تاريخية عظيمة على رحمة النبي ﷺ ولطفه مع الخدم والصغار."},{"type":"mcq","q":"ماذا قال النبي ﷺ للأعرابي الذي استغرب تقبيله للحسن والحسين رضي الله عنهما؟","options":["«تقبيل الأطفال عيب»","«مَن لا يَرحم لا يُرحم»","«القسوة أفضل للتربية»","لم يرد عليه"],"answer":1,"why":"إظهار الحنان والرحمة للأبناء والإخوة الصغار هدي نبوي أصيل."}],"medium":[{"type":"mcq","q":"ما موقف النبي ﷺ من «العنف والضرب» داخل البيت النبوي؟","options":["أجاز القسوة على الخدم","كان يضرب عند الغضب","ما ضرب بيده امرأةً ولا خادمًا قط، بل عالج كل الأمور بالرفق والحوار","لم يهتم بالتربية"],"answer":2,"why":"الرفق واللين والحوار هي منهج البيت النبوي."},{"type":"mcq","q":"كيف نطبّق صفة «كان في مهنة أهله» في حياتنا اليومية كطلاب في عُمان؟","options":["بالانشغال بالهاتف","بترك كل الأعمال على الأم فقط","برفض المساعدة لأنها ليست للرجال","بمساعدة الأم والأب في ترتيب البيت وإحضار الحاجات بابتسامة وطيب نفس"],"answer":3,"why":"المشاركة في أعمال البيت سنة نبوية ورقيّ أخلاقي."},{"type":"mcq","q":"على ماذا يدل أخذ النبي ﷺ بمشورة أم سلمة رضي الله عنها يوم الحديبية في سياق البيت النبوي؟","options":["على الشورى الأسرية وتقدير رأي المرأة وعقلها في البيت النبوي","على ضعف الرأي","على عدم استشارة أحد","أمر نادر بلا دلالة"],"answer":0,"why":"الشورى والاحترام المتبادل ركيزة الأسرة الناجحة."},{"type":"tfr","q":"مشاركة الأبناء والآباء في أعمال المنزل ومساعدة الأم سنة نبوية شريفة («كان في مهنة أهله»).","answer":true,"reasons":["ليست من السنة","أعمال البيت للأم فقط","وليست عيبًا ولا تنتقص من الرجولة بل هي من أرفع الأخلاق"],"reason":2},{"type":"tfr","q":"حسن خلق الإنسان مع أصدقائه خارج البيت يكفي حتى لو كان فظًا سيئ الخلق مع أهله.","answer":false,"reasons":["المعيار النبوي الحقيقي هو «خيركم خيركم لأهله»","نعم يكفي","الأهل لا يحتاجون لطفًا"],"reason":0},{"type":"essay","q":"اذكر أربع سمات بارزة للبيت النبوي الشريف مع دليل أو موقف لكل سمة.","model":"١) التعاون والتواضع («كان في مهنة أهله»). ٢) اللطف والمودة («خيركم خيركم لأهله»). ٣) الرحمة بالأطفال (تقبيل الحسن والحسين). ٤) نبذ العنف وحسن معاملة الخدم (مع أنس بن مالك عشر سنين)."},{"type":"essay","q":"ماذا تستفيد من شهادة السيدة عائشة رضي الله عنها: «كان يكون في مهنة أهله فإذا حضرت الصلاة خرج إلى الصلاة»؟","model":"١) التواضع ومساعدة الأسرة في أعمال البيت. ٢) التوازن الدقيق بين حقوق الأسرة وحقوق الله (المبادرة للصلاة وقت الأذان)."}],"hard":[{"type":"mcq","q":"كيف كانت الجوانب المادية للبيت النبوي مقارنةً بسعادته الروحية؟","options":["كان قصرًا من ذهب","كان بسيطًا متواضعًا من الطين وجريد النخل، لكنه كان أسعد بيت بالمودة والذكر","كان بلا سعادة","كان منعزلًا عن الناس"],"answer":1,"why":"السعادة الحقيقية تصنعها القيم والأخلاق لا المظاهر المادية."},{"type":"mcq","q":"أي تصرف يعارض هدي البيت النبوي داخل الأسرة؟","options":["إكرام الضيف","مساعدة الإخوة في المذاكرة","اللطف مع الأصدقاء خارج البيت والقسوة ورفع الصوت على الوالدين والإخوة داخله","ملاطفة الصغار"],"answer":2,"why":"ازدواجية الخلق تخالف «خيركم خيركم لأهله»."},{"type":"mcq","q":"كيف كان النبي ﷺ يوازن بين خدمة أهله في البيت وبين عبادته؟","options":["لم يشارك في البيت","كان يترك الصلاة لأجل البيت","كان يترك البيت لأجل العبادة فقط","كان في مهنة أهله، فإذا حضرت الصلاة خرج إلى الصلاة فورًا بخشوع"],"answer":3,"why":"توازن رائع يعطي كل ذي حق حقه."},{"type":"mcq","q":"من أبرز ثمرات تطبيق هدي البيت النبوي في أسرنا اليوم:","options":["السكينة والمودة، وتنشئة أبناء واثقين أسوياء، وقلة الخلافات الأسرية","زيادة التوتر","العزلة بين أفراد الأسرة","إهمال الدراسة"],"answer":0,"why":"الاقتداء بالبيت النبوي يصنع أسرةً سعيدةً متماسكةً."},{"type":"tfr","q":"لم يضرب النبي ﷺ بيده امرأةً ولا خادمًا قط، بل كان يربي بالرحمة والحوار والقدوة.","answer":true,"reasons":["كان يستخدم الضرب دائمًا","وهو أعظم نموذج في نبذ العنف الأسري","القسوة أنجح في التربية"],"reason":1},{"type":"tfr","q":"إظهار الحنان والرحمة للإخوة الصغار وتقبيلهم وملاعبتهم من هدي البيت النبوي.","answer":true,"reasons":["يتنافى مع الهيبة","يُفسد تربية الصغار","لقوله ﷺ «من لا يرحم لا يُرحم» وتقبيله للحسن والحسين"],"reason":2},{"type":"tfr","q":"إكرام العاملين في المنزل ومعاملتهم برفق واحترام امتداد لهدي النبي ﷺ مع أنس بن مالك رضي الله عنه.","answer":true,"reasons":["الذي خدمه عشر سنوات ولم يقل له أفٍّ قط","لا يشمل العاملين اليوم","الشدة مع العاملين أفضل"],"reason":0},{"type":"essay","q":"كيف نطبّق هدي البيت النبوي في التعامل مع «الإخوة الصغار» و«العاملين في المنزل»؟","model":"الإخوة الصغار: بالحب واللعب والقدوة والرفق دون سخرية أو ضرب. العاملون في المنزل: بالاحترام واللطف وعدم التكليف فوق الطاقة وشكرهم وأداء حقوقهم."},{"type":"essay","q":"علّل: لماذا كان البيت النبوي أسعد بيت في التاريخ رغم بساطته المادية الشديدة؟","model":"لأن السعادة الأسرية منبعها الإيمان والمودة والرحمة والاحترام والتعاون، وليس فخامة المباني وكثرة الأثاث."},{"type":"essay","q":"اكتب ثلاث مبادرات بسيطة تبدأ بها اليوم لتجعل بيتك أقرب إلى هدي البيت النبوي.","model":"١) مساعدة والدتي في ترتيب المائدة أو البيت يوميًا. ٢) تخصيص وقت للجلوس والحديث مع أسرتي بعيدًا عن الهاتف. ٣) ملاطفة إخوتي الصغار ومساعدتهم في دروسهم."}]}}
);
UNITS.push(
  {"id":"g9-islamic-1-u1","grade":"g9","subject":"islamic","term":1,"title":"الوحدة الأولى","levels":{"easy":[{"type":"mcq","q":"القرآن المكي على التعريف الراجح هو ما نزل:","options":["بعد وفاة النبي ﷺ","بعد الهجرة في مكة","قبل هجرة النبي ﷺ","في المدينة المنورة"],"answer":2,"why":"المعيار الراجح زمني: قبل الهجرة مكي."},{"type":"mcq","q":"معنى «القناطير المقنطرة» في الآية ١٤ هو:","options":["الأراضي الزراعية","الأموال الكثيرة المتراكمة","الجسور الحجرية","السفن البحرية"],"answer":1,"why":"القنطار مقدار كبير من المال، والمقنطرة أي المتراكمة الكثيرة."},{"type":"mcq","q":"راوي حديث «الإجمال في طلب الدنيا» هو الصحابي الجليل:","options":["جابر بن عبد الله رضي الله عنهما","سعد بن معاذ","بلال بن رباح","خالد بن الوليد"],"answer":0,"why":"روى الحديث الصحابي الجليل جابر بن عبد الله."},{"type":"mcq","q":"معنى «الجدّ» في قوله ﷺ: «ولا ينفع ذا الجدّ منك الجدّ» هو:","options":["السفر الطويل","والد الأب","الاجتهاد في الدراسة","الغنى والحظ والسلطان"],"answer":3,"why":"ذا الجدّ هو صاحب الغنى والحظ الدنيوي."}],"medium":[{"type":"mcq","q":"نزلت آية ﴿اليوم أكملت لكم دينكم﴾ في عرفة بمكة في حجة الوداع؛ فتُصنّف:","options":["مكيةً لأنها في مكة","منسوخة","مدنيةً لأنها نزلت بعد الهجرة","ليست مكية ولا مدنية"],"answer":2,"why":"بالمعيار الزمني المعتمد: ما نزل بعد الهجرة مدني وإن نزل بمكة."},{"type":"mcq","q":"لماذا قدّمت الآية ١٧ «الصبر» على سائر صفات المتقين؟","options":["لأنه خاص بالمرض فقط","لأن الصبر أساس الثبات على الطاعات وترك المعاصي والتحمل في كل الأعمال","لأنه آخر صفة","لأنه أسهل صفة"],"answer":1,"why":"بدون الصبر لا يثبت الإنسان على الصدق والقنوت والإنفاق."},{"type":"mcq","q":"ما السبب الذي ذَكَره الحديث ليطمئن الناس فلا يقعوا في الحرام عند تأخر الرزق؟","options":["أن النفس لن تموت حتى تستوفي رزقها المقدّر كاملًا","أن الدنيا بلا أسباب","أن العمل ممنوع","أن المال غير مهم"],"answer":0,"why":"اليقين باستيفاء الرزق يمنع استعجاله بالحرام."},{"type":"tfr","q":"كل سورة فيها سجدة تلاوة فهي سورة مكية.","answer":true,"reasons":["وهذا من الضوابط الأغلبية المشهورة التي استقرأها العلماء في القرآن","لأن السجدات في المدني فقط","لأن السجدات في البقرة"],"reason":0},{"type":"tfr","q":"تحرّم الآية ١٤ من سورة آل عمران امتلاك المال والأراضي والانتفاع بالطيبات الحلال.","answer":false,"reasons":["لأن الزراعة محرمة","لأن المال حرام مطلقًا","بل تبيّن أنها فطرة مباحة في حدود الحلال، وتحذّر من التعلّق بها ونسيان الآخرة"],"reason":2}],"hard":[{"type":"mcq","q":"سورة العنكبوت مكية، ومع ذلك ورد فيها ذكر المنافقين في بدايتها؛ فماذا يدل ذلك؟","options":["أن الضوابط غير مفيدة","أن ضابط ذكر المنافقين ضابط أغلبي له استثناء (وهو أوائل سورة العنكبوت)","أن سورة العنكبوت مدنية بالكامل","أنه لا توجد ضوابط أصلًا"],"answer":1,"why":"ضوابط المكي والمدني أغلبية وقد تستثنى آيات محددة نقلًا عن الصحابة."},{"type":"mcq","q":"كيف يرتبط «الإنفاق في سبيل الله» (والمنفقين) بالآية ١٤ التي ذكرت حب المال؟","options":["الإنفاق دليل عملي على أن حب الله والآخرة في قلب المؤمن أقوى من حب المال","المال لا يُنفق منه","لا علاقة بينهما","الإنفاق يمنع الكسب"],"answer":0,"why":"بذل المال المحبوب للنفس يبرهن صدق الإيمان والتقوى."},{"type":"mcq","q":"لماذا قرن النبي ﷺ «التقوى» بالإجمال في الطلب في قوله «اتقوا الله وأجملوا في الطلب»؟","options":["لأن التقوى للعبادة فقط","للسجع فقط","لأنهما متضادان","لأن التقوى هي الوازع الداخلي الذي يضبط النفس عند إغراء المال الحرام ويدفع للالتزام بالحلال"],"answer":3,"why":"تقوى الله ومراقبته هي الحارس الحقيقي للسلوك المالي."},{"type":"essay","q":"علّل: لماذا اهتمّ علماء الإسلام بتوثيق أماكن وأوقات نزول الآيات القرآنية بهذه الدقة الفائقة؟","model":"لصون القرآن وفهم معانيه في سياقها الصحيح، ومعرفة تدرج التشريع، وتمييز الناسخ والمنسوخ، والوقوف على حكمة الله في تربية الأمة."},{"type":"essay","q":"استنبط ثلاث قيم تربوية من الآيات (١٤–١٧) من سورة آل عمران وكيفية تطبيقها في المجتمع العُماني.","model":"١) الاعتدال وعدم الإسراف في المظاهر. ٢) التكافل والإنفاق على المحتاجين. ٣) الصدق والأمانة والصبر في طلب العلم والعمل."}]},"test":[{"type":"mcq","q":"القرآن المكي على التعريف الراجح هو ما نزل:","options":["بعد وفاة النبي ﷺ","بعد الهجرة في مكة","قبل هجرة النبي ﷺ","في المدينة المنورة"],"answer":2,"why":"المعيار الراجح زمني: قبل الهجرة مكي."},{"type":"mcq","q":"معنى «القناطير المقنطرة» في الآية ١٤ هو:","options":["الأراضي الزراعية","الأموال الكثيرة المتراكمة","الجسور الحجرية","السفن البحرية"],"answer":1,"why":"القنطار مقدار كبير من المال، والمقنطرة أي المتراكمة الكثيرة."},{"type":"mcq","q":"راوي حديث «الإجمال في طلب الدنيا» هو الصحابي الجليل:","options":["جابر بن عبد الله رضي الله عنهما","سعد بن معاذ","بلال بن رباح","خالد بن الوليد"],"answer":0,"why":"روى الحديث الصحابي الجليل جابر بن عبد الله."},{"type":"mcq","q":"معنى «الجدّ» في قوله ﷺ: «ولا ينفع ذا الجدّ منك الجدّ» هو:","options":["السفر الطويل","والد الأب","الاجتهاد في الدراسة","الغنى والحظ والسلطان"],"answer":3,"why":"ذا الجدّ هو صاحب الغنى والحظ الدنيوي."},{"type":"mcq","q":"السنة الهجرية التي وقع فيها صلح الحديبية هي:","options":["السنة الثالثة (٣ هـ)","السنة التاسعة (٩ هـ)","السنة السادسة (٦ هـ)","السنة الأولى (١ هـ)"],"answer":2,"why":"وقع صلح الحديبية عام ٦ هـ."},{"type":"mcq","q":"أعظم مصدر لتحقيق طمأنينة القلب والأمن النفسي في الإسلام هو:","options":["التفاخر بالمظاهر","الإيمان بالله وذكره وحسن التوكل عليه","المقارنة بالآخرين","السهر الطويل"],"answer":1,"why":"قال تعالى: ﴿ألا بذكر الله تطمئن القلوب﴾."},{"type":"mcq","q":"من أبرز علامات السور المكية ورود لفظ:","options":["ذكر المنافقين","أحكام الجهاد","أحكام المواريث التفصيلية","«كلّا»"],"answer":3,"why":"وردت «كلّا» في السور المكية فقط."},{"type":"mcq","q":"معنى «الأسحار» في الآية ١٧ هو:","options":["وقت الغروب","أول المساء","آخر الليل قبيل الفجر","منتصف النهار"],"answer":2,"why":"السحر آخر الليل قبيل الفجر."},{"type":"mcq","q":"معنى «تستوفي رزقها» في الحديث الشريف:","options":["تترك العمل","تأخذ نصيبها المقدّر من الرزق كاملًا","تبيع ممتلكاتها","تسافر بعيدًا"],"answer":1,"why":"الاستيفاء يعني أخذ الشيء كاملًا غير منقوص."},{"type":"mcq","q":"مثال على «عطاء الله الخاص» للمؤمنين:","options":["الهداية للإيمان والتوفيق للطاعة","المطر","شروق الشمس","الهواء والماء"],"answer":0,"why":"الهداية والإيمان عطاء خاص، بينما الهواء والشمس عطاء عام."},{"type":"mcq","q":"الصحابي الذي أرسله النبي ﷺ لمفاوضة قريش وأُشيع مقتله هو:","options":["زيد بن حارثة","أبو بكر الصديق","سعد بن أبي وقاص","عثمان بن عفان رضي الله عنه"],"answer":3,"why":"أُرسل عثمان لمكانته وعشيرته في مكة."},{"type":"mcq","q":"قول النبي ﷺ «عجبًا لأمر المؤمن إن أمره كله خير» يغرس في النفس:","options":["الغضب الدائم","الحسد","الرضا والتفاؤل في السراء والضراء","اليأس والتشاؤم"],"answer":2,"why":"المؤمن بين شكر في السراء وصبر في الضراء وكلاهما خير له."},{"type":"tf","q":"كل سورة فيها سجدة تلاوة فهي سورة مكية.","answer":true,"why":"وهذا من الضوابط الأغلبية المشهورة التي استقرأها العلماء في القرآن"},{"type":"tf","q":"تحرّم الآية ١٤ من سورة آل عمران امتلاك المال والأراضي والانتفاع بالطيبات الحلال.","answer":false,"why":"بل تبيّن أنها فطرة مباحة في حدود الحلال، وتحذّر من التعلّق بها ونسيان الآخرة"},{"type":"tf","q":"يدعو حديث «الإجمال في طلب الدنيا» إلى ترك التجارة والعمل والتفرّغ للجلوس فقط.","answer":false,"why":"بل يأمر بالطلب والسعي المعتدل الحلال مع تقوى الله والقناعة"},{"type":"tf","q":"ينقص ملك الله وخزائنه كلما أعطى عباده من النعم والرزق.","answer":false,"why":"خزائن الله ملأى لا تنقصها النفقة أبدًا، فهو الغني الكريم"},{"type":"tfr","q":"خرج النبي ﷺ وأصحابه في الحديبية عام ٦ هـ بقصد قتال قريش وفتح مكة عسكريًا.","answer":false,"reasons":["نعم خرجوا للحرب","خرجوا للتجارة فقط","بل خرجوا محرمين للعمرة وساقوا الهدي دون سلاح حرب"],"reason":2},{"type":"tfr","q":"تتحقّق السكينة والأمن النفسي بامتلاك المال الكثير وحده حتى مع البعد عن الله.","answer":false,"reasons":["الفقراء لا يملكون أمنًا نفسيًا","المال وسيلة لا تصنع الطمأنينة وحدها؛ فالأمن النفسي الحقيقي يبدأ بالإيمان وذكر الله والرضا","نعم المال يكفي وحده"],"reason":1},{"type":"tfr","q":"لا فائدة عملية من معرفة المكي والمدني سوى معرفة أسماء السور.","answer":false,"reasons":["يستخدم للعدّ فقط","بل له فوائد عظيمة كمعرفة الناسخ والمنسوخ وفهم تدرّج التشريع وتفسير الآيات بسياقها","ليس له أي فائدة"],"reason":1},{"type":"tfr","q":"ختم صفات المتقين بالاستغفار بالأسحار يدل على تواضع المؤمن وعدم اغتراره بطاعته.","answer":true,"reasons":["فبعد الصبر والصدق والإنفاق يستغفر الله لقصوره وافتقاره لرحمته","لأنهم لم يعملوا أي خير","لأن الاستغفار في النهار ممنوع"],"reason":0},{"type":"essay","q":"قارن بين المكي والمدني من حيث: الموضوع الرئيس، طول الآيات، ومثالين لكل منهما.","model":"المكي: التوحيد والعقيدة واليوم الآخر، آيات قصيرة قوية (مثل الإخلاص والمدثر). المدني: التشريعات والمعاملات وبناء المجتمع، آيات طويلة مفصّلة (مثل البقرة والمائدة)."},{"type":"essay","q":"قارن بين متاع الدنيا ونعيم الآخرة كما ورد في الآيتين ١٤ و١٥ من سورة آل عمران.","model":"متاع الدنيا زائل ناقص يزول بالموت أو تغير الأحوال، أما نعيم الآخرة فدائم خالد فيه جنات وأنهار وأزواج مطهرة وأعظمه رضوان الله تعالى."},{"type":"essay","q":"اذكر أربعة آثار إيجابية لتطبيق «الإجمال في الطلب» في السوق والمجتمع.","model":"١) اختفاء الغش والاحتكار والرشوة. ٢) شيوع الأمانة والثقة في المعاملات. ٣) التكافل والبركة في الأموال. ٤) قلة النزاعات والحسد بين الناس."},{"type":"essay","q":"قارن بين «العطاء العام» و«العطاء الخاص» لله تعالى مع مثالين لكل منهما.","model":"العطاء العام: يشمل جميع المخلوقات مؤمنها وكافرها مثل الحياة والرزق والصحة والشمس. العطاء الخاص: يختص به الله عباده المؤمنين مثل الهداية، الإيمان، العلم النافع، والجنة."},{"type":"essay","q":"اذكر ثلاث نتائج عظيمة لصلح الحديبية أثبتت بُعد نظر النبي ﷺ.","model":"١) اعتراف قريش بالدولة الإسلامية. ٢) انتشار الإسلام بسرعة هائلة في جو السلم والأمن. ٣) التفرغ لمراسلة الملوك ومنهم ملكا عُمان، ثم التمهيد لفتح مكة بعد نقض قريش للصلح."}]},
  {"id":"g9-islamic-1-u2","grade":"g9","subject":"islamic","term":1,"title":"الوحدة الثانية","levels":{"easy":[{"type":"mcq","q":"التقاء الساكنين في كلمة ﴿الْحَاقَّةُ﴾ يكون:","options":["في كلمة واحدة وصلاً ووقفًا","عند الوقف فقط","في كلمتين","لا يوجد التقاء ساكنين"],"answer":0,"why":"الألف المدية الساكنة تلتقي بالقاف الأولى الساكنة من المشدّد."},{"type":"mcq","q":"معنى «عَلَىٰ مُكْثٍ» في الآية ١٠٦ هو:","options":["بصوت خافت جدًّا","في السفر","بسرعة فائقة","على مهل وتؤدة وتأنٍّ"],"answer":3,"why":"المكث هو التمهّل والتؤدة ليتدبّره الناس."},{"type":"mcq","q":"معنى «الشُّعبة» في حديث شعب الإيمان هو:","options":["القرية الصغيرة","الطريق الطويل","الفرع والجزء من الشيء","العملة"],"answer":2,"why":"شُعب الإيمان أي فروعه وأجزاؤه كفروع الشجرة."},{"type":"mcq","q":"يُعد نبي الله نوح عليه السلام:","options":["آخر الأنبياء","أول الرسل إلى أهل الأرض ومن أولي العزم","ملكًا في مصر","من أنبياء بني إسرائيل"],"answer":1,"why":"نوح عليه السلام أول رسول أُرسل بعد ظهور الشرك في الأرض."}],"medium":[{"type":"mcq","q":"ماذا يحدث لالتقاء الساكنين في قوله ﴿وَالْعَصْرِ إِنَّ الْإِنسَانَ﴾ عند «وصل» الآيتين؟","options":["يزول التقاء الساكنين لأن الراء تصبح مكسورةً متحركةً","تُحذف الراء","يبقى الساكنان كما هما","يُمدّ ٦ حركات"],"answer":0,"why":"في الوصل تتحرّك الراء بالكسرة فلا يلتقي ساكنان."},{"type":"mcq","q":"ما أثر سماع القرآن الكريم على قلوب «العلماء الصادقين» كما وصفت الآيات؟","options":["التكبر على الناس","الجدال والعناد","الغفلة والإعراض","السجود والبكاء وزيادة الخشوع لله تعالى"],"answer":3,"why":"العلم الحقيقي يقود للخشوع والتواضع أمام كلام الله."},{"type":"mcq","q":"ما دلالة ربط «إماطة الأذى عن الطريق» بالإيمان في الإسلام؟","options":["أن الإيمان يقتصر على المسجد فقط","أن النظافة غير مهمة","أن الحفاظ على النظافة وسلامة الآخرين عبادة وجزء من الدين وليس مجرد سلوك عادي","أن التوحيد غير ضروري"],"answer":2,"why":"الإسلام يربط السلوك الحضاري والمجتمعي بالإيمان مباشرة."},{"type":"tfr","q":"يُغتفر التقاء الساكنين في كلمة واحدة عند الوقف على ﴿الْقَدْرْ﴾ مع مراعاة قلقلة الدال.","answer":true,"reasons":["نُبقي الدال ساكنة مقلقلة ونقف على الراء بالسكون دون تحريك الدال","يُحذف حرف الراء","يجب فتح الدال"],"reason":0},{"type":"tfr","q":"نزل القرآن الكريم كاملًا في ليلة واحدة على النبي ﷺ مكتوبًا في صحف.","answer":false,"reasons":["نزل في سنة واحدة","نعم نزل دفعة واحدة في يوم","نزل مفرّقًا (منجّمًا) على النبي ﷺ خلال ٢٣ سنة لحكم عظيمة كالتثبيت وتيسير الحفظ"],"reason":2}],"hard":[{"type":"mcq","q":"في سورة الفاتحة: ﴿الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ﴾، أي كلمة يحصل فيها التقاء ساكنين «عند الوقف فقط»؟","options":["رَبِّ","الْحَمْدُ","لِلَّهِ","الْعَالَمِينْ"],"answer":3,"why":"الياء المدية الساكنة تلتقي بالنون الساكنة للوقف."},{"type":"mcq","q":"لماذا قدّمت الآية ١٠٧ عبارة ﴿إن الذين أوتوا العلم من قبله﴾ عند الحديث عن الإيمان بالقرآن؟","options":["لأن العلم يمنع الإيمان","لأنه خاص بالعلماء فقط","لأن أهل العلم المنصفين من أهل الكتاب عرفوا صفة النبي ﷺ والقرآن في كتبهم فآمنوا وخشعوا","لأن الجاهل لا يؤمن أبدًا"],"answer":2,"why":"العلماء المنصفون كانوا أسرع الناس لتمييز الحق والخشوع له."},{"type":"mcq","q":"لو أزال طالب زجاجًا مكسورًا من ملعب المدرسة بنية حماية زملائه وطاعة الله، فإنه ينال:","options":["إثمًا","أجر شعبة من شعب الإيمان بالإضافة لحماية زملائه","لا أجر له","تعبًا بلا فائدة"],"answer":1,"why":"النية الصالحة تحوّل إماطة الأذى إلى عبادة يؤجر عليها."},{"type":"essay","q":"استخرج من سورة العصر مثالين لالتقاء الساكنين في كلمة واحدة عند الوقف، وحدّد نوع الساكن الأول في كل منهما.","model":"١) ﴿وَالْعَصْرْ﴾: الساكن الأول حرف صحيح (الصاد). ٢) ﴿خُسْرْ﴾ (أو ﴿بِالصَّبْرْ﴾): الساكن الأول حرف صحيح ساكن (السين / الباء)."},{"type":"essay","q":"بيّن كيف نردّ بأسلوب علمي هادئ على من يظن أن تعدد أسماء الله الحسنى يعني تعدد الآلهة.","model":"نستشهد بالآية ١١٠ ﴿قل ادعوا الله أو ادعوا الرحمن أيًا ما تدعوا فله الأسماء الحسنى﴾؛ فالذات الإلهية واحدة، وتعدد الأسماء إنما هو تعدد لصفات الكمال لإله واحد لا شريك له."}]},"test":[{"type":"mcq","q":"التقاء الساكنين في كلمة ﴿الْحَاقَّةُ﴾ يكون:","options":["في كلمة واحدة وصلاً ووقفًا","عند الوقف فقط","في كلمتين","لا يوجد التقاء ساكنين"],"answer":0,"why":"الألف المدية الساكنة تلتقي بالقاف الأولى الساكنة من المشدّد."},{"type":"mcq","q":"معنى «عَلَىٰ مُكْثٍ» في الآية ١٠٦ هو:","options":["بصوت خافت جدًّا","في السفر","بسرعة فائقة","على مهل وتؤدة وتأنٍّ"],"answer":3,"why":"المكث هو التمهّل والتؤدة ليتدبّره الناس."},{"type":"mcq","q":"معنى «الشُّعبة» في حديث شعب الإيمان هو:","options":["القرية الصغيرة","الطريق الطويل","الفرع والجزء من الشيء","العملة"],"answer":2,"why":"شُعب الإيمان أي فروعه وأجزاؤه كفروع الشجرة."},{"type":"mcq","q":"يُعد نبي الله نوح عليه السلام:","options":["آخر الأنبياء","أول الرسل إلى أهل الأرض ومن أولي العزم","ملكًا في مصر","من أنبياء بني إسرائيل"],"answer":1,"why":"نوح عليه السلام أول رسول أُرسل بعد ظهور الشرك في الأرض."},{"type":"mcq","q":"أول مصادر التشريع الإسلامي هو:","options":["القرآن الكريم","الإجماع","السنة النبوية","القياس"],"answer":0,"why":"القرآن الكريم هو المصدر الأول والأعلى."},{"type":"mcq","q":"يُقصد بـ«السَّمْت» في الأخلاق الإسلامية:","options":["الغضب السريع","الانعزال","المباهاة والإسراف","الوقار وحسن الهيئة والأدب الرفيع"],"answer":3,"why":"السَّمت هو الهدي الصالح والوقار والأدب."},{"type":"mcq","q":"الحرف المشدّد (مثل لّ في الضَّالِّينَ) يتكوّن في الحقيقة من:","options":["ثلاثة حروف","حرفين: الأول ساكن والثاني متحرك","حرف واحد مفتوح","حرفين متحركين"],"answer":1,"why":"كل حرف مشدّد أصله حرفان: ساكن ثم متحرك."},{"type":"mcq","q":"معنى «وَلِيٌّ مِّنَ الذُّلِّ» في الآية ١١١ هو:","options":["نصير أو حليف يحتاج إليه الله لدفع ضعف (والله منزه عن ذلك)","صديق صالح","حاكم عادل","عالم جليل"],"answer":0,"why":"الله عزيز غني لا يحتاج نصيرًا يعينه على ضعف."},{"type":"mcq","q":"أدنى (أيسر) شُعب الإيمان المذكورة في الحديث هي:","options":["الصيام","الحج","الزكاة","إماطة الأذى عن الطريق"],"answer":3,"why":"إماطة الأذى سهلة ومتاحة لكل مسلم يوميًا."},{"type":"mcq","q":"المدة التي قضاها نوح عليه السلام في دعوة قومه هي:","options":["١٠٠٠ سنة كاملة","٥٠٠ سنة","٩٥٠ سنة","٥٠ سنة"],"answer":2,"why":"ألف سنة إلا خمسين عامًا = ٩٥٠ سنة."},{"type":"mcq","q":"المصدر الثاني للتشريع الإسلامي هو:","options":["القياس","السنة النبوية الشريفة","العرف","الآراء الشخصية"],"answer":1,"why":"تأتي السنة النبوية في المرتبة الثانية مباشرةً بعد القرآن."},{"type":"mcq","q":"الحديث الشريف «لو أن أهل عُمان أتيتَ ما سبّوك ولا ضربوك» رواه الإمام:","options":["مسلم","سيبويه","ابن خلدون","المتنبي"],"answer":0,"why":"الحديث ثابت في صحيح مسلم."},{"type":"tf","q":"يُغتفر التقاء الساكنين في كلمة واحدة عند الوقف على ﴿الْقَدْرْ﴾ مع مراعاة قلقلة الدال.","answer":true,"why":"نُبقي الدال ساكنة مقلقلة ونقف على الراء بالسكون دون تحريك الدال"},{"type":"tf","q":"نزل القرآن الكريم كاملًا في ليلة واحدة على النبي ﷺ مكتوبًا في صحف.","answer":false,"why":"نزل مفرّقًا (منجّمًا) على النبي ﷺ خلال ٢٣ سنة لحكم عظيمة كالتثبيت وتيسير الحفظ"},{"type":"tf","q":"لا يضرّ الإيمان تركُ الأعمال الصالحة والأخلاق ما دام الإنسان يقول «لا إله إلا الله» بلسانه فقط.","answer":false,"why":"الإيمان قول وعمل واعتقاد، وترك الشعب ينقص الإيمان ويضعفه"},{"type":"tf","q":"الغلو في تعظيم الصالحين كان السبب الأول في وقوع الشرك في الأرض في قوم نوح.","answer":true,"why":"فقد صنعوا تماثيل لهم ثم عُبدت من دون الله بعد أجيال"},{"type":"tfr","q":"يمكن للمسلم معرفة عدد ركعات الظهر والمغرب والعشاء من القرآن الكريم وحده دون السنة.","answer":false,"reasons":["نعم ذُكرت الركعات بالتفصيل في الفاتحة","لا يوجد عدد محدد للركعات","جاء الأمر بالصلاة في القرآن مجملًا، وبيّنت السنة عدد الركعات والأوقات والهيئة"],"reason":2},{"type":"tfr","q":"التسامح ولين الجانب في السمت العُماني دليل ضعف وتنازل عن الكرامة.","answer":false,"reasons":["نعم دليل ضعف","بل هو دليل قوة أخلاقية وثقة بالنفس وتحضر مستمد من هدي النبي ﷺ","القوة في الفظاظة فقط"],"reason":1},{"type":"tfr","q":"يجوز قصر المد في ﴿وَلَا الضَّالِّينَ﴾ إلى حركتين فقط.","answer":false,"reasons":["لا مدّ فيه أصلًا","بل هو مد لازم كلمي مثقّل يجب مدّه ٦ حركات لزومًا وصلاً ووقفًا","يجوز حركتان فقط"],"reason":1},{"type":"tfr","q":"يُستحب للمسلم أن يدعو الله بالاسم المناسب لحاجته من أسماء الله الحسنى.","answer":true,"reasons":["مثل يا غفور اغفر لي ويا شافي اشفني، عملًا بقوله ﴿فله الأسماء الحسنى﴾","لا يُدعى بالرحمن","يجوز اسم واحد فقط"],"reason":0},{"type":"essay","q":"اذكر الحالات الثلاث التي يجتمع فيها ساكنان في «كلمة واحدة» مع مثال قرآني لكل حالة.","model":"١) مد لازم وصلاً ووقفًا: ﴿الضَّالِّينَ﴾. ٢) مد عارض أو لين وقفًا فقط: ﴿نَسْتَعِينْ﴾، ﴿خَوْفْ﴾. ٣) ساكنان صحيحان وقفًا فقط: ﴿وَالْعَصْرْ﴾."},{"type":"essay","q":"اذكر ثلاث حِكَم من نزول القرآن الكريم مفرّقًا على مهل.","model":"١) تثبيت قلب النبي ﷺ والمؤمنين. ٢) تيسير الحفظ والفهم والتدبّر. ٣) التدرّج في التشريع ومواكبة الأحداث والإجابة عن الأسئلة."},{"type":"essay","q":"اذكر ثلاث صور حديثة لـ«إماطة الأذى» في المدرسة والشارع والإنترنت.","model":"١) في المدرسة: إزالة الأوراق أو الأشياء التي قد يتعثر بها الطلاب. ٢) في الشارع: عدم إلقاء القمامة وترك المواقف والطرق سالكة. ٣) على الإنترنت: منع نشر الشائعات والأذى اللفظي."},{"type":"essay","q":"استخلص أربعة دروس من دعوة نوح عليه السلام تنفعك في حياتك اليومية.","model":"١) الصبر وعدم اليأس عند بطء النتائج. ٢) تنويع أساليب الإقناع والنصح بالرفق سرًا. ٣) الأخذ بالأسباب مع التوكل على الله (بناء السفينة). ٤) عدم الالتفات لسخرية المبطلين."},{"type":"essay","q":"قارن بين «القرآن الكريم» و«السنة النبوية» من حيث اللفظ والمعنى والتعبّد بالتلاوة.","model":"القرآن لفظه ومعناه من الله تعالى ويُتعبّد بتلاوته في الصلاة؛ أما السنة فمعناها وحي من الله ولفظها من النبي ﷺ ولا يُتعبّد بتلاوة ألفاظها في الصلاة لكن يُعمل بأحكامها."}]},
  {"id":"g9-islamic-1-u3","grade":"g9","subject":"islamic","term":1,"title":"الوحدة الثالثة","levels":{"easy":[{"type":"mcq","q":"التخلّص من التقاء الساكنين في ﴿إِذَا الشَّمْسُ﴾ عند الوصل يكون بـ:","options":["كسر الألف","ضم الألف","حذف الألف المدية لفظًا لا خطًا","مدها ٦ حركات"],"answer":2,"why":"الألف حرف مد فيُحذف لفظًا عند الوصل."},{"type":"mcq","q":"المقصود بـ«السَّبع المثاني» في سورة الحجر هو:","options":["سورة الإخلاص","سورة الفاتحة","سورة الناس","سورة الكوثر"],"answer":1,"why":"الفاتحة سبع آيات تُثنّى في كل صلاة."},{"type":"mcq","q":"راوي حديث «أكبر الكبائر» هو الصحابي:","options":["أبو بكرة نفيع بن الحارث رضي الله عنه","أنس بن مالك","أبو هريرة","ابن عباس"],"answer":0,"why":"روى الحديث أبو بكرة رضي الله عنه في الصحيحين."},{"type":"mcq","q":"اتفاق جميع المجتهدين من الأمة بعد وفاة النبي ﷺ على حكم شرعي يُسمّى:","options":["الاجتهاد الفردي","القياس","الاستحسان","الإجماع"],"answer":3,"why":"هذا هو التعريف الدقيق للإجماع."}],"medium":[{"type":"mcq","q":"كيف نتخلص من التقاء الساكنين في قوله ﴿اشْتَرَوُا الضَّلَالَةَ﴾؟","options":["بحذف الواو لفظًا","بمدها ٦ حركات","بتحريك واو اللين بالضم","بكسر الواو"],"answer":2,"why":"واو اللين للجمع (قبلها فتح) تُحرّك بالضم ولا تُحذف."},{"type":"mcq","q":"لماذا قرن الله النهي عن مدّ العين لزينة الدنيا ببيان نعمة «السبع المثاني والقرآن العظيم»؟","options":["لا علاقة بين الآيتين","لأن من أُعطي القرآن فقد أُعطي أعظم كنز يُغنيه عن التعلق بمتاع الدنيا الزائل","لأن الفقير لا يقرأ القرآن","لأن الدنيا أهم من القرآن"],"answer":1,"why":"القرآن أعظم نعمة تملأ القلب غنىً وقناعةً."},{"type":"mcq","q":"قول الصحابة «حتى قلنا ليته سكت» يدل على:","options":["شدة شفقتهم ومحبتهم للنبي ﷺ لما رأوه من تأثره وغضبه لله","رغبتهم في الانصراف","عدم اهتمامهم","ضيقهم من سماع العلم"],"answer":0,"why":"أشفقوا عليه ﷺ من شدة انفعاله واهتمامه بتحذير الأمة."},{"type":"tfr","q":"يُحذف حرف المد في ﴿فِي السَّمَاءِ﴾ خطًا من المصحف ولفظًا في القراءة.","answer":false,"reasons":["يُحذف «لفظًا فقط» عند الوصل، ويبقى مكتوبًا في رسم المصحف","يُحذف من المصحف","لا يُحذف لفظًا"],"reason":0},{"type":"tfr","q":"سُمّيت سورة الفاتحة بـ«المثاني» لأنها تُثنّى وتُكرّر قراءتها في كل ركعة من الصلاة.","answer":true,"reasons":["لأنها آيتان فقط","لأنها تُقرأ مرتين في السنة فقط","وهي سبع آيات مباركات لا تصح الصلاة إلا بها"],"reason":2}],"hard":[{"type":"mcq","q":"في قوله تعالى ﴿عَنِ النَّبَإِ﴾ و﴿مِنَ النَّاسِ﴾، ما حركة النون في الكلمتين على الترتيب؟","options":["الكسر في كليهما","الكسر في «عَنِ»، والفتح في «مِنَ»","الفتح في كليهما","الضم في كليهما"],"answer":1,"why":"«عنْ» تُكسر على الأصل، أما «مِنْ» فتُفتح للتخفيف وكثرة دورانها."},{"type":"mcq","q":"قوله تعالى ﴿إنا كفيناك المستهزئين﴾ يبثّ في نفس الداعي والمصلح:","options":["الثقة بنصر الله وحمايته وعدم الانشغال بالردود العقيمة على الساخرين","التوقف عن قول الحق","الانشغال بالانتقام","الخوف من الناس"],"answer":0,"why":"وعد الله بالكفاية يفرّغ قلب المؤمن للعمل البنّاء."},{"type":"mcq","q":"لماذا قد يقع بعض الناس في شهادة الزور أكثر من وقوعهم في الشرك الصريح؟","options":["لأن الزور حلال","لأن الزور لا يضر أحدًا","لأن الشرك أسهل","لأن الشرك تنفر منه فطرة المسلم، بينما قد تغلب العاطفة أو القرابة أو الطمع فيُتساهل في الكذب والزور"],"answer":3,"why":"وهذا هو سرّ تأكيد النبي ﷺ الشديد وتكراره للتحذير من الزور."},{"type":"essay","q":"قارن بين التقاء الساكنين في «كلمة واحدة» (الدرس السابق) والتقاء الساكنين في «كلمتين» (هذا الدرس) من حيث الحكم.","model":"في كلمة واحدة: جائز ومُغتفر (في المد اللازم ٦ حركات، وعند الوقف في العارض واللين والساكن الصحيح). في كلمتين: لا يُغتفر عند الوصل ونتخلّص منه بحذف حرف المد لفظًا أو تحريك الساكن الصحيح."},{"type":"essay","q":"اشرح كيف توازن بين «الصدع بالحق» و«خفض الجناح» في تعاملك مع زملائك.","model":"أكون واضحًا وثابتًا في مبادئي وأقول الحق بأدب دون مجاملة على باطل، وفي الوقت نفسه أتعامل مع زملائي بتواضع ولطف ورحمة بلا تعالٍ."}]},"test":[{"type":"mcq","q":"التخلّص من التقاء الساكنين في ﴿إِذَا الشَّمْسُ﴾ عند الوصل يكون بـ:","options":["كسر الألف","ضم الألف","حذف الألف المدية لفظًا لا خطًا","مدها ٦ حركات"],"answer":2,"why":"الألف حرف مد فيُحذف لفظًا عند الوصل."},{"type":"mcq","q":"المقصود بـ«السَّبع المثاني» في سورة الحجر هو:","options":["سورة الإخلاص","سورة الفاتحة","سورة الناس","سورة الكوثر"],"answer":1,"why":"الفاتحة سبع آيات تُثنّى في كل صلاة."},{"type":"mcq","q":"راوي حديث «أكبر الكبائر» هو الصحابي:","options":["أبو بكرة نفيع بن الحارث رضي الله عنه","أنس بن مالك","أبو هريرة","ابن عباس"],"answer":0,"why":"روى الحديث أبو بكرة رضي الله عنه في الصحيحين."},{"type":"mcq","q":"اتفاق جميع المجتهدين من الأمة بعد وفاة النبي ﷺ على حكم شرعي يُسمّى:","options":["الاجتهاد الفردي","القياس","الاستحسان","الإجماع"],"answer":3,"why":"هذا هو التعريف الدقيق للإجماع."},{"type":"mcq","q":"من أبرز صفات المجلس النبوي الشريف:","options":["التمييز بين الجلساء","الغيبة والسخرية","الحلم والحياء والأمانة وعدم رفع الأصوات","الصخب والجدال"],"answer":2,"why":"وُصف المجلس النبوي بأنه مجلس حلم وحياء وصبر وأمانة."},{"type":"mcq","q":"معنى «السماحة» في الإسلام هو:","options":["الغش في البيع","السهولة واليسر وكرم النفس في المعاملة","التفريط في الدين","التشدد والعناد"],"answer":1,"why":"السماحة تعني اللين والتيسير وكرم النفس."},{"type":"mcq","q":"في قوله تعالى ﴿مِنَ الْجِنَّةِ﴾ حُرّكت نون «مِنْ» بـ:","options":["الضم","السكون","الكسر","الفتح"],"answer":3,"why":"نون «مِنْ» الجارة تُحرّك بالفتح دائمًا عند التقاء الساكنين."},{"type":"mcq","q":"معنى «فَاصْدَعْ بِمَا تُؤْمَرُ» هو:","options":["سافر ليلًا","اسكت عن الحق","اجهر بالحق وأعلنه بوضوح","أخفِ الدعوة"],"answer":2,"why":"الصدع هو الإعلان الصريح الواضح للحق."},{"type":"mcq","q":"أكبر الذنوب وأعظم الظلم على الإطلاق هو:","options":["قلة المال","الإشراك بالله","التأخر عن الموعد","النسيان"],"answer":1,"why":"قال تعالى: ﴿إن الشرك لظلم عظيم﴾."},{"type":"mcq","q":"إلحاق مسألة جديدة بمسألة منصوص عليها في الحكم لاشتراكهما في العلة يُسمّى:","options":["القياس","التجويد","الإجماع","التواتر"],"answer":0,"why":"القياس ينقل حكم الأصل للفرع بسبب العلة المشتركة."},{"type":"mcq","q":"معنى «المراء» الذي كان المجلس النبوي خاليًا منه:","options":["الابتسامة","الإنصات","المصافحة","الجدال العقيم لإظهار الغلبة"],"answer":3,"why":"المراء هو الجدال المذموم الذي يثير الشحناء."},{"type":"mcq","q":"راوي حديث «رحم الله رجلًا سمحًا إذا باع وإذا اشترى وإذا اقتضى» هو:","options":["أبو بكر الصديق","خالد بن الوليد","جابر بن عبد الله رضي الله عنهما","بلال بن رباح"],"answer":2,"why":"رواه البخاري عن جابر بن عبد الله رضي الله عنهما."},{"type":"tf","q":"يُحذف حرف المد في ﴿فِي السَّمَاءِ﴾ خطًا من المصحف ولفظًا في القراءة.","answer":false,"why":"يُحذف «لفظًا فقط» عند الوصل، ويبقى مكتوبًا في رسم المصحف"},{"type":"tf","q":"سُمّيت سورة الفاتحة بـ«المثاني» لأنها تُثنّى وتُكرّر قراءتها في كل ركعة من الصلاة.","answer":true,"why":"وهي سبع آيات مباركات لا تصح الصلاة إلا بها"},{"type":"tf","q":"الكبائر تُكفّر بالوضوء وحده دون حاجة إلى التوبة النصوح.","answer":false,"why":"الكبائر تحتاج إلى توبة نصوح صادقة وردّ الحقوق إن تعلّقت بالعباد"},{"type":"tf","q":"يجوز لأي شخص غير متخصص في الفقه أن يُصدر قياسًا شرعيًا في المسائل المستجدة.","answer":false,"why":"القياس والاجتهاد من اختصاص العلماء المجتهدين المؤهلين والمجامع الفقهية المعتبرة"},{"type":"tfr","q":"كان النبي ﷺ يخصّص لنفسه مقعدًا مرتفعًا فاخرًا يميّزه عن سائر أصحابه في المجلس.","answer":false,"reasons":["نعم كان له عرش مرتفع","كان يجلس وحده","بل كان يجلس بتواضع بين أصحابه حتى لا يميّزه الغريب إلا بالسؤال"],"reason":2},{"type":"tfr","q":"السماحة تقتصر على المعاملات المالية في الأسواق ولا دخل لها بالعلاقات الأسرية والمدرسية.","answer":false,"reasons":["نعم في السوق فقط","بل تشمل كل تعاملات الإنسان: في البيت والمدرسة والطريق والعمل بجانب السوق","لا تدخل في الأسرة"],"reason":1},{"type":"tfr","q":"حركة التاء في قوله تعالى ﴿قَالَتِ امْرَأَتُ﴾ هي الكسر للتخلّص من التقاء الساكنين.","answer":true,"reasons":["لأنها مجرورة","أصلها «قالتْ» ساكنة فحُرّكت بالكسر على الأصل عند وصلها بساكن","حركتها الضم"],"reason":1},{"type":"tfr","q":"يجوز للمسلم أن يأخذ من أحكام القرآن ما يوافق هواه ويترك ما لا يعجبه.","answer":false,"reasons":["هذا من فعل «المقتسمين الذين جعلوا القرآن عضين» المذموم في الآيات","نعم يجوز الانتقاء","لا بأس بترك بعض الأحكام"],"reason":0},{"type":"essay","q":"اذكر ثلاث حالات مختلفة لتحريك الساكن الأول (بالكسر، بالفتح، بالضم) مع مثال قرآني لكل حالة.","model":"بالكسر: ﴿قُلِ ادْعُوا﴾. بالفتح: ﴿مِنَ اللَّهِ﴾. بالضم: ﴿عَلَيْكُمُ الصِّيَامُ﴾."},{"type":"essay","q":"اذكر ثلاثة توجيهات ربانية في خواتيم سورة الحجر (٨٧–٩٩) لبناء شخصية المؤمن القوية.","model":"١) الغنى بالقرآن وعدم التعلق بمظاهر الدنيا. ٢) التواضع ولين الجانب مع المؤمنين والصدع بالحق. ٣) اللجوء للتسبيح والسجود عند ضيق الصدر والمداومة على العبادة حتى الموت."},{"type":"essay","q":"بيّن الحكمة من الأسلوب التعليمي للنبي ﷺ في حديث «أكبر الكبائر» (السؤال، التكرار، الجلوس).","model":"السؤال «ألا أنبئكم» يشد الانتباه، والتكرار يؤكد عظم الأمر، والانتقال من الاتكاء إلى الجلوس مع تكرار الزور يبرز خطورته الشديدة ويحفر التحذير في القلوب."},{"type":"essay","q":"حدّد أركان القياس الأربعة في مثال «تحريم المخدرات قياسًا على الخمر».","model":"الأصل: الخمر. الفرع: المخدرات. حكم الأصل: التحريم. العلة: الإسكار وإذهاب العقل."},{"type":"essay","q":"اذكر أربعة آداب للمجلس النبوي يمكنك تطبيقها في اجتماع صفي أو مجلس عائلي.","model":"١) إلقاء السلام والتفسح للقادم الجديد. ٢) الإنصات للمتحدث وعدم مقاطعته أو رفع الصوت. ٣) حفظ أسرار المجلس وعدم التصوير دون إذن. ٤) الختام بدعاء كفارة المجلس."}]},
  {"id":"g9-islamic-1-u4","grade":"g9","subject":"islamic","term":1,"title":"الوحدة الرابعة","levels":{"easy":[{"type":"mcq","q":"معنى «فَصَلَتِ الْعِيرُ» في الآية ٩٤ هو:","options":["خرجت القافلة وغادرت مصر","توقفت الرياح","وصلت السفينة","نزل المطر"],"answer":0,"why":"العير هي القافلة، وفصلت أي خرجت وغادرت."},{"type":"mcq","q":"معنى «يوم لا ظلّ إلا ظله» هو:","options":["وقت الليل","فصل الشتاء","يوم العيد","يوم القيامة حيث يظلّ الله عباده بظل عرشه"],"answer":3,"why":"يوم القيامة تدنو الشمس ويشتد الكرب فلا ظل إلا ظل عرش الله."},{"type":"mcq","q":"يُلقّب نبي الله إبراهيم عليه السلام بـ:","options":["ذو النون","كليم الله","خليل الله وأبو الأنبياء","روح الله"],"answer":2,"why":"اتخذ الله إبراهيم خليلًا وجعل النبوة في ذريته."},{"type":"mcq","q":"اليمين التي يحلفها الشخص كاذبًا متعمّدًا على أمر ماضٍ تُسمّى:","options":["اليمين المنعقدة","اليمين الغموس","يمين الصدق","يمين اللغو"],"answer":1,"why":"اليمين الغموس هي الحلف الكاذب المتعمد."}],"medium":[{"type":"mcq","q":"كيف تعامل يوسف عليه السلام مع والديه عند لقائهما في مصر رغم كونه عزيز مصر؟","options":["آواهما وأكرمهما ورفعهما على العرش برًّا وتواضعًا","لم يستقبلهما","تركهما في آخر المجلس","تفاخر عليهما بملكه"],"answer":0,"why":"مهما ارتفع منصب الإنسان يبقى بارًّا متواضعًا لوالديه."},{"type":"mcq","q":"لماذا يُعد «الشاب الناشئ في عبادة الله» أعظم أجرًا وأشد مجاهدةً؟","options":["لأن الكبار لا يُقبل عملهم","لأن الشباب بلا واجبات","لأن العبادة للشباب فقط","لأن مرحلة الشباب تمتلئ بالقوة والمغريات، فالثبات على الطاعة فيها دليل صدق وإرادة قوية"],"answer":3,"why":"مجاهدة الهوى في زمن القوة والفتوّة ترفع الدرجات."},{"type":"mcq","q":"ما الحكمة من وصف النار في الآية بـ«بردًا وسلامًا» ولم يقل «بردًا» فقط؟","options":["للتكرار فقط","لأنها تحولت لثلج","لأن البرد الشديد وحده قد يؤذي ويهلك، فقرنه بالسلام ليكون بردًا لطيفًا آمنًا لا يضرّه","لأنها لم تُشعل"],"answer":2,"why":"دقة التعبير القرآني: بردًا لا يحرق وسلامًا لا يؤذي ببرده."},{"type":"tfr","q":"يجوز للمسلم أن يطلب تعجيل الموت لضرّ أصابه تأسّيًا بدعاء يوسف ﴿توفني مسلمًا﴾.","answer":false,"reasons":["يوسف لم يطلب تعجيل الموت، بل سأل الله أن يثبته على الإسلام حتى يتوفاه عليه؛ وقد نهى النبي ﷺ عن تمني الموت لضر","نعم يجوز تمني الموت","يوسف كان يائسًا"],"reason":0},{"type":"tfr","q":"لا يجوز إعلان الصدقة مطلقًا حتى لو كان بقصد تشجيع الناس على التبرع لحملة خيرية.","answer":false,"reasons":["الإعلان حرام دائمًا","الإخفاء ممنوع","الأصل الإخفاء لكونه أبعد عن الرياء، لكن يجوز الإظهار أحيانًا بنية صالحة لتشجيع الناس والقدوة الحسنة ﴿إن تبدوا الصدقات فنعما هي وإن تخفوها وتؤتوها الفقراء فهو خير لكم﴾"],"reason":2}],"hard":[{"type":"mcq","q":"أي اسم من أسماء الله الحسنى ختم به يوسف ثناءه في الآية ١٠٠ بعد استعراض رحلته من السجن إلى العرش؟","options":["المانع فقط","المنتقم فقط","المتكبر","اللطيف العليم الحكيم"],"answer":3,"why":"﴿إن ربي لطيف لما يشاء إنه هو العليم الحكيم﴾."},{"type":"mcq","q":"لماذا بدأ النبي ﷺ الحديث بـ«الإمام العادل» قبل سائر الأصناف الستة؟","options":["للترتيب العشوائي","لأنه الأسهل","لأن نفعه متعدٍّ يعمّ الأمة كلها؛ بعدله يستقر الأمن وتُحفظ الحقوق وتُعمر المساجد","لأن الباقين لا يهمون"],"answer":2,"why":"صلاح الراعي وعدله يعمّ خيره المجتمع كله."},{"type":"mcq","q":"عندما ادّعى النمرود أنه «يحيي ويميت» بقتل بريء وإطلاق سجين، انتقل إبراهيم فورًا لحجة «الشمس»؛ لماذا؟","options":["لأنه عجز عن الرد","لذكائه الحواري في عدم إضاعة الوقت بالجدل اللفظي والانتقال لبرهان قاطع لا يقبل المغالطة","لأنه نسي الحجة الأولى","لأنه وافقه"],"answer":1,"why":"أروع مهارة في الحوار: تجاوز المغالطات والانتقال لدليل حاسم لا جدال فيه."},{"type":"essay","q":"قارن بين أسلوب يوسف في التعامل مع «الابتلاء في السجن» وتعامله مع «التمكين في العرش».","model":"في الابتلاء: صبر وعفة وثبات ودعوة للتوحيد. وفي التمكين: عفو وتواضع وبرّ بوالديه وشكر لله وطلب لحسن الخاتمة. وفي الحالتين كان عبدًا مخلصًا لله."},{"type":"essay","q":"استخلص من الحديث الشريف كيف يوازن الإسلام بين «العبادة الفردية الخفية» و«المسؤولية الاجتماعية».","model":"ففي الحديث عبادات خفية (ذكر الخلوة، صدقة الخفاء، العفة)، وبجانبها مسؤوليات اجتماعية عامة (عدل الإمام، عمارة المساجد، المحبة في الله)، وبذلك يصلح الفرد والمجتمع معًا."}]},"test":[{"type":"mcq","q":"معنى «فَصَلَتِ الْعِيرُ» في الآية ٩٤ هو:","options":["خرجت القافلة وغادرت مصر","توقفت الرياح","وصلت السفينة","نزل المطر"],"answer":0,"why":"العير هي القافلة، وفصلت أي خرجت وغادرت."},{"type":"mcq","q":"معنى «يوم لا ظلّ إلا ظله» هو:","options":["وقت الليل","فصل الشتاء","يوم العيد","يوم القيامة حيث يظلّ الله عباده بظل عرشه"],"answer":3,"why":"يوم القيامة تدنو الشمس ويشتد الكرب فلا ظل إلا ظل عرش الله."},{"type":"mcq","q":"يُلقّب نبي الله إبراهيم عليه السلام بـ:","options":["ذو النون","كليم الله","خليل الله وأبو الأنبياء","روح الله"],"answer":2,"why":"اتخذ الله إبراهيم خليلًا وجعل النبوة في ذريته."},{"type":"mcq","q":"اليمين التي يحلفها الشخص كاذبًا متعمّدًا على أمر ماضٍ تُسمّى:","options":["اليمين المنعقدة","اليمين الغموس","يمين الصدق","يمين اللغو"],"answer":1,"why":"اليمين الغموس هي الحلف الكاذب المتعمد."},{"type":"mcq","q":"الصحابي الذي قال عنه أبو بكر الصديق «لصوته في الجيش خير من ألف رجل» هو:","options":["القعقاع بن عمرو التميمي","بلال بن رباح","سلمان الفارسي","أبو هريرة"],"answer":0,"why":"هذه الشهادة الشهيرة لأبي بكر في حق القعقاع رضي الله عنه."},{"type":"mcq","q":"التزام الصدق والأمانة والعدل والبعد عن الغش والرشوة في السر والعلن يُسمّى:","options":["التطفيف","المراء","المحسوبية","النزاهة"],"answer":3,"why":"هذا هو المفهوم الشامل للنزاهة."},{"type":"mcq","q":"معنى «فَاطِرَ السَّمَاوَاتِ وَالْأَرْضِ» في الآية ١٠١ هو:","options":["أرض خصبة","خالقهما ومبدعهما على غير مثال سابق","حافظهما فقط","سماء واسعة"],"answer":1,"why":"فاطر السماوات أي مبدعهما وخالقهما أول مرة."},{"type":"mcq","q":"مثال على «المحبة في الله»:","options":["صديقان يتعاونان على الصلاة وطلب العلم والأخلاق الحسنة","صداقة لأجل مصلحة مالية فقط","مجاملة مؤقتة","رفقة على الغيبة وإضاعة الوقت"],"answer":0,"why":"المحبة في الله خالصة نقية تجمع على طاعة الله."},{"type":"mcq","q":"معنى «الآفلين» في قصة إبراهيم مع الكواكب هو:","options":["المضيئين دائمًا","المسافرين","القائمين بالليل","الغائبين الزائلين عن الأنظار"],"answer":3,"why":"الأفول هو الغياب والزوال، وهو صفة المخلوق لا الخالق."},{"type":"mcq","q":"عدد المساكين الذين يُطعمون أو يُكسون في كفارة اليمين هو:","options":["مسكين واحد","ستون مسكينًا","عشرة مساكين","ثلاثة مساكين"],"answer":2,"why":"﴿فكفارته إطعام عشرة مساكين... أو كسوتهم﴾."},{"type":"mcq","q":"المعركة الكبرى في العراق التي برزت فيها عبقرية القعقاع التكتيكية ضد الفيلة هي:","options":["غزوة بدر","معركة القادسية","صلح الحديبية","غزوة أحد"],"answer":1,"why":"كان للقعقاع دور حاسم في نصر القادسية سنة ١٥ هـ."},{"type":"mcq","q":"قول النبي ﷺ: «من غشّنا فليس منّا» يُرسّخ قيمة:","options":["النزاهة والأمانة في الدراسة والتجارة","الكسل","الاحتكار","الرشوة"],"answer":0,"why":"الحديث يحرّم جميع صور الغش."},{"type":"tf","q":"يجوز للمسلم أن يطلب تعجيل الموت لضرّ أصابه تأسّيًا بدعاء يوسف ﴿توفني مسلمًا﴾.","answer":false,"why":"يوسف لم يطلب تعجيل الموت، بل سأل الله أن يثبته على الإسلام حتى يتوفاه عليه؛ وقد نهى النبي ﷺ عن تمني الموت لضر"},{"type":"tf","q":"لا يجوز إعلان الصدقة مطلقًا حتى لو كان بقصد تشجيع الناس على التبرع لحملة خيرية.","answer":false,"why":"الأصل الإخفاء لكونه أبعد عن الرياء، لكن يجوز الإظهار أحيانًا بنية صالحة لتشجيع الناس والقدوة الحسنة ﴿إن تبدوا الصدقات فنعما هي وإن تخفوها وتؤتوها الفقراء فهو خير لكم﴾"},{"type":"tf","q":"حوار إبراهيم عليه السلام مع عبدة الكواكب لم يكن شكًّا منه في ربه، بل أسلوب مناظرة لإقناعهم ببطلان عبادتها.","answer":true,"why":"فقد كان على الفطرة والتوحيد وأراد استدراجهم بالعقل ليدركوا أن الآفل لا يصلح إلهًا"},{"type":"tf","q":"تجوز «يمين اللغو» ولا كفارة فيها، لكن يُستحب تعويد اللسان على حفظ اسم الله وعدم الإكثار من الحلف.","answer":true,"why":"تعظيمًا لاسم الله وعملًا بقوله تعالى ﴿واحفظوا أيمانكم﴾"},{"type":"tfr","q":"لم يقتصر تميّز القعقاع بن عمرو على القوة البدنية، بل جمع معها الذكاء القيادي والفصاحة الشعرية.","answer":true,"reasons":["لم يكن يعرف الشعر","كان مقاتلًا بلا خطط","فقد كان شاعرًا فصيحًا يلهب الحماس ومخططًا عسكريًا ذكيًا"],"reason":2},{"type":"tfr","q":"يكفي وجود القوانين والعقوبات وحدها للقضاء على الفساد دون الحاجة إلى الوازع الديني والضمير.","answer":false,"reasons":["لا حاجة للقانون","القانون ضروري، لكن الوازع الديني والتربية على النزاهة هما الرقيب الداخلي في الخلوة حين لا يراك أحد","نعم القانون وحده يكفي دائمًا"],"reason":1},{"type":"tfr","q":"قوله تعالى ﴿إن ربي لطيف لما يشاء﴾ يعني أن الله يدبّر الأمور بدقة وخفاء ورحمة حتى يأتي الفرج من حيث لا يُحتسب.","answer":true,"reasons":["يعني أنه سريع الغضب","فقد ساق البئر ثم السجن ثم العرش ليحقق لطفه وحكمته بيوسف وأهله","لا علاقة له بالتدبير"],"reason":1},{"type":"tfr","q":"الذكر والبكاء في الخلوة دليل على صدق الإخلاص لانتفاء وجود من يُرائيه الإنسان.","answer":true,"reasons":["في الخلوة لا يراه إلا الله، فتكون دمعته خالصةً صادقةً","البكاء أمام الناس فقط أخلص","لا أجر للذكر سرًا"],"reason":0},{"type":"essay","q":"اذكر أربع قيم أخلاقية بارزة في خواتيم سورة يوسف (٩٤–١٠١).","model":"١) برّ الوالدين وإكرامهما. ٢) العفو الكريم دون معايرة. ٣) التواضع ونسبة الفضل لله عند النجاح. ٤) الحرص على حسن الخاتمة وصحبة الصالحين."},{"type":"essay","q":"اذكر أربعةً من الأصناف السبعة في الحديث يستطيع طالب الصف التاسع التنافس فيها منذ اليوم.","model":"١) شاب نشأ في عبادة الله. ٢) قلب معلّق بالمساجد والمحافظة على الصلاة. ٣) المحبة في الله مع صديق صالح. ٤) صدقة الخفاء وذكر الله في الخلوة والعفة."},{"type":"essay","q":"اذكر ثلاثة مواقف تُبرز «القوة العقلية والحجة الهادئة» في دعوة إبراهيم عليه السلام.","model":"١) إبطال عبادة الكواكب والقمر والشمس بدليل الأفول والغياب. ٢) ترك كبير الأصنام ليقرّ القوم بعجزها. ٣) تحدّي النمرود بتغيير شروق الشمس من المشرق إلى المغرب."},{"type":"essay","q":"اذكر أنواع الأيمان الثلاثة مع مثال واحد لكل نوع.","model":"١) اللغو: قول «لا والله» في الكلام العادي بلا قصد. ٢) المنعقدة: «والله لأتصدقن غدًا» بقصد وعزم. ٣) الغموس: «والله لم أسرق الكتاب» وهو يعلم أنه سرقه."},{"type":"essay","q":"اشرح كيف يمكن لطالب واحد في الصف أن يكون «كألف» في أثره الإيجابي قياسًا على شهادة أبي بكر في القعقاع.","model":"بأن يكون مبادرًا للخير، متفائلًا يرفع همة زملائه، مبدعًا في حل مشكلات المشاريع، وحريصًا على الإصلاح والتعاون بدل السلبية والتذمر."}]},
  {"id":"g9-islamic-2-u1","grade":"g9","subject":"islamic","term":2,"title":"الوحدة الأولى (الفصل الثاني)","levels":{"easy":[{"type":"mcq","q":"ما المقصود بـ«التفسير بالمأثور»؟","options":["التفسير بالخيال الشخصي","تفسير القرآن بالقرآن أو بالسنة أو بأقوال الصحابة والتابعين","تفسير الأحلام فقط","ترجمة الكلمات فقط"],"answer":1,"why":"المأثور ما نُقل عن الوحي والصحابة والتابعين."},{"type":"mcq","q":"أي طريق يُعد «أول وأصح» طرق التفسير بالمأثور؟","options":["التفسير بالرأي المذموم","التخمين اللغوي","تفسير القرآن بالقرآن","آراء غير المتخصصين"],"answer":2,"why":"تفسير القرآن بالقرآن أعلى مراتب التفسير لأن الله أعلم بمراده."},{"type":"mcq","q":"الفرق بين التفسير بالرأي المحمود والمذموم هو:","options":["كلاهما محرّم","لا فرق بينهما","كلاهما مباح للجميع","المحمود مبني على علم باللغة والشرع بلا هوى، والمذموم بجهل وهوى"],"answer":3,"why":"العلم والضوابط الشرعية هما الفارق بين المحمود والمذموم."},{"type":"mcq","q":"من أبرز الصحابة الذين اشتهروا بعلم التفسير (ترجمان القرآن):","options":["عبد الله بن عباس رضي الله عنهما","أبو لهب","سهيل بن عمرو","النجاشي"],"answer":0,"why":"دعا له النبي ﷺ: «اللهم فقهه في الدين وعلّمه التأويل»."}],"medium":[{"type":"mcq","q":"أي شرط مما يلي أساسي في المفسّر؟","options":["امتلاك المال فقط","إتقان علوم اللغة العربية والسنة النبوية وأسباب النزول مع صحة العقيدة","حفظ الشعر فقط دون السنة","السرعة في الكلام"],"answer":1,"why":"التفسير يحتاج أدوات لغوية وشرعية متكاملة."},{"type":"mcq","q":"كتاب «جواهر التفسير» من التفاسير العُمانية المعاصرة لمؤلفه:","options":["الإمام البخاري","سيبويه","سماحة الشيخ أحمد بن حمد الخليلي","ابن خلدون"],"answer":2,"why":"جواهر التفسير من أبرز مؤلفات التفسير العُمانية المعاصرة."},{"type":"mcq","q":"تفسير النبي ﷺ لقوله تعالى ﴿الظلم﴾ في آية الأنعام بـ«الشرك» مثال على:","options":["القياس الفقهي","التفسير بالرأي المذموم","علم التجويد","تفسير القرآن بالسنة النبوية"],"answer":3,"why":"بيّن النبي ﷺ المراد بالظلم في الآية أنه الشرك."},{"type":"tfr","q":"علم التفسير يعين المسلم على التدبّر والعمل الصحيح بأحكام القرآن.","answer":true,"reasons":["لا يفيد في التدبر","فالفهم السليم هو الجسر بين التلاوة والتطبيق العملي","للمتخصصين فقط بلا أثر عملي"],"reason":1},{"type":"tfr","q":"تجمع الآية ٢٩ من سورة الفتح جميع حروف اللغة العربية في آية واحدة، وتصف جيل الصحابة بأرقى الصفات.","answer":true,"reasons":["آية قصيرة جدًّا","لا تصف الصحابة","فهي آية عظيمة المبنى والمعنى في وصف الصحابة الكرام"],"reason":2}],"hard":[{"type":"mcq","q":"ما حكم القول في تفسير القرآن الكريم بالهوى وبغير علم؟","options":["محرّم ومنهي عنه بشدة","مباح للجميع","مستحب","واجب"],"answer":0,"why":"قال تعالى ﴿وأن تقولوا على الله ما لا تعلمون﴾."},{"type":"mcq","q":"من أشهر كتب «التفسير بالمأثور» عبر التاريخ:","options":["الأغاني للأصفهاني","جامع البيان للطبري وتفسير ابن كثير","كتاب العين","المقدمة لابن خلدون"],"answer":1,"why":"الطبري وابن كثير من أمهات كتب التفسير بالمأثور."},{"type":"mcq","q":"معرفة «أسباب النزول» تفيد المفسّر في:","options":["تغيير نص الآية","حذف الآية","فهم سياق الآية والمراد الدقيق منها ودفع الإشكال","تجاهل اللغة العربية"],"answer":2,"why":"سبب النزول يكشف ملابسات الخطاب القرآني بوضوح."},{"type":"essay","q":"عرّف علم التفسير اصطلاحًا واذكر نوعيه الرئيسين.","model":"علم يُفهم به كتاب الله وبيان معانيه واستخراج أحكامه. نوعاه: التفسير بالمأثور، والتفسير بالرأي (المحمود والمذموم)."},{"type":"essay","q":"اذكر أربعة شروط يجب توفرها في المفسّر.","model":"١) صحة العقيدة والإخلاص. ٢) إتقان اللغة العربية وعلومها. ٣) معرفة السنة وأسباب النزول والناسخ والمنسوخ. ٤) البعد عن الهوى."}]},"test":[{"type":"mcq","q":"ما المقصود بـ«التفسير بالمأثور»؟","options":["التفسير بالخيال الشخصي","تفسير القرآن بالقرآن أو بالسنة أو بأقوال الصحابة والتابعين","تفسير الأحلام فقط","ترجمة الكلمات فقط"],"answer":1,"why":"المأثور ما نُقل عن الوحي والصحابة والتابعين."},{"type":"mcq","q":"أي طريق يُعد «أول وأصح» طرق التفسير بالمأثور؟","options":["التفسير بالرأي المذموم","التخمين اللغوي","تفسير القرآن بالقرآن","آراء غير المتخصصين"],"answer":2,"why":"تفسير القرآن بالقرآن أعلى مراتب التفسير لأن الله أعلم بمراده."},{"type":"mcq","q":"الفرق بين التفسير بالرأي المحمود والمذموم هو:","options":["كلاهما محرّم","لا فرق بينهما","كلاهما مباح للجميع","المحمود مبني على علم باللغة والشرع بلا هوى، والمذموم بجهل وهوى"],"answer":3,"why":"العلم والضوابط الشرعية هما الفارق بين المحمود والمذموم."},{"type":"mcq","q":"من أبرز الصحابة الذين اشتهروا بعلم التفسير (ترجمان القرآن):","options":["عبد الله بن عباس رضي الله عنهما","أبو لهب","سهيل بن عمرو","النجاشي"],"answer":0,"why":"دعا له النبي ﷺ: «اللهم فقهه في الدين وعلّمه التأويل»."},{"type":"mcq","q":"أي شرط مما يلي أساسي في المفسّر؟","options":["امتلاك المال فقط","إتقان علوم اللغة العربية والسنة النبوية وأسباب النزول مع صحة العقيدة","حفظ الشعر فقط دون السنة","السرعة في الكلام"],"answer":1,"why":"التفسير يحتاج أدوات لغوية وشرعية متكاملة."},{"type":"mcq","q":"كتاب «جواهر التفسير» من التفاسير العُمانية المعاصرة لمؤلفه:","options":["الإمام البخاري","سيبويه","سماحة الشيخ أحمد بن حمد الخليلي","ابن خلدون"],"answer":2,"why":"جواهر التفسير من أبرز مؤلفات التفسير العُمانية المعاصرة."},{"type":"mcq","q":"تفسير النبي ﷺ لقوله تعالى ﴿الظلم﴾ في آية الأنعام بـ«الشرك» مثال على:","options":["القياس الفقهي","التفسير بالرأي المذموم","علم التجويد","تفسير القرآن بالسنة النبوية"],"answer":3,"why":"بيّن النبي ﷺ المراد بالظلم في الآية أنه الشرك."},{"type":"mcq","q":"ما حكم القول في تفسير القرآن الكريم بالهوى وبغير علم؟","options":["محرّم ومنهي عنه بشدة","مباح للجميع","مستحب","واجب"],"answer":0,"why":"قال تعالى ﴿وأن تقولوا على الله ما لا تعلمون﴾."},{"type":"mcq","q":"من أشهر كتب «التفسير بالمأثور» عبر التاريخ:","options":["الأغاني للأصفهاني","جامع البيان للطبري وتفسير ابن كثير","كتاب العين","المقدمة لابن خلدون"],"answer":1,"why":"الطبري وابن كثير من أمهات كتب التفسير بالمأثور."},{"type":"mcq","q":"معرفة «أسباب النزول» تفيد المفسّر في:","options":["تغيير نص الآية","حذف الآية","فهم سياق الآية والمراد الدقيق منها ودفع الإشكال","تجاهل اللغة العربية"],"answer":2,"why":"سبب النزول يكشف ملابسات الخطاب القرآني بوضوح."},{"type":"mcq","q":"أفضل خطوة لطالب الصف التاسع إذا أشكل عليه معنى آية قرآنية هي:","options":["تجاهل الآية","تأليف معنى من عنده","أخذ أي منشور مجهول","الرجوع إلى تفسير موثوق كالتفسير الميسّر أو سؤال معلمه"],"answer":3,"why":"التثبت من المصادر الموثوقة يحفظ الفهم الصحيح."},{"type":"mcq","q":"ما معنى «شَطْأَه» في قوله تعالى ﴿كزرع أخرج شطأه فآزره﴾؟","options":["فراخه وفروعه التي تنبت حوله فتقوّيه","أوراقه اليابسة","جذوره المقطوعة","الماء المالح"],"answer":0,"why":"الشطء هو الفروع والنباتات الصغيرة التي تخرج بجانب الزرع وتقوّيه."},{"type":"tf","q":"يُعد النبي ﷺ هو المفسّر والمبيّن الأول للقرآن الكريم.","answer":true,"why":"لقوله تعالى ﴿وأنزلنا إليك الذكر لتبين للناس ما نزل إليهم﴾"},{"type":"tf","q":"يجوز لأي شخص تفسير القرآن الكريم برأيه الشخصي دون معرفة اللغة العربية أو السنة.","answer":false,"why":"التفسير بالجهل والهوى محرم؛ وللمفسر شروط علمية وشرعية دقيقة"},{"type":"tf","q":"التفسير بالرأي المحمود مقبول إذا التزم بضوابط اللغة والشرع ولم يخالف النصوص.","answer":true,"why":"وهو اجتهاد علمي منضبط لاستخراج المعاني واللطائف"},{"type":"tf","q":"تفسير القرآن بالقرآن يعني أن ما جاء مجملًا في آية قد يُفصّل في آية أخرى.","answer":true,"why":"وهو أصح طرق التفسير بالمأثور"},{"type":"tfr","q":"علم التفسير يعين المسلم على التدبّر والعمل الصحيح بأحكام القرآن.","answer":true,"reasons":["لا يفيد في التدبر","فالفهم السليم هو الجسر بين التلاوة والتطبيق العملي","للمتخصصين فقط بلا أثر عملي"],"reason":1},{"type":"tfr","q":"تجمع الآية ٢٩ من سورة الفتح جميع حروف اللغة العربية في آية واحدة، وتصف جيل الصحابة بأرقى الصفات.","answer":true,"reasons":["آية قصيرة جدًّا","لا تصف الصحابة","فهي آية عظيمة المبنى والمعنى في وصف الصحابة الكرام"],"reason":2},{"type":"tfr","q":"معنى «رحماء بينهم» يوجب اللين والعفو والتكافل بين المسلمين في الأسرة والمدرسة والمجتمع.","answer":true,"reasons":["فالرحمة المتبادلة أساس تماسك الأمة","تعني القسوة على الإخوة","خاصة بالحرب فقط"],"reason":0},{"type":"tfr","q":"المقصود بـ«سيماهم في وجوههم» هو عبوس الوجه وتجهمه.","answer":false,"reasons":["نعم العبوس","بل النور والسكينة والوقار والبشاشة والسمت الحسن من أثر العبادة","الغضب الدائم"],"reason":1},{"type":"essay","q":"عرّف علم التفسير اصطلاحًا واذكر نوعيه الرئيسين.","model":"علم يُفهم به كتاب الله وبيان معانيه واستخراج أحكامه. نوعاه: التفسير بالمأثور، والتفسير بالرأي (المحمود والمذموم)."},{"type":"essay","q":"اذكر أربعة شروط يجب توفرها في المفسّر.","model":"١) صحة العقيدة والإخلاص. ٢) إتقان اللغة العربية وعلومها. ٣) معرفة السنة وأسباب النزول والناسخ والمنسوخ. ٤) البعد عن الهوى."},{"type":"essay","q":"قارن بين التفسير بالمأثور والتفسير بالرأي المحمود مع مثال لكل منهما.","model":"بالمأثور: يعتمد على القرآن والسنة وأقوال الصحابة (تفسير الطبري وابن كثير). بالرأي المحمود: اجتهاد عالم متمكن بالضوابط اللغوية والشرعية."},{"type":"essay","q":"اذكر مثالًا لتفسير القرآن بالقرآن ومثالًا لتفسير القرآن بالسنة.","model":"بالقرآن: تفسير الكلمات التي تلقاها آدم بـ﴿ربنا ظلمنا أنفسنا﴾. بالسنة: تفسير «القوة» بالرمي و«الظلم» بالشرك."},{"type":"essay","q":"لماذا حذّر الإسلام من التفسير بالهوى وبغير علم؟","model":"لأنه افتراء على الله وتحريف لمعاني كتابه وإضلال للناس عن الفهم الصحيح للدين."}]},
  {"id":"g9-islamic-2-u2","grade":"g9","subject":"islamic","term":2,"title":"الوحدة الثانية (الفصل الثاني)","levels":{"easy":[{"type":"mcq","q":"ما المقصود بـ«الرسم العثماني»؟","options":["الخط الكوفي المزخرف فقط","الإملاء المدرسي الحديث","الهيئة الخاصة التي كُتبت بها كلمات القرآن في مصاحف عهد عثمان بن عفان رضي الله عنه","الكتابة بدون نقط فقط"],"answer":2,"why":"هو الرسم التوقيفي المعتمد للمصحف الشريف."},{"type":"mcq","q":"ماذا يعني وضع «الصفر المستدير» فوق حرف في المصحف (مثل الواو في ﴿أُولَٰئِكَ﴾)؟","options":["أنه يُنطق وصلًا فقط","أنه يُمدّ ٦ حركات","أنه حرف مقلقل","أن الحرف زائد في الرسم ولا يُنطق لا وصلًا ولا وقفًا"],"answer":3,"why":"الصفر المستدير علامة زيادة الحرف خطًا وسقوطه لفظًا."},{"type":"mcq","q":"ما إحدى أعظم فوائد الالتزام بالرسم العثماني في طباعة المصاحف؟","options":["احتمال الكلمة الواحدة للقراءات القرآنية المتواترة (مثل ﴿مَٰلِكِ﴾)","تسهيل تغيير الكلمات","إلغاء الحاجة للمعلم","اختصار عدد السور"],"answer":0,"why":"حذف الألف في ﴿مَٰلِكِ﴾ يجمع قراءتي «مَلِك» و«مَالِك»."},{"type":"mcq","q":"كيف نقف على كلمة ﴿رَحْمَتَ﴾ المرسومة بتاء مفتوحة في المصحف؟","options":["نقف عليها بالهاء (رَحْمَهْ)","نقف عليها بالتاء الساكنة (رَحْمَتْ)","نحذف التاء","نمدّها ٦ حركات"],"answer":1,"why":"يُتبع الرسم عند الوقف: المفتوحة بالتاء والمربوطة بالهاء."}],"medium":[{"type":"mcq","q":"كتابة كلمة ﴿الصَّلَوٰة﴾ بالواو بدل الألف في المصحف مثال على قاعدة:","options":["الحذف فقط","الزيادة","البدل","الإخفاء"],"answer":2,"why":"أُبدلت الألف واوًا في الرسم العثماني وتُنطق ألفًا."},{"type":"mcq","q":"كتابة كلمة ﴿الرَّحْمَٰن﴾ بدون ألف ممدودة في المصحف مثال على قاعدة:","options":["القلب","الزيادة","البدل","الحذف (مع إثبات النطق بالألف الخنجرية)"],"answer":3,"why":"حُذفت الألف خطًا وتُثبت لفظًا."},{"type":"mcq","q":"ماذا يعني وضع «الصفر المستطيل القائم» فوق ألف ﴿أَنَا۠﴾ في المصحف؟","options":["تُثبت الألف عند الوقف وتُحذف لفظًا عند الوصل","تُحذف وقفًا ووصلًا","تُمدّ ٦ حركات","تُنطق واوًا"],"answer":0,"why":"الألفات السبع (ومنها أنا) تثبت وقفًا وتسقط وصلًا."},{"type":"tfr","q":"من فوائد الرسم العثماني أنه يدفع القارئ لتلقي القرآن بالمشافهة عن المعلمين لا بالاعتماد على الخط وحده.","answer":true,"reasons":["يغني عن المعلم","يمنع القراءة","فيحفظ الأداء الصوتي الصحيح المتصل بالسند إلى النبي ﷺ"],"reason":2},{"type":"tfr","q":"أُرسل نبي الله شعيب عليه السلام إلى أصحاب الأيكة فدعاهم للتوحيد وإيفاء الكيل والميزان.","answer":true,"reasons":["فجمع بين إصلاح العقيدة وإصلاح المعاملات الاقتصادية","أرسل إليهم هود","دعاهم للتجارة فقط"],"reason":0}],"hard":[{"type":"mcq","q":"هل يجوز طباعة المصحف الكامل بالرسم الإملائي الحديث وترك الرسم العثماني؟","options":["نعم يجب تغييره كل عام","لا، أجمع العلماء على وجوب الالتزام بالرسم العثماني في طباعة المصحف","مباح تغييره للأسهل","لا أهمية للرسم"],"answer":1,"why":"الرسم العثماني إجماع للأمة لحفظ المصحف ووحدته."},{"type":"mcq","q":"الألف الخنجرية الصغيرة فوق الحرف في المصحف تدل على:","options":["سكون الحرف","حرف لا يُنطق","وجود ألف مدية محذوفة في الرسم يجب نطقها في التلاوة","وجوب الوقف"],"answer":2,"why":"الألف الخنجرية علامة ضبط تُرشد القارئ لنطق الألف المحذوفة رسمًا."},{"type":"mcq","q":"في كلمة ﴿وَلَا تَقُولَنَّ لِشَايْءٍ﴾ (سورة الكهف)، الألف بعد الشين فوقها صفر مستدير، إذن حكمها:","options":["تُكسر","تُمدّ حركتين","تُثبت وقفًا فقط","لا تُنطق مطلقًا لا وصلًا ولا وقفًا"],"answer":3,"why":"وجود الصفر المستدير يعني زيادة الحرف رسمًا دون لفظ."},{"type":"essay","q":"اذكر ثلاث ظواهر من ظواهر الرسم العثماني مع مثال قرآني لكل ظاهرة.","model":"١) الحذف: ﴿الرَّحْمَٰن﴾. ٢) الزيادة: ﴿أُولَٰئِكَ﴾. ٣) البدل: ﴿الصَّلَوٰة﴾ (أو التاء المفتوحة: ﴿رَحْمَتَ﴾)."},{"type":"essay","q":"قارن بين دلالة «الصفر المستدير» و«الصفر المستطيل» في ضبط المصحف مع مثال لكل منهما.","model":"الصفر المستدير: يسقط الحرف لفظًا وصلًا ووقفًا (الواو في ﴿أُولَٰئِكَ﴾). الصفر المستطيل: يسقط الحرف وصلًا ويثبت وقفًا (الألف في ﴿أَنَا۠﴾)."}]},"test":[{"type":"mcq","q":"ما المقصود بـ«الرسم العثماني»؟","options":["الخط الكوفي المزخرف فقط","الإملاء المدرسي الحديث","الهيئة الخاصة التي كُتبت بها كلمات القرآن في مصاحف عهد عثمان بن عفان رضي الله عنه","الكتابة بدون نقط فقط"],"answer":2,"why":"هو الرسم التوقيفي المعتمد للمصحف الشريف."},{"type":"mcq","q":"ماذا يعني وضع «الصفر المستدير» فوق حرف في المصحف (مثل الواو في ﴿أُولَٰئِكَ﴾)؟","options":["أنه يُنطق وصلًا فقط","أنه يُمدّ ٦ حركات","أنه حرف مقلقل","أن الحرف زائد في الرسم ولا يُنطق لا وصلًا ولا وقفًا"],"answer":3,"why":"الصفر المستدير علامة زيادة الحرف خطًا وسقوطه لفظًا."},{"type":"mcq","q":"ما إحدى أعظم فوائد الالتزام بالرسم العثماني في طباعة المصاحف؟","options":["احتمال الكلمة الواحدة للقراءات القرآنية المتواترة (مثل ﴿مَٰلِكِ﴾)","تسهيل تغيير الكلمات","إلغاء الحاجة للمعلم","اختصار عدد السور"],"answer":0,"why":"حذف الألف في ﴿مَٰلِكِ﴾ يجمع قراءتي «مَلِك» و«مَالِك»."},{"type":"mcq","q":"كيف نقف على كلمة ﴿رَحْمَتَ﴾ المرسومة بتاء مفتوحة في المصحف؟","options":["نقف عليها بالهاء (رَحْمَهْ)","نقف عليها بالتاء الساكنة (رَحْمَتْ)","نحذف التاء","نمدّها ٦ حركات"],"answer":1,"why":"يُتبع الرسم عند الوقف: المفتوحة بالتاء والمربوطة بالهاء."},{"type":"mcq","q":"كتابة كلمة ﴿الصَّلَوٰة﴾ بالواو بدل الألف في المصحف مثال على قاعدة:","options":["الحذف فقط","الزيادة","البدل","الإخفاء"],"answer":2,"why":"أُبدلت الألف واوًا في الرسم العثماني وتُنطق ألفًا."},{"type":"mcq","q":"كتابة كلمة ﴿الرَّحْمَٰن﴾ بدون ألف ممدودة في المصحف مثال على قاعدة:","options":["القلب","الزيادة","البدل","الحذف (مع إثبات النطق بالألف الخنجرية)"],"answer":3,"why":"حُذفت الألف خطًا وتُثبت لفظًا."},{"type":"mcq","q":"ماذا يعني وضع «الصفر المستطيل القائم» فوق ألف ﴿أَنَا۠﴾ في المصحف؟","options":["تُثبت الألف عند الوقف وتُحذف لفظًا عند الوصل","تُحذف وقفًا ووصلًا","تُمدّ ٦ حركات","تُنطق واوًا"],"answer":0,"why":"الألفات السبع (ومنها أنا) تثبت وقفًا وتسقط وصلًا."},{"type":"mcq","q":"هل يجوز طباعة المصحف الكامل بالرسم الإملائي الحديث وترك الرسم العثماني؟","options":["نعم يجب تغييره كل عام","لا، أجمع العلماء على وجوب الالتزام بالرسم العثماني في طباعة المصحف","مباح تغييره للأسهل","لا أهمية للرسم"],"answer":1,"why":"الرسم العثماني إجماع للأمة لحفظ المصحف ووحدته."},{"type":"mcq","q":"الألف الخنجرية الصغيرة فوق الحرف في المصحف تدل على:","options":["سكون الحرف","حرف لا يُنطق","وجود ألف مدية محذوفة في الرسم يجب نطقها في التلاوة","وجوب الوقف"],"answer":2,"why":"الألف الخنجرية علامة ضبط تُرشد القارئ لنطق الألف المحذوفة رسمًا."},{"type":"mcq","q":"في كلمة ﴿وَلَا تَقُولَنَّ لِشَايْءٍ﴾ (سورة الكهف)، الألف بعد الشين فوقها صفر مستدير، إذن حكمها:","options":["تُكسر","تُمدّ حركتين","تُثبت وقفًا فقط","لا تُنطق مطلقًا لا وصلًا ولا وقفًا"],"answer":3,"why":"وجود الصفر المستدير يعني زيادة الحرف رسمًا دون لفظ."},{"type":"mcq","q":"كيف يستفيد الطالب من «قائمة مصطلحات الضبط» في آخر المصحف الشريف؟","options":["يتعرّف معاني العلامات (كالصفر المستدير والمستطيل والألف الخنجرية) فيقرأ بلا أخطاء","لا فائدة منها","تحوي معاني الكلمات فقط","تحتوي أسماء السور فقط"],"answer":0,"why":"قائمة مصطلحات الضبط دليل عملي ممتاز للقارئ."},{"type":"mcq","q":"من هو النبي الذي أُرسل إلى «أصحاب الأيكة»؟","options":["صالح عليه السلام","شعيب عليه السلام","نوح عليه السلام","يونس عليه السلام"],"answer":1,"why":"دعا شعيب عليه السلام أهل مدين وأصحاب الأيكة."},{"type":"tf","q":"الرسم العثماني للمصحف الشريف توقيفي أجمعت الأمة على الالتزام به في طباعة المصاحف.","answer":true,"why":"حفظًا للقرآن ووحدته واحتوائه للقراءات المتواترة"},{"type":"tf","q":"يُنطق الحرف الذي فوقه «صفر مستدير» في المصحف عند الوقف عليه.","answer":false,"why":"لا يُنطق لا وصلًا ولا وقفًا، أما الذي يُثبت وقفًا فقط ففوقه صفر مستطيل كـ ﴿أَنَا۠﴾"},{"type":"tf","q":"الفرق بين ﴿نِعْمَتَ﴾ بالتاء المفتوحة و﴿نِعْمَةَ﴾ بالمربوطة يظهر عند الوقف (تاء مقابل هاء).","answer":true,"why":"فتتبع التلاوة رسم المصحف عند الوقف الاختباري أو الاضطراري"},{"type":"tf","q":"إضافة النقط والتشكيل وعلامات الضبط لاحقًا غيّرت حروف الرسم العثماني.","answer":false,"why":"بقيت حروف الرسم العثماني كما هي، وجاء الضبط لتسهيل القراءة الصحيحة على الناس"},{"type":"tfr","q":"من فوائد الرسم العثماني أنه يدفع القارئ لتلقي القرآن بالمشافهة عن المعلمين لا بالاعتماد على الخط وحده.","answer":true,"reasons":["يغني عن المعلم","يمنع القراءة","فيحفظ الأداء الصوتي الصحيح المتصل بالسند إلى النبي ﷺ"],"reason":2},{"type":"tfr","q":"أُرسل نبي الله شعيب عليه السلام إلى أصحاب الأيكة فدعاهم للتوحيد وإيفاء الكيل والميزان.","answer":true,"reasons":["فجمع بين إصلاح العقيدة وإصلاح المعاملات الاقتصادية","أرسل إليهم هود","دعاهم للتجارة فقط"],"reason":0},{"type":"tfr","q":"معنى «القسطاس المستقيم» هو الميزان العادل الدقيق.","answer":true,"reasons":["معناه الشجر الملتف","وهو رمز للعدالة والشفافية في كل المعاملات","معناه السحابة"],"reason":1},{"type":"tfr","q":"يجوز إنقاص الوزن أو الغش قليلًا إذا كان المشتري لا ينتبه.","answer":false,"reasons":["نعم يجوز قليلًا","لا بأس في التجارة","نهى الله بشدة عن التطفيف والبخس سواء انتبه المشتري أم لا لأن الله رقيب عليم"],"reason":2},{"type":"essay","q":"اذكر ثلاث ظواهر من ظواهر الرسم العثماني مع مثال قرآني لكل ظاهرة.","model":"١) الحذف: ﴿الرَّحْمَٰن﴾. ٢) الزيادة: ﴿أُولَٰئِكَ﴾. ٣) البدل: ﴿الصَّلَوٰة﴾ (أو التاء المفتوحة: ﴿رَحْمَتَ﴾)."},{"type":"essay","q":"قارن بين دلالة «الصفر المستدير» و«الصفر المستطيل» في ضبط المصحف مع مثال لكل منهما.","model":"الصفر المستدير: يسقط الحرف لفظًا وصلًا ووقفًا (الواو في ﴿أُولَٰئِكَ﴾). الصفر المستطيل: يسقط الحرف وصلًا ويثبت وقفًا (الألف في ﴿أَنَا۠﴾)."},{"type":"essay","q":"اذكر ثلاث فوائد للالتزام بالرسم العثماني في كتابة المصحف.","model":"١) احتواء القراءات المتواترة. ٢) ثبات رسم المصحف ووحدته عبر العصور. ٣) حفظ التلقي والمشافهة عن أهل القرآن."},{"type":"essay","q":"كيف نقف على كل من ﴿رَحْمَتَ﴾ و﴿رَحْمَةَ﴾ في التلاوة؟ ولماذا؟","model":"نقف على ﴿رَحْمَتَ﴾ بالتاء الساكنة، وعلى ﴿رَحْمَةَ﴾ بالهاء الساكنة، التزامًا برسم المصحف العثماني."},{"type":"essay","q":"ما الفرق بين الرسم القرآني (العثماني) والرسم الإملائي (القياسي)؟","model":"الإملائي يطابق النطق وفق قواعد الإملاء المتعارف عليها، أما العثماني فرسم توقيفي خاص بالمصحف فيه قواعد حذف وزيادة وبدل لحكم علمية وقرائية."}]},
  {"id":"g9-islamic-2-u3","grade":"g9","subject":"islamic","term":2,"title":"الوحدة الثالثة (الفصل الثاني)","levels":{"easy":[{"type":"mcq","q":"ما تعريف «السَّكت» في علم التجويد؟","options":["إدغام الحرفين","الوقف الطويل مع أخذ نفس عميق","المدّ ٦ حركات","قطع الصوت زمنًا يسيرًا (نحو حركتين) دون تنفس بنية استئناف القراءة"],"answer":3,"why":"السكت وقفة لطيفة بلا تنفس وعلامتها (س) صغيرة."},{"type":"mcq","q":"ما الموضع الوحيد الذي فيه «إمالة كبرى» في رواية حفص عن عاصم؟","options":["﴿مَجْرٜىٰهَا﴾ في سورة هود","﴿تَأْمَنَّا﴾ في سورة يوسف","﴿ءَا۬عْجَمِيٌّ﴾ في سورة فصلت","﴿بَلْ ۜ رَانَ﴾ في المطففين"],"answer":0,"why":"ليس لحفص إمالة كبرى إلا في ﴿مجرىها﴾ (هود: ٤١)."},{"type":"mcq","q":"ما الحكم الخاص الذي يُراعى لحفص في كلمة ﴿ءَا۬عْجَمِيٌّ﴾ (فصلت: ٤٤)؟","options":["السكت الواجب","التسهيل في الهمزة الثانية (بين الهمزة والألف)","الإمالة الكبرى","الإقلاب"],"answer":1,"why":"الهمزة الثانية مسهّلة وعلامتها نقطة سوداء مطموسة."},{"type":"mcq","q":"كيف يقرأ حفص كلمة ﴿تَأْمَنَّا﴾ في سورة يوسف؟","options":["بإظهار نونين مفتوحتين","بالإمالة الكبرى","بالإدغام مع الإشمام (ضم الشفتين دون صوت) أو الاختلاس","بالسكت"],"answer":2,"why":"الإشمام يشير لحركة الضمة الأصلية في النون الأولى."}],"medium":[{"type":"mcq","q":"أي مجموعة تمثّل «السكتات الأربع الواجبة» لحفص عند الوصل؟","options":["يبصط وبصطة","الفاتحة والإخلاص فقط","مجرىها وتأمنا","عِوَجَا (الكهف)، مَرْقَدِنَا (يس)، مَنْ رَاقٍ (القيامة)، بَلْ رَانَ (المطففين)"],"answer":3,"why":"هذه هي المواضع الأربعة الواجبة للسكت عند حفص."},{"type":"mcq","q":"كيف يقرأ حفص كلمتَي ﴿وَيَبْصُۜطُ﴾ (البقرة) و﴿بَصْۜطَةً﴾ (الأعراف)؟","options":["بالسين الخالصة فقط","بالصاد فقط","بالتسهيل","بالإمالة"],"answer":0,"why":"توضع سين صغيرة فوق الصاد فيقرؤها حفص بالسين فقط."},{"type":"mcq","q":"كيف يقرأ حفص كلمة ﴿بِمُصَيْطِرٍ﴾ في سورة الغاشية؟","options":["بالإمالة","بالصاد الخالصة فقط","بالسين فقط","بالتسهيل"],"answer":1,"why":"﴿بمصيطر﴾ بالصاد فقط، بينما ﴿المصيطرون﴾ بالطور يجوز فيها الوجهان."},{"type":"tfr","q":"السكت في ﴿عِوَجَا ۜ قَيِّمًا﴾ (الكهف) يمنع توهّم أن «قيمًا» صفة لـ«عوجًا» فيحفظ المعنى الدقيق.","answer":true,"reasons":["بل المعنى: لم يجعل له عوجًا، وجعله كتابًا قيمًا","لا أثر له في المعنى","يُدمج الكلمتين"],"reason":0},{"type":"tfr","q":"يُعدّ الدعاء على أخيك المسلم بالشر أو بقطيعة الرحم من «الاعتداء في الدعاء» المحرّم.","answer":true,"reasons":["لا حرج فيه","لقوله تعالى ﴿إنه لا يحب المعتدين﴾","يجوز عند الغضب"],"reason":1}],"hard":[{"type":"mcq","q":"ما العلامة الموضوعة في المصحف للدلالة على موضع «السكت» الواجب؟","options":["معيّن صغير","صفر مستدير","حرف سين صغيرة (س) فوق آخر الكلمة","نقطة مطموسة"],"answer":2,"why":"حرف (س) الصغير يشير لموضع السكت."},{"type":"mcq","q":"ما فائدة السكت في قوله تعالى ﴿مَنْ ۜ رَاقٍ﴾ و﴿بَلْ ۜ رَانَ﴾؟","options":["الوقف التام","تطويل النفس","تغيير المعنى","منع الإدغام الكامل حتى لا يلتبس اللفظ والمعنى (مَرّاق / بَرّان)"],"answer":3,"why":"السكت يمنع الإدغام ويحفظ وضوح الكلمتين والمعنى."},{"type":"mcq","q":"ما الوجهان الجائزان لحفص في كلمة ﴿ضَعْفٍ﴾ بسورة الروم (آية ٥٤)؟","options":["فتح الضاد (ضَعْف) أو ضمها (ضُعْف) مع توحيد الوجه","كسر الضاد فقط","إمالة الضاد","حذف الضاد"],"answer":0,"why":"يجوز الفتح (المقدم) أو الضم بشرط التوحيد في الآية."},{"type":"essay","q":"اذكر السكتات الأربع الواجبة لحفص مع اسم السورة لكل سكتة.","model":"١) ﴿عوجا ۜ قيما﴾ (الكهف). ٢) ﴿مرقدنا ۜ هذا﴾ (يس). ٣) ﴿من ۜ راق﴾ (القيامة). ٤) ﴿بل ۜ ران﴾ (المطففين)."},{"type":"essay","q":"فرّق بين الإمالة والتسهيل والإشمام مع ذكر موضع كل منها لحفص.","model":"الإمالة: تقريب الفتحة للكسرة والألف للياء في ﴿مجرىها﴾ (هود). التسهيل: نطق الهمزة الثانية بين الهمزة والألف في ﴿ءاعجمي﴾ (فصلت). الإشمام: ضم الشفتين بلا صوت إشارة للضمة في ﴿تأمنا﴾ (يوسف)."}]},"test":[{"type":"mcq","q":"ما تعريف «السَّكت» في علم التجويد؟","options":["إدغام الحرفين","الوقف الطويل مع أخذ نفس عميق","المدّ ٦ حركات","قطع الصوت زمنًا يسيرًا (نحو حركتين) دون تنفس بنية استئناف القراءة"],"answer":3,"why":"السكت وقفة لطيفة بلا تنفس وعلامتها (س) صغيرة."},{"type":"mcq","q":"ما الموضع الوحيد الذي فيه «إمالة كبرى» في رواية حفص عن عاصم؟","options":["﴿مَجْرٜىٰهَا﴾ في سورة هود","﴿تَأْمَنَّا﴾ في سورة يوسف","﴿ءَا۬عْجَمِيٌّ﴾ في سورة فصلت","﴿بَلْ ۜ رَانَ﴾ في المطففين"],"answer":0,"why":"ليس لحفص إمالة كبرى إلا في ﴿مجرىها﴾ (هود: ٤١)."},{"type":"mcq","q":"ما الحكم الخاص الذي يُراعى لحفص في كلمة ﴿ءَا۬عْجَمِيٌّ﴾ (فصلت: ٤٤)؟","options":["السكت الواجب","التسهيل في الهمزة الثانية (بين الهمزة والألف)","الإمالة الكبرى","الإقلاب"],"answer":1,"why":"الهمزة الثانية مسهّلة وعلامتها نقطة سوداء مطموسة."},{"type":"mcq","q":"كيف يقرأ حفص كلمة ﴿تَأْمَنَّا﴾ في سورة يوسف؟","options":["بإظهار نونين مفتوحتين","بالإمالة الكبرى","بالإدغام مع الإشمام (ضم الشفتين دون صوت) أو الاختلاس","بالسكت"],"answer":2,"why":"الإشمام يشير لحركة الضمة الأصلية في النون الأولى."},{"type":"mcq","q":"أي مجموعة تمثّل «السكتات الأربع الواجبة» لحفص عند الوصل؟","options":["يبصط وبصطة","الفاتحة والإخلاص فقط","مجرىها وتأمنا","عِوَجَا (الكهف)، مَرْقَدِنَا (يس)، مَنْ رَاقٍ (القيامة)، بَلْ رَانَ (المطففين)"],"answer":3,"why":"هذه هي المواضع الأربعة الواجبة للسكت عند حفص."},{"type":"mcq","q":"كيف يقرأ حفص كلمتَي ﴿وَيَبْصُۜطُ﴾ (البقرة) و﴿بَصْۜطَةً﴾ (الأعراف)؟","options":["بالسين الخالصة فقط","بالصاد فقط","بالتسهيل","بالإمالة"],"answer":0,"why":"توضع سين صغيرة فوق الصاد فيقرؤها حفص بالسين فقط."},{"type":"mcq","q":"كيف يقرأ حفص كلمة ﴿بِمُصَيْطِرٍ﴾ في سورة الغاشية؟","options":["بالإمالة","بالصاد الخالصة فقط","بالسين فقط","بالتسهيل"],"answer":1,"why":"﴿بمصيطر﴾ بالصاد فقط، بينما ﴿المصيطرون﴾ بالطور يجوز فيها الوجهان."},{"type":"mcq","q":"ما العلامة الموضوعة في المصحف للدلالة على موضع «السكت» الواجب؟","options":["معيّن صغير","صفر مستدير","حرف سين صغيرة (س) فوق آخر الكلمة","نقطة مطموسة"],"answer":2,"why":"حرف (س) الصغير يشير لموضع السكت."},{"type":"mcq","q":"ما فائدة السكت في قوله تعالى ﴿مَنْ ۜ رَاقٍ﴾ و﴿بَلْ ۜ رَانَ﴾؟","options":["الوقف التام","تطويل النفس","تغيير المعنى","منع الإدغام الكامل حتى لا يلتبس اللفظ والمعنى (مَرّاق / بَرّان)"],"answer":3,"why":"السكت يمنع الإدغام ويحفظ وضوح الكلمتين والمعنى."},{"type":"mcq","q":"ما الوجهان الجائزان لحفص في كلمة ﴿ضَعْفٍ﴾ بسورة الروم (آية ٥٤)؟","options":["فتح الضاد (ضَعْف) أو ضمها (ضُعْف) مع توحيد الوجه","كسر الضاد فقط","إمالة الضاد","حذف الضاد"],"answer":0,"why":"يجوز الفتح (المقدم) أو الضم بشرط التوحيد في الآية."},{"type":"mcq","q":"ما الطريقة الصحيحة لتعلّم نطق الإمالة والإشمام والتسهيل؟","options":["القراءة السريعة","التلقي والمشافهة من معلم قرآن متقن","التخمين دون سماع","تجاهل العلامات"],"answer":1,"why":"الأداء الصوتي الدقيق لا يُضبط إلا بالتلقي والمشافهة."},{"type":"mcq","q":"ما الآداب الثلاثة للدعاء المذكورة في الآيتين ٥٥ و٥٦ من سورة الأعراف؟","options":["الصراخ والرياء","الدعاء بالإثم","التضرع، والخفية، والخوف والطمع مع ترك الاعتداء","العجلة والغفلة"],"answer":2,"why":"أمر الله بالدعاء تضرعًا وخفية وخوفًا وطمعًا ونهى عن الاعتداء."},{"type":"tf","q":"الفرق بين السكت والوقف أن السكت يكون «بدون تنفس» لزمن يسير، بينما الوقف يكون مع التنفس.","answer":true,"why":"وهذا هو الفارق الأساسي بين السكت والوقف في التجويد"},{"type":"tf","q":"يقرأ حفص كلمة ﴿مَجْرٜىٰهَا﴾ في سورة هود بالإمالة الكبرى، ولا يوجد غيرها في القرآن لحفص.","answer":true,"why":"فهي الموضع الوحيد للإمالة الكبرى في رواية حفص من طريق الشاطبية"},{"type":"tf","q":"في ﴿الْمُصَۜيْطِرُونَ﴾ بسورة الطور يجوز لحفص القراءة بالصاد أو بالسين.","answer":true,"why":"أما ﴿بمصيطر﴾ بالغاشية فبالصاد فقط، و﴿يبصط/بصطة﴾ بالسين فقط"},{"type":"tf","q":"الإشمام في ﴿تَأْمَنَّا﴾ هو صوت عالٍ يُسمع من بعيد.","answer":false,"why":"الإشمام حركة بصرية للشفتين فقط (ضم الشفتين للأمام دون صوت) إشارةً للضمة"},{"type":"tfr","q":"السكت في ﴿عِوَجَا ۜ قَيِّمًا﴾ (الكهف) يمنع توهّم أن «قيمًا» صفة لـ«عوجًا» فيحفظ المعنى الدقيق.","answer":true,"reasons":["بل المعنى: لم يجعل له عوجًا، وجعله كتابًا قيمًا","لا أثر له في المعنى","يُدمج الكلمتين"],"reason":0},{"type":"tfr","q":"يُعدّ الدعاء على أخيك المسلم بالشر أو بقطيعة الرحم من «الاعتداء في الدعاء» المحرّم.","answer":true,"reasons":["لا حرج فيه","لقوله تعالى ﴿إنه لا يحب المعتدين﴾","يجوز عند الغضب"],"reason":1},{"type":"tfr","q":"إحياء الأرض الميتة بنزول المطر وإخراج الثمرات دليل حسي وعقلي على قدرة الله على البعث.","answer":true,"reasons":["يحدث بالصدفة","لا علاقة له بالبعث","﴿كذلك نخرج الموتى لعلكم تذكرون﴾"],"reason":2},{"type":"tfr","q":"النهي عن الإفساد في الأرض في الآية ٥٦ يشمل التلوث البيئي وتخريب المرافق العامة بجانب المعاصي.","answer":true,"reasons":["فالآية عامة في حفظ صلاح الأرض الديني والبيئي والاجتماعي","يقتصر على الشرك فقط","لا يشمل البيئة"],"reason":0},{"type":"essay","q":"اذكر السكتات الأربع الواجبة لحفص مع اسم السورة لكل سكتة.","model":"١) ﴿عوجا ۜ قيما﴾ (الكهف). ٢) ﴿مرقدنا ۜ هذا﴾ (يس). ٣) ﴿من ۜ راق﴾ (القيامة). ٤) ﴿بل ۜ ران﴾ (المطففين)."},{"type":"essay","q":"فرّق بين الإمالة والتسهيل والإشمام مع ذكر موضع كل منها لحفص.","model":"الإمالة: تقريب الفتحة للكسرة والألف للياء في ﴿مجرىها﴾ (هود). التسهيل: نطق الهمزة الثانية بين الهمزة والألف في ﴿ءاعجمي﴾ (فصلت). الإشمام: ضم الشفتين بلا صوت إشارة للضمة في ﴿تأمنا﴾ (يوسف)."},{"type":"essay","q":"بيّن حكم الصاد والسين عند حفص في: ﴿يبصط﴾، ﴿بصطة﴾، ﴿المصيطرون﴾، ﴿بمصيطر﴾.","model":"يبصط وبصطة: بالسين فقط. المصيطرون: بالوجهين (صاد أو سين). بمصيطر: بالصاد فقط."},{"type":"essay","q":"قارن بين السكت والوقف من حيث الزمن والتنفس والعلامة في المصحف.","model":"السكت: زمن يسير نحو حركتين بلا تنفس وعلامته (س). الوقف: زمن أطول مع التنفس وعلاماته (قلى، صلى، م، ج)."},{"type":"essay","q":"علّل: لماذا لا يُغني الشرح المكتوب وحده عن المشافهة في إتقان درس «ما يُراعى لحفص»؟","model":"لأن الإمالة والإشمام والتسهيل ظواهر صوتية وحركية دقيقة لا تُضبط إلا بالسماع المباشر من معلم متقن وتصحيح النطق."}]},
  {"id":"g9-islamic-2-u4","grade":"g9","subject":"islamic","term":2,"title":"الوحدة الرابعة (الفصل الثاني)","levels":{"easy":[{"type":"mcq","q":"ما معنى «المشكاة» في آية النور (سورة النور: ٣٥)؟","options":["الكُوّة (الفتحة غير النافذة في الجدار) التي تجمع الضوء وتقوّيه","الكتاب المفتوح","السفينة","الشجرة"],"answer":0,"why":"المشكاة هي الكوة في الحائط التي يوضع فيها المصباح."},{"type":"mcq","q":"ما المقصود بـ«الغدوّ والآصال» في قوله ﴿يسبّح له فيها بالغدو والآصال﴾؟","options":["البر والبحر","أول النهار (الصباح) وآخره (المساء)","الشرق والغرب","الشتاء والصيف"],"answer":1,"why":"الغدوّ أول النهار والآصال آخره كناية عن دوام الذكر."},{"type":"mcq","q":"ما نوعا «عمارة المساجد» المستفادان من الآية ٣٦؟","options":["العمارة الحسية فقط بلا صلاة","البيع والشراء داخلها","عمارة حسية (البناء والنظافة والصيانة) وعمارة معنوية (الصلاة والذكر والعلم)","النوم فيها فقط"],"answer":2,"why":"لا تكتمل عمارة المسجد إلا بالبناء والصيانة وبإقامة الصلاة والذكر فيه."},{"type":"mcq","q":"ما دلالة وصف الله لعمّار المساجد بـ﴿لا تلهيهم تجارة ولا بيع عن ذكر الله﴾؟","options":["أنهم لا يعملون ولا يتاجرون أبدًا","أنهم يغلقون الأسواق للأبد","أن التجارة حرام","أنهم يعملون ويتاجرون بالحلال لكنهم يقدّمون الصلاة والذكر فور دخول وقتهما"],"answer":3,"why":"يجمع المؤمن بين السعي في الدنيا وتقديم حق الله عند وقته."}],"medium":[{"type":"mcq","q":"ما المقصود بـ«البيوت» في قوله تعالى ﴿في بيوت أذن الله أن تُرفع ويُذكر فيها اسمه﴾؟","options":["المساجد","الأسواق","القصور","القلاع"],"answer":0,"why":"المساجد هي بيوت الله التي أمر بتعظيمها ورفع شأنها."},{"type":"mcq","q":"ما معنى «نور على نور» في قلب المؤمن؟","options":["البرق والرعد","اجتماع نور الفطرة والعقل السليم مع نور القرآن والوحي الإلهي","الشمس والقمر فقط","مصباحان في الشارع"],"answer":1,"why":"يزداد قلب المؤمن هدايةً وضياءً باجتماع الفطرة والوحي."},{"type":"mcq","q":"ما الدافع الإيماني الذي يجعل عمّار المساجد لا ينشغلون بالتجارة عن الصلاة؟","options":["عدم وجود زبائن","الخوف من الخسارة المالية","﴿يخافون يومًا تتقلب فيه القلوب والأبصار﴾ (خشية يوم القيامة)","حب الراحة فقط"],"answer":2,"why":"استحضار يوم القيامة يضبط أولويات المؤمن."},{"type":"tfr","q":"ترك التجارة لحظة الأذان للصلاة ينقص الرزق ويضيّع البركة.","answer":false,"reasons":["يضيع المال","بل وعد الله عمّار المساجد بالزيادة والرزق بغير حساب في الآية ٣٨","نعم ينقص الرزق"],"reason":1},{"type":"tfr","q":"يُعدّ التباهي بالذنوب القديمة أمام الأصدقاء للإضحاك من صور المجاهرة المذمومة في الحديث.","answer":true,"reasons":["يُعد صراحة محمودة","لا بأس ما دامت قديمة","لأنه يكشف ستر الله عنه ويهوّن الذنب في أعين السامعين"],"reason":2}],"hard":[{"type":"mcq","q":"ما الجزاء الذي وعد الله به عمّار المساجد الصادقين في الآية ٣٨؟","options":["يعطيهم أقل من عملهم","لا جزاء لهم في الآخرة","يقل رزقهم","يجزيهم أحسن ما عملوا ويزيدهم من فضله ويرزقهم بغير حساب"],"answer":3,"why":"﴿ليجزيهم الله أحسن ما عملوا ويزيدهم من فضله والله يرزق من يشاء بغير حساب﴾."},{"type":"mcq","q":"في حياة طالب الصف التاسع اليوم، ما الموقف الذي يطبّق الآية ٣٧؟","options":["ترك الهاتف أو المباراة فور سماع الأذان لأداء الصلاة في وقتها","تأخير الصلاة حتى انتهاء اللعبة","ترك الدراسة تمامًا","رفع الصوت في المسجد"],"answer":0,"why":"تقديم الصلاة على الملهيات هو عين تطبيق الآية."},{"type":"mcq","q":"ما المقصود بـ«الكوكب الدُرّي» في الآية ٣٥؟","options":["الشجرة اليابسة","الكوكب المضيء الصافي اللامع كالدرّ (اللؤلؤ)","السحاب الداكن","الحجر الأسود"],"answer":1,"why":"شُبّهت الزجاجة الصافية بلمعان الكوكب الدري."},{"type":"essay","q":"وضّح باختصار المَثَل القرآني في آية النور (المشكاة، الزجاجة، المصباح، والزيت المبارك).","model":"المشكاة (الكوة) والزجاجة الصافية والمصباح الموقد بزيت زيتون نقي تمثل صفاء قلب المؤمن وفطرته التي يجتمع فيها نور القرآن فيصبح «نورًا على نور»."},{"type":"essay","q":"قارن بين «العمارة الحسية» و«العمارة المعنوية» للمساجد مع مثالين لكل منهما.","model":"الحسية: البناء والصيانة والنظافة وتوفير الماء والتكييف. المعنوية: إقامة الصلوات الجماعية، وحلقات تحفيظ القرآن، والدروس العلمية والذكر."}]},"test":[{"type":"mcq","q":"ما معنى «المشكاة» في آية النور (سورة النور: ٣٥)؟","options":["الكُوّة (الفتحة غير النافذة في الجدار) التي تجمع الضوء وتقوّيه","الكتاب المفتوح","السفينة","الشجرة"],"answer":0,"why":"المشكاة هي الكوة في الحائط التي يوضع فيها المصباح."},{"type":"mcq","q":"ما المقصود بـ«الغدوّ والآصال» في قوله ﴿يسبّح له فيها بالغدو والآصال﴾؟","options":["البر والبحر","أول النهار (الصباح) وآخره (المساء)","الشرق والغرب","الشتاء والصيف"],"answer":1,"why":"الغدوّ أول النهار والآصال آخره كناية عن دوام الذكر."},{"type":"mcq","q":"ما نوعا «عمارة المساجد» المستفادان من الآية ٣٦؟","options":["العمارة الحسية فقط بلا صلاة","البيع والشراء داخلها","عمارة حسية (البناء والنظافة والصيانة) وعمارة معنوية (الصلاة والذكر والعلم)","النوم فيها فقط"],"answer":2,"why":"لا تكتمل عمارة المسجد إلا بالبناء والصيانة وبإقامة الصلاة والذكر فيه."},{"type":"mcq","q":"ما دلالة وصف الله لعمّار المساجد بـ﴿لا تلهيهم تجارة ولا بيع عن ذكر الله﴾؟","options":["أنهم لا يعملون ولا يتاجرون أبدًا","أنهم يغلقون الأسواق للأبد","أن التجارة حرام","أنهم يعملون ويتاجرون بالحلال لكنهم يقدّمون الصلاة والذكر فور دخول وقتهما"],"answer":3,"why":"يجمع المؤمن بين السعي في الدنيا وتقديم حق الله عند وقته."},{"type":"mcq","q":"ما المقصود بـ«البيوت» في قوله تعالى ﴿في بيوت أذن الله أن تُرفع ويُذكر فيها اسمه﴾؟","options":["المساجد","الأسواق","القصور","القلاع"],"answer":0,"why":"المساجد هي بيوت الله التي أمر بتعظيمها ورفع شأنها."},{"type":"mcq","q":"ما معنى «نور على نور» في قلب المؤمن؟","options":["البرق والرعد","اجتماع نور الفطرة والعقل السليم مع نور القرآن والوحي الإلهي","الشمس والقمر فقط","مصباحان في الشارع"],"answer":1,"why":"يزداد قلب المؤمن هدايةً وضياءً باجتماع الفطرة والوحي."},{"type":"mcq","q":"ما الدافع الإيماني الذي يجعل عمّار المساجد لا ينشغلون بالتجارة عن الصلاة؟","options":["عدم وجود زبائن","الخوف من الخسارة المالية","﴿يخافون يومًا تتقلب فيه القلوب والأبصار﴾ (خشية يوم القيامة)","حب الراحة فقط"],"answer":2,"why":"استحضار يوم القيامة يضبط أولويات المؤمن."},{"type":"mcq","q":"ما الجزاء الذي وعد الله به عمّار المساجد الصادقين في الآية ٣٨؟","options":["يعطيهم أقل من عملهم","لا جزاء لهم في الآخرة","يقل رزقهم","يجزيهم أحسن ما عملوا ويزيدهم من فضله ويرزقهم بغير حساب"],"answer":3,"why":"﴿ليجزيهم الله أحسن ما عملوا ويزيدهم من فضله والله يرزق من يشاء بغير حساب﴾."},{"type":"mcq","q":"في حياة طالب الصف التاسع اليوم، ما الموقف الذي يطبّق الآية ٣٧؟","options":["ترك الهاتف أو المباراة فور سماع الأذان لأداء الصلاة في وقتها","تأخير الصلاة حتى انتهاء اللعبة","ترك الدراسة تمامًا","رفع الصوت في المسجد"],"answer":0,"why":"تقديم الصلاة على الملهيات هو عين تطبيق الآية."},{"type":"mcq","q":"ما المقصود بـ«الكوكب الدُرّي» في الآية ٣٥؟","options":["الشجرة اليابسة","الكوكب المضيء الصافي اللامع كالدرّ (اللؤلؤ)","السحاب الداكن","الحجر الأسود"],"answer":1,"why":"شُبّهت الزجاجة الصافية بلمعان الكوكب الدري."},{"type":"mcq","q":"أي تصرف يخلّ بآداب المسجد وتعظيمه ﴿أذن الله أن تُرفع﴾؟","options":["تلاوة القرآن بهدوء","صلاة تحية المسجد","ترك رنين الهاتف مرتفعًا أو رمي المناديل أو رفع الصوت باللغو","تنظيف المسجد"],"answer":2,"why":"تعظيم المسجد يقتضي نظافته وهدوءه وصيانته."},{"type":"mcq","q":"ما معنى «المجاهرون» في الحديث الشريف «كل أمتي معافى إلا المجاهرين»؟","options":["الذين يستترون ويتوبون","الذين يجهرون بقراءة القرآن في الصلاة","الذين ينصحون بالخير","الذين يعلنون معاصيهم أمام الناس أو يتحدثون بها تفاخرًا بعد أن سترهم الله"],"answer":3,"why":"المجاهرة هي إظهار المعصية أو التحدث بها وهتك ستر الله."},{"type":"tf","q":"تجمع الآية ٣٧ بين السعي في التجارة والعمل وبين تقديم الصلاة والذكر عند دخول وقتهما.","answer":true,"why":"فالإسلام لا يعارض العمل بل يمنع أن يلهي العمل عن طاعة الله"},{"type":"tf","q":"تقتصر عمارة المساجد على بنائها وزخرفتها دون الحاجة لإقامة الصلاة والذكر فيها.","answer":false,"why":"العمارة الحقيقية تشمل العمارة الحسية (البناء والنظافة) والعمارة المعنوية (الصلاة والذكر والعلم)"},{"type":"tf","q":"وصف الله الشجرة المباركة في آية النور بأنها شجرة الزيتون لصفاء زيتها وشدة إضاءته.","answer":true,"why":"﴿يوقد من شجرة مباركة زيتونة... يكاد زيتها يضيء ولو لم تمسسه نار﴾"},{"type":"tf","q":"حفظ المسجد نظيفًا وهادئًا وصامت الهاتف من صور تعظيم بيوت الله.","answer":true,"why":"وهو داخل في قوله ﴿في بيوت أذن الله أن ترفع﴾"},{"type":"tfr","q":"ترك التجارة لحظة الأذان للصلاة ينقص الرزق ويضيّع البركة.","answer":false,"reasons":["يضيع المال","بل وعد الله عمّار المساجد بالزيادة والرزق بغير حساب في الآية ٣٨","نعم ينقص الرزق"],"reason":1},{"type":"tfr","q":"يُعدّ التباهي بالذنوب القديمة أمام الأصدقاء للإضحاك من صور المجاهرة المذمومة في الحديث.","answer":true,"reasons":["يُعد صراحة محمودة","لا بأس ما دامت قديمة","لأنه يكشف ستر الله عنه ويهوّن الذنب في أعين السامعين"],"reason":2},{"type":"tfr","q":"سؤال العالم أو الأخصائي سرًا بنية التوبة والعلاج يُعدّ مجاهرةً محرّمة.","answer":false,"reasons":["الاستفتاء وطلب العلاج بنية صادقة جائز ومشروع وليس مجاهرة","نعم مجاهرة","يحرم السؤال عن الذنب"],"reason":0},{"type":"tfr","q":"المجاهرة بالمعصية على وسائل التواصل قد تجعل صاحبها يتحمّل وزر من قلّده بسبب نشره.","answer":true,"reasons":["لا يتحمل أي وزر","فهي قدوة سيئة وإشاعة للفساد يجب التوبة منها وحذفها فورًا","المشاهدات تمحو الذنب"],"reason":1},{"type":"essay","q":"وضّح باختصار المَثَل القرآني في آية النور (المشكاة، الزجاجة، المصباح، والزيت المبارك).","model":"المشكاة (الكوة) والزجاجة الصافية والمصباح الموقد بزيت زيتون نقي تمثل صفاء قلب المؤمن وفطرته التي يجتمع فيها نور القرآن فيصبح «نورًا على نور»."},{"type":"essay","q":"قارن بين «العمارة الحسية» و«العمارة المعنوية» للمساجد مع مثالين لكل منهما.","model":"الحسية: البناء والصيانة والنظافة وتوفير الماء والتكييف. المعنوية: إقامة الصلوات الجماعية، وحلقات تحفيظ القرآن، والدروس العلمية والذكر."},{"type":"essay","q":"كيف تردّ من خلال الآية ٣٧ على من يظن أن التدين يعني ترك التجارة والعمل الدنيوي؟","model":"الآية مدحت رجالًا يعملون في التجارة والبيع، لكنها أثنت عليهم بأن عملهم لا يلهيهم عن ذكر الله وإقام الصلاة وإيتاء الزكاة؛ فالمؤمن يعمل ويتقن ويقدم حق الله."},{"type":"essay","q":"اذكر أربعة آداب يحرص عليها المسلم عند دخول المسجد.","model":"١) دخول باليمنى ودعاء الدخول وصلاة تحية المسجد. ٢) وضع الهاتف على الصامت. ٣) خفض الصوت وترك اللغو. ٤) المحافظة على نظافة المسجد."},{"type":"essay","q":"ما المعنى الإيماني لقوله تعالى ﴿تتقلّب فيه القلوب والأبصار﴾ في الآية ٣٧؟","model":"يصف شدة هول يوم القيامة فتضطرب القلوب وتزيغ الأبصار من الرهبة، واستحضار ذلك اليوم يحفظ المؤمن من الغفلة."}]}
);
